    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbePlacementUniformPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const int ScreenProbePlacementUniformPassIndex = 16;
        private const string ScreenProbePlacementComputeShaderResourcePath = "BurtGIScreenProbePlacement";
        private const string ScreenProbePlacementUniformComputeKernelName = "ScreenProbePlacementUniformCS";
        private const int ScreenProbePlacementUniformThreadGroupSize = 8;
        private static readonly int BurtHiZDepthTextureId = BurtRenderGraphResourceRegistry.HiZDepthTextureId;
        private static readonly int BurtGIScreenProbePlacementParamsId = Shader.PropertyToID("_BurtGIScreenProbePlacementParams");
        private static readonly int BurtGIScreenProbeScreenDepthWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeScreenDepthWriteTexture");
        private static readonly int BurtGIScreenProbeWorldNormalWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeWorldNormalWriteTexture");
        private static readonly int BurtGIScreenProbeWorldPositionWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeWorldPositionWriteTexture");
        private static ComputeShader screenProbePlacementComputeShader;
        private static bool hasLoggedMissingScreenProbePlacementComputeShader;
        private static bool hasLoggedMissingScreenProbePlacementUniformKernel;

        public override string Name => "Burt ScreenProbe Placement Uniform";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadGBuffer1();
            builder.ReadGBuffer2();
            builder.ReadGBuffer3();
            builder.ReadGBuffer4();
            builder.ReadGBuffer5();
            if (BurtHiZDepthPassUtility.ShouldUseHiZDepth(builder.Request, builder.Asset))
            {
                builder.ReadHiZDepth();
            }

            builder.WriteBurtGIScreenProbeScreenDepth();
            builder.WriteBurtGIScreenProbeWorldNormal();
            builder.WriteBurtGIScreenProbeWorldPosition();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(
                    context,
                    out var cameraDepthTarget,
                    out var gbuffer0Target,
                    out var gbuffer1Target,
                    out var gbuffer2Target,
                    out var gbuffer3Target,
                    out var gbuffer4Target,
                    out var gbuffer5Target,
                    out var screenDepthTarget,
                    out var worldNormalTarget,
                    out var worldPositionTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            if (!settings.Enabled || !screenProbeSettings.Enabled)
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            if (camera == null)
            {
                return;
            }

            var sourceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var probeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
            if (TryDispatchPlacementUniformCompute(
                    context,
                    camera,
                    settings,
                    screenProbeSettings,
                    sourceDescriptor,
                    probeDescriptor,
                    cameraDepthTarget,
                    gbuffer0Target,
                    gbuffer2Target,
                    screenDepthTarget,
                    worldNormalTarget,
                    worldPositionTarget))
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            if (material == null)
            {
                return;
            }

            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetRenderTarget(
                new[]
                {
                    screenDepthTarget.Identifier,
                    worldNormalTarget.Identifier,
                    worldPositionTarget.Identifier,
                },
                new RenderTargetIdentifier(BuiltinRenderTextureType.None));
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, probeDescriptor.width, probeDescriptor.height);
            cmd.SetGlobalTexture(CameraDepthTextureId, cameraDepthTarget.Identifier);
            var hiZDepthTarget = context != null ? context.HiZDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.HiZDepthName);
            var hiZDepthValid = hiZDepthTarget.IsValid && BurtHiZDepthPassUtility.ShouldUseHiZDepth(context.Request, context.Asset);
            cmd.SetGlobalTexture(BurtHiZDepthTextureId, hiZDepthValid ? hiZDepthTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetGlobalVector(BurtGIScreenProbePlacementParamsId, new Vector4(hiZDepthValid ? 1f : 0f, 0f, screenProbeSettings.SpacingPixels, 0f));
            BurtDeferredStencilTextureUtility.BindGlobal(cmd, cameraDepthTarget, camera);
            BindGBufferInputs(cmd, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, gbuffer4Target, gbuffer5Target);
            UploadCameraGlobals(cmd, context.Request, camera, sourceDescriptor);
            UploadSettings(cmd, settings);
            UploadScreenProbeSettings(cmd, screenProbeSettings, probeDescriptor);
            cmd.DrawProcedural(Matrix4x4.identity, material, ScreenProbePlacementUniformPassIndex, MeshTopology.Triangles, 3, 1);
            cmd.SetGlobalTexture(BurtGIScreenProbeScreenDepthTextureId, screenDepthTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeWorldNormalTextureId, worldNormalTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryDispatchPlacementUniformCompute(
            BurtRenderGraphContext context,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor sourceDescriptor,
            RenderTextureDescriptor probeDescriptor,
            BurtRenderTargetHandle cameraDepthTarget,
            BurtRenderTargetHandle gbuffer0Target,
            BurtRenderTargetHandle gbuffer2Target,
            BurtRenderTargetHandle screenDepthTarget,
            BurtRenderTargetHandle worldNormalTarget,
            BurtRenderTargetHandle worldPositionTarget)
        {
            var shader = GetScreenProbePlacementComputeShader();
            if (!TryFindScreenProbePlacementUniformKernel(shader, out var kernel))
            {
                return false;
            }

            var hiZDepthTarget = context != null ? context.HiZDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.HiZDepthName);
            var hiZDepthValid = hiZDepthTarget.IsValid && BurtHiZDepthPassUtility.ShouldUseHiZDepth(context.Request, context.Asset);
            var placementJitterIndex = screenProbeSettings.FixedJitterIndex >= 0
                ? -(screenProbeSettings.FixedJitterIndex + 1f)
                : Mathf.Max(0, Time.frameCount);
            var cmd = context.AcquireCommandBuffer("Burt ScreenProbe Placement Uniform Compute");
            cmd.SetComputeTextureParam(shader, kernel, CameraDepthTextureId, cameraDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer0Id, gbuffer0Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer2Id, gbuffer2Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtHiZDepthTextureId, hiZDepthValid ? hiZDepthTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthWriteTextureId, screenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalWriteTextureId, worldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionWriteTextureId, worldPositionTarget.Identifier);
            UploadCameraGlobals(cmd, context.Request, camera, sourceDescriptor);
            UploadSettings(cmd, settings);
            UploadScreenProbeSettings(cmd, screenProbeSettings, probeDescriptor);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbePlacementParamsId, new Vector4(
                hiZDepthValid ? 1f : 0f,
                placementJitterIndex,
                Mathf.Max(1f, screenProbeSettings.SpacingPixels),
                0f));
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (probeDescriptor.width + ScreenProbePlacementUniformThreadGroupSize - 1) / ScreenProbePlacementUniformThreadGroupSize),
                Mathf.Max(1, (probeDescriptor.height + ScreenProbePlacementUniformThreadGroupSize - 1) / ScreenProbePlacementUniformThreadGroupSize),
                1);
            cmd.SetGlobalTexture(BurtGIScreenProbeScreenDepthTextureId, screenDepthTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeWorldNormalTextureId, worldNormalTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static ComputeShader GetScreenProbePlacementComputeShader()
        {
            if (screenProbePlacementComputeShader != null)
            {
                return screenProbePlacementComputeShader;
            }

            screenProbePlacementComputeShader = Resources.Load<ComputeShader>(ScreenProbePlacementComputeShaderResourcePath);
            if (screenProbePlacementComputeShader == null && !hasLoggedMissingScreenProbePlacementComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ScreenProbePlacementComputeShaderResourcePath);
                hasLoggedMissingScreenProbePlacementComputeShader = true;
            }

            return screenProbePlacementComputeShader;
        }

        private static bool TryFindScreenProbePlacementUniformKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(ScreenProbePlacementUniformComputeKernelName))
            {
                if (!hasLoggedMissingScreenProbePlacementUniformKernel)
                {
                    Debug.LogWarning("BurtRP screen probe placement compute shader missing kernel: " + ScreenProbePlacementUniformComputeKernelName);
                    hasLoggedMissingScreenProbePlacementUniformKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(ScreenProbePlacementUniformComputeKernelName);
            return kernel >= 0;
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle cameraDepthTarget,
            out BurtRenderTargetHandle gbuffer0Target,
            out BurtRenderTargetHandle gbuffer1Target,
            out BurtRenderTargetHandle gbuffer2Target,
            out BurtRenderTargetHandle gbuffer3Target,
            out BurtRenderTargetHandle gbuffer4Target,
            out BurtRenderTargetHandle gbuffer5Target,
            out BurtRenderTargetHandle screenDepthTarget,
            out BurtRenderTargetHandle worldNormalTarget,
            out BurtRenderTargetHandle worldPositionTarget)
        {
            cameraDepthTarget = context != null ? context.CameraDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.CameraDepthName);
            gbuffer0Target = context != null ? context.GBuffer0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer0Name);
            gbuffer1Target = context != null ? context.GBuffer1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer1Name);
            gbuffer2Target = context != null ? context.GBuffer2Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer2Name);
            gbuffer3Target = context != null ? context.GBuffer3Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer3Name);
            gbuffer4Target = context != null ? context.GBuffer4Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer4Name);
            gbuffer5Target = context != null ? context.GBuffer5Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer5Name);
            screenDepthTarget = context != null ? context.BurtGIScreenProbeScreenDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthName);
            worldNormalTarget = context != null ? context.BurtGIScreenProbeWorldNormalTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalName);
            worldPositionTarget = context != null ? context.BurtGIScreenProbeWorldPositionTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionName);

            return cameraDepthTarget.IsValid &&
                gbuffer0Target.IsValid &&
                gbuffer1Target.IsValid &&
                gbuffer2Target.IsValid &&
                gbuffer3Target.IsValid &&
                gbuffer4Target.IsValid &&
                gbuffer5Target.IsValid &&
                screenDepthTarget.IsValid &&
                worldNormalTarget.IsValid &&
                worldPositionTarget.IsValid;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeAdaptivePlacementSetupPass : BurtRenderPass
    {
        private const string ScreenProbeAdaptivePlacementComputeShaderResourcePath = "BurtGIScreenProbeAdaptivePlacement";
        private const string ScreenProbeAdaptivePlacementKernelName = "ScreenProbePlacementAdaptiveCS";
        private const string ScreenProbeAdaptivePlacementFallbackKernelName = "ScreenProbeAdaptivePlacementLiteCS";
        private const int ScreenProbeAdaptivePlacementThreadGroupSize = 8;
        private static readonly uint[] ZeroUint = { 0u };
        private static readonly int BurtGIScreenProbeScreenDepthTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthTextureId;
        private static readonly int BurtGIScreenProbeWorldNormalTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalTextureId;
        private static readonly int BurtGIScreenProbeWorldPositionTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionTextureId;
        private static readonly int BurtGIScreenProbeAdaptiveParamsId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveParams");
        private static readonly int BurtGIScreenProbeAdaptivePlacementParamsId = Shader.PropertyToID("_BurtGIScreenProbeAdaptivePlacementParams");
        private static readonly int BurtGIScreenProbeAdaptiveProbeHeaderTextureId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeHeaderTexture");
        private static readonly int BurtGIScreenProbeAdaptiveProbeIndicesTextureId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeIndicesTexture");
        private static readonly int BurtGIScreenProbeAdaptiveProbeNumBufferId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeNumBuffer");
        private static readonly int BurtGIScreenProbeAdaptiveProbeDataBufferId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeDataBuffer");
        private static ComputeShader screenProbeAdaptivePlacementComputeShader;
        private static bool hasLoggedMissingScreenProbeAdaptivePlacementComputeShader;
        private static bool hasLoggedMissingScreenProbeAdaptivePlacementKernel;

        public override string Name => "Burt ScreenProbe Adaptive Placement Setup";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadCameraDepth();
            builder.ReadBurtGIScreenProbeScreenDepth();
            builder.ReadBurtGIScreenProbeWorldNormal();
            builder.ReadBurtGIScreenProbeWorldPosition();
            builder.WriteBurtGIScreenProbeAdaptiveProbeHeader();
            builder.WriteBurtGIScreenProbeAdaptiveProbeIndices();
            builder.WriteBurtGIScreenProbeAdaptiveProbeNumBuffer();
            builder.WriteBurtGIScreenProbeAdaptiveProbeDataBuffer();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(context.Request, context.Asset))
            {
                return;
            }

            var headerTarget = context.BurtGIScreenProbeAdaptiveProbeHeaderTarget;
            var indicesTarget = context.BurtGIScreenProbeAdaptiveProbeIndicesTarget;
            var cmd = context.AcquireCommandBuffer(Name);
            var hasCommandBufferWork = false;
            if (headerTarget.IsValid || indicesTarget.IsValid)
            {
                if (headerTarget.IsValid)
                {
                    cmd.SetRenderTarget(headerTarget.Identifier);
                    cmd.ClearRenderTarget(false, true, Color.clear);
                    cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIScreenProbeAdaptiveProbeHeaderTextureId, headerTarget.Identifier);
                    hasCommandBufferWork = true;
                }

                if (indicesTarget.IsValid)
                {
                    cmd.SetRenderTarget(indicesTarget.Identifier);
                    cmd.ClearRenderTarget(false, true, Color.clear);
                    cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIScreenProbeAdaptiveProbeIndicesTextureId, indicesTarget.Identifier);
                    hasCommandBufferWork = true;
                }
            }

            var probeNumBuffer = context.BurtGIScreenProbeAdaptiveProbeNumBuffer;
            if (probeNumBuffer.HasBuffer)
            {
                probeNumBuffer.Buffer.SetData(ZeroUint);
                cmd.SetGlobalBuffer(BurtGIScreenProbeAdaptiveProbeNumBufferId, probeNumBuffer.Buffer);
                hasCommandBufferWork = true;
            }

            var probeDataBuffer = context.BurtGIScreenProbeAdaptiveProbeDataBuffer;
            if (probeDataBuffer.HasBuffer)
            {
                probeDataBuffer.Buffer.SetData(ZeroUint);
                cmd.SetGlobalBuffer(BurtGIScreenProbeAdaptiveProbeDataBufferId, probeDataBuffer.Buffer);
                hasCommandBufferWork = true;
            }

            hasCommandBufferWork |= TryAppendAdaptivePlacementCompute(context, cmd);
            if (hasCommandBufferWork)
            {
                context.ExecuteLegacyCommandBuffer(cmd);
            }

            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryAppendAdaptivePlacementCompute(BurtRenderGraphContext context, CommandBuffer cmd)
        {
            if (!HasAdaptivePlacementInputs(context))
            {
                return false;
            }

            var shader = GetScreenProbeAdaptivePlacementComputeShader();
            if (!TryFindScreenProbeAdaptivePlacementKernel(shader, out var kernel))
            {
                return false;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var probeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            var screenProbeWidth = Mathf.Max(1, probeDescriptor.width);
            var screenProbeHeight = Mathf.Max(1, probeDescriptor.height);
            var tileCapacity = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeAdaptiveProbeIndexTileCapacity(settings);
            var maxAdaptiveProbes = Mathf.Max(1, context.BurtGIScreenProbeAdaptiveProbeDataBuffer.Buffer.count);
            var adaptiveParams = new Vector4(
                screenProbeWidth,
                screenProbeHeight,
                tileCapacity,
                maxAdaptiveProbes);

            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, context.BurtGIScreenProbeScreenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, context.BurtGIScreenProbeWorldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, context.BurtGIScreenProbeWorldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeHeaderTextureId, context.BurtGIScreenProbeAdaptiveProbeHeaderTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeIndicesTextureId, context.BurtGIScreenProbeAdaptiveProbeIndicesTarget.Identifier);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeNumBufferId, context.BurtGIScreenProbeAdaptiveProbeNumBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeDataBufferId, context.BurtGIScreenProbeAdaptiveProbeDataBuffer.Buffer);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeAdaptiveParamsId, adaptiveParams);
            cmd.SetGlobalVector(BurtGIScreenProbeAdaptiveParamsId, adaptiveParams);

            var uniformDownSampleFactor = Mathf.Max(1, settings.SpacingPixels);
            var minDownSampleFactor = Mathf.Max(
                1,
                Mathf.Min(
                    uniformDownSampleFactor,
                    settings.AdaptiveMinDownSampleFactor));
            if (maxAdaptiveProbes <= 0 || minDownSampleFactor >= uniformDownSampleFactor)
            {
                return false;
            }

            var dispatched = false;
            var adaptiveDownSampleFactor = uniformDownSampleFactor;
            do
            {
                adaptiveDownSampleFactor = Mathf.Max(1, adaptiveDownSampleFactor / 2);
                var adaptiveSubGridSize = Mathf.Max(1, Mathf.CeilToInt(uniformDownSampleFactor / (float)adaptiveDownSampleFactor));
                var adaptiveLevel = 0;
                while ((1 << adaptiveLevel) < adaptiveSubGridSize && adaptiveLevel < 15)
                {
                    ++adaptiveLevel;
                }

                adaptiveSubGridSize = 1 << adaptiveLevel;
                cmd.SetComputeVectorParam(
                    shader,
                    BurtGIScreenProbeAdaptivePlacementParamsId,
                    new Vector4(uniformDownSampleFactor, adaptiveDownSampleFactor, adaptiveSubGridSize, adaptiveLevel));
                cmd.DispatchCompute(
                    shader,
                    kernel,
                    Mathf.CeilToInt(screenProbeWidth * adaptiveSubGridSize / (float)ScreenProbeAdaptivePlacementThreadGroupSize),
                    Mathf.CeilToInt(screenProbeHeight * adaptiveSubGridSize / (float)ScreenProbeAdaptivePlacementThreadGroupSize),
                    1);
                dispatched = true;
            } while (adaptiveDownSampleFactor > minDownSampleFactor);

            return dispatched;
        }

        private static bool HasAdaptivePlacementInputs(BurtRenderGraphContext context)
        {
            return context != null &&
                context.BurtGIScreenProbeScreenDepthTarget.IsValid &&
                context.BurtGIScreenProbeWorldNormalTarget.IsValid &&
                context.BurtGIScreenProbeWorldPositionTarget.IsValid &&
                context.BurtGIScreenProbeAdaptiveProbeHeaderTarget.IsValid &&
                context.BurtGIScreenProbeAdaptiveProbeIndicesTarget.IsValid &&
                context.BurtGIScreenProbeAdaptiveProbeNumBuffer.HasBuffer &&
                context.BurtGIScreenProbeAdaptiveProbeDataBuffer.HasBuffer;
        }

        private static ComputeShader GetScreenProbeAdaptivePlacementComputeShader()
        {
            if (screenProbeAdaptivePlacementComputeShader != null)
            {
                return screenProbeAdaptivePlacementComputeShader;
            }

            screenProbeAdaptivePlacementComputeShader = Resources.Load<ComputeShader>(ScreenProbeAdaptivePlacementComputeShaderResourcePath);
            if (screenProbeAdaptivePlacementComputeShader == null && !hasLoggedMissingScreenProbeAdaptivePlacementComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ScreenProbeAdaptivePlacementComputeShaderResourcePath);
                hasLoggedMissingScreenProbeAdaptivePlacementComputeShader = true;
            }

            return screenProbeAdaptivePlacementComputeShader;
        }

        private static bool TryFindScreenProbeAdaptivePlacementKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            var kernelName = ScreenProbeAdaptivePlacementKernelName;
            if (!shader.HasKernel(kernelName))
            {
                kernelName = ScreenProbeAdaptivePlacementFallbackKernelName;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingScreenProbeAdaptivePlacementKernel)
                {
                    Debug.LogWarning("BurtRP screen probe adaptive placement compute shader missing kernel: " + ScreenProbeAdaptivePlacementKernelName);
                    hasLoggedMissingScreenProbeAdaptivePlacementKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeIndirectArgsSetupPass : BurtRenderPass
    {
        private const string ScreenProbeIndirectArgsComputeShaderResourcePath = "BurtGIScreenProbeIndirectArgs";
        private const string ScreenProbeIndirectArgsKernelName = "ScreenProbeIndirectArgsSetupCS";
        private const int DispatchThreadGroupSize = 64;
        private static readonly int BurtGIScreenProbeGridParamsId = Shader.PropertyToID("_BurtGIScreenProbeGridParams");
        private static readonly int BurtGIScreenProbeIndirectArgsParamsId = Shader.PropertyToID("_BurtGIScreenProbeIndirectArgsParams");
        private static readonly int BurtGIScreenProbeAdaptiveParamsId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveParams");
        private static readonly int BurtGIScreenProbeTraceCompactGroupSizeId = Shader.PropertyToID("_BurtGIScreenProbeTraceCompactGroupSize");
        private static readonly int BurtGIScreenProbeIndirectArgsBufferId = Shader.PropertyToID("_BurtGIScreenProbeIndirectArgsBuffer");
        private static readonly int BurtGIScreenProbeAdaptiveProbeNumBufferId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeNumBuffer");
        private static ComputeShader screenProbeIndirectArgsComputeShader;
        private static bool hasLoggedMissingScreenProbeIndirectArgsComputeShader;
        private static bool hasLoggedMissingScreenProbeIndirectArgsKernel;

        public override string Name => "Burt ScreenProbe Indirect Args Setup";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGIScreenProbeAdaptiveProbeNumBuffer();
            builder.ReadBurtGIScreenProbeAdaptiveProbeDataBuffer();
            builder.WriteBurtGIScreenProbeIndirectArgsBuffer();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(context.Request, context.Asset))
            {
                return;
            }

            var buffer = context.BurtGIScreenProbeIndirectArgsBuffer;
            if (!buffer.HasBuffer)
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            if (TryExecuteGpuIndirectArgsSetup(context, buffer, settings, descriptor))
            {
                return;
            }

            ExecuteCpuFallback(buffer, settings, descriptor);
        }

        private void ExecuteCpuFallback(
            BurtRenderBufferHandle buffer,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            RenderTextureDescriptor descriptor)
        {
            var probeCount = Mathf.Max(1, descriptor.width * descriptor.height);
            var tracingResolution = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(settings);
            var gatherResolution = tracingResolution;
            var gatherResolutionWithBorder = gatherResolution + 2;
            var lightSampleResolutionXY = 2;
            var args = new uint[(int)BurtScreenProbeIndirectArgsType.Count * 3];

            SetDispatchArgs(args, BurtScreenProbeIndirectArgsType.GroupPerProbe, probeCount, 1);
            SetDispatchArgs(args, BurtScreenProbeIndirectArgsType.ThreadPerProbe, probeCount, DispatchThreadGroupSize);
            SetDispatchArgs(args, BurtScreenProbeIndirectArgsType.ThreadPerTrace, probeCount * tracingResolution * tracingResolution, DispatchThreadGroupSize);
            SetDispatchArgs(args, BurtScreenProbeIndirectArgsType.ThreadPerGather, probeCount * gatherResolution * gatherResolution, DispatchThreadGroupSize);
            SetDispatchArgs(args, BurtScreenProbeIndirectArgsType.ThreadPerGatherWithBorder, probeCount * gatherResolutionWithBorder * gatherResolutionWithBorder, DispatchThreadGroupSize);
            SetDispatchArgs(args, BurtScreenProbeIndirectArgsType.ThreadPerLightSample, probeCount * lightSampleResolutionXY * lightSampleResolutionXY, DispatchThreadGroupSize);
            buffer.Buffer.SetData(args);
        }

        private bool TryExecuteGpuIndirectArgsSetup(
            BurtRenderGraphContext context,
            BurtRenderBufferHandle buffer,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            RenderTextureDescriptor descriptor)
        {
            if (!context.BurtGIScreenProbeAdaptiveProbeNumBuffer.HasBuffer ||
                !context.BurtGIScreenProbeAdaptiveProbeDataBuffer.HasBuffer)
            {
                return false;
            }

            var shader = GetScreenProbeIndirectArgsComputeShader();
            if (!TryFindScreenProbeIndirectArgsKernel(shader, out var kernel))
            {
                return false;
            }

            var screenProbeWidth = Mathf.Max(1, descriptor.width);
            var screenProbeHeight = Mathf.Max(1, descriptor.height);
            var traceResolution = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(settings);
            var gatherResolution = traceResolution;
            var gatherResolutionWithBorder = gatherResolution + 2;
            var lightSampleResolutionXY = 2;
            var maxAdaptiveProbes = Mathf.Max(1, context.BurtGIScreenProbeAdaptiveProbeDataBuffer.Buffer.count);

            var cmd = context.AcquireCommandBuffer(Name + " Compute");
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(
                screenProbeWidth,
                screenProbeHeight,
                1f / screenProbeWidth,
                1f / screenProbeHeight));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeIndirectArgsParamsId, new Vector4(
                traceResolution,
                gatherResolution,
                gatherResolutionWithBorder,
                lightSampleResolutionXY));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeAdaptiveParamsId, new Vector4(
                screenProbeWidth,
                screenProbeHeight,
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeAdaptiveProbeIndexTileCapacity(settings),
                maxAdaptiveProbes));
            cmd.SetComputeIntParam(shader, BurtGIScreenProbeTraceCompactGroupSizeId, DispatchThreadGroupSize);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeIndirectArgsBufferId, buffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeNumBufferId, context.BurtGIScreenProbeAdaptiveProbeNumBuffer.Buffer);
            cmd.DispatchCompute(shader, kernel, 1, 1, 1);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static ComputeShader GetScreenProbeIndirectArgsComputeShader()
        {
            if (screenProbeIndirectArgsComputeShader != null)
            {
                return screenProbeIndirectArgsComputeShader;
            }

            screenProbeIndirectArgsComputeShader = Resources.Load<ComputeShader>(ScreenProbeIndirectArgsComputeShaderResourcePath);
            if (screenProbeIndirectArgsComputeShader == null && !hasLoggedMissingScreenProbeIndirectArgsComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ScreenProbeIndirectArgsComputeShaderResourcePath);
                hasLoggedMissingScreenProbeIndirectArgsComputeShader = true;
            }

            return screenProbeIndirectArgsComputeShader;
        }

        private static bool TryFindScreenProbeIndirectArgsKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(ScreenProbeIndirectArgsKernelName))
            {
                if (!hasLoggedMissingScreenProbeIndirectArgsKernel)
                {
                    Debug.LogWarning("BurtRP screen probe indirect args compute shader missing kernel: " + ScreenProbeIndirectArgsKernelName);
                    hasLoggedMissingScreenProbeIndirectArgsKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(ScreenProbeIndirectArgsKernelName);
            return kernel >= 0;
        }

        private static void SetDispatchArgs(uint[] args, BurtScreenProbeIndirectArgsType type, int workItemCount, int threadGroupSize)
        {
            var offset = (int)type * 3;
            args[offset] = DivRoundUp(Mathf.Max(1, workItemCount), Mathf.Max(1, threadGroupSize));
            args[offset + 1] = 1u;
            args[offset + 2] = 1u;
        }

        private static uint DivRoundUp(int value, int divisor)
        {
            return (uint)((value + divisor - 1) / divisor);
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassificationMarkPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string ComputeShaderResourcePath = "BurtGIScreenProbeIntegrateTileClassification";
        private const string KernelName = "ScreenProbeIntegrateClassificationMarkCS";
        private static readonly uint[] EmptyIndirectArgs =
        {
            0u, 1u, 1u,
            0u, 1u, 1u
        };

        private static readonly int BurtGIScreenProbeIntegrateTileParamsId = Shader.PropertyToID("_BurtGIScreenProbeIntegrateTileParams");
        private static ComputeShader computeShader;
        private static bool hasLoggedMissingComputeShader;
        private static bool hasLoggedMissingKernel;

        public override string Name => "Burt ScreenProbe Integrate Tile Classification Mark";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!ShouldRun(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadGBuffer2();
            builder.ReadGBuffer3();
            builder.WriteBurtGIScreenProbeIntegrateTileIndirectArgsBuffer();
            builder.WriteBurtGIScreenProbeIntegrateTileDataDiffuseBuffer();
            builder.WriteBurtGIScreenProbeIntegrateTileDataAllBuffer();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !ShouldRun(context.Request, context.Asset))
            {
                return;
            }

            var indirectArgsBuffer = context.BurtGIScreenProbeIntegrateTileIndirectArgsBuffer;
            var tileDataDiffuseBuffer = context.BurtGIScreenProbeIntegrateTileDataDiffuseBuffer;
            var tileDataAllBuffer = context.BurtGIScreenProbeIntegrateTileDataAllBuffer;
            if (!indirectArgsBuffer.HasBuffer || !tileDataDiffuseBuffer.HasBuffer || !tileDataAllBuffer.HasBuffer)
            {
                return;
            }

            indirectArgsBuffer.Buffer.SetData(EmptyIndirectArgs);
            var shader = GetComputeShader();
            if (!TryFindKernel(shader, out var kernel) ||
                !HasInputs(context))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            var tileSize = Mathf.Max(1, BurtScreenSpaceGlobalIlluminationPassUtility.ScreenProbeIntegrateTileSize);
            var groupsX = Mathf.Max(1, (width + tileSize - 1) / tileSize);
            var groupsY = Mathf.Max(1, (height + tileSize - 1) / tileSize);

            var cmd = context.AcquireCommandBuffer(Name + " Compute");
            cmd.SetComputeTextureParam(shader, kernel, CameraDepthTextureId, context.CameraDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer0Id, context.GBuffer0Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer2Id, context.GBuffer2Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer3Id, context.GBuffer3Target.Identifier);
            cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileIndirectArgsBufferId, indirectArgsBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileDataDiffuseBufferId, tileDataDiffuseBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileDataAllBufferId, tileDataAllBuffer.Buffer);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeIntegrateTileParamsId, new Vector4(
                width,
                height,
                settings.EnableRoughSpecular ? 1f : 0f,
                settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular));
            cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool ShouldRun(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            return BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassification(request, asset);
        }

        private static bool HasInputs(BurtRenderGraphContext context)
        {
            return context.CameraDepthTarget.IsValid &&
                context.GBuffer0Target.IsValid &&
                context.GBuffer2Target.IsValid &&
                context.GBuffer3Target.IsValid;
        }

        private static ComputeShader GetComputeShader()
        {
            if (computeShader != null)
            {
                return computeShader;
            }

            computeShader = Resources.Load<ComputeShader>(ComputeShaderResourcePath);
            if (computeShader == null && !hasLoggedMissingComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ComputeShaderResourcePath);
                hasLoggedMissingComputeShader = true;
            }

            return computeShader;
        }

        private static bool TryFindKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(KernelName))
            {
                if (!hasLoggedMissingKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + KernelName + " in " + ComputeShaderResourcePath);
                    hasLoggedMissingKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(KernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassificationVisualizePass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string ComputeShaderResourcePath = "BurtGIScreenProbeIntegrateTileClassification";
        private const string DiffuseKernelName = "ScreenProbeIntegrateClassificationVisualizeDiffuseCS";
        private const string AllKernelName = "ScreenProbeIntegrateClassificationVisualizeAllCS";
        private const uint DiffuseIndirectArgsOffset = 0u;
        private const uint AllIndirectArgsOffset = 12u;
        private static readonly int BurtGIScreenProbeIntegrateTileParamsId = Shader.PropertyToID("_BurtGIScreenProbeIntegrateTileParams");
        private static ComputeShader computeShader;
        private static bool hasLoggedMissingComputeShader;
        private static bool hasLoggedMissingDiffuseKernel;
        private static bool hasLoggedMissingAllKernel;

        public override string Name => "Burt ScreenProbe Integrate Tile Classification Visualize";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassification(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGIScreenProbeIntegrateTileIndirectArgsBuffer();
            builder.ReadBurtGIScreenProbeIntegrateTileDataDiffuseBuffer();
            builder.ReadBurtGIScreenProbeIntegrateTileDataAllBuffer();
            builder.WriteBurtGIScreenProbeIntegrateTileClassification();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassification(context.Request, context.Asset))
            {
                return;
            }

            var indirectArgsBuffer = context.BurtGIScreenProbeIntegrateTileIndirectArgsBuffer;
            var tileDataDiffuseBuffer = context.BurtGIScreenProbeIntegrateTileDataDiffuseBuffer;
            var tileDataAllBuffer = context.BurtGIScreenProbeIntegrateTileDataAllBuffer;
            var classificationTarget = context.BurtGIScreenProbeIntegrateTileClassificationTarget;
            if (!indirectArgsBuffer.HasBuffer ||
                !tileDataDiffuseBuffer.HasBuffer ||
                !tileDataAllBuffer.HasBuffer ||
                !classificationTarget.IsValid)
            {
                return;
            }

            var shader = GetComputeShader();
            if (!TryFindKernel(shader, DiffuseKernelName, ref hasLoggedMissingDiffuseKernel, out var diffuseKernel) ||
                !TryFindKernel(shader, AllKernelName, ref hasLoggedMissingAllKernel, out var allKernel))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassificationDescriptor(camera, settings);
            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            var paramsValue = new Vector4(
                width,
                height,
                settings.EnableRoughSpecular ? 1f : 0f,
                settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular);

            var cmd = context.AcquireCommandBuffer(Name + " Compute");
            cmd.SetRenderTarget(classificationTarget.Identifier);
            cmd.ClearRenderTarget(false, true, Color.clear);
            BindKernel(cmd, shader, diffuseKernel, classificationTarget, tileDataDiffuseBuffer, tileDataAllBuffer, paramsValue);
            BindKernel(cmd, shader, allKernel, classificationTarget, tileDataDiffuseBuffer, tileDataAllBuffer, paramsValue);
            cmd.DispatchCompute(shader, diffuseKernel, indirectArgsBuffer.Buffer, DiffuseIndirectArgsOffset);
            cmd.DispatchCompute(shader, allKernel, indirectArgsBuffer.Buffer, AllIndirectArgsOffset);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static void BindKernel(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderTargetHandle classificationTarget,
            BurtRenderBufferHandle tileDataDiffuseBuffer,
            BurtRenderBufferHandle tileDataAllBuffer,
            Vector4 paramsValue)
        {
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileClassificationTextureId, classificationTarget.Identifier);
            cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileDataDiffuseBufferId, tileDataDiffuseBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileDataAllBufferId, tileDataAllBuffer.Buffer);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeIntegrateTileParamsId, paramsValue);
        }

        private static ComputeShader GetComputeShader()
        {
            if (computeShader != null)
            {
                return computeShader;
            }

            computeShader = Resources.Load<ComputeShader>(ComputeShaderResourcePath);
            if (computeShader == null && !hasLoggedMissingComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ComputeShaderResourcePath);
                hasLoggedMissingComputeShader = true;
            }

            return computeShader;
        }

        private static bool TryFindKernel(ComputeShader shader, string kernelName, ref bool hasLoggedMissingKernel, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + kernelName + " in " + ComputeShaderResourcePath);
                    hasLoggedMissingKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeIntegrateSimpleSHPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string ComputeShaderResourcePath = "BurtGIScreenProbeIntegrateSimpleSH";
        private const string DirectKernelName = "ScreenProbeIntegrateSimpleSHCS";
        private const string DiffuseKernelName = "ScreenProbeIntegrateSimpleSHDiffuseCS";
        private const string AllKernelName = "ScreenProbeIntegrateSimpleSHAllCS";
        private const uint DiffuseIndirectArgsOffset = 0u;
        private const uint AllIndirectArgsOffset = 12u;
        private static readonly int BurtGIScreenProbeIntegrateSimpleSHParamsId = Shader.PropertyToID("_BurtGIScreenProbeIntegrateSimpleSHParams");
        private static readonly int BurtGIScreenProbeIntegrateSimpleSHParams1Id = Shader.PropertyToID("_BurtGIScreenProbeIntegrateSimpleSHParams1");
        private static ComputeShader computeShader;
        private static bool hasLoggedMissingComputeShader;
        private static bool hasLoggedMissingDirectKernel;
        private static bool hasLoggedMissingDiffuseKernel;
        private static bool hasLoggedMissingAllKernel;

        public override string Name => "Burt ScreenProbe Integrate SimpleSH";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!ShouldRun(builder.Request, builder.Asset))
            {
                return;
            }

            builder.WriteScreenSpaceGlobalIllumination();
            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadGBuffer1();
            builder.ReadGBuffer2();
            builder.ReadGBuffer3();
            builder.ReadBurtGIScreenProbeHitDistance();
            builder.ReadBurtGIScreenProbeBentNormal();
            builder.ReadBurtGIScreenProbeWorldNormal();
            builder.ReadBurtGIScreenProbeWorldPosition();
            builder.ReadBurtGIScreenProbeIrradianceOct();
            builder.ReadBurtGIScreenProbeRadianceOct();
            builder.ReadBurtGIScreenProbeRadianceSHAmbient();
            builder.ReadBurtGIScreenProbeRadianceSHDirectional();
            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassification(builder.Request, builder.Asset))
            {
                builder.ReadBurtGIScreenProbeIntegrateTileIndirectArgsBuffer();
                builder.ReadBurtGIScreenProbeIntegrateTileDataDiffuseBuffer();
                builder.ReadBurtGIScreenProbeIntegrateTileDataAllBuffer();
            }
            builder.WriteBurtGIBackfaceDiffuseIndirect();
            builder.WriteBurtGIRoughSpecularIndirect();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !ShouldRun(context.Request, context.Asset))
            {
                return;
            }

            var burtGITarget = context.ScreenSpaceGlobalIlluminationTarget;
            var cameraDepthTarget = context.CameraDepthTarget;
            var gbuffer0Target = context.GBuffer0Target;
            var gbuffer1Target = context.GBuffer1Target;
            var gbuffer2Target = context.GBuffer2Target;
            var gbuffer3Target = context.GBuffer3Target;
            var hitDistanceTarget = context.BurtGIScreenProbeHitDistanceTarget;
            var bentNormalTarget = context.BurtGIScreenProbeBentNormalTarget;
            var worldNormalTarget = context.BurtGIScreenProbeWorldNormalTarget;
            var worldPositionTarget = context.BurtGIScreenProbeWorldPositionTarget;
            var irradianceOctTarget = context.BurtGIScreenProbeIrradianceOctTarget;
            var radianceOctTarget = context.BurtGIScreenProbeRadianceOctTarget;
            var radianceSHAmbientTarget = context.BurtGIScreenProbeRadianceSHAmbientTarget;
            var radianceSHDirectionalTarget = context.BurtGIScreenProbeRadianceSHDirectionalTarget;
            var backfaceDiffuseTarget = context.BurtGIBackfaceDiffuseIndirectTarget;
            var roughSpecularTarget = context.BurtGIRoughSpecularIndirectTarget;
            var indirectArgsBuffer = context.BurtGIScreenProbeIntegrateTileIndirectArgsBuffer;
            var tileDataDiffuseBuffer = context.BurtGIScreenProbeIntegrateTileDataDiffuseBuffer;
            var tileDataAllBuffer = context.BurtGIScreenProbeIntegrateTileDataAllBuffer;
            var useTileClassification = BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassification(context.Request, context.Asset);
            if (!burtGITarget.IsValid ||
                !cameraDepthTarget.IsValid ||
                !gbuffer0Target.IsValid ||
                !gbuffer1Target.IsValid ||
                !gbuffer2Target.IsValid ||
                !gbuffer3Target.IsValid ||
                !hitDistanceTarget.IsValid ||
                !bentNormalTarget.IsValid ||
                !worldNormalTarget.IsValid ||
                !worldPositionTarget.IsValid ||
                !irradianceOctTarget.IsValid ||
                !radianceOctTarget.IsValid ||
                !radianceSHAmbientTarget.IsValid ||
                !radianceSHDirectionalTarget.IsValid ||
                !backfaceDiffuseTarget.IsValid ||
                !roughSpecularTarget.IsValid ||
                (useTileClassification &&
                    (!indirectArgsBuffer.HasBuffer ||
                     !tileDataDiffuseBuffer.HasBuffer ||
                     !tileDataAllBuffer.HasBuffer)))
            {
                return;
            }

            var shader = GetComputeShader();
            var directKernel = -1;
            var diffuseKernel = -1;
            var allKernel = -1;
            if (useTileClassification
                ? (!TryFindKernel(shader, DiffuseKernelName, ref hasLoggedMissingDiffuseKernel, out diffuseKernel) ||
                   !TryFindKernel(shader, AllKernelName, ref hasLoggedMissingAllKernel, out allKernel))
                : !TryFindKernel(shader, DirectKernelName, ref hasLoggedMissingDirectKernel, out directKernel))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var camera = context.Request != null ? context.Request.Camera : null;
            if (camera == null)
            {
                return;
            }

            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var probeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
            var screenProbeWidth = Mathf.Max(1, probeDescriptor.width);
            var screenProbeHeight = Mathf.Max(1, probeDescriptor.height);
            var irradianceOctDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeIrradianceOctDescriptor(camera, screenProbeSettings);
            var atlasProbeHeight = Mathf.Max(
                screenProbeHeight,
                irradianceOctDescriptor.height / BurtScreenSpaceGlobalIlluminationPassUtility.ScreenProbeIrradianceOctResolutionWithBorder);
            var temporalAA = context.Request != null ? context.Request.TemporalAA : null;
            var useTemporalAA = temporalAA != null && temporalAA.Enabled;
            var viewMatrix = useTemporalAA ? temporalAA.ViewMatrix : camera.worldToCameraMatrix;
            var viewProjectionMatrix = useTemporalAA
                ? temporalAA.CurrentViewProjectionMatrix
                : GL.GetGPUProjectionMatrix(camera.projectionMatrix, true) * viewMatrix;
            var inverseViewProjectionMatrix = useTemporalAA
                ? temporalAA.InverseCurrentViewProjectionMatrix
                : viewProjectionMatrix.inverse;
            var cameraPosition = camera.transform.position;
            var paramsValue = new Vector4(
                Mathf.Max(1, descriptor.width),
                Mathf.Max(1, descriptor.height),
                settings.EnableRoughSpecular ? 1f : 0f,
                settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular);
            var params1Value = new Vector4(
                settings.EnableBackfaceDiffuse ? 1f : 0f,
                screenProbeSettings.TraceDistance,
                settings.ShortRangeAO ? settings.ShortRangeAOWeight : 0f,
                screenProbeSettings.IrradianceFormat == ScreenProbeIrradianceFormat.Octahedral ? 1f : 0f);

            var cmd = context.AcquireCommandBuffer(Name + " Compute");
            cmd.SetRenderTarget(
                new[]
                {
                    burtGITarget.Identifier,
                    backfaceDiffuseTarget.Identifier,
                    roughSpecularTarget.Identifier,
                },
                new RenderTargetIdentifier(BuiltinRenderTextureType.None));
            cmd.ClearRenderTarget(false, true, Color.clear);
            if (useTileClassification)
            {
                BindKernel(cmd, shader, diffuseKernel, cameraDepthTarget, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, burtGITarget, hitDistanceTarget, bentNormalTarget, worldNormalTarget, worldPositionTarget, irradianceOctTarget, radianceOctTarget, radianceSHAmbientTarget, radianceSHDirectionalTarget, backfaceDiffuseTarget, roughSpecularTarget, tileDataDiffuseBuffer, tileDataAllBuffer, paramsValue, params1Value, descriptor, screenProbeSettings, screenProbeWidth, screenProbeHeight, atlasProbeHeight, inverseViewProjectionMatrix, cameraPosition);
                BindKernel(cmd, shader, allKernel, cameraDepthTarget, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, burtGITarget, hitDistanceTarget, bentNormalTarget, worldNormalTarget, worldPositionTarget, irradianceOctTarget, radianceOctTarget, radianceSHAmbientTarget, radianceSHDirectionalTarget, backfaceDiffuseTarget, roughSpecularTarget, tileDataDiffuseBuffer, tileDataAllBuffer, paramsValue, params1Value, descriptor, screenProbeSettings, screenProbeWidth, screenProbeHeight, atlasProbeHeight, inverseViewProjectionMatrix, cameraPosition);
                cmd.DispatchCompute(shader, diffuseKernel, indirectArgsBuffer.Buffer, DiffuseIndirectArgsOffset);
                cmd.DispatchCompute(shader, allKernel, indirectArgsBuffer.Buffer, AllIndirectArgsOffset);
            }
            else
            {
                BindKernel(cmd, shader, directKernel, cameraDepthTarget, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, burtGITarget, hitDistanceTarget, bentNormalTarget, worldNormalTarget, worldPositionTarget, irradianceOctTarget, radianceOctTarget, radianceSHAmbientTarget, radianceSHDirectionalTarget, backfaceDiffuseTarget, roughSpecularTarget, tileDataDiffuseBuffer, tileDataAllBuffer, paramsValue, params1Value, descriptor, screenProbeSettings, screenProbeWidth, screenProbeHeight, atlasProbeHeight, inverseViewProjectionMatrix, cameraPosition);
                var threadGroupSize = Mathf.Max(1, BurtScreenSpaceGlobalIlluminationPassUtility.ScreenProbeIntegrateTileSize);
                cmd.DispatchCompute(
                    shader,
                    directKernel,
                    Mathf.Max(1, (descriptor.width + threadGroupSize - 1) / threadGroupSize),
                    Mathf.Max(1, (descriptor.height + threadGroupSize - 1) / threadGroupSize),
                    1);
            }
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool ShouldRun(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            return BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(request, asset);
        }

        private static void BindKernel(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderTargetHandle cameraDepthTarget,
            BurtRenderTargetHandle gbuffer0Target,
            BurtRenderTargetHandle gbuffer1Target,
            BurtRenderTargetHandle gbuffer2Target,
            BurtRenderTargetHandle gbuffer3Target,
            BurtRenderTargetHandle burtGITarget,
            BurtRenderTargetHandle hitDistanceTarget,
            BurtRenderTargetHandle bentNormalTarget,
            BurtRenderTargetHandle worldNormalTarget,
            BurtRenderTargetHandle worldPositionTarget,
            BurtRenderTargetHandle irradianceOctTarget,
            BurtRenderTargetHandle radianceOctTarget,
            BurtRenderTargetHandle radianceSHAmbientTarget,
            BurtRenderTargetHandle radianceSHDirectionalTarget,
            BurtRenderTargetHandle backfaceDiffuseTarget,
            BurtRenderTargetHandle roughSpecularTarget,
            BurtRenderBufferHandle tileDataDiffuseBuffer,
            BurtRenderBufferHandle tileDataAllBuffer,
            Vector4 paramsValue,
            Vector4 params1Value,
            RenderTextureDescriptor sourceDescriptor,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            int screenProbeWidth,
            int screenProbeHeight,
            int atlasProbeHeight,
            Matrix4x4 inverseViewProjectionMatrix,
            Vector3 cameraPosition)
        {
            cmd.SetComputeTextureParam(shader, kernel, CameraDepthTextureId, cameraDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer0Id, gbuffer0Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer1Id, gbuffer1Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer2Id, gbuffer2Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer3Id, gbuffer3Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationTextureId, burtGITarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeHitDistanceTextureId, hitDistanceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeBentNormalTextureId, bentNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalTextureId, worldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIrradianceOctTextureId, irradianceOctTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeRadianceOctTextureId, radianceOctTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeRadianceSHAmbientTextureId, radianceSHAmbientTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeRadianceSHDirectionalTextureId, radianceSHDirectionalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectTextureId, backfaceDiffuseTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectTextureId, roughSpecularTarget.Identifier);
            if (tileDataDiffuseBuffer.HasBuffer && tileDataAllBuffer.HasBuffer)
            {
                cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileDataDiffuseBufferId, tileDataDiffuseBuffer.Buffer);
                cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeIntegrateTileDataAllBufferId, tileDataAllBuffer.Buffer);
            }
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeIntegrateSimpleSHParamsId, paramsValue);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeIntegrateSimpleSHParams1Id, params1Value);
            cmd.SetComputeVectorParam(shader, BurtGISourceTexelSizeId, new Vector4(
                1f / Mathf.Max(1, sourceDescriptor.width),
                1f / Mathf.Max(1, sourceDescriptor.height),
                Mathf.Max(1, sourceDescriptor.width),
                Mathf.Max(1, sourceDescriptor.height)));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeParamsId, new Vector4(
                screenProbeSettings.SpacingPixels,
                screenProbeSettings.TraceDistance,
                screenProbeSettings.SampleCount,
                screenProbeSettings.ApplyStrength));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(
                screenProbeWidth,
                screenProbeHeight,
                1f / screenProbeWidth,
                1f / screenProbeHeight));
            var traceResolution = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsGlobalId, new Vector4(
                traceResolution,
                screenProbeWidth * traceResolution,
                atlasProbeHeight * traceResolution,
                screenProbeSettings.TraceDistance));
            cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, inverseViewProjectionMatrix);
            cmd.SetComputeVectorParam(shader, CameraWorldPositionId, new Vector4(cameraPosition.x, cameraPosition.y, cameraPosition.z, 1f));
        }

        private static ComputeShader GetComputeShader()
        {
            if (computeShader != null)
            {
                return computeShader;
            }

            computeShader = Resources.Load<ComputeShader>(ComputeShaderResourcePath);
            if (computeShader == null && !hasLoggedMissingComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ComputeShaderResourcePath);
                hasLoggedMissingComputeShader = true;
            }

            return computeShader;
        }

        private static bool TryFindKernel(ComputeShader shader, string kernelName, ref bool hasLoggedMissingKernel, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + kernelName + " in " + ComputeShaderResourcePath);
                    hasLoggedMissingKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeIntegrateSimpleSHHistoryCopyPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string ComputeShaderResourcePath = "BurtGIScreenProbeIndirectReprojection";
        private const string KernelName = "ScreenProbeIndirectReprojectionCS";
        private const string SceneVelocityKernelName = "ScreenProbeIndirectSceneVelocityCS";
        private const string ClearUseCountKernelName = "ScreenProbeIndirectUseCountClearCS";
        private const string ScatterUseCountKernelName = "ScreenProbeIndirectUseCountScatterCS";
        private const int ThreadGroupSize = 8;
        private const int CopyDepthNormalPassIndex = 5;
        private static readonly int BurtGIIndirectHistoryDepthNormalTextureId = Shader.PropertyToID("_BurtGIIndirectHistoryDepthNormalTexture");
        private static readonly int BurtGIDiffuseIndirectCurrentTextureId = Shader.PropertyToID("_BurtGIDiffuseIndirectCurrentTexture");
        private static readonly int BurtGIBackfaceDiffuseIndirectCurrentTextureId = Shader.PropertyToID("_BurtGIBackfaceDiffuseIndirectCurrentTexture");
        private static readonly int BurtGIRoughSpecularIndirectCurrentTextureId = Shader.PropertyToID("_BurtGIRoughSpecularIndirectCurrentTexture");
        private static readonly int BurtGIDiffuseIndirectHistoryTextureId = Shader.PropertyToID("_BurtGIDiffuseIndirectHistoryTexture");
        private static readonly int BurtGIBackfaceDiffuseIndirectHistoryTextureId = Shader.PropertyToID("_BurtGIBackfaceDiffuseIndirectHistoryTexture");
        private static readonly int BurtGIRoughSpecularIndirectHistoryTextureId = Shader.PropertyToID("_BurtGIRoughSpecularIndirectHistoryTexture");
        private static readonly int BurtGIHistoryDepthNormalTextureId = Shader.PropertyToID("_BurtGIHistoryDepthNormalTexture");
        private static readonly int BurtGIIndirectNumFramesAccumulatedHistoryTextureId = Shader.PropertyToID("_BurtGIIndirectNumFramesAccumulatedHistoryTexture");
        private static readonly int BurtGIIndirectUseCountReadTextureId = Shader.PropertyToID("_BurtGIIndirectUseCountReadTexture");
        private static readonly int BurtGIIndirectUseCountTextureId = Shader.PropertyToID("_BurtGIIndirectUseCountTexture");
        private static readonly int BurtGIScreenProbeSceneVelocityTextureId = Shader.PropertyToID("_BurtGIScreenProbeSceneVelocityTexture");
        private static readonly int BurtGIScreenProbeSceneVelocityOutputTextureId = Shader.PropertyToID("_BurtGIScreenProbeSceneVelocityOutputTexture");
        private static readonly int BurtGIDiffuseIndirectOutputTextureId = Shader.PropertyToID("_BurtGIDiffuseIndirectOutputTexture");
        private static readonly int BurtGIBackfaceDiffuseIndirectOutputTextureId = Shader.PropertyToID("_BurtGIBackfaceDiffuseIndirectOutputTexture");
        private static readonly int BurtGIRoughSpecularIndirectOutputTextureId = Shader.PropertyToID("_BurtGIRoughSpecularIndirectOutputTexture");
        private static readonly int BurtGIIndirectNumFramesAccumulatedOutputTextureId = Shader.PropertyToID("_BurtGIIndirectNumFramesAccumulatedOutputTexture");
        private static readonly int BurtGIIndirectReprojectionParamsId = Shader.PropertyToID("_BurtGIIndirectReprojectionParams");
        private static readonly int BurtGIIndirectReprojectionParams1Id = Shader.PropertyToID("_BurtGIIndirectReprojectionParams1");
        private static readonly int BurtGIIndirectReprojectionParams2Id = Shader.PropertyToID("_BurtGIIndirectReprojectionParams2");
        private static readonly int BurtGIPreviousViewProjectionMatrixId = Shader.PropertyToID("_BurtGIPreviousViewProjectionMatrix");
        private static ComputeShader computeShader;
        private static bool hasLoggedMissingComputeShader;
        private static bool hasLoggedMissingReprojectionKernel;
        private static bool hasLoggedMissingSceneVelocityKernel;
        private static bool hasLoggedMissingClearUseCountKernel;
        private static bool hasLoggedMissingScatterUseCountKernel;

        public override string Name => "Burt ScreenProbe Integrate SimpleSH Reprojection";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadScreenSpaceGlobalIllumination();
            builder.WriteScreenSpaceGlobalIllumination();
            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadGBuffer1();
            builder.ReadGBuffer2();
            builder.ReadGBuffer3();
            builder.ReadGBuffer4();
            builder.ReadGBuffer5();
            builder.ReadBurtGIBackfaceDiffuseIndirect();
            builder.WriteBurtGIBackfaceDiffuseIndirect();
            builder.ReadBurtGIRoughSpecularIndirect();
            builder.WriteBurtGIRoughSpecularIndirect();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(context.Request, context.Asset))
            {
                return;
            }

            if (!TryGetTargets(
                    context,
                    out var cameraDepthTarget,
                    out var gbuffer0Target,
                    out var gbuffer1Target,
                    out var gbuffer2Target,
                    out var gbuffer3Target,
                    out var gbuffer4Target,
                    out var gbuffer5Target,
                    out var diffuseTarget,
                    out var backfaceDiffuseTarget,
                    out var roughSpecularTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            if (!settings.Enabled || !settings.TemporalAccumulation)
            {
                return;
            }

            var shader = GetComputeShader();
            if (!TryFindKernel(shader, KernelName, ref hasLoggedMissingReprojectionKernel, out var kernel) ||
                !TryFindKernel(shader, SceneVelocityKernelName, ref hasLoggedMissingSceneVelocityKernel, out var sceneVelocityKernel) ||
                !TryFindKernel(shader, ClearUseCountKernelName, ref hasLoggedMissingClearUseCountKernel, out var clearUseCountKernel) ||
                !TryFindKernel(shader, ScatterUseCountKernelName, ref hasLoggedMissingScatterUseCountKernel, out var scatterUseCountKernel))
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            var camera = context.Request != null ? context.Request.Camera : null;
            if (material == null || camera == null)
            {
                return;
            }

            var history = BurtScreenSpaceGlobalIlluminationIndirectChannelHistoryUtility.EnsureHistoryTextures(context.Request, context.Asset, settings, out var historyValid);
            if (history.Diffuse == null ||
                history.BackfaceDiffuse == null ||
                history.RoughSpecular == null ||
                history.DepthNormal == null ||
                history.NumFramesAccumulated == null)
            {
                return;
            }

            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var outputDescriptor = descriptor;
            outputDescriptor.enableRandomWrite = true;
            outputDescriptor.depthBufferBits = 0;
            outputDescriptor.msaaSamples = 1;
            outputDescriptor.useMipMap = false;
            outputDescriptor.autoGenerateMips = false;
            outputDescriptor.sRGB = false;
            var numFramesDescriptor = outputDescriptor;
            numFramesDescriptor.colorFormat = RenderTextureFormat.RFloat;
            var useCountDescriptor = outputDescriptor;
            useCountDescriptor.colorFormat = RenderTextureFormat.Default;
            useCountDescriptor.graphicsFormat = GraphicsFormat.R32_UInt;
            var sceneVelocityDescriptor = outputDescriptor;
            var sceneVelocityFormat = ResolveSceneVelocityFormat();
            var sceneVelocityAllocated = sceneVelocityFormat != GraphicsFormat.None;
            if (sceneVelocityAllocated)
            {
                sceneVelocityDescriptor.colorFormat = RenderTextureFormat.Default;
                sceneVelocityDescriptor.graphicsFormat = sceneVelocityFormat;
            }

            var maxFramesAccumulated = ResolveMaxFramesAccumulated(settings);
            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            var groupsX = (width + ThreadGroupSize - 1) / ThreadGroupSize;
            var groupsY = (height + ThreadGroupSize - 1) / ThreadGroupSize;
            var useCountAllocated = SupportsIndirectUseCountTexture();
            var useCountValid = historyValid && useCountAllocated;
            var cmd = context.AcquireCommandBuffer(Name);
            cmd.GetTemporaryRT(BurtGIDiffuseIndirectOutputTextureId, outputDescriptor, FilterMode.Bilinear);
            cmd.GetTemporaryRT(BurtGIBackfaceDiffuseIndirectOutputTextureId, outputDescriptor, FilterMode.Bilinear);
            cmd.GetTemporaryRT(BurtGIRoughSpecularIndirectOutputTextureId, outputDescriptor, FilterMode.Bilinear);
            cmd.GetTemporaryRT(BurtGIIndirectNumFramesAccumulatedOutputTextureId, numFramesDescriptor, FilterMode.Point);
            if (sceneVelocityAllocated)
            {
                var sceneVelocityTarget = new RenderTargetIdentifier(BurtGIScreenProbeSceneVelocityOutputTextureId);
                cmd.GetTemporaryRT(BurtGIScreenProbeSceneVelocityOutputTextureId, sceneVelocityDescriptor, FilterMode.Point);
                cmd.SetComputeTextureParam(shader, sceneVelocityKernel, CameraDepthTextureId, cameraDepthTarget.Identifier);
                cmd.SetComputeTextureParam(shader, sceneVelocityKernel, BurtGIScreenProbeSceneVelocityOutputTextureId, sceneVelocityTarget);
                cmd.SetComputeVectorParam(shader, BurtGIIndirectReprojectionParamsId, new Vector4(width, height, historyValid ? 1f : 0f, maxFramesAccumulated));
                cmd.SetComputeVectorParam(shader, BurtGIIndirectReprojectionParams2Id, Vector4.zero);
                cmd.SetComputeMatrixParam(shader, BurtGIPreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
                cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, history.CurrentInverseViewProjectionMatrix);
                cmd.DispatchCompute(shader, sceneVelocityKernel, groupsX, groupsY, 1);

                BurtScreenSpaceGlobalIlluminationScreenProbeTemporalFilterPass.DrawScreenProbeObjectMotionVectors(
                    context,
                    cmd,
                    camera,
                    sceneVelocityTarget,
                    cameraDepthTarget,
                    history.PreviousViewProjectionMatrix,
                    width,
                    height);
            }

            if (useCountAllocated)
            {
                cmd.GetTemporaryRT(BurtGIIndirectUseCountTextureId, useCountDescriptor, FilterMode.Point);
                var useCountTarget = new RenderTargetIdentifier(BurtGIIndirectUseCountTextureId);
                cmd.SetComputeVectorParam(shader, BurtGIIndirectReprojectionParamsId, new Vector4(width, height, historyValid ? 1f : 0f, maxFramesAccumulated));
                cmd.SetComputeVectorParam(shader, BurtGIIndirectReprojectionParams2Id, new Vector4(sceneVelocityAllocated ? 1f : 0f, 0f, 0f, 0f));
                cmd.SetComputeMatrixParam(shader, BurtGIPreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
                cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, history.CurrentInverseViewProjectionMatrix);
                cmd.SetComputeTextureParam(shader, clearUseCountKernel, BurtGIIndirectUseCountTextureId, useCountTarget);
                cmd.DispatchCompute(shader, clearUseCountKernel, groupsX, groupsY, 1);
                if (historyValid)
                {
                    cmd.SetComputeTextureParam(shader, scatterUseCountKernel, CameraDepthTextureId, cameraDepthTarget.Identifier);
                    cmd.SetComputeTextureParam(shader, scatterUseCountKernel, BurtGIScreenProbeSceneVelocityTextureId, sceneVelocityAllocated ? new RenderTargetIdentifier(BurtGIScreenProbeSceneVelocityOutputTextureId) : new RenderTargetIdentifier(Texture2D.blackTexture));
                    cmd.SetComputeTextureParam(shader, scatterUseCountKernel, BurtGIIndirectUseCountTextureId, useCountTarget);
                    cmd.DispatchCompute(shader, scatterUseCountKernel, groupsX, groupsY, 1);
                }
            }

            cmd.SetComputeTextureParam(shader, kernel, CameraDepthTextureId, cameraDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer0Id, gbuffer0Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer2Id, gbuffer2Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIDiffuseIndirectCurrentTextureId, diffuseTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIBackfaceDiffuseIndirectCurrentTextureId, backfaceDiffuseTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRoughSpecularIndirectCurrentTextureId, roughSpecularTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIDiffuseIndirectHistoryTextureId, historyValid ? (Texture)history.Diffuse : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIBackfaceDiffuseIndirectHistoryTextureId, historyValid ? (Texture)history.BackfaceDiffuse : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRoughSpecularIndirectHistoryTextureId, historyValid ? (Texture)history.RoughSpecular : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIHistoryDepthNormalTextureId, historyValid ? (Texture)history.DepthNormal : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIIndirectNumFramesAccumulatedHistoryTextureId, historyValid ? (Texture)history.NumFramesAccumulated : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIIndirectUseCountReadTextureId, useCountAllocated ? new RenderTargetIdentifier(BurtGIIndirectUseCountTextureId) : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeSceneVelocityTextureId, sceneVelocityAllocated ? new RenderTargetIdentifier(BurtGIScreenProbeSceneVelocityOutputTextureId) : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIDiffuseIndirectOutputTextureId, new RenderTargetIdentifier(BurtGIDiffuseIndirectOutputTextureId));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIBackfaceDiffuseIndirectOutputTextureId, new RenderTargetIdentifier(BurtGIBackfaceDiffuseIndirectOutputTextureId));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRoughSpecularIndirectOutputTextureId, new RenderTargetIdentifier(BurtGIRoughSpecularIndirectOutputTextureId));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIIndirectNumFramesAccumulatedOutputTextureId, new RenderTargetIdentifier(BurtGIIndirectNumFramesAccumulatedOutputTextureId));
            cmd.SetComputeVectorParam(shader, BurtGIIndirectReprojectionParamsId, new Vector4(
                width,
                height,
                historyValid ? 1f : 0f,
                maxFramesAccumulated));
            cmd.SetComputeVectorParam(shader, BurtGIIndirectReprojectionParams1Id, new Vector4(
                settings.TemporalDepthRejection,
                settings.TemporalNormalRejection,
                history.HistoryExposureCorrection,
                useCountValid ? 1f : 0f));
            cmd.SetComputeVectorParam(shader, BurtGIIndirectReprojectionParams2Id, new Vector4(sceneVelocityAllocated ? 1f : 0f, 0f, 0f, 0f));
            cmd.SetComputeMatrixParam(shader, BurtGIPreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
            cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, history.CurrentInverseViewProjectionMatrix);
            cmd.DispatchCompute(
                shader,
                kernel,
                groupsX,
                groupsY,
                1);
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIDiffuseIndirectOutputTextureId), diffuseTarget.Identifier);
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIBackfaceDiffuseIndirectOutputTextureId), backfaceDiffuseTarget.Identifier);
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIRoughSpecularIndirectOutputTextureId), roughSpecularTarget.Identifier);
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIDiffuseIndirectOutputTextureId), new RenderTargetIdentifier(history.Diffuse));
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIBackfaceDiffuseIndirectOutputTextureId), new RenderTargetIdentifier(history.BackfaceDiffuse));
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIRoughSpecularIndirectOutputTextureId), new RenderTargetIdentifier(history.RoughSpecular));
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIIndirectNumFramesAccumulatedOutputTextureId), new RenderTargetIdentifier(history.NumFramesAccumulated));
            cmd.SetGlobalTexture(CameraDepthTextureId, cameraDepthTarget.Identifier);
            BindGBufferInputs(cmd, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, gbuffer4Target, gbuffer5Target);
            UploadCameraGlobals(cmd, context.Request, camera, descriptor);

            var depthNormalDescriptor = BurtScreenSpaceGlobalIlluminationHistoryUtility.CreateDepthNormalHistoryDescriptor(camera, settings);
            cmd.GetTemporaryRT(BurtGIIndirectHistoryDepthNormalTextureId, depthNormalDescriptor, FilterMode.Point);
            cmd.SetRenderTarget(new RenderTargetIdentifier(BurtGIIndirectHistoryDepthNormalTextureId));
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, descriptor.width, descriptor.height);
            cmd.DrawProcedural(Matrix4x4.identity, material, CopyDepthNormalPassIndex, MeshTopology.Triangles, 3, 1);
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIIndirectHistoryDepthNormalTextureId), new RenderTargetIdentifier(history.DepthNormal));
            cmd.ReleaseTemporaryRT(BurtGIIndirectHistoryDepthNormalTextureId);
            BurtScreenSpaceGlobalIlluminationIndirectChannelHistoryUtility.MarkHistoryValid(camera);
            cmd.ReleaseTemporaryRT(BurtGIDiffuseIndirectOutputTextureId);
            cmd.ReleaseTemporaryRT(BurtGIBackfaceDiffuseIndirectOutputTextureId);
            cmd.ReleaseTemporaryRT(BurtGIRoughSpecularIndirectOutputTextureId);
            cmd.ReleaseTemporaryRT(BurtGIIndirectNumFramesAccumulatedOutputTextureId);
            if (sceneVelocityAllocated)
            {
                cmd.ReleaseTemporaryRT(BurtGIScreenProbeSceneVelocityOutputTextureId);
            }

            if (useCountAllocated)
            {
                cmd.ReleaseTemporaryRT(BurtGIIndirectUseCountTextureId);
            }

            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static float ResolveMaxFramesAccumulated(BurtScreenSpaceGlobalIlluminationSettings settings)
        {
            return Mathf.Clamp(1f / Mathf.Max(1f - settings.TemporalFeedback, 0.02f), 1f, 50f);
        }

        private static bool SupportsIndirectUseCountTexture()
        {
            return SystemInfo.IsFormatSupported(GraphicsFormat.R32_UInt, FormatUsage.Render) &&
                SystemInfo.IsFormatSupported(GraphicsFormat.R32_UInt, FormatUsage.LoadStore);
        }

        private static GraphicsFormat ResolveSceneVelocityFormat()
        {
            if (SystemInfo.IsFormatSupported(GraphicsFormat.R16G16B16A16_SFloat, FormatUsage.Render) &&
                SystemInfo.IsFormatSupported(GraphicsFormat.R16G16B16A16_SFloat, FormatUsage.LoadStore))
            {
                return GraphicsFormat.R16G16B16A16_SFloat;
            }

            if (SystemInfo.IsFormatSupported(GraphicsFormat.R32G32B32A32_SFloat, FormatUsage.Render) &&
                SystemInfo.IsFormatSupported(GraphicsFormat.R32G32B32A32_SFloat, FormatUsage.LoadStore))
            {
                return GraphicsFormat.R32G32B32A32_SFloat;
            }

            return GraphicsFormat.None;
        }

        private static ComputeShader GetComputeShader()
        {
            if (computeShader != null)
            {
                return computeShader;
            }

            computeShader = Resources.Load<ComputeShader>(ComputeShaderResourcePath);
            if (computeShader == null && !hasLoggedMissingComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ComputeShaderResourcePath);
                hasLoggedMissingComputeShader = true;
            }

            return computeShader;
        }

        private static bool TryFindKernel(ComputeShader shader, string kernelName, ref bool hasLoggedMissingKernel, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + kernelName + " in " + ComputeShaderResourcePath);
                    hasLoggedMissingKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle cameraDepthTarget,
            out BurtRenderTargetHandle gbuffer0Target,
            out BurtRenderTargetHandle gbuffer1Target,
            out BurtRenderTargetHandle gbuffer2Target,
            out BurtRenderTargetHandle gbuffer3Target,
            out BurtRenderTargetHandle gbuffer4Target,
            out BurtRenderTargetHandle gbuffer5Target,
            out BurtRenderTargetHandle diffuseTarget,
            out BurtRenderTargetHandle backfaceDiffuseTarget,
            out BurtRenderTargetHandle roughSpecularTarget)
        {
            cameraDepthTarget = context != null ? context.CameraDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.CameraDepthName);
            gbuffer0Target = context != null ? context.GBuffer0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer0Name);
            gbuffer1Target = context != null ? context.GBuffer1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer1Name);
            gbuffer2Target = context != null ? context.GBuffer2Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer2Name);
            gbuffer3Target = context != null ? context.GBuffer3Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer3Name);
            gbuffer4Target = context != null ? context.GBuffer4Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer4Name);
            gbuffer5Target = context != null ? context.GBuffer5Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer5Name);
            diffuseTarget = context != null ? context.ScreenSpaceGlobalIlluminationTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationName);
            backfaceDiffuseTarget = context != null ? context.BurtGIBackfaceDiffuseIndirectTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectName);
            roughSpecularTarget = context != null ? context.BurtGIRoughSpecularIndirectTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectName);

            return cameraDepthTarget.IsValid &&
                gbuffer0Target.IsValid &&
                gbuffer1Target.IsValid &&
                gbuffer2Target.IsValid &&
                gbuffer3Target.IsValid &&
                gbuffer4Target.IsValid &&
                gbuffer5Target.IsValid &&
                diffuseTarget.IsValid &&
                backfaceDiffuseTarget.IsValid &&
                roughSpecularTarget.IsValid;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeTraceCompactSetupPass : BurtRenderPass
    {
        private const string ScreenProbeTraceCompactComputeShaderResourcePath = "BurtGIScreenProbeTraceCompactSetup";
        private const string ScreenProbeTraceCompactKernelName = "ScreenProbeTraceCompactCS";
        private const string ScreenProbeTraceGenArgsKernelName = "ScreenProbeTraceGenArgsCS";
        private const int ScreenProbeTraceCompactThreadGroupSize = 64;
        private const float ScreenProbeTraceCompactNoDistanceCull = 100000f;
        private const uint ScreenProbeIndirectArgsStrideBytes = 12u;
        private static readonly uint[] ZeroUint = { 0u };
        private static readonly uint[] ZeroDispatchArgs = { 0u, 1u, 1u };
        private static readonly int BurtGIScreenProbeScreenDepthTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthTextureId;
        private static readonly int BurtGIScreenProbeWorldNormalTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalTextureId;
        private static readonly int BurtGIScreenProbeWorldPositionTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionTextureId;
        private static readonly int BurtGIScreenProbeHitDistanceTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeHitDistanceTextureId;
        private static readonly int BurtGIScreenProbeHistoryWorldPositionTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryWorldPositionTexture");
        private static readonly int BurtGIScreenProbeHistoryTraceHitTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryTraceHitTexture");
        private static readonly int BurtGIScreenProbeGridParamsId = Shader.PropertyToID("_BurtGIScreenProbeGridParams");
        private static readonly int BurtGIScreenProbeAdaptiveParamsId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveParams");
        private static readonly int BurtGIScreenProbeAdaptiveProbeNumBufferId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeNumBuffer");
        private static readonly int BurtGIScreenProbeAdaptiveProbeDataBufferId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeDataBuffer");
        private static readonly int BurtGIScreenProbeTraceParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceParams");
        private static readonly int BurtGIScreenProbeTraceCompactParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceCompactParams");
        private static readonly int BurtGIScreenProbeTraceCompactGroupSizeId = Shader.PropertyToID("_BurtGIScreenProbeTraceCompactGroupSize");
        private static readonly int BurtDeferredCameraWorldPositionId = Shader.PropertyToID("_BurtDeferredCameraWorldPosition");
        private static readonly int BurtGIScreenProbeTraceCompactTexelCountBufferId = Shader.PropertyToID("_BurtGIScreenProbeTraceCompactTexelCountBuffer");
        private static readonly int BurtGIScreenProbeTraceCompactTexelDataBufferId = Shader.PropertyToID("_BurtGIScreenProbeTraceCompactTexelDataBuffer");
        private static readonly int BurtGIScreenProbeTraceCompactIndirectArgsBufferId = Shader.PropertyToID("_BurtGIScreenProbeTraceCompactIndirectArgsBuffer");
        private static readonly int BurtGIScreenProbeTraceCompactThreadCountXBufferId = Shader.PropertyToID("_BurtGIScreenProbeTraceCompactThreadCountXBuffer");
        private static ComputeShader screenProbeTraceCompactComputeShader;
        private static bool hasLoggedMissingScreenProbeTraceCompactComputeShader;
        private static bool hasLoggedMissingScreenProbeTraceCompactKernel;

        public override string Name => "Burt ScreenProbe Trace Compact Setup";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(builder.Request, builder.Asset);
            if (!settings.Enabled || !settings.TraceCompact ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.SupportsScreenProbeTraceCompactCompute())
            {
                return;
            }

            builder.ReadBurtGIScreenProbeScreenDepth();
            builder.ReadBurtGIScreenProbeWorldNormal();
            builder.ReadBurtGIScreenProbeWorldPosition();
            builder.ReadBurtGIScreenProbeHitDistance();
            builder.ReadBurtGIScreenProbeIndirectArgsBuffer();
            builder.ReadBurtGIScreenProbeAdaptiveProbeNumBuffer();
            builder.ReadBurtGIScreenProbeAdaptiveProbeDataBuffer();
            builder.WriteBurtGIScreenProbeTraceCompactTexelCountBuffer();
            builder.WriteBurtGIScreenProbeTraceCompactTexelDataBuffer();
            builder.WriteBurtGIScreenProbeTraceCompactIndirectArgsBuffer();
            builder.WriteBurtGIScreenProbeTraceCompactThreadCountXBuffer();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context != null ? context.Request : null, context != null ? context.Asset : null);
            if (context == null || !settings.Enabled || !settings.TraceCompact ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.SupportsScreenProbeTraceCompactCompute())
            {
                return;
            }

            var texelCountBuffer = context.BurtGIScreenProbeTraceCompactTexelCountBuffer;
            var texelDataBuffer = context.BurtGIScreenProbeTraceCompactTexelDataBuffer;
            var compactIndirectArgsBuffer = context.BurtGIScreenProbeTraceCompactIndirectArgsBuffer;
            var threadCountXBuffer = context.BurtGIScreenProbeTraceCompactThreadCountXBuffer;
            ClearCompactBuffers(texelCountBuffer, texelDataBuffer, compactIndirectArgsBuffer, threadCountXBuffer);

            if (!HasCompactInputs(context, texelCountBuffer, texelDataBuffer, compactIndirectArgsBuffer, threadCountXBuffer))
            {
                return;
            }

            var shader = GetScreenProbeTraceCompactComputeShader();
            if (!TryFindScreenProbeTraceCompactKernel(shader, ScreenProbeTraceCompactKernelName, out var compactKernel) ||
                !TryFindScreenProbeTraceCompactKernel(shader, ScreenProbeTraceGenArgsKernelName, out var genArgsKernel))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var probeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeTraceDescriptor(camera, settings);
            var screenProbeWidth = Mathf.Max(1, probeDescriptor.width);
            var screenProbeHeight = Mathf.Max(1, probeDescriptor.height);
            var traceWidth = Mathf.Max(1, traceDescriptor.width);
            var traceHeight = Mathf.Max(1, traceDescriptor.height);
            var traceTexelCount = Mathf.Max(1, traceWidth * traceHeight);
            var maxAdaptiveProbes = Mathf.Max(1, context.BurtGIScreenProbeAdaptiveProbeDataBuffer.Buffer.count);
            var screenProbeHistory = BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.GetHistoryTextures(context.Request, settings, out var screenProbeHistoryValid);

            var cmd = context.AcquireCommandBuffer(Name + " Compute");
            BurtIndirectLightingUtility.UploadSkyReflectionForTracing(cmd, context.Request);
            BurtLocalSkyProbeUtility.BindCompute(cmd, shader, compactKernel, camera);
            BindCompactInputs(cmd, shader, compactKernel, context, texelCountBuffer, texelDataBuffer, screenProbeHistory, screenProbeHistoryValid);
            UploadCompactParams(cmd, shader, settings, camera, screenProbeHistoryValid, screenProbeWidth, screenProbeHeight, traceWidth, traceHeight, traceTexelCount, maxAdaptiveProbes);
            cmd.DispatchCompute(
                shader,
                compactKernel,
                context.BurtGIScreenProbeIndirectArgsBuffer.Buffer,
                (uint)BurtScreenProbeIndirectArgsType.ThreadPerTrace * ScreenProbeIndirectArgsStrideBytes);

            BindGenArgsInputs(cmd, shader, genArgsKernel, texelCountBuffer, compactIndirectArgsBuffer, threadCountXBuffer);
            cmd.SetComputeIntParam(shader, BurtGIScreenProbeTraceCompactGroupSizeId, ScreenProbeTraceCompactThreadGroupSize);
            cmd.DispatchCompute(shader, genArgsKernel, 1, 1, 1);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static void ClearCompactBuffers(
            BurtRenderBufferHandle texelCountBuffer,
            BurtRenderBufferHandle texelDataBuffer,
            BurtRenderBufferHandle compactIndirectArgsBuffer,
            BurtRenderBufferHandle threadCountXBuffer)
        {
            if (texelCountBuffer.HasBuffer)
            {
                texelCountBuffer.Buffer.SetData(ZeroUint);
            }

            if (texelDataBuffer.HasBuffer)
            {
                texelDataBuffer.Buffer.SetData(ZeroUint, 0, 0, 1);
            }

            if (compactIndirectArgsBuffer.HasBuffer)
            {
                compactIndirectArgsBuffer.Buffer.SetData(ZeroDispatchArgs);
            }

            if (threadCountXBuffer.HasBuffer)
            {
                threadCountXBuffer.Buffer.SetData(ZeroUint);
            }
        }

        private static bool HasCompactInputs(
            BurtRenderGraphContext context,
            BurtRenderBufferHandle texelCountBuffer,
            BurtRenderBufferHandle texelDataBuffer,
            BurtRenderBufferHandle compactIndirectArgsBuffer,
            BurtRenderBufferHandle threadCountXBuffer)
        {
            return context.BurtGIScreenProbeScreenDepthTarget.IsValid &&
                context.BurtGIScreenProbeWorldNormalTarget.IsValid &&
                context.BurtGIScreenProbeWorldPositionTarget.IsValid &&
                context.BurtGIScreenProbeHitDistanceTarget.IsValid &&
                context.BurtGIScreenProbeIndirectArgsBuffer.HasBuffer &&
                context.BurtGIScreenProbeAdaptiveProbeNumBuffer.HasBuffer &&
                context.BurtGIScreenProbeAdaptiveProbeDataBuffer.HasBuffer &&
                texelCountBuffer.HasBuffer &&
                texelDataBuffer.HasBuffer &&
                compactIndirectArgsBuffer.HasBuffer &&
                threadCountXBuffer.HasBuffer;
        }

        private static ComputeShader GetScreenProbeTraceCompactComputeShader()
        {
            if (screenProbeTraceCompactComputeShader != null)
            {
                return screenProbeTraceCompactComputeShader;
            }

            screenProbeTraceCompactComputeShader = Resources.Load<ComputeShader>(ScreenProbeTraceCompactComputeShaderResourcePath);
            if (screenProbeTraceCompactComputeShader == null && !hasLoggedMissingScreenProbeTraceCompactComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ScreenProbeTraceCompactComputeShaderResourcePath);
                hasLoggedMissingScreenProbeTraceCompactComputeShader = true;
            }

            return screenProbeTraceCompactComputeShader;
        }

        private static bool TryFindScreenProbeTraceCompactKernel(ComputeShader shader, string kernelName, out int kernel)
        {
            kernel = -1;
            if (shader == null || string.IsNullOrEmpty(kernelName))
            {
                return false;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingScreenProbeTraceCompactKernel)
                {
                    Debug.LogWarning("BurtRP screen probe trace compact compute shader missing kernel: " + kernelName);
                    hasLoggedMissingScreenProbeTraceCompactKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }

        private static void BindCompactInputs(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderGraphContext context,
            BurtRenderBufferHandle texelCountBuffer,
            BurtRenderBufferHandle texelDataBuffer,
            BurtScreenSpaceGlobalIlluminationScreenProbeHistoryTextures screenProbeHistory,
            bool screenProbeHistoryValid)
        {
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, context.BurtGIScreenProbeScreenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, context.BurtGIScreenProbeWorldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, context.BurtGIScreenProbeWorldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHitDistanceTextureId, context.BurtGIScreenProbeHitDistanceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryWorldPositionTextureId, screenProbeHistoryValid && screenProbeHistory.WorldPosition != null ? (Texture)screenProbeHistory.WorldPosition : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryTraceHitTextureId, screenProbeHistoryValid && screenProbeHistory.TraceHit != null ? (Texture)screenProbeHistory.TraceHit : Texture2D.blackTexture);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactTexelCountBufferId, texelCountBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactTexelDataBufferId, texelDataBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeNumBufferId, context.BurtGIScreenProbeAdaptiveProbeNumBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeDataBufferId, context.BurtGIScreenProbeAdaptiveProbeDataBuffer.Buffer);
        }

        private static void BindGenArgsInputs(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderBufferHandle texelCountBuffer,
            BurtRenderBufferHandle compactIndirectArgsBuffer,
            BurtRenderBufferHandle threadCountXBuffer)
        {
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactTexelCountBufferId, texelCountBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactIndirectArgsBufferId, compactIndirectArgsBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactThreadCountXBufferId, threadCountXBuffer.Buffer);
        }

        private static void UploadCompactParams(
            CommandBuffer cmd,
            ComputeShader shader,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            Camera camera,
            bool screenProbeHistoryValid,
            int screenProbeWidth,
            int screenProbeHeight,
            int traceWidth,
            int traceHeight,
            int traceTexelCount,
            int maxAdaptiveProbes)
        {
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(
                screenProbeWidth,
                screenProbeHeight,
                1f / screenProbeWidth,
                1f / screenProbeHeight));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsId, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(settings),
                traceWidth,
                traceHeight,
                settings.TraceDistance));
            var compactTracingEndDistance = ScreenProbeTraceCompactNoDistanceCull;
            var cameraPosition = camera != null ? camera.transform.position : Vector3.zero;
            cmd.SetComputeVectorParam(shader, BurtDeferredCameraWorldPositionId, new Vector4(
                cameraPosition.x,
                cameraPosition.y,
                cameraPosition.z,
                1f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceCompactParamsId, new Vector4(
                traceTexelCount,
                compactTracingEndDistance,
                screenProbeHistoryValid ? 1f : 0f,
                settings.TraceCompact ? 0f : 1f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeAdaptiveParamsId, new Vector4(
                screenProbeWidth,
                screenProbeHeight,
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeAdaptiveProbeIndexTileCapacity(settings),
                maxAdaptiveProbes));
            cmd.SetComputeIntParam(shader, BurtGIScreenProbeTraceCompactGroupSizeId, ScreenProbeTraceCompactThreadGroupSize);
        }
    }

