        protected static void ExecuteContract(BurtRenderGraphContext context, string passName, ClipMapStage stage, bool clearCounters, bool preservePersistentProbeState = false)
        {
            if (context == null || !ShouldUse(context.Request, context.Asset))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, settings);
            var cmd = context.AcquireCommandBuffer(passName);
            BindTexture(cmd, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapIndirectionTextureId, context.BurtGIRadianceCacheClipMapIndirectionTarget);
            BindTexture(cmd, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapDepthProbeAtlasTextureId, context.BurtGIRadianceCacheClipMapDepthProbeAtlasTarget);
            BindTexture(cmd, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapRadianceProbeAtlasTextureId, context.BurtGIRadianceCacheClipMapRadianceProbeAtlasTarget);
            BindTexture(cmd, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, context.BurtGIRadianceCacheClipMapFinalRadianceAtlasTarget);
            BindTexture(cmd, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget);
            BindTexture(cmd, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget);
            BindTexture(cmd, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, context.BurtGIRadianceCacheClipMapProbeSkyAOAtlasTarget);
            BindClipMapBuffers(cmd, context);
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapParamsId, clipMapState.Params);
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapWorldParamsId, clipMapState.WorldParams);
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapStageParamsId, new Vector4((float)stage, clearCounters ? 1f : 0f, Time.frameCount, 0f));
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapWorldPositionToProbeCoordId, clipMapState.WorldPositionToProbeCoord);
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapProbeCoordToWorldCenterId, clipMapState.ProbeCoordToWorldCenter);
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapClipmapCenterExtentId, clipMapState.ClipmapCenterExtent);
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapClipmapParamsId, clipMapState.ClipmapParams);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);

            if (!clearCounters)
            {
                return;
            }

            if (!preservePersistentProbeState)
            {
                ClearUint(context.BurtGIRadianceCacheClipMapProbeAllocatorBuffer);
                ClearUint(context.BurtGIRadianceCacheClipMapProbeFreeListAllocatorBuffer);
                ClearUint(context.BurtGIRadianceCacheClipMapProbeFreeListBuffer);
                ClearUint(context.BurtGIRadianceCacheClipMapProbeLastUsedFrameBuffer);
                ClearUint(context.BurtGIRadianceCacheClipMapProbeLastTracedFrameBuffer);
                ClearVector4(context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer);
            }
            ClearVector4(context.BurtGIRadianceCacheClipMapProbeTraceDataBuffer);
            ClearUint(context.BurtGIRadianceCacheClipMapProbeTraceAllocatorBuffer);
            ClearUint(context.BurtGIRadianceCacheClipMapPriorityHistogramBuffer);
            ClearUint(context.BurtGIRadianceCacheClipMapMaxUpdateBucketBuffer);
            ClearUint(context.BurtGIRadianceCacheClipMapMaxTracesFromMaxUpdateBucketBuffer);
            ClearUint(context.BurtGIRadianceCacheClipMapProbesToUpdateTraceCostBuffer);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapClearProbePDFsIndirectArgsBuffer, ZeroDispatchArgs2);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapGenerateProbeTraceTilesIndirectArgsBuffer, ZeroDispatchArgs3);
            ClearUint(context.BurtGIRadianceCacheClipMapProbeTraceTileAllocatorBuffer);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapFilterProbesIndirectArgsBuffer, ZeroDispatchArgs5);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapPrepareProbeOcclusionIndirectArgsBuffer, ZeroDispatchArgs7);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapFixupProbeBordersIndirectArgsBuffer, ZeroDispatchArgs8);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapTraceProbesIndirectArgsBuffer, ZeroDispatchArgs4);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapSortProbeTraceTilesIndirectArgsBuffer, ZeroDispatchArgs5);
            ClearDispatchArgs(context.BurtGIRadianceCacheClipMapRadianceCacheHardwareRayTracingIndirectArgsBuffer, ZeroDispatchArgs6);
            ClearUint(context.BurtGIRadianceCacheClipMapHardwareRayTracingRayAllocatorBuffer);
        }

        protected static bool TryDispatchSceneVoxelHistoryReprojection(
            BurtRenderGraphContext context,
            string passName,
            BurtGISceneVoxelHistoryTextures history,
            int groupsX,
            int groupsY,
            int groupsZ)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                !history.NeedsReprojection ||
                history.Radiance == null ||
                history.Geometry == null ||
                history.Lighting == null ||
                !HasRadianceCacheSceneVoxelComputeResources(context))
            {
                return false;
            }

            var sceneVoxelBuildShader = GetSceneVoxelBuildComputeShader();
            if (TryFindRadianceCacheClipMapComputeKernel(sceneVoxelBuildShader, "SceneVoxelReprojectHistoryCS", out var sceneVoxelBuildKernel))
            {
                var sceneVoxelBuildCmd = context.AcquireCommandBuffer(passName + " Reproject Scene Voxel History");
                BindComputeTexture(sceneVoxelBuildCmd, sceneVoxelBuildShader, sceneVoxelBuildKernel, BurtGISceneVoxelRadianceTextureId, context.BurtGISceneVoxelRadianceTarget);
                BindComputeTexture(sceneVoxelBuildCmd, sceneVoxelBuildShader, sceneVoxelBuildKernel, BurtGISceneVoxelGeometryTextureId, context.BurtGISceneVoxelGeometryTarget);
                BindComputeTexture(sceneVoxelBuildCmd, sceneVoxelBuildShader, sceneVoxelBuildKernel, BurtGISceneVoxelLightingTextureId, context.BurtGISceneVoxelLightingTarget);
                sceneVoxelBuildCmd.SetComputeTextureParam(sceneVoxelBuildShader, sceneVoxelBuildKernel, BurtGISceneVoxelHistoryRadianceTextureId, history.Radiance);
                sceneVoxelBuildCmd.SetComputeTextureParam(sceneVoxelBuildShader, sceneVoxelBuildKernel, BurtGISceneVoxelHistoryGeometryTextureId, history.Geometry);
                sceneVoxelBuildCmd.SetComputeTextureParam(sceneVoxelBuildShader, sceneVoxelBuildKernel, BurtGISceneVoxelHistoryLightingTextureId, history.Lighting);
                sceneVoxelBuildCmd.SetComputeVectorParam(sceneVoxelBuildShader, BurtGISceneVoxelHistoryPreviousCenterExtentId, history.PreviousCenterExtent);
                sceneVoxelBuildCmd.SetComputeVectorParam(sceneVoxelBuildShader, BurtGISceneVoxelHistoryCurrentCenterExtentId, history.CurrentCenterExtent);
                sceneVoxelBuildCmd.SetComputeVectorParam(sceneVoxelBuildShader, BurtGISceneVoxelHistoryParamsId, new Vector4(history.HistoryExposureCorrection, 0f, 0f, 0f));
                sceneVoxelBuildCmd.DispatchCompute(sceneVoxelBuildShader, sceneVoxelBuildKernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
                context.ExecuteLegacyCommandBuffer(sceneVoxelBuildCmd);
                context.ReleaseCommandBuffer(sceneVoxelBuildCmd);
                return true;
            }

            return false;
        }

        protected static bool TryBuildPersistentSceneVoxelClipmap(
            BurtRenderGraphContext context,
            string passName,
            BurtGISceneVoxelClipmapResources resources,
            Vector4 centerExtent,
            int triangleCount)
        {
            if (resources == null || !resources.IsValid ||
                !BurtGISceneVoxelOctreeUtility.EnsureResources(resources.Octree, "BurtGI Scene Voxel Clipmap " + resources.Level, resources.RadianceResolution))
            {
                return false;
            }

            var sceneVoxelResolution = resources.RadianceResolution;
            var occupancyResolution = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelOccupancyMipResolution(sceneVoxelResolution);
            var clearGroupSize = BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelRadianceClearThreadGroupSize;
            var occupancyGroupSize = BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelOccupancyMipThreadGroupSize;
            var lightingGroupSize = BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize;
            var built = TryDispatchPersistentSceneVoxelClipmapBuildCompute(
                context,
                passName,
                resources,
                "SceneVoxelClearLiteCS",
                DivRoundUpSceneVoxelResolution(sceneVoxelResolution, clearGroupSize),
                DivRoundUpSceneVoxelResolution(sceneVoxelResolution, clearGroupSize),
                DivRoundUpSceneVoxelResolution(sceneVoxelResolution, clearGroupSize),
                0,
                0);
            var camera = context.Request != null ? context.Request.Camera : null;
            var globalIlluminationSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var gpuVoxelized = BurtGISceneVoxelGpuRasterizerUtility.Rasterize(
                context,
                passName + " Clipmap " + resources.Level,
                camera,
                centerExtent,
                sceneVoxelResolution,
                new RenderTargetIdentifier(resources.Radiance),
                new RenderTargetIdentifier(resources.Geometry),
                new RenderTargetIdentifier(resources.Lighting),
                globalIlluminationSettings);
            built &= gpuVoxelized || triangleCount > 0;
            if (triangleCount > 0)
            {
                built &= TryDispatchPersistentSceneVoxelClipmapBuildCompute(
                    context,
                    passName,
                    resources,
                    "SceneVoxelVoxelizeTrianglesCS",
                    Mathf.Max(1, (triangleCount + BurtGISceneVoxelMeshRasterizerUtility.ThreadGroupSize - 1) / BurtGISceneVoxelMeshRasterizerUtility.ThreadGroupSize),
                    1,
                    1,
                    0,
                    0);
            }

            built &= TryDispatchPersistentSceneVoxelClipmapBuildCompute(
                context,
                passName,
                resources,
                "SceneVoxelBuildOccupancyMipLiteCS",
                DivRoundUpSceneVoxelResolution(occupancyResolution, occupancyGroupSize),
                DivRoundUpSceneVoxelResolution(occupancyResolution, occupancyGroupSize),
                DivRoundUpSceneVoxelResolution(occupancyResolution, occupancyGroupSize),
                0,
                0);
            for (var targetMip = 1; targetMip < BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelOccupancyMipCount(sceneVoxelResolution); ++targetMip)
            {
                var targetResolution = Mathf.Max(1, occupancyResolution >> targetMip);
                built &= TryDispatchPersistentSceneVoxelClipmapBuildCompute(
                    context,
                    passName,
                    resources,
                    "SceneVoxelDownsampleOccupancyMipCS",
                    DivRoundUpSceneVoxelResolution(targetResolution, occupancyGroupSize),
                    DivRoundUpSceneVoxelResolution(targetResolution, occupancyGroupSize),
                    DivRoundUpSceneVoxelResolution(targetResolution, occupancyGroupSize),
                    targetMip,
                    targetMip - 1);
            }

            TryDispatchPersistentSceneVoxelClipmapSdfCompute(context, passName, resources);

            built &= TryDispatchPersistentSceneVoxelClipmapLightingCompute(
                context,
                passName,
                resources,
                centerExtent,
                DivRoundUpSceneVoxelResolution(sceneVoxelResolution, lightingGroupSize),
                DivRoundUpSceneVoxelResolution(sceneVoxelResolution, lightingGroupSize),
                DivRoundUpSceneVoxelResolution(sceneVoxelResolution, lightingGroupSize));
            built &= TryDispatchPersistentSceneVoxelClipmapProbeTraceCompute(
                context,
                passName,
                resources,
                centerExtent);
            built &= TryDispatchPersistentSceneVoxelClipmapOctreeBuildCompute(
                context,
                passName,
                resources,
                "SceneVoxelBuildOctreeLeafCS",
                Mathf.Max(1, sceneVoxelResolution / 4),
                Mathf.Max(1, sceneVoxelResolution / 4),
                Mathf.Max(1, sceneVoxelResolution / 4));
            built &= TryDispatchPersistentSceneVoxelClipmapOctreeBuildCompute(
                context,
                passName,
                resources,
                "SceneVoxelBuildOctreeParentCS",
                Mathf.Max(1, sceneVoxelResolution / 16),
                Mathf.Max(1, sceneVoxelResolution / 16),
                Mathf.Max(1, sceneVoxelResolution / 16));
            built &= TryDispatchPersistentSceneVoxelClipmapOctreeBuildCompute(
                context,
                passName,
                resources,
                "SceneVoxelBuildOctreeRootCS",
                Mathf.Max(1, sceneVoxelResolution / 64),
                Mathf.Max(1, sceneVoxelResolution / 64),
                Mathf.Max(1, sceneVoxelResolution / 64));
            if (built)
            {
                BurtGISceneVoxelOctreeUtility.MarkBuilt(resources.Octree);
            }

            return built;
        }

        private static bool TryDispatchPersistentSceneVoxelClipmapSdfCompute(
            BurtRenderGraphContext context,
            string passName,
            BurtGISceneVoxelClipmapResources resources)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                resources == null || !resources.IsValid)
            {
                if (resources != null)
                {
                    resources.SdfStatus = "Skipped(InvalidContextOrResources)";
                }

                return false;
            }

            if (!resources.ConfigureSdfContext(true))
            {
                return false;
            }

            var shader = GetSceneVoxelSdfComputeShader();
            if (!BurtXGISdfGenDispatchUtility.HasRequiredKernels(shader))
            {
                resources.SdfStatus = "MissingKernels(FillUV,JFA,Finalize)";
                return false;
            }

            var cmd = context.AcquireCommandBuffer(passName + " Generate Scene Voxel Clipmap SDF " + resources.Level);
            var dispatched = BurtXGISdfGenDispatchUtility.TryDispatchGenerateFromOccupancy(
                cmd,
                shader,
                resources.OccupancyMip,
                resources.SdfContext,
                0);
            if (dispatched)
            {
                context.ExecuteLegacyCommandBuffer(cmd);
                resources.SdfStatus = "Ready(" + resources.SdfContext.ResolveStatusLabel() + ")";
            }
            else
            {
                resources.SdfStatus = "DispatchFailed(" + resources.SdfContext.ResolveStatusLabel() + ")";
            }

            context.ReleaseCommandBuffer(cmd);
            return dispatched;
        }

        private static bool TryDispatchPersistentSceneVoxelClipmapBuildCompute(
            BurtRenderGraphContext context,
            string passName,
            BurtGISceneVoxelClipmapResources resources,
            string kernelName,
            int groupsX,
            int groupsY,
            int groupsZ,
            int targetMip,
            int sourceMip)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                resources == null || !resources.IsValid)
            {
                return false;
            }

            var shader = GetSceneVoxelBuildComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = CommandBufferPool.Get(passName + " Build Scene Voxel Clipmap " + resources.Level);
            var useAsyncCompute = BurtGIAsyncComputeUtility.Begin(context, cmd);
            switch (kernelName)
            {
                case "SceneVoxelClearLiteCS":
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelRadianceTextureId, resources.Radiance);
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelGeometryTextureId, resources.Geometry);
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelLightingTextureId, resources.Lighting);
                    break;
                case "SceneVoxelBuildOccupancyMipLiteCS":
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelGeometryReadTextureId, resources.Geometry);
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelOccupancyMipTextureId, resources.OccupancyMip);
                    break;
                case "SceneVoxelVoxelizeTrianglesCS":
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelRadianceTextureId, resources.Radiance);
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelGeometryTextureId, resources.Geometry);
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelLightingTextureId, resources.Lighting);
                    BurtGISceneVoxelMeshRasterizerUtility.BindCompute(cmd, shader, kernel, kernelName);
                    UploadSceneVoxelBuildComputeParams(cmd, shader, context);
                    break;
                case "SceneVoxelDownsampleOccupancyMipCS":
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelOccupancyMipReadTextureId, resources.OccupancyMip);
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelOccupancyMipTextureId, resources.OccupancyMip, targetMip);
                    cmd.SetComputeIntParam(shader, BurtGISceneVoxelOccupancyMipSourceMipId, sourceMip);
                    break;
                default:
                    context.ReleaseCommandBuffer(cmd);
                    return false;
            }

            cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            BurtGIAsyncComputeUtility.Execute(context, cmd, useAsyncCompute);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static bool TryDispatchPersistentSceneVoxelClipmapLightingCompute(
            BurtRenderGraphContext context,
            string passName,
            BurtGISceneVoxelClipmapResources resources,
            Vector4 centerExtent,
            int groupsX,
            int groupsY,
            int groupsZ)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                resources == null || !resources.IsValid)
            {
                return false;
            }

            var shader = GetSceneVoxelLightingComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, "SceneVoxelBuildLightingLiteCS", out var kernel))
            {
                return false;
            }

            var cmd = CommandBufferPool.Get(passName + " Build Scene Voxel Clipmap Lighting " + resources.Level);
            var useAsyncCompute = BurtGIAsyncComputeUtility.Begin(context, cmd);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelRadianceReadTextureId, resources.Radiance);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelGeometryReadTextureId, resources.Geometry);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelOccupancyMipReadTextureId, resources.OccupancyMip);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelLightingTextureId, resources.Lighting);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapIndirectionTextureId, context.BurtGIRadianceCacheClipMapIndirectionTarget.IsValid ? context.BurtGIRadianceCacheClipMapIndirectionTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget.IsValid ? context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget.IsValid ? context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            BindComputeBufferOrFallbackFloat4(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer);
            BurtGISceneVoxelOctreeUtility.BindCompute(cmd, shader, kernel, resources.Octree);
            var camera = context.Request != null ? context.Request.Camera : null;
            BurtGISceneVoxelClipmapStateUtility.BindRadianceCacheTraceCompute(
                cmd,
                shader,
                kernel,
                camera,
                centerExtent,
                resources.Radiance,
                resources.Geometry,
                resources.OccupancyMip,
                resources.Lighting);
            BurtGIXGILightGridUtility.BindCompute(cmd, shader, kernel, camera);
            UploadClipMapComputeParams(cmd, shader, context, default);
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelCenterExtentId, centerExtent);
            cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            BurtGIAsyncComputeUtility.Execute(context, cmd, useAsyncCompute);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static bool TryDispatchPersistentSceneVoxelClipmapProbeTraceCompute(
            BurtRenderGraphContext context,
            string passName,
            BurtGISceneVoxelClipmapResources resources,
            Vector4 centerExtent)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                resources == null || !resources.IsValid)
            {
                return false;
            }

            var setupShader = GetSceneVoxelLightingProbeSetupComputeShader();
            var traceShader = GetSceneVoxelLightingProbeTraceComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(setupShader, "ProbePlacement", out var placementKernel) ||
                !TryFindRadianceCacheClipMapComputeKernel(setupShader, "ProbeMark", out var markKernel) ||
                !TryFindRadianceCacheClipMapComputeKernel(setupShader, "ProbeCompact", out var compactKernel) ||
                !TryFindRadianceCacheClipMapComputeKernel(setupShader, "ProbeGenArgs", out var genArgsKernel) ||
                !TryFindRadianceCacheClipMapComputeKernel(traceShader, "ProbeTraceRadiance", out var traceKernel))
            {
                return false;
            }

            var probeNodeSize = Mathf.Max(1, resources.ProbeNodeSize);
            var probeIndexOffset = Mathf.Max(1, resources.ProbeIndexOffsetForClipmap);
            resources.ProbeIndexBuffer.SetData(ZeroSceneVoxelProbeIndexHeader, 0, 0, ZeroSceneVoxelProbeIndexHeader.Length);
            resources.ProbeArgsBuffer.SetData(ZeroSceneVoxelProbeDispatchArgs, 0, 0, ZeroSceneVoxelProbeDispatchArgs.Length);
            resources.ProbeArgsParamsBuffer.SetData(ZeroSceneVoxelProbeArgsParams, 0, 0, ZeroSceneVoxelProbeArgsParams.Length);

            var cmd = context.AcquireCommandBuffer(passName + " Build Scene Voxel Clipmap Probe Trace " + resources.Level);

            BindPersistentSceneVoxelProbeCommon(cmd, setupShader, placementKernel, context, resources, centerExtent, probeIndexOffset);
            cmd.SetComputeTextureParam(setupShader, placementKernel, ProbePlaceProbePageTableId, resources.ProbePageTable);
            cmd.DispatchCompute(
                setupShader,
                placementKernel,
                DivRoundUpSceneVoxelResolution(probeNodeSize, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize),
                DivRoundUpSceneVoxelResolution(probeNodeSize, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize),
                DivRoundUpSceneVoxelResolution(probeNodeSize, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize));

            BindPersistentSceneVoxelProbeCommon(cmd, setupShader, markKernel, context, resources, centerExtent, probeIndexOffset);
            cmd.SetComputeTextureParam(setupShader, markKernel, ProbePlaceProbePageTableId, resources.ProbePageTable);
            cmd.DispatchCompute(
                setupShader,
                markKernel,
                DivRoundUpSceneVoxelResolution(resources.RadianceResolution, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize),
                DivRoundUpSceneVoxelResolution(resources.RadianceResolution, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize),
                DivRoundUpSceneVoxelResolution(resources.RadianceResolution, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize));

            BindPersistentSceneVoxelProbeCommon(cmd, setupShader, compactKernel, context, resources, centerExtent, probeIndexOffset);
            cmd.SetComputeTextureParam(setupShader, compactKernel, ProbePlaceProbePageTableId, resources.ProbePageTable);
            cmd.SetComputeBufferParam(setupShader, compactKernel, RWProbePlaceProbeIndexId, resources.ProbeIndexBuffer);
            cmd.DispatchCompute(
                setupShader,
                compactKernel,
                DivRoundUpSceneVoxelResolution(probeNodeSize, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize),
                DivRoundUpSceneVoxelResolution(probeNodeSize, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize),
                DivRoundUpSceneVoxelResolution(probeNodeSize, BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelLightingThreadGroupSize));

            BindPersistentSceneVoxelProbeCommon(cmd, setupShader, genArgsKernel, context, resources, centerExtent, probeIndexOffset);
            cmd.SetComputeBufferParam(setupShader, genArgsKernel, RWVoxelProbeArgsBufferId, resources.ProbeArgsBuffer);
            cmd.SetComputeBufferParam(setupShader, genArgsKernel, RWVoxelProbeArgsBufferParamsId, resources.ProbeArgsParamsBuffer);
            cmd.SetComputeBufferParam(setupShader, genArgsKernel, VoxelProbeArgsProbeIndexId, resources.ProbeIndexBuffer);
            cmd.SetComputeIntParam(setupShader, VoxelProbeArgsMaxProbeCountId, probeIndexOffset);
            cmd.SetComputeIntParam(setupShader, VoxelProbeArgsClipmapCountId, 1);
            cmd.DispatchCompute(setupShader, genArgsKernel, 1, 1, 1);

            BindPersistentSceneVoxelProbeCommon(cmd, traceShader, traceKernel, context, resources, centerExtent, probeIndexOffset);
            BurtGIXGILightGridUtility.BindCompute(cmd, traceShader, traceKernel, context.Request != null ? context.Request.Camera : null);
            BurtGISceneVoxelOctreeUtility.BindCompute(cmd, traceShader, traceKernel, resources.Octree);
            cmd.SetComputeTextureParam(traceShader, traceKernel, RWVoxelProbeIrradianceSHAmbientId, resources.ProbeIrradianceSHAmbient);
            cmd.SetComputeTextureParam(traceShader, traceKernel, RWVoxelProbeIrradianceSHDirectionalId, resources.ProbeIrradianceSHDirectional);
            cmd.SetComputeTextureParam(traceShader, traceKernel, VoxelProbePageTableId, resources.ProbePageTable);
            cmd.SetComputeBufferParam(traceShader, traceKernel, VoxelProbeIndexBufferId, resources.ProbeIndexBuffer);
            cmd.SetComputeBufferParam(traceShader, traceKernel, VoxelProbeArgsBufferParamsId, resources.ProbeArgsParamsBuffer);
            cmd.DispatchCompute(traceShader, traceKernel, resources.ProbeArgsBuffer, 0u);

            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static void BindPersistentSceneVoxelProbeCommon(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderGraphContext context,
            BurtGISceneVoxelClipmapResources resources,
            Vector4 centerExtent,
            int probeIndexOffset)
        {
            UploadClipMapComputeParams(cmd, shader, context, default);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelRadianceReadTextureId, resources.Radiance);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelGeometryReadTextureId, resources.Geometry);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelOccupancyMipReadTextureId, resources.OccupancyMip);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelLightingReadTextureId, resources.Lighting);
            if (shader == sceneVoxelLightingProbeSetupComputeShader)
            {
                BindPersistentSceneVoxelProbeSetupFallbackTextures(cmd, shader, kernel, resources);
            }
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelCenterExtentId, centerExtent);
            var clipmapCenterExtents = new Vector4[BurtGISceneVoxelClipmapStateUtility.ClipmapCount];
            for (var level = 0; level < clipmapCenterExtents.Length; ++level)
            {
                clipmapCenterExtents[level] = centerExtent;
            }
            cmd.SetComputeVectorArrayParam(shader, BurtGISceneVoxelClipmapCenterExtentId, clipmapCenterExtents);
            cmd.SetComputeIntParam(shader, BurtGISceneVoxelClipmapValidMaskId, 1);
            cmd.SetComputeIntParam(shader, XGISceneRepresentUpdateVoxelClipMapResolutionId, resources.RadianceResolution);
            cmd.SetComputeIntParam(shader, XGISceneRepresentUpdateVoxelClipMapNumId, 1);
            cmd.SetComputeIntParam(shader, VoxelApplyTextureSizeId, resources.RadianceResolution);
            cmd.SetComputeIntParam(shader, VoxelApplyVolumeSizeId, resources.RadianceResolution);
            cmd.SetComputeIntParam(shader, VoxelApplyClipmapCountId, 1);
            cmd.SetComputeIntParam(shader, VoxelApplyMaterialIndexOffsetForClipmapId, probeIndexOffset);
            cmd.SetComputeIntParam(shader, ProbePlaceIndexOffsetClipmapId, probeIndexOffset);
            cmd.SetComputeIntParam(shader, ProbePlaceClipmapIndexId, 0);
            cmd.SetComputeIntParam(shader, ProbePlaceClipmapCountId, 1);
            cmd.SetComputeIntParam(shader, VoxelProbeIndexOffsetClipmapId, probeIndexOffset);
            cmd.SetComputeIntParam(shader, VoxelProbeClipmapValidMaskId, 1);
        }

        private static void BindPersistentSceneVoxelProbeSetupFallbackTextures(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtGISceneVoxelClipmapResources resources)
        {
            for (var index = 0; index < BurtGISceneVoxelProbeSetupFallbackGeometryTextureIds.Length; ++index)
            {
                cmd.SetComputeTextureParam(
                    shader,
                    kernel,
                    BurtGISceneVoxelProbeSetupFallbackGeometryTextureIds[index],
                    resources.Geometry);
                cmd.SetComputeTextureParam(
                    shader,
                    kernel,
                    BurtGISceneVoxelProbeSetupFallbackOccupancyTextureIds[index],
                    resources.OccupancyMip);
            }
        }

        private static bool TryDispatchPersistentSceneVoxelClipmapOctreeBuildCompute(
            BurtRenderGraphContext context,
            string passName,
            BurtGISceneVoxelClipmapResources resources,
            string kernelName,
            int groupsX,
            int groupsY,
            int groupsZ)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                resources == null || !resources.IsValid ||
                !BurtGISceneVoxelOctreeUtility.EnsureResources(resources.Octree, "BurtGI Scene Voxel Clipmap " + resources.Level))
            {
                return false;
            }

            var shader = GetSceneVoxelOctreeBuildComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = CommandBufferPool.Get(passName + " Build Scene Voxel Clipmap Octree " + resources.Level);
            var useAsyncCompute = BurtGIAsyncComputeUtility.Begin(context, cmd);
            cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelGeometryReadTextureId, resources.Geometry);
            BurtGISceneVoxelOctreeUtility.BindCompute(cmd, shader, kernel, resources.Octree);
            cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            BurtGIAsyncComputeUtility.Execute(context, cmd, useAsyncCompute);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static int DivRoundUpSceneVoxelResolution(int value, int divisor)
        {
            return (Mathf.Max(0, value) + Mathf.Max(1, divisor) - 1) / Mathf.Max(1, divisor);
        }

        private static bool IsRadianceCacheHashGridKernel(string kernelName)
        {
            return kernelName == "HashGridClearCountCS" ||
                kernelName == "RadianceCacheHashGridPrepareLiteCS" ||
                kernelName == "HashGridPopulateCellsGenIndirectArgsCS" ||
                kernelName == "HashGridPopulateCellsCS" ||
                kernelName == "RadianceCacheHashGridPopulateScreenProbesLiteCS" ||
                kernelName == "HashGridUpdateTilesGenIndirectArgsCS" ||
                kernelName == "RadianceCacheHashGridUpdateTilesGenIndirectArgsLiteCS" ||
                kernelName == "HashGridUpdateTilesCS" ||
                kernelName == "RadianceCacheHashGridUpdateTilesLiteCS" ||
                kernelName == "HashGridResolveCellsCS" ||
                kernelName == "RadianceCacheHashGridResolveTraceRadianceLiteCS" ||
                kernelName == "HashGridPurgeTilesGenIndirectArgsCS" ||
                kernelName == "HashGridPurgeTilesCS" ||
                kernelName == "RadianceCacheHashGridPurgeTilesLiteCS" ||
                kernelName == "HashGridDebugGenIndirectArgsCS";
        }

        private static bool IsRadianceCacheHashGridSceneCacheKernel(string kernelName)
        {
            return kernelName == "TraceFromProbesCS" ||
                kernelName == "MarkUsedRadianceProbesByVoxelPassCS" ||
                kernelName == "MarkUsedRadianceProbesFromSceneVoxelCS";
        }

        private static bool IsRadianceCacheSceneVoxelKernel(string kernelName)
        {
            return kernelName == "SceneVoxelClearLiteCS" ||
                kernelName == "SceneVoxelReprojectHistoryCS" ||
                kernelName == "SceneVoxelPopulateScreenProbesLiteCS" ||
                kernelName == "SceneVoxelVoxelizeTrianglesCS" ||
                kernelName == "SceneVoxelBuildOccupancyMipLiteCS" ||
                kernelName == "SceneVoxelDownsampleOccupancyMipCS" ||
                kernelName == "SceneVoxelBuildLightingLiteCS" ||
                kernelName == "SceneVoxelBuildOctreeLeafCS" ||
                kernelName == "SceneVoxelBuildOctreeParentCS" ||
                kernelName == "SceneVoxelBuildOctreeRootCS";
        }

        private static bool IsRadianceCacheSceneVoxelReadKernel(string kernelName)
        {
            return kernelName == "TraceFromProbesCS";
        }

        private static bool ShouldBindSceneVoxelClipmapInputs(string kernelName)
        {
            return IsRadianceCacheSceneVoxelKernel(kernelName) ||
                IsRadianceCacheSceneVoxelReadKernel(kernelName);
        }

        private static bool RequiresScreenProbeTraceRadianceRWTexture(string kernelName)
        {
            return kernelName == "FilterProbeRadianceWithGatherCS" ||
                kernelName == "FilterProbeRadianceCS" ||
                kernelName == "CalculateProbeIrradiance" ||
                kernelName == "CalculateProbeIrradianceCS" ||
                kernelName == "HashGridPopulateCellsCS" ||
                kernelName == "RadianceCacheHashGridPopulateScreenProbesLiteCS" ||
                kernelName == "HashGridResolveCellsCS" ||
                kernelName == "RadianceCacheHashGridResolveTraceRadianceLiteCS";
        }

        private static void BindSceneVoxelClipmapInputs(CommandBuffer cmd, ComputeShader shader, int kernel, string kernelName, BurtRenderGraphContext context)
        {
            if (cmd == null || shader == null || context == null)
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var globalSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, settings);
            var sceneVoxelCenterExtent = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(camera, settings, clipMapState, globalSettings.SceneVoxelClipMapResolution);
            BurtGISceneVoxelClipmapStateUtility.BindRadianceCacheTraceCompute(
                cmd,
                shader,
                kernel,
                camera,
                sceneVoxelCenterExtent,
                ResolveSceneVoxelFallbackIdentifier(context.BurtGISceneVoxelRadianceTarget),
                ResolveSceneVoxelFallbackIdentifier(context.BurtGISceneVoxelGeometryTarget),
                ResolveSceneVoxelFallbackIdentifier(context.BurtGISceneVoxelOccupancyMipTarget),
                ResolveSceneVoxelFallbackIdentifier(context.BurtGISceneVoxelLightingTarget));
        }

        private static RenderTargetIdentifier ResolveSceneVoxelFallbackIdentifier(BurtRenderTargetHandle target)
        {
            return target.IsValid
                ? target.Identifier
                : new RenderTargetIdentifier(BurtGITranslucencyVolumeFallbackUtility.BlackVolumeRenderTexture);
        }

        private static bool ShouldUploadRadianceCacheSkyReflection(string kernelName)
        {
            return kernelName == "GenerateProbeTraceTilesCS" ||
                kernelName == "TraceFromProbesCS";
        }

        internal static string ResolveComputeResourceStatusLabel()
        {
            if (!SystemInfo.supportsComputeShaders)
            {
                return "Unsupported(SystemInfo.supportsComputeShaders=false)";
            }

            var missing = string.Empty;
            var missingCount = 0;
            var kernelCount = 0;
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapInitComputeShader, RadianceCacheClipMapInitComputeShaderResourcePath, "InitClipMapCS,InitClipMapFrameCountersCS,InitClipMapIndirectArgsCS,InitClipMapProbeStateCS,ClearProbeIndirectionCS,ClearProbeFreeListCS,ClearRadianceCacheUpdateResourcesCS", ref missing, ref missingCount, ref kernelCount);
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapSetupArgsComputeShader, RadianceCacheClipMapSetupArgsComputeShaderResourcePath, "SetupProbeIndirectArgsCS,SetupProbeFilterIndirectArgsCS", ref missing, ref missingCount, ref kernelCount);
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapAllocateTracesComputeShader, RadianceCacheClipMapAllocateTracesComputeShaderResourcePath, "AllocateProbeTracesCS", ref missing, ref missingCount, ref kernelCount);
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapSetupTraceComputeShader, RadianceCacheClipMapSetupTraceComputeShaderResourcePath, "SetupTraceFromProbesCS", ref missing, ref missingCount, ref kernelCount);
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapSortTraceTilesComputeShader, RadianceCacheClipMapSortTraceTilesComputeShaderResourcePath, "SortProbeTraceTilesCS", ref missing, ref missingCount, ref kernelCount);
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapTraceUtilityComputeShader, RadianceCacheClipMapTraceUtilityComputeShaderResourcePath, "SelectMaxPriorityBucketCS,ClearProbePDFsCS,ComputeProbeWorldOffsets,ComputeProbeWorldOffsetsLiteCS", ref missing, ref missingCount, ref kernelCount);
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapPrepareProbeOcclusionComputeShader, RadianceCacheClipMapPrepareProbeOcclusionComputeShaderResourcePath, "PrepareProbeOcclusion,PrepareProbeOcclusionCS", ref missing, ref missingCount, ref kernelCount);
            AppendMissingComputeResourceKernels(ref radianceCacheClipMapFilterComputeShader, RadianceCacheClipMapFilterComputeShaderResourcePath, "FilterProbeRadianceWithGatherCS,FilterProbeRadianceCS,CalculateProbeIrradiance,CalculateProbeIrradianceCS", ref missing, ref missingCount, ref kernelCount);
