        private static void AppendMissingComputeResourceKernels(
            ref ComputeShader shader,
            string resourcePath,
            string kernelCsv,
            ref string missing,
            ref int missingCount,
            ref int kernelCount)
        {
            if (shader == null)
            {
                shader = Resources.Load<ComputeShader>(resourcePath);
            }

            if (shader == null)
            {
                AppendMissingComputeResourceItem(resourcePath, ref missing, ref missingCount);
                return;
            }

            var kernels = kernelCsv.Split(',');
            for (var i = 0; i < kernels.Length; i++)
            {
                var kernel = kernels[i];
                kernelCount++;
                if (!shader.HasKernel(kernel))
                {
                    AppendMissingComputeResourceItem(resourcePath + "." + kernel, ref missing, ref missingCount);
                }
            }
        }

        private static void AppendMissingComputeResourceItem(string item, ref string missing, ref int missingCount)
        {
            if (missingCount > 0)
            {
                missing += ",";
            }

            missing += item;
            missingCount++;
        }

        private static void AppendMissingComputeResource(ref ComputeShader shader, string resourcePath, ref string missing, ref int missingCount)
        {
            if (shader == null)
            {
                shader = Resources.Load<ComputeShader>(resourcePath);
            }

            if (shader != null)
            {
                return;
            }

            if (missingCount > 0)
            {
                missing += ",";
            }

            missing += resourcePath;
            missingCount++;
        }

