            BindComputeBuffer(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeTraceDataBufferId, context.BurtGIRadianceCacheClipMapProbeTraceDataBuffer);
            BindComputeBuffer(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeTraceAllocatorBufferId, context.BurtGIRadianceCacheClipMapProbeTraceAllocatorBuffer);
            BindComputeBuffer(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbesToUpdateTraceCostBufferId, context.BurtGIRadianceCacheClipMapProbesToUpdateTraceCostBuffer);
            BindComputeBuffer(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapRadianceProbePDFBufferId, context.BurtGIRadianceCacheClipMapRadianceProbePDFBuffer);
            BindComputeBuffer(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeTraceTileAllocatorBufferId, context.BurtGIRadianceCacheClipMapProbeTraceTileAllocatorBuffer);
            BindComputeBuffer(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeTraceTileDataBufferId, context.BurtGIRadianceCacheClipMapProbeTraceTileDataBuffer);
        }

        private static void BindComputeTexture(CommandBuffer cmd, ComputeShader shader, int kernel, int textureId, BurtRenderTargetHandle target)
        {
            if (target.IsValid)
            {
                cmd.SetComputeTextureParam(shader, kernel, textureId, target.Identifier);
            }
        }

        private static void BindComputeBuffer(CommandBuffer cmd, ComputeShader shader, int kernel, int bufferId, BurtRenderBufferHandle buffer)
        {
            if (buffer.HasBuffer)
            {
                cmd.SetComputeBufferParam(shader, kernel, bufferId, buffer.Buffer);
            }
        }

        private static void BindComputeBufferOrFallbackFloat4(CommandBuffer cmd, ComputeShader shader, int kernel, int bufferId, BurtRenderBufferHandle buffer)
        {
            cmd.SetComputeBufferParam(shader, kernel, bufferId, buffer.HasBuffer ? buffer.Buffer : RadianceCacheClipMapFallbackFloat4StructuredBuffer);
        }

        private static void BindComputeBufferOrFallbackUInt4(CommandBuffer cmd, ComputeShader shader, int kernel, int bufferId, BurtRenderBufferHandle buffer)
        {
            cmd.SetComputeBufferParam(shader, kernel, bufferId, buffer.HasBuffer ? buffer.Buffer : RadianceCacheClipMapFallbackUInt4StructuredBuffer);
        }

        private static GraphicsBuffer radianceCacheClipMapFallbackFloat4StructuredBuffer;
        private static GraphicsBuffer radianceCacheClipMapFallbackUInt4StructuredBuffer;

#if UNITY_EDITOR
        [UnityEditor.InitializeOnLoadMethod]
        private static void RegisterRadianceCacheClipMapFallbackBufferCleanup()
        {
            UnityEditor.AssemblyReloadEvents.beforeAssemblyReload -= ReleaseRadianceCacheClipMapFallbackBuffers;
            UnityEditor.AssemblyReloadEvents.beforeAssemblyReload += ReleaseRadianceCacheClipMapFallbackBuffers;
        }
#endif

        private static GraphicsBuffer RadianceCacheClipMapFallbackFloat4StructuredBuffer
        {
            get
            {
                if (radianceCacheClipMapFallbackFloat4StructuredBuffer == null)
                {
                    radianceCacheClipMapFallbackFloat4StructuredBuffer = new GraphicsBuffer(GraphicsBuffer.Target.Structured, 1, 16)
                    {
                        name = "BurtGI RadianceCache ClipMap Fallback Float4 Buffer"
                    };
                    radianceCacheClipMapFallbackFloat4StructuredBuffer.SetData(new[] { Vector4.zero });
                }

                return radianceCacheClipMapFallbackFloat4StructuredBuffer;
            }
        }

        private static GraphicsBuffer RadianceCacheClipMapFallbackUInt4StructuredBuffer
        {
            get
            {
                if (radianceCacheClipMapFallbackUInt4StructuredBuffer == null)
                {
                    radianceCacheClipMapFallbackUInt4StructuredBuffer = new GraphicsBuffer(GraphicsBuffer.Target.Structured, 1, 16)
                    {
                        name = "BurtGI RadianceCache ClipMap Fallback UInt4 Buffer"
                    };
                    radianceCacheClipMapFallbackUInt4StructuredBuffer.SetData(new[] { Vector4.zero });
                }

                return radianceCacheClipMapFallbackUInt4StructuredBuffer;
            }
        }

        private static void ReleaseRadianceCacheClipMapFallbackBuffers()
        {
            if (radianceCacheClipMapFallbackFloat4StructuredBuffer != null)
            {
                radianceCacheClipMapFallbackFloat4StructuredBuffer.Release();
                radianceCacheClipMapFallbackFloat4StructuredBuffer = null;
            }

            if (radianceCacheClipMapFallbackUInt4StructuredBuffer != null)
            {
                radianceCacheClipMapFallbackUInt4StructuredBuffer.Release();
                radianceCacheClipMapFallbackUInt4StructuredBuffer = null;
            }
        }

        protected static bool TryDispatchSceneVoxelBuildCompute(
            BurtRenderGraphContext context,
            string passName,
            string kernelName,
            int groupsX,
            int groupsY,
            int groupsZ,
            int targetMip = 0,
            int sourceMip = 0)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                !HasSceneVoxelBuildTargets(context, kernelName))
            {
                return false;
            }

            var shader = GetSceneVoxelBuildComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = CommandBufferPool.Get(passName + " Scene Voxel Build Compute");
            var useAsyncCompute = BurtGIAsyncComputeUtility.Begin(context, cmd);
            BindSceneVoxelBuildComputeTextures(cmd, shader, kernel, kernelName, context, targetMip, sourceMip);
            cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            BurtGIAsyncComputeUtility.Execute(context, cmd, useAsyncCompute);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static bool HasSceneVoxelBuildTargets(BurtRenderGraphContext context, string kernelName)
        {
            switch (kernelName)
            {
                case "SceneVoxelClearLiteCS":
                    return context.BurtGISceneVoxelRadianceTarget.IsValid &&
                        context.BurtGISceneVoxelGeometryTarget.IsValid &&
                        context.BurtGISceneVoxelLightingTarget.IsValid;
                case "SceneVoxelPopulateScreenProbesLiteCS":
                    return context.BurtGISceneVoxelRadianceTarget.IsValid &&
                        context.BurtGISceneVoxelGeometryTarget.IsValid &&
                        context.BurtGISceneVoxelLightingTarget.IsValid &&
                        context.ScreenSpaceGlobalIlluminationRawTarget.IsValid &&
                        context.BurtGIScreenProbeWorldNormalTarget.IsValid &&
                        context.BurtGIScreenProbeWorldPositionTarget.IsValid;
                case "SceneVoxelVoxelizeTrianglesCS":
                    return context.BurtGISceneVoxelRadianceTarget.IsValid &&
                        context.BurtGISceneVoxelGeometryTarget.IsValid &&
                        context.BurtGISceneVoxelLightingTarget.IsValid;
                case "SceneVoxelBuildOccupancyMipLiteCS":
                    return context.BurtGISceneVoxelGeometryTarget.IsValid &&
                        context.BurtGISceneVoxelOccupancyMipTarget.IsValid;
                case "SceneVoxelDownsampleOccupancyMipCS":
                    return context.BurtGISceneVoxelOccupancyMipTarget.IsValid;
                default:
                    return false;
            }
        }

        private static void BindSceneVoxelBuildComputeTextures(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            string kernelName,
            BurtRenderGraphContext context,
            int targetMip,
            int sourceMip)
        {
            switch (kernelName)
            {
                case "SceneVoxelClearLiteCS":
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelRadianceTextureId, context.BurtGISceneVoxelRadianceTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryTextureId, context.BurtGISceneVoxelGeometryTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelLightingTextureId, context.BurtGISceneVoxelLightingTarget);
                    break;
                case "SceneVoxelPopulateScreenProbesLiteCS":
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelRadianceTextureId, context.BurtGISceneVoxelRadianceTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryTextureId, context.BurtGISceneVoxelGeometryTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelLightingTextureId, context.BurtGISceneVoxelLightingTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGIRawTextureId, context.ScreenSpaceGlobalIlluminationRawTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGIScreenProbeWorldNormalTextureId, context.BurtGIScreenProbeWorldNormalTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGIScreenProbeWorldPositionTextureId, context.BurtGIScreenProbeWorldPositionTarget);
                    UploadSceneVoxelBuildComputeParams(cmd, shader, context);
                    break;
                case "SceneVoxelVoxelizeTrianglesCS":
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelRadianceTextureId, context.BurtGISceneVoxelRadianceTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryTextureId, context.BurtGISceneVoxelGeometryTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelLightingTextureId, context.BurtGISceneVoxelLightingTarget);
                    BurtGISceneVoxelMeshRasterizerUtility.BindCompute(cmd, shader, kernel, kernelName);
                    UploadSceneVoxelBuildComputeParams(cmd, shader, context);
                    break;
                case "SceneVoxelBuildOccupancyMipLiteCS":
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryReadTextureId, context.BurtGISceneVoxelGeometryTarget);
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelOccupancyMipTextureId, context.BurtGISceneVoxelOccupancyMipTarget);
                    break;
                case "SceneVoxelDownsampleOccupancyMipCS":
                    BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelOccupancyMipReadTextureId, context.BurtGISceneVoxelOccupancyMipTarget);
                    cmd.SetComputeTextureParam(shader, kernel, BurtGISceneVoxelOccupancyMipTextureId, context.BurtGISceneVoxelOccupancyMipTarget.Identifier, targetMip);
                    cmd.SetComputeIntParam(shader, BurtGISceneVoxelOccupancyMipSourceMipId, sourceMip);
                    break;
            }
        }

        private static void UploadSceneVoxelBuildComputeParams(CommandBuffer cmd, ComputeShader shader, BurtRenderGraphContext context)
        {
            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var globalIlluminationSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, settings);
            var screenProbeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            var screenProbeWidth = Mathf.Max(1, screenProbeDescriptor.width);
            var screenProbeHeight = Mathf.Max(1, screenProbeDescriptor.height);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(screenProbeWidth, screenProbeHeight, 1f / screenProbeWidth, 1f / screenProbeHeight));
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelCenterExtentId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(camera, settings, clipMapState, globalIlluminationSettings.SceneVoxelClipMapResolution));
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelTraceControlsId, new Vector4(
                globalIlluminationSettings.SceneVoxelTraceMaxSteps,
                globalIlluminationSettings.SceneVoxelTraceStepFactor,
                globalIlluminationSettings.SceneVoxelMaxSampleCount,
                globalIlluminationSettings.SceneVoxelMultiBounce ? 1f : 0f));
            cmd.SetComputeIntParam(shader, XGISceneRepresentUpdateVoxelVoxelDirectionsNumId, globalIlluminationSettings.SceneVoxelDirectionCount);
        }

        protected static bool TryDispatchSceneVoxelLightingCompute(
            BurtRenderGraphContext context,
            string passName,
            int groupsX,
            int groupsY,
            int groupsZ)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                !context.BurtGISceneVoxelRadianceTarget.IsValid ||
                !context.BurtGISceneVoxelGeometryTarget.IsValid ||
                !context.BurtGISceneVoxelOccupancyMipTarget.IsValid ||
                !context.BurtGISceneVoxelLightingTarget.IsValid)
            {
                return false;
            }

            var shader = GetSceneVoxelLightingComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, "SceneVoxelBuildLightingLiteCS", out var kernel))
            {
                return false;
            }

            var cmd = CommandBufferPool.Get(passName + " Scene Voxel Lighting Compute");
            var useAsyncCompute = BurtGIAsyncComputeUtility.Begin(context, cmd);
            BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelRadianceReadTextureId, context.BurtGISceneVoxelRadianceTarget);
            BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryReadTextureId, context.BurtGISceneVoxelGeometryTarget);
            BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelOccupancyMipReadTextureId, context.BurtGISceneVoxelOccupancyMipTarget);
            BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelLightingTextureId, context.BurtGISceneVoxelLightingTarget);
            BindComputeTexture(cmd, shader, kernel, BurtGIRadianceCacheClipMapIndirectionTextureId, context.BurtGIRadianceCacheClipMapIndirectionTarget);
            BindComputeTexture(cmd, shader, kernel, BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget.IsValid ? context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            BindComputeBuffer(cmd, shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer);
            BurtGISceneVoxelOctreeUtility.BindCompute(cmd, shader, kernel);
            BindSceneVoxelClipmapInputs(cmd, shader, kernel, "SceneVoxelBuildLightingLiteCS", context);
            BurtGIXGILightGridUtility.BindCompute(cmd, shader, kernel, context.Request != null ? context.Request.Camera : null);
            UploadClipMapComputeParams(cmd, shader, context, default);
            cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            BurtGIAsyncComputeUtility.Execute(context, cmd, useAsyncCompute);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        protected static bool TryDispatchSceneVoxelOctreeBuildCompute(
            BurtRenderGraphContext context,
            string passName,
            string kernelName,
            int groupsX,
            int groupsY,
            int groupsZ)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(context.Request, context.Asset) ||
                !context.BurtGISceneVoxelGeometryTarget.IsValid ||
                !BurtGISceneVoxelOctreeUtility.EnsureResources())
            {
                return false;
            }

            var shader = GetSceneVoxelOctreeBuildComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = context.AcquireCommandBuffer(passName + " Scene Voxel Octree Compute");
            BindComputeTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryReadTextureId, context.BurtGISceneVoxelGeometryTarget);
            BurtGISceneVoxelOctreeUtility.BindCompute(cmd, shader, kernel);
            cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

