        protected static bool TryDispatchRadianceCacheHashGridCompute(
            BurtRenderGraphContext context,
            string passName,
            string kernelName,
            int groupsX,
            int groupsY,
            int groupsZ,
            bool indirect,
            BurtRenderBufferHandle indirectArgsBuffer,
            uint indirectArgsOffset)
        {
            if (context == null ||
                !ShouldUseHashGrid(context.Request, context.Asset) ||
                !HasRadianceCacheHashGridComputeBuffers(context) ||
                !context.BurtGIScreenProbeWorldPositionTarget.IsValid ||
                !context.BurtGIScreenProbeHitDistanceTarget.IsValid ||
                !context.BurtGIScreenProbeTraceRadianceTarget.IsValid ||
                !context.BurtGIScreenProbeTraceHitTarget.IsValid ||
                !context.BurtGIScreenProbeImportanceRayInfoTarget.IsValid ||
                (indirect && !indirectArgsBuffer.HasBuffer))
            {
                return false;
            }

            var shader = GetRadianceCacheHashGridComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = context.AcquireCommandBuffer(passName + " HashGrid Compute");
            BindRadianceCacheHashGridComputeResources(cmd, shader, kernel, context);
            UploadClipMapComputeParams(cmd, shader, context, default);
            if (indirect)
            {
                cmd.DispatchCompute(shader, kernel, indirectArgsBuffer.Buffer, indirectArgsOffset);
            }
            else
            {
                cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            }

            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        protected static bool TryDispatchRadianceCacheClipMapTraceFromProbesComputeIndirect(
            BurtRenderGraphContext context,
            string passName,
            BurtRenderBufferHandle indirectArgsBuffer,
            uint indirectArgsOffset)
        {
            const string kernelName = "TraceFromProbesCS";
            if (context == null ||
                !ShouldUse(context.Request, context.Asset) ||
                !indirectArgsBuffer.HasBuffer ||
                !HasRadianceCacheClipMapComputeBuffers(context) ||
                !context.ScreenSpaceGlobalIlluminationRawTarget.IsValid ||
                !context.BurtGIScreenProbeWorldPositionTarget.IsValid ||
                !context.BurtGIScreenProbeWorldNormalTarget.IsValid ||
                !context.BurtGIScreenProbeTraceRadianceTarget.IsValid ||
                !context.BurtGIScreenProbeTraceHitTarget.IsValid ||
                !context.BurtGIScreenProbeImportanceRayInfoTarget.IsValid ||
                !context.BurtGIRadianceCacheClipMapDepthProbeAtlasTarget.IsValid ||
                !context.BurtGIRadianceCacheClipMapRadianceProbeAtlasTarget.IsValid)
            {
                return false;
            }

            var shader = GetRadianceCacheClipMapTraceFromProbesComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = context.AcquireCommandBuffer(passName + " Trace From Probes Compute");
            BurtGISceneVoxelClipmapStateUtility.BindTraceFallbackCompute(cmd, shader, kernel);
            BurtIndirectLightingUtility.UploadSkyReflectionForTracing(cmd, context.Request);
            BindClipMapComputeTextures(cmd, shader, kernel, kernelName, context, default);
            BurtGISceneVoxelOctreeUtility.BindCompute(cmd, shader, kernel);
            BindClipMapComputeBuffers(cmd, shader, kernel, kernelName, context);
            BurtGISceneVoxelMeshRasterizerUtility.BindCompute(cmd, shader, kernel, kernelName);
            BindSceneVoxelClipmapInputs(cmd, shader, kernel, kernelName, context);
            UploadClipMapComputeParams(cmd, shader, context, default, true);
            cmd.DispatchCompute(shader, kernel, indirectArgsBuffer.Buffer, indirectArgsOffset);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        protected static bool TryDispatchRadianceCacheClipMapAllocateTracesCompute(BurtRenderGraphContext context, string passName)
        {
            if (context == null ||
                !ShouldUse(context.Request, context.Asset) ||
                !context.BurtGIRadianceCacheClipMapIndirectionTarget.IsValid ||
                !HasRadianceCacheClipMapComputeBuffers(context))
            {
                return false;
            }

            const string kernelName = "AllocateProbeTracesCS";
            var shader = GetRadianceCacheClipMapAllocateTracesComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = context.AcquireCommandBuffer(passName + " Allocate Traces Compute");
            BindClipMapAllocateTracesComputeResources(cmd, shader, kernel, context);
            UploadClipMapComputeParams(cmd, shader, context, default);
            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationRadianceCacheClipMapIndirectionDescriptor(camera, settings);
            cmd.DispatchCompute(
                shader,
                kernel,
                DivRoundUpInt(descriptor.width, RadianceCacheClipMapAllocateProbeTracesThreadGroupSize),
                DivRoundUpInt(descriptor.height, RadianceCacheClipMapAllocateProbeTracesThreadGroupSize),
                1);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

