        protected static bool TryDispatchRadianceCacheClipMapSortTraceTilesCompute(BurtRenderGraphContext context, string passName)
        {
            if (context == null ||
                !ShouldUse(context.Request, context.Asset) ||
                !context.BurtGIRadianceCacheClipMapSortProbeTraceTilesIndirectArgsBuffer.HasBuffer ||
                !HasRadianceCacheClipMapComputeBuffers(context))
            {
                return false;
            }

            const string kernelName = "SortProbeTraceTilesCS";
            var shader = GetRadianceCacheClipMapSortTraceTilesComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = context.AcquireCommandBuffer(passName + " Sort Trace Tiles Compute");
            BindClipMapSortTraceTilesComputeResources(cmd, shader, kernel, context);
            UploadClipMapComputeParams(cmd, shader, context, default);
            cmd.DispatchCompute(shader, kernel, context.BurtGIRadianceCacheClipMapSortProbeTraceTilesIndirectArgsBuffer.Buffer, 0u);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
