        private static bool TryDispatchRadianceCacheClipMapTraceUtilityCompute(
            BurtRenderGraphContext context,
            string passName,
            string kernelName,
            int groupsX,
            int groupsY,
            int groupsZ,
            bool indirect,
            BurtRenderBufferHandle indirectArgsBuffer,
            uint indirectArgsOffset)
        {
            if (context == null ||
                !ShouldUse(context.Request, context.Asset) ||
                !HasRadianceCacheClipMapTraceUtilityComputeBuffers(context, kernelName) ||
                (indirect && !indirectArgsBuffer.HasBuffer))
            {
                return false;
            }

            var shader = GetRadianceCacheClipMapTraceUtilityComputeShader();
            if (!TryFindRadianceCacheClipMapComputeKernel(shader, kernelName, out var kernel))
            {
                return false;
            }

            var cmd = context.AcquireCommandBuffer(passName + " Trace Utility Compute");
            BindClipMapTraceUtilityComputeResources(cmd, shader, kernel, kernelName, context);
            UploadClipMapComputeParams(cmd, shader, context, default);
            if (indirect)
            {
                cmd.DispatchCompute(shader, kernel, indirectArgsBuffer.Buffer, indirectArgsOffset);
            }
            else
            {
                cmd.DispatchCompute(shader, kernel, Mathf.Max(1, groupsX), Mathf.Max(1, groupsY), Mathf.Max(1, groupsZ));
            }

            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static bool HasRadianceCacheClipMapTraceUtilityComputeBuffers(BurtRenderGraphContext context, string kernelName)
        {
            switch (kernelName)
            {
                case "SelectMaxPriorityBucketCS":
                    return context.BurtGIRadianceCacheClipMapPriorityHistogramBuffer.HasBuffer &&
                        context.BurtGIRadianceCacheClipMapMaxUpdateBucketBuffer.HasBuffer &&
                        context.BurtGIRadianceCacheClipMapMaxTracesFromMaxUpdateBucketBuffer.HasBuffer;
                case "ClearProbePDFsCS":
                    return context.BurtGIRadianceCacheClipMapProbeTraceAllocatorBuffer.HasBuffer &&
                        context.BurtGIRadianceCacheClipMapProbeTraceDataBuffer.HasBuffer &&
                        context.BurtGIRadianceCacheClipMapRadianceProbePDFBuffer.HasBuffer;
                case "ComputeProbeWorldOffsets":
                case "ComputeProbeWorldOffsetsLiteCS":
                    return context.BurtGIRadianceCacheClipMapProbeTraceAllocatorBuffer.HasBuffer &&
                        context.BurtGIRadianceCacheClipMapProbeTraceDataBuffer.HasBuffer &&
                        context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer.HasBuffer;
                default:
                    return false;
            }
        }

