        private static bool HasRadianceCacheClipMapFilterComputeResources(BurtRenderGraphContext context, string kernelName)
        {
            if (!context.BurtGIRadianceCacheClipMapDepthProbeAtlasTarget.IsValid ||
                !context.BurtGIRadianceCacheClipMapRadianceProbeAtlasTarget.IsValid ||
                !context.BurtGIRadianceCacheClipMapProbeTraceAllocatorBuffer.HasBuffer ||
                !context.BurtGIRadianceCacheClipMapProbeTraceDataBuffer.HasBuffer)
            {
                return false;
            }

            switch (kernelName)
            {
                case "FilterProbeRadianceWithGatherCS":
                case "FilterProbeRadianceCS":
                    return context.BurtGIRadianceCacheClipMapIndirectionTarget.IsValid &&
                        context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer.HasBuffer;
                case "CalculateProbeIrradiance":
                case "CalculateProbeIrradianceCS":
                    return context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget.IsValid &&
                        context.BurtGIRadianceCacheClipMapProbeSkyAOAtlasTarget.IsValid;
                default:
                    return false;
            }
        }

