        private static ComputeShader LoadScreenProbeTraceComputeShader(
            string resourcePath,
            ref ComputeShader shader,
            ref bool hasLoggedMissingResource)
        {
            if (shader != null)
            {
                return shader;
            }

            shader = Resources.Load<ComputeShader>(resourcePath);
            if (shader == null && !hasLoggedMissingResource)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + resourcePath);
                hasLoggedMissingResource = true;
            }

            return shader;
        }

        private static bool TryFindScreenProbeTraceAtlasKernel(ComputeShader shader, string kernelName, out int kernel, string fallbackKernelName = null)
        {
            kernel = -1;
            if (shader == null || string.IsNullOrEmpty(kernelName))
            {
                return false;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!string.IsNullOrEmpty(fallbackKernelName) && shader.HasKernel(fallbackKernelName))
                {
                    kernel = shader.FindKernel(fallbackKernelName);
                    return kernel >= 0;
                }

                if (!hasLoggedMissingScreenProbeTraceAtlasKernel)
                {
                    Debug.LogWarning("BurtRP screen probe trace compute shader missing kernel: " + kernelName + " in " + shader.name);
                    hasLoggedMissingScreenProbeTraceAtlasKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }

        private static void UploadCompactTraceAtlasParams(
            CommandBuffer cmd,
            ComputeShader shader,
            BurtScreenSpaceGlobalIlluminationSettings giSettings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            Camera camera,
            int probeWidth,
            int probeHeight,
            int traceWidth,
            int traceHeight,
            int maxAdaptiveProbes,
            bool hiZDepthValid)
        {
            var fullSkylightLeakingDistance = Mathf.Clamp(
                giSettings.ScreenProbeFullSkylightLeakingDistance,
                0.001f,
                Mathf.Max(settings.TraceDistance, 0.001f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(
                probeWidth,
                probeHeight,
                1f / probeWidth,
                1f / probeHeight));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsId, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(settings),
                traceWidth,
                traceHeight,
                settings.TraceDistance));
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelTraceControlsId, new Vector4(
                Mathf.Clamp(settings.TraceVoxelMaxTraceSteps * 2, 1, 128),
                settings.TraceVoxelStepFactor,
                0f,
                0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeSkyLeakParamsId, new Vector4(
                giSettings.ScreenProbeSkylightLeaking,
                1f / fullSkylightLeakingDistance,
                giSettings.ScreenProbeSkylightLeakingRoughness,
                giSettings.ScreenProbeTraceSkyCubemap ? 1f : 0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeAdaptiveParamsId, new Vector4(
                probeWidth,
                probeHeight,
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeAdaptiveProbeIndexTileCapacity(settings),
                maxAdaptiveProbes));
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheHashGridParams0Id, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridCellSize,
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridTileCellRatio,
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridBucketCount,
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridTilesPerBucket));
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheHashGridParams1Id, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheHashGridTileCount(),
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheHashGridCellCount(),
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridCellsPerTile,
                Mathf.Max(1, traceWidth * traceHeight)));
            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, settings);
            cmd.SetComputeVectorArrayParam(shader, BurtGIRadianceCacheClipMapClipmapCenterExtentId, clipMapState.ClipmapCenterExtent);
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelCenterExtentId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(camera, settings, clipMapState, giSettings.SceneVoxelClipMapResolution));
            var traceFrameIndex = settings.FixedJitterIndex >= 0
                ? settings.FixedJitterIndex
                : Mathf.Max(0, Time.frameCount);
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFrameIndexId, traceFrameIndex);
            UploadRadianceCacheClipMapParams(cmd, shader, settings, camera, clipMapState);
            var projectionMatrix = GL.GetGPUProjectionMatrix(camera.projectionMatrix, true);
            var viewProjectionMatrix = projectionMatrix * camera.worldToCameraMatrix;
            var hiZDescriptor = BurtRenderTargetDescriptorUtility.CreateHiZDepthDescriptor(camera);
            var sourceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, giSettings);
            var screenTraceStrength = hiZDepthValid && settings.TraceScreenDistance > 0.0001f ? 1f : 0f;
            var screenTraceDistance = settings.TraceScreenDistance;
            var tanHalfHorizontalFov = camera != null && !camera.orthographic
                ? Mathf.Tan(camera.fieldOfView * 0.5f * Mathf.Deg2Rad) * Mathf.Max(camera.aspect, 0.0001f)
                : 0f;
            var screenTraceMaxScreenDistanceScale = 0.2f * 2f * tanHalfHorizontalFov;
            var placementJitterIndex = settings.FixedJitterIndex >= 0
                ? -(settings.FixedJitterIndex + 1f)
                : Mathf.Max(0, Time.frameCount);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbeViewProjectionMatrixId, viewProjectionMatrix);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeScreenTraceParamsId, new Vector4(
                screenTraceStrength,
                screenTraceDistance,
                Mathf.Max(1, hiZDescriptor.width),
                Mathf.Max(1, hiZDescriptor.height)));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeScreenTraceParams1Id, new Vector4(
                settings.TraceRelativeDepthThickness,
                settings.TraceHistoryDepthTestRelativeThickness,
                settings.TraceHierarchicalMaxIterations,
                screenTraceMaxScreenDistanceScale));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeScreenTraceParams2Id, new Vector4(
                settings.SpacingPixels,
                placementJitterIndex,
                Mathf.Max(1, sourceDescriptor.width),
                Mathf.Max(1, sourceDescriptor.height)));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceModeParamsId, new Vector4(
                settings.TraceHierarchically ? 1f : 0f,
                settings.ScreenTraceThicknessScaleWhenNoFallback,
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeGatherMaxRayIntensity(settings, camera),
                tanHalfHorizontalFov));
            var traceStageMask = settings.TraceSources;
            if (settings.TraceUseWorldRadianceClipMap)
            {
                traceStageMask |= ScreenProbeTraceSource.RadianceCacheClipMap;
            }

            cmd.SetComputeIntParam(shader, BurtGIScreenProbeTraceStageMaskId, (int)traceStageMask);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceIntensityParamsId, new Vector4(settings.TraceRadianceIntensityScale, 0f, 0f, 0f));
        }

        private static void BindCompactTraceAtlasInputs(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderTargetHandle radianceTarget,
            BurtRenderTargetHandle irradianceTarget,
            BurtRenderTargetHandle confidenceTarget,
            BurtRenderTargetHandle hitDistanceTarget,
            BurtRenderTargetHandle importancePDFTarget,
            BurtRenderTargetHandle importanceRayInfoTarget,
            BurtRenderGraphContext context,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var screenProbeHistory = BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.GetHistoryTextures(context.Request, settings, out var screenProbeHistoryValid);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeRadianceTextureId, radianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeIrradianceTextureId, irradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeConfidenceTextureId, confidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHitDistanceTextureId, hitDistanceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeImportancePDFTextureId, importancePDFTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeImportanceRayInfoTextureId, importanceRayInfoTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeImportancePDFReadTextureId, importancePDFTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeImportanceRayInfoReadTextureId, importanceRayInfoTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, context.BurtGIScreenProbeScreenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, context.BurtGIScreenProbeWorldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, context.BurtGIScreenProbeWorldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryRadianceTextureId, screenProbeHistoryValid && screenProbeHistory.Radiance != null ? (Texture)screenProbeHistory.Radiance : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryTraceRadianceTextureId, screenProbeHistoryValid && screenProbeHistory.TraceRadiance != null ? (Texture)screenProbeHistory.TraceRadiance : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryScreenDepthTextureId, screenProbeHistoryValid && screenProbeHistory.ScreenDepth != null ? (Texture)screenProbeHistory.ScreenDepth : Texture2D.blackTexture);
            var previousSceneColor = BurtGIPreviousSceneColorHistoryUtility.GetPreviousSceneColor(
                context.Request,
                context.Asset,
                out var previousSceneColorValid,
                out var previousSceneColorExposureCorrection);
            var previousSceneColorWidth = previousSceneColor != null ? Mathf.Max(1, previousSceneColor.width) : 1;
            var previousSceneColorHeight = previousSceneColor != null ? Mathf.Max(1, previousSceneColor.height) : 1;
            cmd.SetComputeTextureParam(
                shader,
                kernel,
                BurtGIPreviousSceneColorTextureId,
                previousSceneColorValid && previousSceneColor != null ? (Texture)previousSceneColor : Texture2D.blackTexture);
            cmd.SetComputeVectorParam(shader, BurtGIPreviousSceneColorParamsId, new Vector4(
                previousSceneColorValid ? 1f : 0f,
                previousSceneColorExposureCorrection,
                1f / previousSceneColorWidth,
                1f / previousSceneColorHeight));
            BindCompactSceneVoxelTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryReadTextureId, context.BurtGISceneVoxelGeometryTarget);
            BindCompactSceneVoxelTexture(cmd, shader, kernel, BurtGISceneVoxelOccupancyMipReadTextureId, context.BurtGISceneVoxelOccupancyMipTarget);
            BindCompactSceneVoxelTexture(cmd, shader, kernel, BurtGISceneVoxelLightingReadTextureId, context.BurtGISceneVoxelLightingTarget);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapIndirectionTextureId, context.BurtGIRadianceCacheClipMapIndirectionTarget.IsValid ? context.BurtGIRadianceCacheClipMapIndirectionTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, context.BurtGIRadianceCacheClipMapFinalRadianceAtlasTarget.IsValid ? context.BurtGIRadianceCacheClipMapFinalRadianceAtlasTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget.IsValid ? context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtHiZDepthTextureId, context.HiZDepthTarget.IsValid ? context.HiZDepthTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactTexelCountBufferId, context.BurtGIScreenProbeTraceCompactTexelCountBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactTexelDataBufferId, context.BurtGIScreenProbeTraceCompactTexelDataBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactThreadCountXBufferId, context.BurtGIScreenProbeTraceCompactThreadCountXBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeNumBufferId, context.BurtGIScreenProbeAdaptiveProbeNumBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeDataBufferId, context.BurtGIScreenProbeAdaptiveProbeDataBuffer.Buffer);
            BindCompactTraceAtlasBuffer(cmd, shader, kernel, BurtGIRadianceCacheHashGridValueBufferId, context.GetBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridValueBufferName), FallbackUint4StructuredBuffer);
            BindCompactTraceAtlasBuffer(cmd, shader, kernel, BurtGIRadianceCacheHashGridTileBufferId, context.GetBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridTileBufferName), FallbackUint4StructuredBuffer);
            BindCompactTraceAtlasBuffer(cmd, shader, kernel, BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer, FallbackFloat4StructuredBuffer);
        }

        private static void BindCompactTraceAtlasVoxelOctreeInputs(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderTargetHandle radianceTarget,
            BurtRenderTargetHandle irradianceTarget,
            BurtRenderTargetHandle confidenceTarget,
            BurtRenderTargetHandle hitDistanceTarget,
            BurtRenderTargetHandle importancePDFTarget,
            BurtRenderTargetHandle importanceRayInfoTarget,
            BurtRenderGraphContext context)
        {
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeRadianceTextureId, radianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeIrradianceTextureId, irradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeConfidenceTextureId, confidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHitDistanceTextureId, hitDistanceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeImportancePDFReadTextureId, importancePDFTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeImportanceRayInfoReadTextureId, importanceRayInfoTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, context.BurtGIScreenProbeScreenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, context.BurtGIScreenProbeWorldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, context.BurtGIScreenProbeWorldPositionTarget.Identifier);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactTexelCountBufferId, context.BurtGIScreenProbeTraceCompactTexelCountBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactTexelDataBufferId, context.BurtGIScreenProbeTraceCompactTexelDataBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceCompactThreadCountXBufferId, context.BurtGIScreenProbeTraceCompactThreadCountXBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeNumBufferId, context.BurtGIScreenProbeAdaptiveProbeNumBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeDataBufferId, context.BurtGIScreenProbeAdaptiveProbeDataBuffer.Buffer);
        }

        private static void BindCompactTraceAtlasBuffer(CommandBuffer cmd, ComputeShader shader, int kernel, int bufferId, BurtRenderBufferHandle buffer, GraphicsBuffer fallback)
        {
            cmd.SetComputeBufferParam(shader, kernel, bufferId, buffer.HasBuffer ? buffer.Buffer : fallback);
        }

        private static void BindCompactSceneVoxelTexture(CommandBuffer cmd, ComputeShader shader, int kernel, int textureId, BurtRenderTargetHandle target)
        {
            cmd.SetComputeTextureParam(shader, kernel, textureId, ResolveCompactSceneVoxelFallback(target));
        }

        private static RenderTargetIdentifier ResolveCompactSceneVoxelFallback(BurtRenderTargetHandle target)
        {
            return target.IsValid
                ? target.Identifier
                : new RenderTargetIdentifier(BurtGITranslucencyVolumeFallbackUtility.BlackVolumeRenderTexture);
        }

        private static GraphicsBuffer FallbackUint4StructuredBuffer
        {
            get
            {
                if (fallbackUint4StructuredBuffer != null)
                {
                    return fallbackUint4StructuredBuffer;
                }

                fallbackUint4StructuredBuffer = CreateFallbackStructuredBuffer("BurtGI ScreenProbe Fallback UInt4 Buffer");
                return fallbackUint4StructuredBuffer;
            }
        }

        private static GraphicsBuffer FallbackFloat4StructuredBuffer
        {
            get
            {
                if (fallbackFloat4StructuredBuffer != null)
                {
                    return fallbackFloat4StructuredBuffer;
                }

                fallbackFloat4StructuredBuffer = CreateFallbackStructuredBuffer("BurtGI ScreenProbe Fallback Float4 Buffer");
                return fallbackFloat4StructuredBuffer;
            }
        }

        private static GraphicsBuffer CreateFallbackStructuredBuffer(string name)
        {
            var buffer = new GraphicsBuffer(GraphicsBuffer.Target.Structured, 1, sizeof(float) * 4)
            {
                name = name
            };
            buffer.SetData(new[] { Vector4.zero });
            return buffer;
        }

        private static void ReleaseFallbackBuffers()
        {
            ReleaseFallbackBuffer(ref fallbackUint4StructuredBuffer);
            ReleaseFallbackBuffer(ref fallbackFloat4StructuredBuffer);
        }

        private static void ReleaseFallbackBuffer(ref GraphicsBuffer buffer)
        {
            if (buffer == null)
            {
                return;
            }

            buffer.Release();
            buffer = null;
        }

        private static void UploadRadianceCacheClipMapParams(
            CommandBuffer cmd,
            ComputeShader shader,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            Camera camera,
            BurtRadianceCacheClipMapState clipMapState)
        {
            if (!settings.Enabled || !settings.TraceUseWorldRadianceClipMap)
            {
                cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapIndirectionSizeId, Vector4.zero);
                cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapParamsId, Vector4.zero);
                cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapWorldParamsId, Vector4.zero);
                cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalRadianceAtlasMaxMipId, 0);
                cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalIrradianceProbeResolutionId, 0);
                cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalOcclusionProbeResolutionId, 0);
                cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapApplyParamsId, Vector4.zero);
                return;
            }

            var indirectionDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationRadianceCacheClipMapIndirectionDescriptor(camera, settings);
            var indirectionWidth = Mathf.Max(1, indirectionDescriptor.width);
            var indirectionHeight = Mathf.Max(1, indirectionDescriptor.height);
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapIndirectionSizeId, new Vector4(indirectionWidth, indirectionHeight, 1f / indirectionWidth, 1f / indirectionHeight));
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapParamsId, clipMapState.Params);
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapWorldParamsId, clipMapState.WorldParams);
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalRadianceAtlasMaxMipId, BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheClipMapFinalRadianceAtlasMaxMip);
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalIrradianceProbeResolutionId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapFinalIrradianceProbeResolution(settings));
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalOcclusionProbeResolutionId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapFinalOcclusionProbeResolution(settings));
            cmd.SetComputeVectorArrayParam(shader, BurtGIRadianceCacheClipMapWorldPositionToProbeCoordId, clipMapState.WorldPositionToProbeCoord);
            cmd.SetComputeVectorArrayParam(shader, BurtGIRadianceCacheClipMapProbeCoordToWorldCenterId, clipMapState.ProbeCoordToWorldCenter);
            cmd.SetComputeVectorArrayParam(shader, BurtGIRadianceCacheClipMapClipmapCenterExtentId, clipMapState.ClipmapCenterExtent);
            cmd.SetComputeVectorArrayParam(shader, BurtGIRadianceCacheClipMapClipmapParamsId, clipMapState.ClipmapParams);
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapApplyParamsId, new Vector4(1f, settings.RadianceCacheReprojectionRadiusScale, settings.RadianceCacheVisualizeClipmapIndex, settings.RadianceCacheVisualizeRadiusScale));
        }

        private static void BindCompactTraceAtlasOutputs(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            BurtRenderTargetHandle traceRadianceTarget,
            BurtRenderTargetHandle traceHitTarget)
        {
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceRadianceTextureId, traceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
        }

        private static int DivRoundUpInt(int value, int divisor)
        {
            return (value + Mathf.Max(1, divisor) - 1) / Mathf.Max(1, divisor);
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeCompositeTracesPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string ScreenProbeCompositeTracesComputeShaderResourcePath = "BurtGIScreenProbeCompositeTraces";
        private const string ScreenProbeCompositeTracesKernelName = "ScreenProbeFilterCompositeTraces";
        private const int ScreenProbeCompositeTracesThreadGroupSize = 8;
        private static readonly int BurtGIScreenProbeRadianceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeRadianceWriteTexture");
        private static readonly int BurtGIScreenProbeIrradianceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeIrradianceWriteTexture");
        private static readonly int BurtGIScreenProbeConfidenceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeConfidenceWriteTexture");
        private static readonly int BurtGIScreenProbeHitDistanceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeHitDistanceWriteTexture");
        private static readonly int BurtGIScreenProbeTraceParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceParams");
        private static readonly int BurtGIScreenProbeTraceModeParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceModeParams");
        private static readonly int BurtGIScreenProbeTraceIntensityParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceIntensityParams");
        private static ComputeShader screenProbeCompositeTracesComputeShader;
        private static bool hasLoggedMissingScreenProbeCompositeTracesComputeShader;
        private static bool hasLoggedMissingScreenProbeCompositeTracesKernel;

        public override string Name => "Burt ScreenProbe Lite Composite Traces";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGIScreenProbeRadiance();
            builder.ReadBurtGIScreenProbeIrradiance();
            builder.ReadBurtGIScreenProbeConfidence();
            builder.ReadBurtGIScreenProbeScreenDepth();
            builder.ReadBurtGIScreenProbeTraceRadiance();
            builder.ReadBurtGIScreenProbeTraceHit();
            builder.WriteBurtGIScreenProbeFilteredRadiance();
            builder.WriteBurtGIScreenProbeFilteredIrradiance();
            builder.WriteBurtGIScreenProbeFilteredConfidence();
            builder.WriteBurtGIScreenProbeHitDistance();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(
                    context,
                    out var radianceTarget,
                    out var irradianceTarget,
                    out var confidenceTarget,
                    out var screenDepthTarget,
                    out var traceRadianceTarget,
                    out var traceHitTarget,
                    out var compositeRadianceTarget,
                    out var compositeIrradianceTarget,
                    out var compositeConfidenceTarget,
                    out var compositeHitDistanceTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            if (!settings.Enabled || !screenProbeSettings.Enabled)
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            if (camera == null)
            {
                return;
            }

            var probeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeTraceDescriptor(camera, screenProbeSettings);
            var cmd = context.AcquireCommandBuffer(Name);
            if (!TryDispatchCompositeTracesCompute(
                    cmd,
                    camera,
                    settings,
                    screenProbeSettings,
                    probeDescriptor,
                    traceDescriptor,
                    radianceTarget,
                    irradianceTarget,
                    confidenceTarget,
                    screenDepthTarget,
                    traceRadianceTarget,
                    traceHitTarget,
                    compositeRadianceTarget,
                    compositeIrradianceTarget,
                    compositeConfidenceTarget,
                    compositeHitDistanceTarget))
            {
                cmd.CopyTexture(radianceTarget.Identifier, compositeRadianceTarget.Identifier);
                cmd.CopyTexture(irradianceTarget.Identifier, compositeIrradianceTarget.Identifier);
                cmd.CopyTexture(confidenceTarget.Identifier, compositeConfidenceTarget.Identifier);
            }

            cmd.SetGlobalTexture(BurtGIScreenProbeFilteredRadianceTextureId, compositeRadianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeFilteredIrradianceTextureId, compositeIrradianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeFilteredConfidenceTextureId, compositeConfidenceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeHitDistanceTextureId, compositeHitDistanceTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryDispatchCompositeTracesCompute(
            CommandBuffer cmd,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor probeDescriptor,
            RenderTextureDescriptor traceDescriptor,
            BurtRenderTargetHandle radianceTarget,
            BurtRenderTargetHandle irradianceTarget,
            BurtRenderTargetHandle confidenceTarget,
            BurtRenderTargetHandle screenDepthTarget,
            BurtRenderTargetHandle traceRadianceTarget,
            BurtRenderTargetHandle traceHitTarget,
            BurtRenderTargetHandle compositeRadianceTarget,
            BurtRenderTargetHandle compositeIrradianceTarget,
            BurtRenderTargetHandle compositeConfidenceTarget,
            BurtRenderTargetHandle compositeHitDistanceTarget)
        {
            var shader = GetScreenProbeCompositeTracesComputeShader();
            if (!TryFindScreenProbeCompositeTracesKernel(shader, out var kernel))
            {
                return false;
            }

            var width = Mathf.Max(1, probeDescriptor.width);
            var height = Mathf.Max(1, probeDescriptor.height);
            var traceWidth = Mathf.Max(1, traceDescriptor.width);
            var traceHeight = Mathf.Max(1, traceDescriptor.height);
            var groupsX = Mathf.CeilToInt(width / (float)ScreenProbeCompositeTracesThreadGroupSize);
            var groupsY = Mathf.CeilToInt(height / (float)ScreenProbeCompositeTracesThreadGroupSize);
            var tanHalfHorizontalFov = camera != null && !camera.orthographic
                ? Mathf.Tan(camera.fieldOfView * 0.5f * Mathf.Deg2Rad) * Mathf.Max(camera.aspect, 0.0001f)
                : 0f;

            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeRadianceTextureId, radianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeIrradianceTextureId, irradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeConfidenceTextureId, confidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, screenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceRadianceTextureId, traceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeRadianceWriteTextureId, compositeRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeIrradianceWriteTextureId, compositeIrradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeConfidenceWriteTextureId, compositeConfidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHitDistanceWriteTextureId, compositeHitDistanceTarget.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeParamsId, new Vector4(screenProbeSettings.SpacingPixels, screenProbeSettings.TraceDistance, screenProbeSettings.SampleCount, screenProbeSettings.ApplyStrength));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(width, height, 1f / width, 1f / height));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsId, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                traceWidth,
                traceHeight,
                screenProbeSettings.TraceDistance));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceModeParamsId, new Vector4(
                screenProbeSettings.TraceHierarchically ? 1f : 0f,
                screenProbeSettings.ScreenTraceThicknessScaleWhenNoFallback,
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeGatherMaxRayIntensity(screenProbeSettings, camera),
                tanHalfHorizontalFov));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceIntensityParamsId, new Vector4(screenProbeSettings.TraceRadianceIntensityScale, 0f, 0f, 0f));
            cmd.SetComputeVectorParam(shader, BurtGIParams0Id, new Vector4(settings.Radius, settings.SampleCount, settings.MaxSteps, settings.Thickness));
            cmd.SetComputeVectorParam(shader, BurtGIParams1Id, new Vector4(settings.Intensity, settings.SkyFallback, settings.Blur ? 1f : 0f, settings.BlurSharpness));
            cmd.SetComputeVectorParam(shader, BurtGIParams2Id, new Vector4(Time.frameCount & 1023, settings.NormalWeight, settings.DistanceFade, settings.RadianceClamp));
            cmd.SetComputeVectorParam(shader, BurtGIParams3Id, new Vector4(settings.SpatialDenoiseRadius, settings.SpatialDenoiseStrength, settings.TemporalVarianceClamp, settings.TemporalHitRejection));
            cmd.SetComputeVectorParam(shader, BurtGIParams4Id, new Vector4(settings.LeakGuardStrength, settings.EdgeFadeStrength, settings.NormalConeTightness, settings.SkyEdgeSuppression));
            cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
            return true;
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle radianceTarget,
            out BurtRenderTargetHandle irradianceTarget,
            out BurtRenderTargetHandle confidenceTarget,
            out BurtRenderTargetHandle screenDepthTarget,
            out BurtRenderTargetHandle traceRadianceTarget,
            out BurtRenderTargetHandle traceHitTarget,
            out BurtRenderTargetHandle compositeRadianceTarget,
            out BurtRenderTargetHandle compositeIrradianceTarget,
            out BurtRenderTargetHandle compositeConfidenceTarget,
            out BurtRenderTargetHandle compositeHitDistanceTarget)
        {
            radianceTarget = context != null ? context.BurtGIScreenProbeRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeRadianceName);
            irradianceTarget = context != null ? context.BurtGIScreenProbeIrradianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeIrradianceName);
            confidenceTarget = context != null ? context.BurtGIScreenProbeConfidenceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeConfidenceName);
            screenDepthTarget = context != null ? context.BurtGIScreenProbeScreenDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthName);
            traceRadianceTarget = context != null ? context.BurtGIScreenProbeTraceRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceRadianceName);
            traceHitTarget = context != null ? context.BurtGIScreenProbeTraceHitTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceHitName);
            compositeRadianceTarget = context != null ? context.BurtGIScreenProbeFilteredRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeFilteredRadianceName);
            compositeIrradianceTarget = context != null ? context.BurtGIScreenProbeFilteredIrradianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeFilteredIrradianceName);
            compositeConfidenceTarget = context != null ? context.BurtGIScreenProbeFilteredConfidenceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeFilteredConfidenceName);
            compositeHitDistanceTarget = context != null ? context.BurtGIScreenProbeHitDistanceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeHitDistanceName);

            return radianceTarget.IsValid &&
                irradianceTarget.IsValid &&
                confidenceTarget.IsValid &&
                screenDepthTarget.IsValid &&
                traceRadianceTarget.IsValid &&
                traceHitTarget.IsValid &&
                compositeRadianceTarget.IsValid &&
                compositeIrradianceTarget.IsValid &&
                compositeConfidenceTarget.IsValid &&
                compositeHitDistanceTarget.IsValid;
        }

        private static ComputeShader GetScreenProbeCompositeTracesComputeShader()
        {
            if (screenProbeCompositeTracesComputeShader != null)
            {
                return screenProbeCompositeTracesComputeShader;
            }

            screenProbeCompositeTracesComputeShader = Resources.Load<ComputeShader>(ScreenProbeCompositeTracesComputeShaderResourcePath);
            if (screenProbeCompositeTracesComputeShader == null && !hasLoggedMissingScreenProbeCompositeTracesComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ScreenProbeCompositeTracesComputeShaderResourcePath);
                hasLoggedMissingScreenProbeCompositeTracesComputeShader = true;
            }

            return screenProbeCompositeTracesComputeShader;
        }

        private static bool TryFindScreenProbeCompositeTracesKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(ScreenProbeCompositeTracesKernelName))
            {
                if (!hasLoggedMissingScreenProbeCompositeTracesKernel)
                {
                    Debug.LogWarning("BurtRP screen probe trace compact compute shader missing kernel: " + ScreenProbeCompositeTracesKernelName);
                    hasLoggedMissingScreenProbeCompositeTracesKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(ScreenProbeCompositeTracesKernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeBentNormalPass : BurtRenderPass
    {
        private const string ScreenProbeTraceCompactComputeShaderResourcePath = "BurtGIScreenProbeBentNormal";
        private const string ScreenProbeBentNormalKernelName = "ScreenProbeShortRangeAOCS";
        private const string ScreenProbeBentNormalFallbackKernelName = "ScreenProbeBentNormalCS";
        private const int DispatchThreadGroupSize = 8;
        private static readonly int BurtGIScreenProbeGridParamsId = Shader.PropertyToID("_BurtGIScreenProbeGridParams");
        private static readonly int BurtGIScreenProbeTraceParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceParams");
        private static readonly int BurtGIScreenProbeScreenDepthTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthTextureId;
        private static readonly int BurtGIScreenProbeWorldNormalTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalTextureId;
        private static readonly int BurtGIScreenProbeWorldPositionTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionTextureId;
        private static readonly int BurtGIScreenProbeTraceRadianceTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceRadianceTextureId;
        private static readonly int BurtGIScreenProbeTraceHitTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceHitTextureId;
        private static readonly int BurtGIScreenProbeBentNormalTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeBentNormalTextureId;
        private static readonly int BurtHiZDepthTextureId = BurtRenderGraphResourceRegistry.HiZDepthTextureId;
        private static readonly int BurtGIScreenProbeHistoryBentNormalTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryBentNormalTexture");
        private static readonly int BurtGIScreenProbeHistoryScreenDepthTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryScreenDepthTexture");
        private static readonly int BurtGIScreenProbeHistoryWorldPositionTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryWorldPositionTexture");
        private static readonly int BurtGIScreenProbeBentNormalParamsId = Shader.PropertyToID("_BurtGIScreenProbeBentNormalParams");
        private static readonly int BurtGIScreenProbeBentNormalParams1Id = Shader.PropertyToID("_BurtGIScreenProbeBentNormalParams1");
        private static readonly int BurtGIScreenProbeScreenTraceParamsId = Shader.PropertyToID("_BurtGIScreenProbeScreenTraceParams");
        private static readonly int BurtGIScreenProbeScreenTraceParams1Id = Shader.PropertyToID("_BurtGIScreenProbeScreenTraceParams1");
        private static readonly int BurtGIScreenProbeTraceModeParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceModeParams");
        private static readonly int BurtGIScreenProbeViewProjectionMatrixId = Shader.PropertyToID("_BurtGIScreenProbeViewProjectionMatrix");
        private static readonly int BurtGIScreenProbePreviousViewProjectionMatrixId = Shader.PropertyToID("_BurtGIPreviousViewProjectionMatrix");
        private static readonly int BurtDeferredCameraWorldPositionId = Shader.PropertyToID("_BurtDeferredCameraWorldPosition");
        private static readonly int BurtGIRadianceCacheClipMapFrameIndexId = Shader.PropertyToID("_BurtGIRadianceCacheClipMapFrameIndex");
        private static ComputeShader screenProbeTraceCompactComputeShader;
        private static bool hasLoggedMissingScreenProbeTraceCompactComputeShader;
        private static bool hasLoggedMissingScreenProbeBentNormalKernel;

        public override string Name => "Burt ScreenProbe Bent Normal";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGIScreenProbeScreenDepth();
            builder.ReadBurtGIScreenProbeWorldNormal();
            builder.ReadBurtGIScreenProbeWorldPosition();
            builder.ReadBurtGIScreenProbeTraceRadiance();
            builder.ReadBurtGIScreenProbeTraceHit();
            if (BurtHiZDepthPassUtility.ShouldUseHiZDepth(builder.Request, builder.Asset))
            {
                builder.ReadHiZDepth();
            }

            builder.WriteBurtGIScreenProbeBentNormal();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(context.Request, context.Asset))
            {
                return;
            }

            var bentNormalTarget = context.BurtGIScreenProbeBentNormalTarget;
            if (!bentNormalTarget.IsValid)
            {
                return;
            }

            var shader = GetScreenProbeTraceCompactComputeShader();
            if (!TryFindScreenProbeBentNormalKernel(shader, out var kernel))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var giSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
            var sourceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, giSettings);
            var probeWidth = Mathf.Max(1, descriptor.width);
            var probeHeight = Mathf.Max(1, descriptor.height);
            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeTraceDescriptor(camera, screenProbeSettings);
            var screenProbeHistory = BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.GetHistoryTextures(context.Request, screenProbeSettings, out var screenProbeHistoryValid);
            var hiZDepthTarget = context.HiZDepthTarget;
            var hiZDepthValid = hiZDepthTarget.IsValid && giSettings.ShortRangeAO && giSettings.ShortRangeAOWeight > 0.0001f;
            var hiZDescriptor = BurtRenderTargetDescriptorUtility.CreateHiZDepthDescriptor(camera);
            var projectionMatrix = GL.GetGPUProjectionMatrix(camera.projectionMatrix, true);
            var viewProjectionMatrix = projectionMatrix * camera.worldToCameraMatrix;
            var screenTraceDistance = screenProbeSettings.TraceScreenDistance;
            var shortRangeAODepthThickness = Mathf.Max(
                0.0001f,
                screenProbeSettings.TraceRelativeDepthThickness * Mathf.Max(0f, giSettings.ShortRangeAOSlopeCompareToleranceScale));
            var cameraPosition = camera != null ? camera.transform.position : Vector3.zero;
            var viewWidth = camera != null ? Mathf.Max(1, camera.pixelWidth) : Mathf.Max(1, probeWidth * screenProbeSettings.SpacingPixels);
            var shortRangeAOMaxScreenTraceFraction = Mathf.Max(1f, screenProbeSettings.SpacingPixels) * 2f / viewWidth;
            var tanHalfHorizontalFov = camera != null && !camera.orthographic
                ? Mathf.Tan(camera.fieldOfView * 0.5f * Mathf.Deg2Rad) * Mathf.Max(camera.aspect, 0.0001f)
                : 0f;
            var shortRangeAOTraceDistanceScale = shortRangeAOMaxScreenTraceFraction * 2f * tanHalfHorizontalFov;
            var placementJitterIndex = screenProbeSettings.FixedJitterIndex >= 0
                ? -(screenProbeSettings.FixedJitterIndex + 1f)
                : Mathf.Max(0, Time.frameCount);

            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(
                probeWidth,
                probeHeight,
                1f / probeWidth,
                1f / probeHeight));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsId, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                Mathf.Max(1, traceDescriptor.width),
                Mathf.Max(1, traceDescriptor.height),
                screenProbeSettings.TraceDistance));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, context.BurtGIScreenProbeScreenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, context.BurtGIScreenProbeWorldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, context.BurtGIScreenProbeWorldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceRadianceTextureId, context.BurtGIScreenProbeTraceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, context.BurtGIScreenProbeTraceHitTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtHiZDepthTextureId, hiZDepthValid ? hiZDepthTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryBentNormalTextureId, screenProbeHistory.BentNormal != null ? (Texture)screenProbeHistory.BentNormal : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryScreenDepthTextureId, screenProbeHistory.ScreenDepth != null ? (Texture)screenProbeHistory.ScreenDepth : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryWorldPositionTextureId, screenProbeHistory.WorldPosition != null ? (Texture)screenProbeHistory.WorldPosition : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeBentNormalTextureId, bentNormalTarget.Identifier);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbeViewProjectionMatrixId, viewProjectionMatrix);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbePreviousViewProjectionMatrixId, screenProbeHistory.PreviousViewProjectionMatrix);
            cmd.SetComputeVectorParam(shader, BurtDeferredCameraWorldPositionId, new Vector4(cameraPosition.x, cameraPosition.y, cameraPosition.z, 1f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeScreenTraceParamsId, new Vector4(
                hiZDepthValid ? Mathf.Clamp01(giSettings.ShortRangeAOWeight) : 0f,
                screenTraceDistance,
                Mathf.Max(1, hiZDescriptor.width),
                Mathf.Max(1, hiZDescriptor.height)));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeScreenTraceParams1Id, new Vector4(
                shortRangeAODepthThickness,
                screenProbeSettings.TraceHistoryDepthTestRelativeThickness,
                screenProbeSettings.TraceHierarchicalMaxIterations,
                shortRangeAOTraceDistanceScale));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceModeParamsId, new Vector4(
                screenProbeSettings.TraceHierarchically ? 1f : 0f,
                1f,
                0f,
                tanHalfHorizontalFov));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeBentNormalParamsId, new Vector4(
                screenProbeHistoryValid ? 1f : 0f,
                screenProbeSettings.TemporalFeedback,
                0.3f,
                hiZDepthValid ? Mathf.Clamp01(giSettings.ShortRangeAOWeight) : 0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeBentNormalParams1Id, new Vector4(
                screenProbeSettings.SpacingPixels,
                placementJitterIndex,
                Mathf.Max(1, sourceDescriptor.width),
                Mathf.Max(1, sourceDescriptor.height)));
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFrameIndexId, Mathf.Max(0, Time.frameCount));
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.CeilToInt(probeWidth / (float)DispatchThreadGroupSize),
                Mathf.CeilToInt(probeHeight / (float)DispatchThreadGroupSize),
                1);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static ComputeShader GetScreenProbeTraceCompactComputeShader()
        {
            if (screenProbeTraceCompactComputeShader != null)
            {
                return screenProbeTraceCompactComputeShader;
            }

            screenProbeTraceCompactComputeShader = Resources.Load<ComputeShader>(ScreenProbeTraceCompactComputeShaderResourcePath);
            if (screenProbeTraceCompactComputeShader == null && !hasLoggedMissingScreenProbeTraceCompactComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ScreenProbeTraceCompactComputeShaderResourcePath);
                hasLoggedMissingScreenProbeTraceCompactComputeShader = true;
            }

            return screenProbeTraceCompactComputeShader;
        }

        private static bool TryFindScreenProbeBentNormalKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(ScreenProbeBentNormalKernelName))
            {
                if (shader.HasKernel(ScreenProbeBentNormalFallbackKernelName))
                {
                    kernel = shader.FindKernel(ScreenProbeBentNormalFallbackKernelName);
                    return kernel >= 0;
                }

                if (!hasLoggedMissingScreenProbeBentNormalKernel)
                {
                    Debug.LogWarning("BurtRP screen probe trace compact compute shader missing kernel: " + ScreenProbeBentNormalKernelName);
                    hasLoggedMissingScreenProbeBentNormalKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(ScreenProbeBentNormalKernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeTemporalFilterPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const int ScreenProbeTemporalFilterPassIndex = 10;
        private const string ScreenProbeUseCountComputeShaderResourcePath = "BurtGIScreenProbeTemporalUseCount";
        private const string ScreenProbeTemporalFilterKernelName = "ScreenProbeFilterTemporalCS";
        private const string ScreenProbeReprojectionKernelName = "ScreenProbeReprojectionCS";
        private const string ScreenProbeDirectionalTemporalKernelName = "ScreenProbeDirectionalTemporalCS";
        private const string ScreenProbeSceneVelocityKernelName = "ScreenProbeSceneVelocityCS";
        private const string ScreenProbeClearUseCountKernelName = "ScreenProbeClearUseCountCS";
        private const string ScreenProbeUseCountScatterKernelName = "XGIScreenProbeUseCountScatterCS";
        private const string ScreenProbeUseCountScatterFallbackKernelName = "ScreenProbeUseCountScatterCS";
        private const int ScreenProbeUseCountThreadGroupSize = 8;
        private static readonly RenderQueueRange ScreenProbeObjectMotionVectorQueueRange = new RenderQueueRange
        {
            lowerBound = 0,
            upperBound = (int)RenderQueue.GeometryLast
        };

        private static readonly RenderQueueRange ScreenProbeTransparentMotionVectorQueueRange = new RenderQueueRange
        {
            lowerBound = (int)RenderQueue.Transparent,
            upperBound = 5000
        };

        private static readonly int BurtGIScreenProbeSceneVelocityTextureId = Shader.PropertyToID("_BurtGIScreenProbeSceneVelocityTexture");
        private static readonly int BurtGIScreenProbeSceneVelocityOutputTextureId = Shader.PropertyToID("_BurtGIScreenProbeSceneVelocityOutputTexture");
        private static readonly int BurtTAACurrentDepthTextureId = Shader.PropertyToID("_BurtTAACurrentDepthTexture");
        private static readonly int BurtTAACurrentViewProjectionId = Shader.PropertyToID("_BurtTAACurrentViewProjection");
        private static readonly int BurtTAACurrentNonJitteredViewProjectionId = Shader.PropertyToID("_BurtTAACurrentNonJitteredViewProjection");
        private static readonly int BurtTAAPreviousNonJitteredViewProjectionId = Shader.PropertyToID("_BurtTAAPreviousNonJitteredViewProjection");
        private static readonly int BurtTAATexelSizeId = Shader.PropertyToID("_BurtTAATexelSize");
        private static readonly int BurtGIScreenProbeViewProjectionMatrixId = Shader.PropertyToID("_BurtGIScreenProbeViewProjectionMatrix");
        private static readonly int BurtGIScreenProbeHistoryBentNormalTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryBentNormalTexture");
        private static readonly int BurtGIScreenProbeHistoryScreenDepthTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryScreenDepthTexture");
        private static readonly int BurtGIScreenProbeHistoryWorldPositionTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryWorldPositionTexture");
        private static readonly int BurtGIScreenProbeHistoryWorldNormalTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryWorldNormalTexture");
        private static readonly int BurtGIScreenProbeHistoryTraceHitTextureId = Shader.PropertyToID("_BurtGIScreenProbeHistoryTraceHitTexture");
        private static readonly int BurtGIScreenProbeHistoryParamsId = Shader.PropertyToID("_BurtGIScreenProbeHistoryParams");
        private static readonly int BurtGIScreenProbeTraceParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceParams");
        private static readonly int BurtGIScreenProbeTraceModeParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceModeParams");
        private static readonly int BurtGIScreenProbeTraceIntensityParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceIntensityParams");
        private static readonly int BurtGIScreenProbeTemporalRadianceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeTemporalRadianceWriteTexture");
        private static readonly int BurtGIScreenProbeTemporalIrradianceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeTemporalIrradianceWriteTexture");
        private static readonly int BurtGIScreenProbeTemporalConfidenceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeTemporalConfidenceWriteTexture");
        private static readonly int BurtGIScreenProbeNumFramesAccumulatedWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeNumFramesAccumulatedWriteTexture");
        private static readonly int BurtGIScreenProbeDirectionalTemporalWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeDirectionalTemporalWriteTexture");
        private static readonly int BurtGIScreenProbeDirectionalTemporalTempTextureId = Shader.PropertyToID("_BurtGIScreenProbeDirectionalTemporalTempTexture");
        private static ComputeShader screenProbeUseCountComputeShader;
        private static bool hasLoggedMissingScreenProbeUseCountComputeShader;
        private static bool hasLoggedMissingScreenProbeUseCountKernel;

        public override string Name => "Burt ScreenProbe Lite Temporal Filter";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGIScreenProbeFilteredRadiance();
            builder.ReadBurtGIScreenProbeFilteredIrradiance();
            builder.ReadBurtGIScreenProbeFilteredConfidence();
            builder.ReadBurtGIScreenProbeScreenDepth();
            builder.ReadBurtGIScreenProbeWorldPosition();
            builder.ReadBurtGIScreenProbeWorldNormal();
            builder.ReadBurtGIScreenProbeBentNormal();
            builder.ReadBurtGIScreenProbeTraceRadiance();
            builder.WriteBurtGIScreenProbeTraceRadiance();
            builder.ReadBurtGIScreenProbeTraceHit();
            builder.ReadBurtGIScreenProbeImportanceRayInfo();
            builder.WriteBurtGIScreenProbeTemporalRadiance();
            builder.WriteBurtGIScreenProbeTemporalIrradiance();
            builder.WriteBurtGIScreenProbeTemporalConfidence();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(
                    context,
                    out var radianceTarget,
                    out var irradianceTarget,
                    out var confidenceTarget,
                    out var screenDepthTarget,
                    out var worldPositionTarget,
                    out var worldNormalTarget,
                    out var bentNormalTarget,
                    out var traceRadianceTarget,
                    out var traceHitTarget,
                    out var importanceRayInfoTarget,
                    out var temporalRadianceTarget,
                    out var temporalIrradianceTarget,
                    out var temporalConfidenceTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            if (!settings.Enabled || !screenProbeSettings.Enabled)
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            var camera = context.Request != null ? context.Request.Camera : null;
            if (material == null || camera == null)
            {
                return;
            }

            var sourceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var probeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeTraceDescriptor(camera, screenProbeSettings);
            var numFramesDescriptor = BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.CreateNumFramesAccumulatedHistoryDescriptor(camera, screenProbeSettings);
            numFramesDescriptor.enableRandomWrite = true;
            var useCountDescriptor = BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.CreateUseCountDescriptor(camera, screenProbeSettings);
            var screenProbeHistory = BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.EnsureHistoryTextures(context.Request, context.Asset, screenProbeSettings, out var screenProbeHistoryValid);
            var cmd = CommandBufferPool.Get(Name);
            cmd.GetTemporaryRT(BurtGIScreenProbeNumFramesAccumulatedTextureId, numFramesDescriptor, FilterMode.Point);
            cmd.GetTemporaryRT(BurtGIScreenProbeUseCountTextureId, useCountDescriptor, FilterMode.Point);
            var useCountValid = screenProbeHistoryValid && screenProbeSettings.TemporalFilter && screenProbeSettings.TemporalReprojection;
            var sceneVelocityId = new RenderTargetIdentifier(Texture2D.blackTexture);
            var sceneVelocityAllocated = false;
            if (useCountValid)
            {
                sceneVelocityAllocated = TryBuildScreenProbeSceneVelocity(
                    context,
                    cmd,
                    camera,
                    useCountDescriptor,
                    screenDepthTarget,
                    worldPositionTarget,
                    screenProbeHistory.PreviousViewProjectionMatrix);
                sceneVelocityId = sceneVelocityAllocated ? new RenderTargetIdentifier(BurtGIScreenProbeSceneVelocityTextureId) : sceneVelocityId;
                useCountValid = TryDispatchScreenProbeUseCount(
                    cmd,
                    useCountDescriptor,
                    worldPositionTarget,
                    screenDepthTarget,
                    screenProbeHistory.PreviousViewProjectionMatrix,
                    sceneVelocityId);
            }

            cmd.SetGlobalTexture(BurtGIScreenProbeUseCountTextureId, new RenderTargetIdentifier(BurtGIScreenProbeUseCountTextureId));
            cmd.SetGlobalTexture(BurtGIScreenProbeSceneVelocityTextureId, sceneVelocityId);
            cmd.SetGlobalVector(BurtGIScreenProbeUseCountParamsId, new Vector4(
                Mathf.Max(1, useCountDescriptor.width),
                Mathf.Max(1, useCountDescriptor.height),
                1f / Mathf.Max(1, useCountDescriptor.width),
                useCountValid ? 1f : 0f));
            TryDispatchScreenProbeDirectionalTemporalFilter(
                cmd,
                screenProbeSettings,
                probeDescriptor,
                traceDescriptor,
                traceRadianceTarget,
                traceHitTarget,
                worldPositionTarget,
                worldNormalTarget,
                sceneVelocityId,
                screenProbeHistory,
                screenProbeHistoryValid);
            if (TryDispatchScreenProbeTemporalFilterCompute(
                    cmd,
                    context,
                    camera,
                    settings,
                    screenProbeSettings,
                    sourceDescriptor,
                    probeDescriptor,
                    traceDescriptor,
                    useCountDescriptor,
                    radianceTarget,
                    irradianceTarget,
                    confidenceTarget,
                    screenDepthTarget,
                    worldPositionTarget,
                    worldNormalTarget,
                    traceRadianceTarget,
                    traceHitTarget,
                    sceneVelocityId,
                    new RenderTargetIdentifier(BurtGIScreenProbeNumFramesAccumulatedTextureId),
                    temporalRadianceTarget,
                    temporalIrradianceTarget,
                    temporalConfidenceTarget,
                    screenProbeHistory,
                    screenProbeHistoryValid))
            {
                cmd.SetGlobalTexture(BurtGIScreenProbeTemporalRadianceTextureId, temporalRadianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeTemporalIrradianceTextureId, temporalIrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeTemporalConfidenceTextureId, temporalConfidenceTarget.Identifier);
                CopyScreenProbeHistory(cmd, camera, temporalRadianceTarget, temporalIrradianceTarget, temporalConfidenceTarget, new RenderTargetIdentifier(BurtGIScreenProbeNumFramesAccumulatedTextureId), screenDepthTarget, worldPositionTarget, worldNormalTarget, bentNormalTarget, traceHitTarget, traceRadianceTarget, screenProbeHistory);
                if (sceneVelocityAllocated)
                {
                    cmd.ReleaseTemporaryRT(BurtGIScreenProbeSceneVelocityTextureId);
                }

                cmd.ReleaseTemporaryRT(BurtGIScreenProbeUseCountTextureId);
                cmd.ReleaseTemporaryRT(BurtGIScreenProbeNumFramesAccumulatedTextureId);
                context.ExecuteLegacyCommandBuffer(cmd);
                context.ReleaseCommandBuffer(cmd);
                return;
            }

            cmd.SetRenderTarget(
                new[]
                {
                    temporalRadianceTarget.Identifier,
                    temporalIrradianceTarget.Identifier,
                    temporalConfidenceTarget.Identifier,
                    new RenderTargetIdentifier(BurtGIScreenProbeNumFramesAccumulatedTextureId),
                },
                new RenderTargetIdentifier(BuiltinRenderTextureType.None));
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, probeDescriptor.width, probeDescriptor.height);
            cmd.SetGlobalTexture(BurtGIScreenProbeRadianceTextureId, radianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeIrradianceTextureId, irradianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeConfidenceTextureId, confidenceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeTraceRadianceTextureId, traceRadianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeImportanceRayInfoTextureId, importanceRayInfoTarget.Identifier);
            cmd.SetGlobalVector(
                BurtGIScreenProbeTraceParamsId,
                new Vector4(
                    BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                    Mathf.Max(1, traceDescriptor.width),
                    Mathf.Max(1, traceDescriptor.height),
                    screenProbeSettings.TraceDistance));
            UploadCameraGlobals(cmd, context.Request, camera, sourceDescriptor);
            UploadSettings(cmd, settings);
            UploadScreenProbeSettings(cmd, screenProbeSettings, probeDescriptor);
            BindScreenProbeHistory(cmd, screenProbeHistory, screenProbeHistoryValid, screenProbeSettings);
            cmd.DrawProcedural(Matrix4x4.identity, material, ScreenProbeTemporalFilterPassIndex, MeshTopology.Triangles, 3, 1);
            cmd.SetGlobalTexture(BurtGIScreenProbeTemporalRadianceTextureId, temporalRadianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeTemporalIrradianceTextureId, temporalIrradianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeTemporalConfidenceTextureId, temporalConfidenceTarget.Identifier);
            CopyScreenProbeHistory(cmd, camera, temporalRadianceTarget, temporalIrradianceTarget, temporalConfidenceTarget, new RenderTargetIdentifier(BurtGIScreenProbeNumFramesAccumulatedTextureId), screenDepthTarget, worldPositionTarget, worldNormalTarget, bentNormalTarget, traceHitTarget, traceRadianceTarget, screenProbeHistory);
            if (sceneVelocityAllocated)
            {
                cmd.ReleaseTemporaryRT(BurtGIScreenProbeSceneVelocityTextureId);
            }

            cmd.ReleaseTemporaryRT(BurtGIScreenProbeUseCountTextureId);
            cmd.ReleaseTemporaryRT(BurtGIScreenProbeNumFramesAccumulatedTextureId);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryDispatchScreenProbeDirectionalTemporalFilter(
            CommandBuffer cmd,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor probeDescriptor,
            RenderTextureDescriptor traceDescriptor,
            BurtRenderTargetHandle traceRadianceTarget,
            BurtRenderTargetHandle traceHitTarget,
            BurtRenderTargetHandle worldPositionTarget,
            BurtRenderTargetHandle worldNormalTarget,
            RenderTargetIdentifier sceneVelocityId,
            BurtScreenSpaceGlobalIlluminationScreenProbeHistoryTextures history,
            bool historyValid)
        {
            var shader = GetScreenProbeUseCountComputeShader();
            if (!screenProbeSettings.TemporalFilter ||
                !historyValid ||
                history.TraceRadiance == null ||
                !TryFindScreenProbeUseCountKernel(shader, ScreenProbeDirectionalTemporalKernelName, out var kernel))
            {
                return false;
            }

            traceDescriptor.depthBufferBits = 0;
            traceDescriptor.msaaSamples = 1;
            traceDescriptor.enableRandomWrite = true;
            cmd.GetTemporaryRT(BurtGIScreenProbeDirectionalTemporalTempTextureId, traceDescriptor, FilterMode.Point);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceRadianceTextureId, traceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryTraceRadianceTextureId, history.TraceRadiance);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryTraceHitTextureId, history.TraceHit != null ? (Texture)history.TraceHit : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, worldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryWorldPositionTextureId, history.WorldPosition != null ? (Texture)history.WorldPosition : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryWorldNormalTextureId, history.WorldNormal != null ? (Texture)history.WorldNormal : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeSceneVelocityTextureId, sceneVelocityId);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeDirectionalTemporalWriteTextureId, new RenderTargetIdentifier(BurtGIScreenProbeDirectionalTemporalTempTextureId));
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbePreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
            cmd.SetComputeVectorParam(shader, CameraWorldPositionId, Shader.GetGlobalVector(CameraWorldPositionId));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(
                Mathf.Max(1, probeDescriptor.width),
                Mathf.Max(1, probeDescriptor.height),
                1f / Mathf.Max(1, probeDescriptor.width),
                1f / Mathf.Max(1, probeDescriptor.height)));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsId, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                Mathf.Max(1, traceDescriptor.width),
                Mathf.Max(1, traceDescriptor.height),
                screenProbeSettings.TraceDistance));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTemporalParamsId, new Vector4(
                screenProbeSettings.TemporalFilterHistoryWeight,
                screenProbeSettings.TemporalReprojection ? 1f : 0f,
                screenProbeSettings.HistoryDistanceThreshold,
                1f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeReprojectionParamsId, new Vector4(
                screenProbeSettings.ReprojectionDepthRejectParamsA,
                screenProbeSettings.ReprojectionDepthRejectParamsB,
                screenProbeSettings.ReprojectionMaxFramesAccumulated,
                Mathf.Cos(screenProbeSettings.TemporalHistoryNormalThreshold * Mathf.Deg2Rad)));
            var groupsX = Mathf.CeilToInt(Mathf.Max(1, traceDescriptor.width) / (float)ScreenProbeUseCountThreadGroupSize);
            var groupsY = Mathf.CeilToInt(Mathf.Max(1, traceDescriptor.height) / (float)ScreenProbeUseCountThreadGroupSize);
            cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIScreenProbeDirectionalTemporalTempTextureId), traceRadianceTarget.Identifier);
            cmd.ReleaseTemporaryRT(BurtGIScreenProbeDirectionalTemporalTempTextureId);
            return true;
        }

        private static bool TryDispatchScreenProbeTemporalFilterCompute(
            CommandBuffer cmd,
            BurtRenderGraphContext context,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor sourceDescriptor,
            RenderTextureDescriptor probeDescriptor,
            RenderTextureDescriptor traceDescriptor,
            RenderTextureDescriptor useCountDescriptor,
            BurtRenderTargetHandle radianceTarget,
            BurtRenderTargetHandle irradianceTarget,
            BurtRenderTargetHandle confidenceTarget,
            BurtRenderTargetHandle screenDepthTarget,
            BurtRenderTargetHandle worldPositionTarget,
            BurtRenderTargetHandle worldNormalTarget,
            BurtRenderTargetHandle traceRadianceTarget,
            BurtRenderTargetHandle traceHitTarget,
            RenderTargetIdentifier sceneVelocityId,
            RenderTargetIdentifier numFramesAccumulatedTarget,
            BurtRenderTargetHandle temporalRadianceTarget,
            BurtRenderTargetHandle temporalIrradianceTarget,
            BurtRenderTargetHandle temporalConfidenceTarget,
            BurtScreenSpaceGlobalIlluminationScreenProbeHistoryTextures history,
            bool historyValid)
        {
            var shader = GetScreenProbeUseCountComputeShader();
            var useReprojectionKernel = historyValid && screenProbeSettings.TemporalFilter && screenProbeSettings.TemporalReprojection;
            var temporalKernelName = useReprojectionKernel ? ScreenProbeReprojectionKernelName : ScreenProbeTemporalFilterKernelName;
            if (!TryFindScreenProbeUseCountKernel(shader, temporalKernelName, ScreenProbeTemporalFilterKernelName, out var kernel))
            {
                return false;
            }

            var width = Mathf.Max(1, probeDescriptor.width);
            var height = Mathf.Max(1, probeDescriptor.height);
            var groupsX = Mathf.CeilToInt(width / (float)ScreenProbeUseCountThreadGroupSize);
            var groupsY = Mathf.CeilToInt(height / (float)ScreenProbeUseCountThreadGroupSize);
            var temporalAA = context.Request != null ? context.Request.TemporalAA : null;
            var useTemporalAA = temporalAA != null && temporalAA.Enabled;
            var viewMatrix = useTemporalAA ? temporalAA.ViewMatrix : camera.worldToCameraMatrix;
            var viewProjectionMatrix = useTemporalAA
                ? temporalAA.CurrentViewProjectionMatrix
                : GL.GetGPUProjectionMatrix(camera.projectionMatrix, true) * viewMatrix;
            var inverseViewProjectionMatrix = useTemporalAA
                ? temporalAA.InverseCurrentViewProjectionMatrix
                : viewProjectionMatrix.inverse;
            var cameraPosition = camera.transform.position;
            var useCountWidth = Mathf.Max(1, useCountDescriptor.width);
            var useCountHeight = Mathf.Max(1, useCountDescriptor.height);
            var tanHalfHorizontalFov = Mathf.Tan(camera.fieldOfView * 0.5f * Mathf.Deg2Rad) * Mathf.Max(0.0001f, camera.aspect);

            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeRadianceTextureId, radianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeIrradianceTextureId, irradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeConfidenceTextureId, confidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, screenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, worldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceRadianceTextureId, traceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeSceneVelocityTextureId, sceneVelocityId);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeUseCountTextureId, new RenderTargetIdentifier(BurtGIScreenProbeUseCountTextureId));
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryRadianceTextureId, historyValid && history.Radiance != null ? (Texture)history.Radiance : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryIrradianceTextureId, historyValid && history.Irradiance != null ? (Texture)history.Irradiance : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryConfidenceTextureId, historyValid && history.Confidence != null ? (Texture)history.Confidence : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryNumFramesAccumulatedTextureId, historyValid && history.NumFramesAccumulated != null ? (Texture)history.NumFramesAccumulated : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryScreenDepthTextureId, historyValid && history.ScreenDepth != null ? (Texture)history.ScreenDepth : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryWorldPositionTextureId, historyValid && history.WorldPosition != null ? (Texture)history.WorldPosition : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryWorldNormalTextureId, historyValid && history.WorldNormal != null ? (Texture)history.WorldNormal : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHistoryTraceHitTextureId, historyValid && history.TraceHit != null ? (Texture)history.TraceHit : Texture2D.blackTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTemporalRadianceWriteTextureId, temporalRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTemporalIrradianceWriteTextureId, temporalIrradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTemporalConfidenceWriteTextureId, temporalConfidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeNumFramesAccumulatedWriteTextureId, numFramesAccumulatedTarget);
            cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, inverseViewProjectionMatrix);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbeViewProjectionMatrixId, viewProjectionMatrix);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbePreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
            cmd.SetComputeVectorParam(shader, CameraWorldPositionId, new Vector4(cameraPosition.x, cameraPosition.y, cameraPosition.z, 1f));
            cmd.SetComputeVectorParam(shader, BurtGISourceTexelSizeId, new Vector4(1f / Mathf.Max(1, sourceDescriptor.width), 1f / Mathf.Max(1, sourceDescriptor.height), Mathf.Max(1, sourceDescriptor.width), Mathf.Max(1, sourceDescriptor.height)));
            BurtScreenSpaceGlobalIlluminationPassUtility.GetCameraTargetSize(camera, out var cameraWidth, out var cameraHeight);
            cmd.SetComputeVectorParam(shader, DeferredScreenSizeId, new Vector4(cameraWidth, cameraHeight, 1f / cameraWidth, 1f / cameraHeight));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(width, height, 1f / width, 1f / height));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsId, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                Mathf.Max(1, traceDescriptor.width),
                Mathf.Max(1, traceDescriptor.height),
                screenProbeSettings.TraceDistance));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceModeParamsId, new Vector4(
                screenProbeSettings.TraceHierarchically ? 1f : 0f,
                screenProbeSettings.ScreenTraceThicknessScaleWhenNoFallback,
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeGatherMaxRayIntensity(screenProbeSettings, camera),
                tanHalfHorizontalFov));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceIntensityParamsId, new Vector4(screenProbeSettings.TraceRadianceIntensityScale, 0f, 0f, 0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeUseCountParamsId, new Vector4(
                useCountWidth,
                useCountHeight,
                1f / useCountWidth,
                historyValid && screenProbeSettings.TemporalFilter && screenProbeSettings.TemporalReprojection ? 1f : 0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeHistoryParamsId, new Vector4(history.HistoryExposureCorrection, 0f, 0f, 0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTemporalParamsId, new Vector4(
                screenProbeSettings.TemporalFilterHistoryWeight,
                historyValid && screenProbeSettings.TemporalFilter && screenProbeSettings.TemporalReprojection ? 1f : 0f,
                screenProbeSettings.HistoryDistanceThreshold,
                screenProbeSettings.TemporalFilter ? 1f : 0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeReprojectionParamsId, new Vector4(
                screenProbeSettings.ReprojectionDepthRejectParamsA,
                screenProbeSettings.ReprojectionDepthRejectParamsB,
                screenProbeSettings.ReprojectionMaxFramesAccumulated,
                Mathf.Cos(screenProbeSettings.TemporalHistoryNormalThreshold * Mathf.Deg2Rad)));
            cmd.SetComputeVectorParam(shader, BurtGIParams0Id, new Vector4(settings.Radius, settings.SampleCount, settings.MaxSteps, settings.Thickness));
            cmd.SetComputeVectorParam(shader, BurtGIParams1Id, new Vector4(settings.Intensity, settings.SkyFallback, settings.Blur ? 1f : 0f, settings.BlurSharpness));
            cmd.SetComputeVectorParam(shader, BurtGIParams2Id, new Vector4(Time.frameCount & 1023, settings.NormalWeight, settings.DistanceFade, settings.RadianceClamp));
            cmd.SetComputeVectorParam(shader, BurtGIParams3Id, new Vector4(settings.SpatialDenoiseRadius, settings.SpatialDenoiseStrength, settings.TemporalVarianceClamp, settings.TemporalHitRejection));
            cmd.SetComputeVectorParam(shader, BurtGIParams4Id, new Vector4(settings.LeakGuardStrength, settings.EdgeFadeStrength, settings.NormalConeTightness, settings.SkyEdgeSuppression));
            cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
            return true;
        }

        private static bool TryBuildScreenProbeSceneVelocity(
            BurtRenderGraphContext context,
            CommandBuffer cmd,
            Camera camera,
            RenderTextureDescriptor useCountDescriptor,
            BurtRenderTargetHandle screenDepthTarget,
            BurtRenderTargetHandle worldPositionTarget,
            Matrix4x4 previousViewProjectionMatrix)
        {
            var shader = GetScreenProbeUseCountComputeShader();
            if (!TryFindScreenProbeUseCountKernel(shader, ScreenProbeSceneVelocityKernelName, out var velocityKernel))
            {
                return false;
            }

            var width = Mathf.Max(1, useCountDescriptor.width);
            var height = Mathf.Max(1, useCountDescriptor.height);
            var descriptor = useCountDescriptor;
            descriptor.depthBufferBits = 0;
            descriptor.msaaSamples = 1;
            var velocityFormat = SystemInfo.IsFormatSupported(GraphicsFormat.R16G16B16A16_SFloat, FormatUsage.Render) &&
                SystemInfo.IsFormatSupported(GraphicsFormat.R16G16B16A16_SFloat, FormatUsage.LoadStore)
                    ? GraphicsFormat.R16G16B16A16_SFloat
                    : (SystemInfo.IsFormatSupported(GraphicsFormat.R32G32B32A32_SFloat, FormatUsage.Render) &&
                        SystemInfo.IsFormatSupported(GraphicsFormat.R32G32B32A32_SFloat, FormatUsage.LoadStore)
                            ? GraphicsFormat.R32G32B32A32_SFloat
                            : GraphicsFormat.None);
            if (velocityFormat == GraphicsFormat.None)
            {
                return false;
            }

            descriptor.graphicsFormat = velocityFormat;
            descriptor.enableRandomWrite = true;
            cmd.GetTemporaryRT(BurtGIScreenProbeSceneVelocityTextureId, descriptor, FilterMode.Point);

            var sceneVelocityTarget = new RenderTargetIdentifier(BurtGIScreenProbeSceneVelocityTextureId);
            var groupsX = Mathf.CeilToInt(width / (float)ScreenProbeUseCountThreadGroupSize);
            var groupsY = Mathf.CeilToInt(height / (float)ScreenProbeUseCountThreadGroupSize);
            var useCountParams = new Vector4(width, height, 1f / width, 1f / height);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeUseCountParamsId, useCountParams);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbePreviousViewProjectionMatrixId, previousViewProjectionMatrix);
            cmd.SetComputeTextureParam(shader, velocityKernel, BurtGIScreenProbeSceneVelocityOutputTextureId, sceneVelocityTarget);
            cmd.SetComputeTextureParam(shader, velocityKernel, BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, velocityKernel, BurtGIScreenProbeScreenDepthTextureId, screenDepthTarget.Identifier);
            cmd.DispatchCompute(shader, velocityKernel, groupsX, groupsY, 1);

            DrawScreenProbeObjectMotionVectors(context, cmd, camera, sceneVelocityTarget, screenDepthTarget, previousViewProjectionMatrix, width, height);
            return true;
        }

        internal static void DrawScreenProbeObjectMotionVectors(
            BurtRenderGraphContext context,
            CommandBuffer cmd,
            Camera camera,
            RenderTargetIdentifier sceneVelocityTarget,
            BurtRenderTargetHandle screenDepthTarget,
            Matrix4x4 previousViewProjectionMatrix,
            int width,
            int height)
        {
            if (context == null || context.Request == null || camera == null || !screenDepthTarget.IsValid)
            {
                return;
            }

            var currentViewProjection = ResolveCurrentViewProjection(camera);
            var temporalAA = context.Request.TemporalAA;
            var currentNonJitteredViewProjection = temporalAA != null
                ? temporalAA.CurrentNonJitteredViewProjectionMatrix
                : currentViewProjection;
            var previousNonJitteredViewProjection = temporalAA != null
                ? temporalAA.PreviousNonJitteredViewProjectionMatrix
                : previousViewProjectionMatrix;

            cmd.SetGlobalMatrix(BurtTAACurrentViewProjectionId, temporalAA != null ? temporalAA.CurrentViewProjectionMatrix : currentViewProjection);
            cmd.SetGlobalMatrix(BurtTAACurrentNonJitteredViewProjectionId, currentNonJitteredViewProjection);
            cmd.SetGlobalMatrix(BurtTAAPreviousNonJitteredViewProjectionId, previousNonJitteredViewProjection);
            cmd.SetGlobalVector(BurtTAATexelSizeId, new Vector4(1f / width, 1f / height, width, height));
            cmd.SetGlobalTexture(BurtTAACurrentDepthTextureId, screenDepthTarget.Identifier);
            cmd.SetRenderTarget(sceneVelocityTarget);
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, width, height);

            camera.depthTextureMode |= DepthTextureMode.MotionVectors | DepthTextureMode.Depth;
            BurtDrawingSettingsUtility.RestoreCameraMatricesForMainDraw(context, cmd);
            context.ExecuteLegacyCommandBuffer(cmd);
            cmd.Clear();

            var sortingSettings = new SortingSettings(camera) { criteria = SortingCriteria.CommonOpaque };
            var drawingSettings = new DrawingSettings(new ShaderTagId("BurtMotionVectors"), sortingSettings)
            {
                perObjectData = PerObjectData.MotionVectors,
                enableDynamicBatching = false,
                enableInstancing = true
            };
            var filteringSettings = new FilteringSettings(ScreenProbeObjectMotionVectorQueueRange, camera.cullingMask);
            context.ScriptableContext.DrawRenderers(context.Request.CullingResults, ref drawingSettings, ref filteringSettings);

            var transparentSortingSettings = new SortingSettings(camera) { criteria = SortingCriteria.CommonTransparent };
            var transparentDrawingSettings = new DrawingSettings(new ShaderTagId("BurtTransparentMotionVectors"), transparentSortingSettings)
            {
                perObjectData = PerObjectData.MotionVectors,
                enableDynamicBatching = false,
                enableInstancing = true
            };
            var transparentFilteringSettings = new FilteringSettings(ScreenProbeTransparentMotionVectorQueueRange, camera.cullingMask);
            context.ScriptableContext.DrawRenderers(context.Request.CullingResults, ref transparentDrawingSettings, ref transparentFilteringSettings);

            BurtFurBlurPassUtility.UploadMotionVectorGlobals(cmd, context.Request, width, height);
            cmd.SetRenderTarget(sceneVelocityTarget);
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, width, height);
            BurtMultipassRenderer.DrawAll(cmd, context, BurtMultipassShaderPass.MotionVectors, RenderQueueRange.opaque);
        }

        private static Matrix4x4 ResolveCurrentViewProjection(Camera camera)
        {
            if (camera == null)
            {
                return Matrix4x4.identity;
            }

            return GL.GetGPUProjectionMatrix(camera.projectionMatrix, true) * camera.worldToCameraMatrix;
        }

        private static bool TryDispatchScreenProbeUseCount(
            CommandBuffer cmd,
            RenderTextureDescriptor useCountDescriptor,
            BurtRenderTargetHandle worldPositionTarget,
            BurtRenderTargetHandle screenDepthTarget,
            Matrix4x4 previousViewProjectionMatrix,
            RenderTargetIdentifier sceneVelocityTexture)
        {
            var shader = GetScreenProbeUseCountComputeShader();
            if (!TryFindScreenProbeUseCountKernel(shader, ScreenProbeClearUseCountKernelName, out var clearKernel) ||
                !TryFindScreenProbeUseCountKernel(shader, ScreenProbeUseCountScatterKernelName, ScreenProbeUseCountScatterFallbackKernelName, out var scatterKernel))
            {
                return false;
            }

            var width = Mathf.Max(1, useCountDescriptor.width);
            var height = Mathf.Max(1, useCountDescriptor.height);
            var groupsX = Mathf.CeilToInt(width / (float)ScreenProbeUseCountThreadGroupSize);
            var groupsY = Mathf.CeilToInt(height / (float)ScreenProbeUseCountThreadGroupSize);
            var useCountParams = new Vector4(width, height, 1f / width, 1f / height);
            var useCountTarget = new RenderTargetIdentifier(BurtGIScreenProbeUseCountTextureId);

            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeUseCountParamsId, useCountParams);
            cmd.SetComputeTextureParam(shader, clearKernel, BurtGIScreenProbeUseCountTextureId, useCountTarget);
            cmd.DispatchCompute(shader, clearKernel, groupsX, groupsY, 1);

            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeUseCountParamsId, useCountParams);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbePreviousViewProjectionMatrixId, previousViewProjectionMatrix);
            cmd.SetComputeTextureParam(shader, scatterKernel, BurtGIScreenProbeUseCountTextureId, useCountTarget);
            cmd.SetComputeTextureParam(shader, scatterKernel, BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, scatterKernel, BurtGIScreenProbeScreenDepthTextureId, screenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, scatterKernel, BurtGIScreenProbeSceneVelocityTextureId, sceneVelocityTexture);
            cmd.DispatchCompute(shader, scatterKernel, groupsX, groupsY, 1);
            return true;
        }

        private static ComputeShader GetScreenProbeUseCountComputeShader()
        {
            if (screenProbeUseCountComputeShader != null)
            {
                return screenProbeUseCountComputeShader;
            }

            screenProbeUseCountComputeShader = Resources.Load<ComputeShader>(ScreenProbeUseCountComputeShaderResourcePath);
            if (screenProbeUseCountComputeShader == null && !hasLoggedMissingScreenProbeUseCountComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ScreenProbeUseCountComputeShaderResourcePath);
                hasLoggedMissingScreenProbeUseCountComputeShader = true;
            }

            return screenProbeUseCountComputeShader;
        }

        private static bool TryFindScreenProbeUseCountKernel(ComputeShader shader, string kernelName, out int kernel)
        {
            return TryFindScreenProbeUseCountKernel(shader, kernelName, null, out kernel);
        }

        private static bool TryFindScreenProbeUseCountKernel(ComputeShader shader, string kernelName, string fallbackKernelName, out int kernel)
        {
            kernel = -1;
            if (shader == null || string.IsNullOrEmpty(kernelName))
            {
                return false;
            }

            var resolvedKernelName = kernelName;
            if (!shader.HasKernel(resolvedKernelName) && !string.IsNullOrEmpty(fallbackKernelName))
            {
                resolvedKernelName = fallbackKernelName;
            }

            if (!shader.HasKernel(resolvedKernelName))
            {
                if (!hasLoggedMissingScreenProbeUseCountKernel)
                {
                    Debug.LogWarning("BurtRP screen probe use-count compute shader missing kernel: " + kernelName);
                    hasLoggedMissingScreenProbeUseCountKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(resolvedKernelName);
            return kernel >= 0;
        }

        private static void BindScreenProbeHistory(
            CommandBuffer cmd,
            BurtScreenSpaceGlobalIlluminationScreenProbeHistoryTextures history,
            bool historyValid,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings)
        {
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryRadianceTextureId, history.Radiance != null ? (Texture)history.Radiance : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryIrradianceTextureId, history.Irradiance != null ? (Texture)history.Irradiance : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryConfidenceTextureId, history.Confidence != null ? (Texture)history.Confidence : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryNumFramesAccumulatedTextureId, history.NumFramesAccumulated != null ? (Texture)history.NumFramesAccumulated : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryScreenDepthTextureId, history.ScreenDepth != null ? (Texture)history.ScreenDepth : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryWorldPositionTextureId, history.WorldPosition != null ? (Texture)history.WorldPosition : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryWorldNormalTextureId, history.WorldNormal != null ? (Texture)history.WorldNormal : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryBentNormalTextureId, history.BentNormal != null ? (Texture)history.BentNormal : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHistoryTraceHitTextureId, history.TraceHit != null ? (Texture)history.TraceHit : Texture2D.blackTexture);
            cmd.SetGlobalMatrix(BurtGIScreenProbePreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
            cmd.SetGlobalVector(BurtGIScreenProbeHistoryParamsId, new Vector4(history.HistoryExposureCorrection, 0f, 0f, 0f));
            cmd.SetGlobalVector(BurtGIScreenProbeTemporalParamsId, new Vector4(
                screenProbeSettings.TemporalFilterHistoryWeight,
                historyValid && screenProbeSettings.TemporalFilter && screenProbeSettings.TemporalReprojection ? 1f : 0f,
                screenProbeSettings.HistoryDistanceThreshold,
                screenProbeSettings.TemporalFilter ? 1f : 0f));
            cmd.SetGlobalVector(BurtGIScreenProbeReprojectionParamsId, new Vector4(
                screenProbeSettings.ReprojectionDepthRejectParamsA,
                screenProbeSettings.ReprojectionDepthRejectParamsB,
                screenProbeSettings.ReprojectionMaxFramesAccumulated,
                Mathf.Cos(screenProbeSettings.TemporalHistoryNormalThreshold * Mathf.Deg2Rad)));
        }

        private static void CopyScreenProbeHistory(
            CommandBuffer cmd,
            Camera camera,
            BurtRenderTargetHandle radianceTarget,
            BurtRenderTargetHandle irradianceTarget,
            BurtRenderTargetHandle confidenceTarget,
            RenderTargetIdentifier numFramesAccumulatedTarget,
            BurtRenderTargetHandle screenDepthTarget,
            BurtRenderTargetHandle worldPositionTarget,
            BurtRenderTargetHandle worldNormalTarget,
            BurtRenderTargetHandle bentNormalTarget,
            BurtRenderTargetHandle traceHitTarget,
            BurtRenderTargetHandle traceRadianceTarget,
            BurtScreenSpaceGlobalIlluminationScreenProbeHistoryTextures history)
        {
            if (history.Radiance == null ||
                history.Irradiance == null ||
                history.Confidence == null ||
                history.NumFramesAccumulated == null ||
                history.ScreenDepth == null ||
                history.WorldPosition == null ||
                history.WorldNormal == null ||
                history.BentNormal == null ||
                history.TraceHit == null ||
                history.TraceRadiance == null)
            {
                BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.InvalidateHistory(camera, "HistoryMissing");
                return;
            }

            cmd.CopyTexture(radianceTarget.Identifier, new RenderTargetIdentifier(history.Radiance));
            cmd.CopyTexture(irradianceTarget.Identifier, new RenderTargetIdentifier(history.Irradiance));
            cmd.CopyTexture(confidenceTarget.Identifier, new RenderTargetIdentifier(history.Confidence));
            cmd.CopyTexture(numFramesAccumulatedTarget, new RenderTargetIdentifier(history.NumFramesAccumulated));
            cmd.CopyTexture(screenDepthTarget.Identifier, new RenderTargetIdentifier(history.ScreenDepth));
            cmd.CopyTexture(worldPositionTarget.Identifier, new RenderTargetIdentifier(history.WorldPosition));
            cmd.CopyTexture(worldNormalTarget.Identifier, new RenderTargetIdentifier(history.WorldNormal));
            cmd.CopyTexture(bentNormalTarget.Identifier, new RenderTargetIdentifier(history.BentNormal));
            cmd.CopyTexture(traceHitTarget.Identifier, new RenderTargetIdentifier(history.TraceHit));
            cmd.CopyTexture(traceRadianceTarget.Identifier, new RenderTargetIdentifier(history.TraceRadiance));
            BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.MarkHistoryValid(camera);
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle radianceTarget,
            out BurtRenderTargetHandle irradianceTarget,
            out BurtRenderTargetHandle confidenceTarget,
            out BurtRenderTargetHandle screenDepthTarget,
            out BurtRenderTargetHandle worldPositionTarget,
            out BurtRenderTargetHandle worldNormalTarget,
            out BurtRenderTargetHandle bentNormalTarget,
            out BurtRenderTargetHandle traceRadianceTarget,
            out BurtRenderTargetHandle traceHitTarget,
            out BurtRenderTargetHandle importanceRayInfoTarget,
            out BurtRenderTargetHandle temporalRadianceTarget,
            out BurtRenderTargetHandle temporalIrradianceTarget,
            out BurtRenderTargetHandle temporalConfidenceTarget)
        {
            radianceTarget = context != null ? context.BurtGIScreenProbeFilteredRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeFilteredRadianceName);
            irradianceTarget = context != null ? context.BurtGIScreenProbeFilteredIrradianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeFilteredIrradianceName);
            confidenceTarget = context != null ? context.BurtGIScreenProbeFilteredConfidenceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeFilteredConfidenceName);
            screenDepthTarget = context != null ? context.BurtGIScreenProbeScreenDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthName);
            worldPositionTarget = context != null ? context.BurtGIScreenProbeWorldPositionTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionName);
            worldNormalTarget = context != null ? context.BurtGIScreenProbeWorldNormalTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalName);
            bentNormalTarget = context != null ? context.BurtGIScreenProbeBentNormalTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeBentNormalName);
            traceRadianceTarget = context != null ? context.BurtGIScreenProbeTraceRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceRadianceName);
            traceHitTarget = context != null ? context.BurtGIScreenProbeTraceHitTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceHitName);
            importanceRayInfoTarget = context != null ? context.BurtGIScreenProbeImportanceRayInfoTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeImportanceRayInfoName);
            temporalRadianceTarget = context != null ? context.BurtGIScreenProbeTemporalRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeTemporalRadianceName);
            temporalIrradianceTarget = context != null ? context.BurtGIScreenProbeTemporalIrradianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeTemporalIrradianceName);
            temporalConfidenceTarget = context != null ? context.BurtGIScreenProbeTemporalConfidenceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeTemporalConfidenceName);

            return radianceTarget.IsValid &&
                irradianceTarget.IsValid &&
                confidenceTarget.IsValid &&
                screenDepthTarget.IsValid &&
                worldPositionTarget.IsValid &&
                worldNormalTarget.IsValid &&
                bentNormalTarget.IsValid &&
                traceRadianceTarget.IsValid &&
                traceHitTarget.IsValid &&
                importanceRayInfoTarget.IsValid &&
                temporalRadianceTarget.IsValid &&
                temporalIrradianceTarget.IsValid &&
                temporalConfidenceTarget.IsValid;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationScreenProbeSpatialFilterPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const int ScreenProbeSpatialFilterPassIndex = 11;
        private const string ScreenProbeSpatialFilterComputeShaderResourcePath = "BurtGIScreenProbeSpatialFilter";
        private const string ScreenProbeSpatialFilterKernelName = "ScreenProbeFilterSpatialCS";
        private const string ScreenProbeDirectionalSpatialFilterKernelName = "ScreenProbeDirectionalSpatialCS";
        private const int ScreenProbeSpatialFilterThreadGroupSize = 8;
        private static readonly int BurtGIScreenProbeTraceParamsId = Shader.PropertyToID("_BurtGIScreenProbeTraceParams");
        private static readonly int BurtGIScreenProbeSpatialTemp0RadianceTextureId = Shader.PropertyToID("_BurtGIScreenProbeSpatialTemp0RadianceTexture");
        private static readonly int BurtGIScreenProbeSpatialTemp0IrradianceTextureId = Shader.PropertyToID("_BurtGIScreenProbeSpatialTemp0IrradianceTexture");
        private static readonly int BurtGIScreenProbeSpatialTemp0ConfidenceTextureId = Shader.PropertyToID("_BurtGIScreenProbeSpatialTemp0ConfidenceTexture");
        private static readonly int BurtGIScreenProbeSpatialTemp1RadianceTextureId = Shader.PropertyToID("_BurtGIScreenProbeSpatialTemp1RadianceTexture");
        private static readonly int BurtGIScreenProbeSpatialTemp1IrradianceTextureId = Shader.PropertyToID("_BurtGIScreenProbeSpatialTemp1IrradianceTexture");
        private static readonly int BurtGIScreenProbeSpatialTemp1ConfidenceTextureId = Shader.PropertyToID("_BurtGIScreenProbeSpatialTemp1ConfidenceTexture");
        private static readonly int BurtGIScreenProbeFilteredRadianceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeFilteredRadianceWriteTexture");
        private static readonly int BurtGIScreenProbeFilteredIrradianceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeFilteredIrradianceWriteTexture");
        private static readonly int BurtGIScreenProbeFilteredConfidenceWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeFilteredConfidenceWriteTexture");
        private static readonly int BurtGIScreenProbeDirectionalSpatialSourceTextureId = Shader.PropertyToID("_BurtGIScreenProbeDirectionalSpatialSourceTexture");
        private static readonly int BurtGIScreenProbeDirectionalSpatialWriteTextureId = Shader.PropertyToID("_BurtGIScreenProbeDirectionalSpatialWriteTexture");
        private static readonly int BurtGIScreenProbeDirectionalSpatialTemp0TextureId = Shader.PropertyToID("_BurtGIScreenProbeDirectionalSpatialTemp0Texture");
        private static readonly int BurtGIScreenProbeDirectionalSpatialTemp1TextureId = Shader.PropertyToID("_BurtGIScreenProbeDirectionalSpatialTemp1Texture");
        private static ComputeShader screenProbeSpatialFilterComputeShader;
        private static bool hasLoggedMissingScreenProbeSpatialFilterComputeShader;
        private static bool hasLoggedMissingScreenProbeSpatialFilterKernel;

        public override string Name => "Burt ScreenProbe Lite Spatial Filter";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGIScreenProbeTemporalRadiance();
            builder.ReadBurtGIScreenProbeTemporalIrradiance();
            builder.ReadBurtGIScreenProbeTemporalConfidence();
            builder.ReadBurtGIScreenProbeScreenDepth();
            builder.ReadBurtGIScreenProbeWorldPosition();
            builder.ReadBurtGIScreenProbeWorldNormal();
            builder.ReadBurtGIScreenProbeHitDistance();
            builder.ReadBurtGIScreenProbeTraceHit();
            builder.ReadBurtGIScreenProbeTraceRadiance();
            builder.WriteBurtGIScreenProbeTraceRadiance();
            builder.WriteBurtGIScreenProbeFilteredRadiance();
            builder.WriteBurtGIScreenProbeFilteredIrradiance();
            builder.WriteBurtGIScreenProbeFilteredConfidence();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(
                    context,
                    out var temporalRadianceTarget,
                    out var temporalIrradianceTarget,
                    out var temporalConfidenceTarget,
                    out var screenDepthTarget,
                    out var worldPositionTarget,
                    out var worldNormalTarget,
                    out var hitDistanceTarget,
                    out var traceHitTarget,
                    out var filteredRadianceTarget,
                    out var filteredIrradianceTarget,
                    out var filteredConfidenceTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            if (!settings.Enabled || !screenProbeSettings.Enabled)
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            if (camera == null)
            {
                return;
            }

            var probeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeTraceDescriptor(camera, screenProbeSettings);
            var cmd = context.AcquireCommandBuffer(Name);
            var useSpatialFilter = screenProbeSettings.SpatialFilter && screenProbeSettings.SpatialFilterHalfKernelSize > 0;
            var spatialPassCount = useSpatialFilter ? Mathf.Max(1, screenProbeSettings.SpatialFilterPasses) : 1;
            var needsTemp0 = spatialPassCount > 1;
            var needsTemp1 = spatialPassCount > 2;
            if (needsTemp0)
            {
                AllocateSpatialFilterTemp(cmd, probeDescriptor, BurtGIScreenProbeSpatialTemp0RadianceTextureId, BurtGIScreenProbeSpatialTemp0IrradianceTextureId, BurtGIScreenProbeSpatialTemp0ConfidenceTextureId);
            }

            if (needsTemp1)
            {
                AllocateSpatialFilterTemp(cmd, probeDescriptor, BurtGIScreenProbeSpatialTemp1RadianceTextureId, BurtGIScreenProbeSpatialTemp1IrradianceTextureId, BurtGIScreenProbeSpatialTemp1ConfidenceTextureId);
            }

            TryDispatchScreenProbeDirectionalSpatialFilter(
                cmd,
                screenProbeSettings,
                probeDescriptor,
                traceDescriptor,
                context.BurtGIScreenProbeTraceRadianceTarget,
                traceHitTarget,
                worldPositionTarget,
                worldNormalTarget,
                hitDistanceTarget,
                spatialPassCount);

            if (TryDispatchScreenProbeSpatialFilterCompute(
                    cmd,
                    screenProbeSettings,
                    probeDescriptor,
                    traceDescriptor,
                    temporalRadianceTarget,
                    temporalIrradianceTarget,
                    temporalConfidenceTarget,
                    screenDepthTarget,
                    worldPositionTarget,
                    worldNormalTarget,
                    hitDistanceTarget,
                    traceHitTarget,
                    filteredRadianceTarget,
                    filteredIrradianceTarget,
                    filteredConfidenceTarget,
                    spatialPassCount))
            {
                cmd.SetGlobalTexture(BurtGIScreenProbeFilteredRadianceTextureId, filteredRadianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeFilteredIrradianceTextureId, filteredIrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeFilteredConfidenceTextureId, filteredConfidenceTarget.Identifier);
                if (needsTemp1)
                {
                    ReleaseSpatialFilterTemp(cmd, BurtGIScreenProbeSpatialTemp1RadianceTextureId, BurtGIScreenProbeSpatialTemp1IrradianceTextureId, BurtGIScreenProbeSpatialTemp1ConfidenceTextureId);
                }

                if (needsTemp0)
                {
                    ReleaseSpatialFilterTemp(cmd, BurtGIScreenProbeSpatialTemp0RadianceTextureId, BurtGIScreenProbeSpatialTemp0IrradianceTextureId, BurtGIScreenProbeSpatialTemp0ConfidenceTextureId);
                }

                context.ExecuteLegacyCommandBuffer(cmd);
                context.ReleaseCommandBuffer(cmd);
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            if (material == null)
            {
                if (needsTemp1)
                {
                    ReleaseSpatialFilterTemp(cmd, BurtGIScreenProbeSpatialTemp1RadianceTextureId, BurtGIScreenProbeSpatialTemp1IrradianceTextureId, BurtGIScreenProbeSpatialTemp1ConfidenceTextureId);
                }

                if (needsTemp0)
                {
                    ReleaseSpatialFilterTemp(cmd, BurtGIScreenProbeSpatialTemp0RadianceTextureId, BurtGIScreenProbeSpatialTemp0IrradianceTextureId, BurtGIScreenProbeSpatialTemp0ConfidenceTextureId);
                }

                context.ExecuteLegacyCommandBuffer(cmd);
                context.ReleaseCommandBuffer(cmd);
                return;
            }

            cmd.SetGlobalTexture(BurtGIScreenProbeHitDistanceTextureId, hitDistanceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetGlobalVector(
                BurtGIScreenProbeTraceParamsId,
                new Vector4(
                    BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                    Mathf.Max(1, traceDescriptor.width),
                    Mathf.Max(1, traceDescriptor.height),
                    screenProbeSettings.TraceDistance));
            UploadScreenProbeSettings(cmd, screenProbeSettings, probeDescriptor);
            var sourceRadiance = temporalRadianceTarget.Identifier;
            var sourceIrradiance = temporalIrradianceTarget.Identifier;
            var sourceConfidence = temporalConfidenceTarget.Identifier;
            for (var passIndex = 0; passIndex < spatialPassCount; ++passIndex)
            {
                var finalPass = passIndex == spatialPassCount - 1;
                ResolveSpatialFilterOutputTargets(
                    passIndex,
                    finalPass,
                    filteredRadianceTarget.Identifier,
                    filteredIrradianceTarget.Identifier,
                    filteredConfidenceTarget.Identifier,
                    out var outputRadiance,
                    out var outputIrradiance,
                    out var outputConfidence);
                cmd.SetRenderTarget(
                    new[]
                    {
                        outputRadiance,
                        outputIrradiance,
                        outputConfidence,
                    },
                    new RenderTargetIdentifier(BuiltinRenderTextureType.None));
                BurtRenderTargetDescriptorUtility.SetViewport(cmd, probeDescriptor.width, probeDescriptor.height);
                cmd.SetGlobalTexture(BurtGIScreenProbeTemporalRadianceTextureId, sourceRadiance);
                cmd.SetGlobalTexture(BurtGIScreenProbeTemporalIrradianceTextureId, sourceIrradiance);
                cmd.SetGlobalTexture(BurtGIScreenProbeTemporalConfidenceTextureId, sourceConfidence);
                cmd.DrawProcedural(Matrix4x4.identity, material, ScreenProbeSpatialFilterPassIndex, MeshTopology.Triangles, 3, 1);
                sourceRadiance = outputRadiance;
                sourceIrradiance = outputIrradiance;
                sourceConfidence = outputConfidence;
            }

            cmd.SetGlobalTexture(BurtGIScreenProbeFilteredRadianceTextureId, filteredRadianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeFilteredIrradianceTextureId, filteredIrradianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeFilteredConfidenceTextureId, filteredConfidenceTarget.Identifier);
            if (needsTemp1)
            {
                ReleaseSpatialFilterTemp(cmd, BurtGIScreenProbeSpatialTemp1RadianceTextureId, BurtGIScreenProbeSpatialTemp1IrradianceTextureId, BurtGIScreenProbeSpatialTemp1ConfidenceTextureId);
            }

            if (needsTemp0)
            {
                ReleaseSpatialFilterTemp(cmd, BurtGIScreenProbeSpatialTemp0RadianceTextureId, BurtGIScreenProbeSpatialTemp0IrradianceTextureId, BurtGIScreenProbeSpatialTemp0ConfidenceTextureId);
            }

            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryDispatchScreenProbeDirectionalSpatialFilter(
            CommandBuffer cmd,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor probeDescriptor,
            RenderTextureDescriptor traceDescriptor,
            BurtRenderTargetHandle traceRadianceTarget,
            BurtRenderTargetHandle traceHitTarget,
            BurtRenderTargetHandle worldPositionTarget,
            BurtRenderTargetHandle worldNormalTarget,
            BurtRenderTargetHandle hitDistanceTarget,
            int spatialPassCount)
        {
            var shader = GetScreenProbeSpatialFilterComputeShader();
            if (!screenProbeSettings.SpatialFilter ||
                screenProbeSettings.SpatialFilterHalfKernelSize <= 0 ||
                !traceRadianceTarget.IsValid ||
                !TryFindScreenProbeSpatialFilterKernel(shader, ScreenProbeDirectionalSpatialFilterKernelName, out var kernel))
            {
                return false;
            }

            traceDescriptor.depthBufferBits = 0;
            traceDescriptor.msaaSamples = 1;
            traceDescriptor.enableRandomWrite = true;
            cmd.GetTemporaryRT(BurtGIScreenProbeDirectionalSpatialTemp0TextureId, traceDescriptor, FilterMode.Point);
            if (spatialPassCount > 1)
            {
                cmd.GetTemporaryRT(BurtGIScreenProbeDirectionalSpatialTemp1TextureId, traceDescriptor, FilterMode.Point);
            }

            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, worldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHitDistanceTextureId, hitDistanceTarget.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(
                Mathf.Max(1, probeDescriptor.width),
                Mathf.Max(1, probeDescriptor.height),
                1f / Mathf.Max(1, probeDescriptor.width),
                1f / Mathf.Max(1, probeDescriptor.height)));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeFilterParamsId, new Vector4(
                Mathf.Max(1, spatialPassCount),
                screenProbeSettings.SpatialFilterHalfKernelSize,
                screenProbeSettings.FixupBorders ? 1f : 0f,
                0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeSpatialFilterParamsId, new Vector4(
                screenProbeSettings.SpatialFilterMaxRadianceHitAngle,
                screenProbeSettings.SpatialFilterPositionWeightScale,
                0f,
                0f));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceParamsId, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                Mathf.Max(1, traceDescriptor.width),
                Mathf.Max(1, traceDescriptor.height),
                screenProbeSettings.TraceDistance));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeParamsId, new Vector4(
                screenProbeSettings.SpacingPixels,
                screenProbeSettings.TraceDistance,
                screenProbeSettings.SampleCount,
                screenProbeSettings.ApplyStrength));

            var source = traceRadianceTarget.Identifier;
            var groupsX = Mathf.CeilToInt(Mathf.Max(1, traceDescriptor.width) / (float)ScreenProbeSpatialFilterThreadGroupSize);
            var groupsY = Mathf.CeilToInt(Mathf.Max(1, traceDescriptor.height) / (float)ScreenProbeSpatialFilterThreadGroupSize);
            for (var passIndex = 0; passIndex < spatialPassCount; ++passIndex)
            {
                var outputId = passIndex % 2 == 0
                    ? BurtGIScreenProbeDirectionalSpatialTemp0TextureId
                    : BurtGIScreenProbeDirectionalSpatialTemp1TextureId;
                var output = new RenderTargetIdentifier(outputId);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeDirectionalSpatialSourceTextureId, source);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeDirectionalSpatialWriteTextureId, output);
                cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
                source = output;
            }

            cmd.CopyTexture(source, traceRadianceTarget.Identifier);
            if (spatialPassCount > 1)
            {
                cmd.ReleaseTemporaryRT(BurtGIScreenProbeDirectionalSpatialTemp1TextureId);
            }
            cmd.ReleaseTemporaryRT(BurtGIScreenProbeDirectionalSpatialTemp0TextureId);
            return true;
        }

        private static void AllocateSpatialFilterTemp(
            CommandBuffer cmd,
            RenderTextureDescriptor descriptor,
            int radianceId,
            int irradianceId,
            int confidenceId)
        {
            descriptor.depthBufferBits = 0;
            descriptor.msaaSamples = 1;
            descriptor.enableRandomWrite = true;
            cmd.GetTemporaryRT(radianceId, descriptor, FilterMode.Point);
            cmd.GetTemporaryRT(irradianceId, descriptor, FilterMode.Point);
            cmd.GetTemporaryRT(confidenceId, descriptor, FilterMode.Point);
        }

        private static bool TryDispatchScreenProbeSpatialFilterCompute(
            CommandBuffer cmd,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor probeDescriptor,
            RenderTextureDescriptor traceDescriptor,
            BurtRenderTargetHandle temporalRadianceTarget,
            BurtRenderTargetHandle temporalIrradianceTarget,
            BurtRenderTargetHandle temporalConfidenceTarget,
            BurtRenderTargetHandle screenDepthTarget,
            BurtRenderTargetHandle worldPositionTarget,
            BurtRenderTargetHandle worldNormalTarget,
            BurtRenderTargetHandle hitDistanceTarget,
            BurtRenderTargetHandle traceHitTarget,
            BurtRenderTargetHandle filteredRadianceTarget,
            BurtRenderTargetHandle filteredIrradianceTarget,
            BurtRenderTargetHandle filteredConfidenceTarget,
            int spatialPassCount)
        {
            var shader = GetScreenProbeSpatialFilterComputeShader();
            if (!TryFindScreenProbeSpatialFilterKernel(shader, out var kernel))
            {
                return false;
            }

            var width = Mathf.Max(1, probeDescriptor.width);
            var height = Mathf.Max(1, probeDescriptor.height);
            var groupsX = Mathf.CeilToInt(width / (float)ScreenProbeSpatialFilterThreadGroupSize);
            var groupsY = Mathf.CeilToInt(height / (float)ScreenProbeSpatialFilterThreadGroupSize);
            var useSpatialFilter = screenProbeSettings.SpatialFilter && screenProbeSettings.SpatialFilterHalfKernelSize > 0;
            var placementJitterIndex = screenProbeSettings.FixedJitterIndex >= 0
                ? -(screenProbeSettings.FixedJitterIndex + 1f)
                : Mathf.Max(0, Time.frameCount);
            var sourceRadiance = temporalRadianceTarget.Identifier;
            var sourceIrradiance = temporalIrradianceTarget.Identifier;
            var sourceConfidence = temporalConfidenceTarget.Identifier;

            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, screenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldPositionTextureId, worldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, worldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHitDistanceTextureId, hitDistanceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(width, height, 1f / width, 1f / height));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeFilterParamsId, new Vector4(useSpatialFilter ? screenProbeSettings.SpatialFilterPasses : 0f, screenProbeSettings.SpatialFilterHalfKernelSize, screenProbeSettings.FixupBorders ? 1f : 0f, placementJitterIndex));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeSpatialFilterParamsId, new Vector4(screenProbeSettings.SpatialFilterMaxRadianceHitAngle, screenProbeSettings.SpatialFilterPositionWeightScale, 0f, 0f));
            cmd.SetComputeVectorParam(
                shader,
                BurtGIScreenProbeTraceParamsId,
                new Vector4(
                    BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                    Mathf.Max(1, traceDescriptor.width),
                    Mathf.Max(1, traceDescriptor.height),
                    screenProbeSettings.TraceDistance));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeParamsId, new Vector4(screenProbeSettings.SpacingPixels, screenProbeSettings.TraceDistance, screenProbeSettings.SampleCount, screenProbeSettings.ApplyStrength));

            for (var passIndex = 0; passIndex < spatialPassCount; ++passIndex)
            {
                var finalPass = passIndex == spatialPassCount - 1;
                ResolveSpatialFilterOutputTargets(
                    passIndex,
                    finalPass,
                    filteredRadianceTarget.Identifier,
                    filteredIrradianceTarget.Identifier,
                    filteredConfidenceTarget.Identifier,
                    out var outputRadiance,
                    out var outputIrradiance,
                    out var outputConfidence);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTemporalRadianceTextureId, sourceRadiance);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTemporalIrradianceTextureId, sourceIrradiance);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTemporalConfidenceTextureId, sourceConfidence);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFilteredRadianceWriteTextureId, outputRadiance);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFilteredIrradianceWriteTextureId, outputIrradiance);
                cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFilteredConfidenceWriteTextureId, outputConfidence);
                cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
                sourceRadiance = outputRadiance;
                sourceIrradiance = outputIrradiance;
                sourceConfidence = outputConfidence;
            }

            return true;
        }

        private static ComputeShader GetScreenProbeSpatialFilterComputeShader()
        {
            if (screenProbeSpatialFilterComputeShader != null)
            {
                return screenProbeSpatialFilterComputeShader;
            }

            screenProbeSpatialFilterComputeShader = Resources.Load<ComputeShader>(ScreenProbeSpatialFilterComputeShaderResourcePath);
            if (screenProbeSpatialFilterComputeShader == null && !hasLoggedMissingScreenProbeSpatialFilterComputeShader)
            {
                Debug.LogWarning("BurtRP could not load compute shader resource: " + ScreenProbeSpatialFilterComputeShaderResourcePath);
                hasLoggedMissingScreenProbeSpatialFilterComputeShader = true;
            }

            return screenProbeSpatialFilterComputeShader;
        }

        private static bool TryFindScreenProbeSpatialFilterKernel(ComputeShader shader, out int kernel)
        {
            return TryFindScreenProbeSpatialFilterKernel(shader, ScreenProbeSpatialFilterKernelName, out kernel);
        }

        private static bool TryFindScreenProbeSpatialFilterKernel(ComputeShader shader, string kernelName, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingScreenProbeSpatialFilterKernel)
                {
                    Debug.LogWarning("BurtRP screen probe spatial filter compute shader missing kernel: " + kernelName);
                    hasLoggedMissingScreenProbeSpatialFilterKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }

        private static void ReleaseSpatialFilterTemp(CommandBuffer cmd, int radianceId, int irradianceId, int confidenceId)
        {
            cmd.ReleaseTemporaryRT(radianceId);
            cmd.ReleaseTemporaryRT(irradianceId);
            cmd.ReleaseTemporaryRT(confidenceId);
        }

        private static void ResolveSpatialFilterOutputTargets(
            int passIndex,
            bool finalPass,
            RenderTargetIdentifier finalRadiance,
            RenderTargetIdentifier finalIrradiance,
            RenderTargetIdentifier finalConfidence,
            out RenderTargetIdentifier outputRadiance,
            out RenderTargetIdentifier outputIrradiance,
            out RenderTargetIdentifier outputConfidence)
        {
            if (finalPass)
            {
                outputRadiance = finalRadiance;
                outputIrradiance = finalIrradiance;
                outputConfidence = finalConfidence;
                return;
            }

            if ((passIndex & 1) == 0)
            {
                outputRadiance = new RenderTargetIdentifier(BurtGIScreenProbeSpatialTemp0RadianceTextureId);
                outputIrradiance = new RenderTargetIdentifier(BurtGIScreenProbeSpatialTemp0IrradianceTextureId);
                outputConfidence = new RenderTargetIdentifier(BurtGIScreenProbeSpatialTemp0ConfidenceTextureId);
                return;
            }

            outputRadiance = new RenderTargetIdentifier(BurtGIScreenProbeSpatialTemp1RadianceTextureId);
            outputIrradiance = new RenderTargetIdentifier(BurtGIScreenProbeSpatialTemp1IrradianceTextureId);
            outputConfidence = new RenderTargetIdentifier(BurtGIScreenProbeSpatialTemp1ConfidenceTextureId);
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle temporalRadianceTarget,
            out BurtRenderTargetHandle temporalIrradianceTarget,
            out BurtRenderTargetHandle temporalConfidenceTarget,
            out BurtRenderTargetHandle screenDepthTarget,
            out BurtRenderTargetHandle worldPositionTarget,
