        private Material screenSpaceGlobalIlluminationMaterial;
        private bool hasLoggedMissingShader;

        protected Material GetScreenSpaceGlobalIlluminationMaterial()
        {
            if (screenSpaceGlobalIlluminationMaterial != null)
            {
                return screenSpaceGlobalIlluminationMaterial;
            }

            var shader = Shader.Find(ScreenSpaceGlobalIlluminationShaderName);
            if (shader == null)
            {
                if (!hasLoggedMissingShader)
                {
                    Debug.LogWarning("BurtRP could not find shader: " + ScreenSpaceGlobalIlluminationShaderName);
                    hasLoggedMissingShader = true;
                }

                return null;
            }

            screenSpaceGlobalIlluminationMaterial = new Material(shader);
            screenSpaceGlobalIlluminationMaterial.hideFlags = HideFlags.HideAndDontSave;
            return screenSpaceGlobalIlluminationMaterial;
        }

        protected static void BindGBufferInputs(
            CommandBuffer cmd,
            BurtRenderTargetHandle gbuffer0Target,
            BurtRenderTargetHandle gbuffer1Target,
            BurtRenderTargetHandle gbuffer2Target,
            BurtRenderTargetHandle gbuffer3Target,
            BurtRenderTargetHandle gbuffer4Target,
            BurtRenderTargetHandle gbuffer5Target)
        {
            cmd.SetGlobalTexture(GBuffer0Id, gbuffer0Target.Identifier);
            cmd.SetGlobalTexture(GBuffer1Id, gbuffer1Target.Identifier);
            cmd.SetGlobalTexture(GBuffer2Id, gbuffer2Target.Identifier);
            cmd.SetGlobalTexture(GBuffer3Id, gbuffer3Target.Identifier);
            cmd.SetGlobalTexture(GBuffer4Id, gbuffer4Target.Identifier);
            cmd.SetGlobalTexture(GBuffer5Id, gbuffer5Target.Identifier);
        }

        protected static void UploadCameraGlobals(CommandBuffer cmd, BurtRenderRequest request, Camera camera, RenderTextureDescriptor descriptor)
        {
            var temporalAA = request != null ? request.TemporalAA : null;
            var useTemporalAA = temporalAA != null && temporalAA.Enabled;
            var viewMatrix = useTemporalAA ? temporalAA.ViewMatrix : camera.worldToCameraMatrix;
            var viewProjectionMatrix = useTemporalAA
                ? temporalAA.CurrentViewProjectionMatrix
                : GL.GetGPUProjectionMatrix(camera.projectionMatrix, true) * viewMatrix;
            var inverseViewProjectionMatrix = useTemporalAA
                ? temporalAA.InverseCurrentViewProjectionMatrix
                : viewProjectionMatrix.inverse;
            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            var cameraPosition = camera.transform.position;

            BurtScreenSpaceGlobalIlluminationPassUtility.GetCameraTargetSize(camera, out var cameraWidth, out var cameraHeight);
            cmd.SetGlobalMatrix(BurtGIViewMatrixId, viewMatrix);
            cmd.SetGlobalMatrix(BurtGIViewProjectionMatrixId, viewProjectionMatrix);
            cmd.SetGlobalMatrix(InverseViewProjectionMatrixId, inverseViewProjectionMatrix);
            cmd.SetGlobalVector(CameraWorldPositionId, new Vector4(cameraPosition.x, cameraPosition.y, cameraPosition.z, 1f));
            cmd.SetGlobalVector(DeferredScreenSizeId, new Vector4(cameraWidth, cameraHeight, 1f / cameraWidth, 1f / cameraHeight));
            cmd.SetGlobalVector(BurtGISourceTexelSizeId, new Vector4(1f / width, 1f / height, width, height));
        }

        protected static void CopyTranslucencyVolumeHistory(
            CommandBuffer cmd,
            Camera camera,
            BurtRenderTargetHandle volume0Target,
            BurtRenderTargetHandle volume1Target,
            BurtGITranslucencyVolumeHistoryTextures history)
        {
            if (history.Volume0 == null || history.Volume1 == null)
            {
                BurtGITranslucencyVolumeHistoryUtility.InvalidateHistory(camera, "HistoryMissing");
                return;
            }

            var history0Target = new RenderTargetIdentifier(history.Volume0);
            var history1Target = new RenderTargetIdentifier(history.Volume1);
            var width = Mathf.Max(1, history.Volume0.width);
            var height = Mathf.Max(1, history.Volume0.height);
            var depth = Mathf.Max(1, history.Volume0.volumeDepth);
            if (!TryCopyTexture3DFloat4(cmd, volume0Target.Identifier, history0Target, width, height, depth))
            {
                cmd.CopyTexture(volume0Target.Identifier, history0Target);
            }

            width = Mathf.Max(1, history.Volume1.width);
            height = Mathf.Max(1, history.Volume1.height);
            depth = Mathf.Max(1, history.Volume1.volumeDepth);
            if (!TryCopyTexture3DFloat4(cmd, volume1Target.Identifier, history1Target, width, height, depth))
            {
                cmd.CopyTexture(volume1Target.Identifier, history1Target);
            }

            BurtGITranslucencyVolumeHistoryUtility.MarkHistoryValid(camera);
        }

        protected internal static bool TryCopyTexture3DFloat4(
            CommandBuffer cmd,
            RenderTargetIdentifier source,
            RenderTargetIdentifier destination,
            int width,
            int height,
            int depth)
        {
            return TryCopyTexture3DFloat4Mip(cmd, source, destination, width, height, depth, 0);
        }

        protected internal static bool TryCopyTexture3DFloat4Mips(
            CommandBuffer cmd,
            RenderTargetIdentifier source,
            RenderTargetIdentifier destination,
            int width,
            int height,
            int depth,
            int mipCount)
        {
            mipCount = Mathf.Max(1, mipCount);
            for (var mip = 0; mip < mipCount; ++mip)
            {
                var mipWidth = Mathf.Max(1, width >> mip);
                var mipHeight = Mathf.Max(1, height >> mip);
                var mipDepth = Mathf.Max(1, depth >> mip);
                if (!TryCopyTexture3DFloat4Mip(cmd, source, destination, mipWidth, mipHeight, mipDepth, mip))
                {
                    return false;
                }
            }

            return true;
        }

        protected internal static bool TryCopyTexture3DUInt(
            CommandBuffer cmd,
            RenderTargetIdentifier source,
            RenderTargetIdentifier destination,
            int width,
            int height,
            int depth)
        {
            return TryCopyTexture3DUIntMip(cmd, source, destination, width, height, depth, 0);
        }

        protected internal static bool TryCopyTexture3DUIntMips(
            CommandBuffer cmd,
            RenderTargetIdentifier source,
            RenderTargetIdentifier destination,
            int width,
            int height,
            int depth,
            int mipCount)
        {
            mipCount = Mathf.Max(1, mipCount);
            for (var mip = 0; mip < mipCount; ++mip)
            {
                var mipWidth = Mathf.Max(1, width >> mip);
                var mipHeight = Mathf.Max(1, height >> mip);
                var mipDepth = Mathf.Max(1, depth >> mip);
                if (!TryCopyTexture3DUIntMip(cmd, source, destination, mipWidth, mipHeight, mipDepth, mip))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool TryCopyTexture3DFloat4Mip(
            CommandBuffer cmd,
            RenderTargetIdentifier source,
            RenderTargetIdentifier destination,
            int width,
            int height,
            int depth,
            int mip)
        {
            var shader = GetCopyTexture3DComputeShader();
            if (cmd == null || shader == null || !TryFindCopyTexture3DFloat4Kernel(shader, out var kernel))
            {
                return false;
            }

            width = Mathf.Max(1, width);
            height = Mathf.Max(1, height);
            depth = Mathf.Max(1, depth);
            mip = Mathf.Max(0, mip);
            cmd.SetComputeTextureParam(shader, kernel, BurtGICopyTexture3DSrcFloat4Id, source, mip);
            cmd.SetComputeTextureParam(shader, kernel, BurtGICopyTexture3DDstFloat4Id, destination, mip);
            cmd.SetComputeVectorParam(shader, BurtGICopyTexture3DSizeId, new Vector4(width, height, depth, 0f));
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (width + CopyTexture3DComputeThreadGroupSize - 1) / CopyTexture3DComputeThreadGroupSize),
                Mathf.Max(1, (height + CopyTexture3DComputeThreadGroupSize - 1) / CopyTexture3DComputeThreadGroupSize),
                Mathf.Max(1, (depth + CopyTexture3DComputeThreadGroupSize - 1) / CopyTexture3DComputeThreadGroupSize));
            return true;
        }

        private static bool TryCopyTexture3DUIntMip(
            CommandBuffer cmd,
            RenderTargetIdentifier source,
            RenderTargetIdentifier destination,
            int width,
            int height,
            int depth,
            int mip)
        {
            var shader = GetCopyTexture3DComputeShader();
            if (cmd == null || shader == null || !TryFindCopyTexture3DUIntKernel(shader, out var kernel))
            {
                return false;
            }

            width = Mathf.Max(1, width);
            height = Mathf.Max(1, height);
            depth = Mathf.Max(1, depth);
            mip = Mathf.Max(0, mip);
            cmd.SetComputeTextureParam(shader, kernel, BurtGICopyTexture3DSrcUIntId, source, mip);
            cmd.SetComputeTextureParam(shader, kernel, BurtGICopyTexture3DDstUIntId, destination, mip);
            cmd.SetComputeVectorParam(shader, BurtGICopyTexture3DSizeId, new Vector4(width, height, depth, 0f));
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (width + CopyTexture3DComputeThreadGroupSize - 1) / CopyTexture3DComputeThreadGroupSize),
