        protected static void UploadSettings(CommandBuffer cmd, BurtScreenSpaceGlobalIlluminationSettings settings)
        {
            cmd.SetGlobalVector(BurtGIParams0Id, new Vector4(settings.Radius, settings.SampleCount, settings.MaxSteps, settings.Thickness));
            cmd.SetGlobalVector(BurtGIParams1Id, new Vector4(settings.Intensity, settings.SkyFallback, settings.Blur ? 1f : 0f, settings.BlurSharpness));
            cmd.SetGlobalVector(BurtGIParams2Id, new Vector4(Time.frameCount & 1023, settings.NormalWeight, settings.DistanceFade, settings.RadianceClamp));
            cmd.SetGlobalVector(BurtGIParams3Id, new Vector4(settings.SpatialDenoiseRadius, settings.SpatialDenoiseStrength, settings.TemporalVarianceClamp, settings.TemporalHitRejection));
            cmd.SetGlobalVector(BurtGIParams4Id, new Vector4(settings.LeakGuardStrength, settings.EdgeFadeStrength, settings.NormalConeTightness, settings.SkyEdgeSuppression));
        }

        protected static void UploadScreenProbeSettings(CommandBuffer cmd, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings, RenderTextureDescriptor descriptor)
        {
            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            var placementJitterIndex = settings.FixedJitterIndex >= 0
                ? -(settings.FixedJitterIndex + 1f)
                : Mathf.Max(0, Time.frameCount);
            cmd.SetGlobalVector(BurtGIScreenProbeParamsId, new Vector4(settings.SpacingPixels, settings.TraceDistance, settings.SampleCount, settings.ApplyStrength));
            cmd.SetGlobalVector(BurtGIScreenProbeGridParamsId, new Vector4(width, height, 1f / width, 1f / height));
            var useSpatialFilter = settings.SpatialFilter && settings.SpatialFilterHalfKernelSize > 0;
            cmd.SetGlobalVector(BurtGIScreenProbeFilterParamsId, new Vector4(useSpatialFilter ? settings.SpatialFilterPasses : 0f, settings.SpatialFilterHalfKernelSize, settings.FixupBorders ? 1f : 0f, placementJitterIndex));
            cmd.SetGlobalVector(BurtGIScreenProbeSpatialFilterParamsId, new Vector4(settings.SpatialFilterMaxRadianceHitAngle, settings.SpatialFilterPositionWeightScale, 0f, 0f));
        }

        protected static bool TryDispatchScreenProbeFixupBordersCompute(
            BurtRenderGraphContext context,
            string passName,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor probeDescriptor,
            RenderTextureDescriptor traceDescriptor,
            BurtRenderTargetHandle filteredRadianceTarget,
            BurtRenderTargetHandle filteredIrradianceTarget,
            BurtRenderTargetHandle filteredConfidenceTarget,
            BurtRenderTargetHandle hitDistanceTarget,
            BurtRenderTargetHandle traceHitTarget,
            BurtRenderTargetHandle fixupRadianceTarget,
            BurtRenderTargetHandle fixupIrradianceTarget,
            BurtRenderTargetHandle fixupConfidenceTarget)
        {
            var shader = GetScreenProbeFilterComputeShader();
            if (shader == null || !TryFindScreenProbeFilterFixupBordersKernel(shader, out var kernel))
            {
                return false;
            }

            var width = Mathf.Max(1, probeDescriptor.width);
            var height = Mathf.Max(1, probeDescriptor.height);
            var traceWidth = Mathf.Max(1, traceDescriptor.width);
            var traceHeight = Mathf.Max(1, traceDescriptor.height);
            var groupsX = Mathf.CeilToInt(width / (float)ScreenProbeFilterFixupBordersComputeThreadGroupSize);
            var groupsY = Mathf.CeilToInt(height / (float)ScreenProbeFilterFixupBordersComputeThreadGroupSize);
            var placementJitterIndex = screenProbeSettings.FixedJitterIndex >= 0
                ? -(screenProbeSettings.FixedJitterIndex + 1f)
                : Mathf.Max(0, Time.frameCount);
            var useSpatialFilter = screenProbeSettings.SpatialFilter && screenProbeSettings.SpatialFilterHalfKernelSize > 0;

            var cmd = context.AcquireCommandBuffer(passName);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFilteredRadianceTextureId, filteredRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFilteredIrradianceTextureId, filteredIrradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFilteredConfidenceTextureId, filteredConfidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeHitDistanceTextureId, hitDistanceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeTraceHitTextureId, traceHitTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFixupRadianceWriteTextureId, fixupRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFixupIrradianceWriteTextureId, fixupIrradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFixupConfidenceWriteTextureId, fixupConfidenceTarget.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(width, height, 1f / width, 1f / height));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeFilterParamsId, new Vector4(useSpatialFilter ? screenProbeSettings.SpatialFilterPasses : 0f, screenProbeSettings.SpatialFilterHalfKernelSize, screenProbeSettings.FixupBorders ? 1f : 0f, placementJitterIndex));
            cmd.SetComputeVectorParam(
                shader,
                BurtGIScreenProbeTraceParamsGlobalId,
                new Vector4(
                    BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings),
                    traceWidth,
                    traceHeight,
                    screenProbeSettings.TraceDistance));
            cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
            cmd.SetGlobalTexture(BurtGIScreenProbeFixupRadianceTextureId, fixupRadianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeFixupIrradianceTextureId, fixupIrradianceTarget.Identifier);
            cmd.SetGlobalTexture(BurtGIScreenProbeFixupConfidenceTextureId, fixupConfidenceTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        protected static bool TryDispatchScreenProbeGenerateMipCompute(
            BurtRenderGraphContext context,
            string passName,
            RenderTextureDescriptor parentDescriptor,
            RenderTextureDescriptor targetDescriptor,
            BurtRenderTargetHandle sourceRadianceTarget,
            BurtRenderTargetHandle sourceIrradianceTarget,
            BurtRenderTargetHandle sourceConfidenceTarget,
            BurtRenderTargetHandle targetRadianceTarget,
            BurtRenderTargetHandle targetIrradianceTarget,
            BurtRenderTargetHandle targetConfidenceTarget,
            int outputRadianceTextureId,
            int outputIrradianceTextureId,
            int outputConfidenceTextureId)
        {
            var shader = GetScreenProbeFilterComputeShader();
            if (shader == null || !TryFindScreenProbeFilterGenerateMipKernel(shader, out var kernel))
            {
                return false;
            }

            var parentWidth = Mathf.Max(1, parentDescriptor.width);
            var parentHeight = Mathf.Max(1, parentDescriptor.height);
            var targetWidth = Mathf.Max(1, targetDescriptor.width);
            var targetHeight = Mathf.Max(1, targetDescriptor.height);
            var groupsX = Mathf.CeilToInt(targetWidth / (float)ScreenProbeFilterGenerateMipComputeThreadGroupSize);
            var groupsY = Mathf.CeilToInt(targetHeight / (float)ScreenProbeFilterGenerateMipComputeThreadGroupSize);
            var cmd = context.AcquireCommandBuffer(passName);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFixupRadianceTextureId, sourceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFixupIrradianceTextureId, sourceIrradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeFixupConfidenceTextureId, sourceConfidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeMipRadianceWriteTextureId, targetRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeMipIrradianceWriteTextureId, targetIrradianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeMipConfidenceWriteTextureId, targetConfidenceTarget.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeGridParamsId, new Vector4(parentWidth, parentHeight, 1f / parentWidth, 1f / parentHeight));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeFilterGenerateMipParamsId, new Vector4(targetWidth, targetHeight, 1f / targetWidth, 1f / targetHeight));
            cmd.DispatchCompute(shader, kernel, groupsX, groupsY, 1);
            cmd.SetGlobalTexture(outputRadianceTextureId, targetRadianceTarget.Identifier);
            cmd.SetGlobalTexture(outputIrradianceTextureId, targetIrradianceTarget.Identifier);
            cmd.SetGlobalTexture(outputConfidenceTextureId, targetConfidenceTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            return true;
        }

        private static ComputeShader GetScreenProbeFilterComputeShader()
        {
            if (screenProbeFilterComputeShader != null)
            {
                return screenProbeFilterComputeShader;
            }

            screenProbeFilterComputeShader = Resources.Load<ComputeShader>(ScreenProbeFilterComputeShaderResourcePath);
            if (screenProbeFilterComputeShader == null && !hasLoggedMissingScreenProbeFilterComputeShader)
            {
                Debug.LogWarning("BurtRP could not load compute shader resource: " + ScreenProbeFilterComputeShaderResourcePath);
                hasLoggedMissingScreenProbeFilterComputeShader = true;
            }

            return screenProbeFilterComputeShader;
        }

        private static bool TryFindScreenProbeFilterGenerateMipKernel(ComputeShader shader, out int kernel)
        {
            try
            {
                kernel = shader.FindKernel(ScreenProbeFilterGenerateMipComputeKernelName);
                return kernel >= 0;
            }
            catch (System.ArgumentException)
            {
                kernel = -1;
                if (!hasLoggedMissingScreenProbeFilterGenerateMipKernel)
                {
                    Debug.LogWarning("BurtRP could not find compute kernel: " + ScreenProbeFilterGenerateMipComputeKernelName);
                    hasLoggedMissingScreenProbeFilterGenerateMipKernel = true;
                }

                return false;
            }
        }

        private static bool TryFindScreenProbeFilterFixupBordersKernel(ComputeShader shader, out int kernel)
        {
            try
            {
                kernel = shader.FindKernel(ScreenProbeFilterFixupBordersComputeKernelName);
                return kernel >= 0;
            }
            catch (System.ArgumentException)
            {
                kernel = -1;
                if (!hasLoggedMissingScreenProbeFilterFixupBordersKernel)
                {
                    Debug.LogWarning("BurtRP could not find compute kernel: " + ScreenProbeFilterFixupBordersComputeKernelName);
                    hasLoggedMissingScreenProbeFilterFixupBordersKernel = true;
                }

                return false;
            }
        }

        private static ComputeShader GetCopyTexture3DComputeShader()
        {
            if (copyTexture3DComputeShader != null)
            {
                return copyTexture3DComputeShader;
            }

            copyTexture3DComputeShader = Resources.Load<ComputeShader>(CopyTexture3DComputeShaderResourcePath);
            if (copyTexture3DComputeShader == null && !hasLoggedMissingCopyTexture3DComputeShader)
