        }

        private static bool TryFindCopyTexture3DFloat4Kernel(ComputeShader shader, out int kernel)
        {
            try
            {
                kernel = shader.FindKernel(CopyTexture3DFloat4KernelName);
                return kernel >= 0;
            }
            catch (System.ArgumentException)
            {
                kernel = -1;
                if (!hasLoggedMissingCopyTexture3DFloat4Kernel)
                {
                    Debug.LogWarning("BurtRP could not find compute kernel: " + CopyTexture3DFloat4KernelName);
                    hasLoggedMissingCopyTexture3DFloat4Kernel = true;
                }

                return false;
            }
        }

        private static bool TryFindCopyTexture3DUIntKernel(ComputeShader shader, out int kernel)
        {
            try
            {
                kernel = shader.FindKernel(CopyTexture3DUIntKernelName);
                return kernel >= 0;
            }
            catch (System.ArgumentException)
            {
                kernel = -1;
                if (!hasLoggedMissingCopyTexture3DUIntKernel)
