        internal static string ResolveCopyTexture3DResourceStatusLabel()
        {
            if (!SystemInfo.supportsComputeShaders)
            {
                return "Unsupported(SystemInfo.supportsComputeShaders=false)";
            }

            var shader = GetCopyTexture3DComputeShader();
            if (shader == null)
            {
                return "Missing(" + CopyTexture3DComputeShaderResourcePath + ")";
            }

            if (!TryFindCopyTexture3DFloat4Kernel(shader, out _))
            {
                return "MissingKernel(" + CopyTexture3DFloat4KernelName + ")";
            }

            if (!TryFindCopyTexture3DUIntKernel(shader, out _))
            {
                return "MissingKernel(" + CopyTexture3DUIntKernelName + ")";
            }

            if (!shader.HasKernel(CopyTexture3DXRenderKernelName))
            {
                return "MissingKernel(" + CopyTexture3DXRenderKernelName + ")";
            }

            foreach (var kernelName in CopyTexture3DXGIToolKernelNames)
            {
                if (!shader.HasKernel(kernelName))
                {
                    return "MissingKernel(" + kernelName + ")";
                }
            }

            return "Ready(Float4,UInt,XRenderAlias,XGIToolsClearTexture3D+CopyBuffer)";
        }

        protected static void UploadRadianceCacheClipMapSettings(
            CommandBuffer cmd,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            int sceneVoxelResolution = BurtScreenSpaceGlobalIlluminationPassUtility.SceneVoxelRadianceResolution)
        {
            if (!settings.Enabled)
            {
                cmd.SetGlobalVector(BurtGIRadianceCacheClipMapIndirectionSizeId, Vector4.zero);
                cmd.SetGlobalVector(BurtGIRadianceCacheClipMapParamsId, Vector4.zero);
                cmd.SetGlobalVector(BurtGIRadianceCacheClipMapApplyParamsGlobalId, Vector4.zero);
                cmd.SetGlobalVector(BurtGIRadianceCacheClipMapWorldParamsId, Vector4.zero);
                cmd.SetGlobalInt(BurtGIRadianceCacheClipMapFinalRadianceAtlasMaxMipGlobalId, 0);
                cmd.SetGlobalInt(BurtGIRadianceCacheClipMapFinalIrradianceProbeResolutionId, 0);
                cmd.SetGlobalInt(BurtGIRadianceCacheClipMapFinalOcclusionProbeResolutionId, 0);
                return;
            }

            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, settings);
            var indirectionDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationRadianceCacheClipMapIndirectionDescriptor(camera, settings);
            var indirectionWidth = Mathf.Max(1, indirectionDescriptor.width);
            var indirectionHeight = Mathf.Max(1, indirectionDescriptor.height);
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapIndirectionSizeId, new Vector4(indirectionWidth, indirectionHeight, 1f / indirectionWidth, 1f / indirectionHeight));
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapParamsId, clipMapState.Params);
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapApplyParamsGlobalId, new Vector4(1f, settings.RadianceCacheReprojectionRadiusScale, settings.RadianceCacheVisualizeClipmapIndex, settings.RadianceCacheVisualizeRadiusScale));
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapWorldParamsId, clipMapState.WorldParams);
            cmd.SetGlobalInt(BurtGIRadianceCacheClipMapFinalRadianceAtlasMaxMipGlobalId, BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheClipMapFinalRadianceAtlasMaxMip);
            cmd.SetGlobalInt(BurtGIRadianceCacheClipMapFinalIrradianceProbeResolutionId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapFinalIrradianceProbeResolution(settings));
            cmd.SetGlobalInt(BurtGIRadianceCacheClipMapFinalOcclusionProbeResolutionId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapFinalOcclusionProbeResolution(settings));
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapWorldPositionToProbeCoordId, clipMapState.WorldPositionToProbeCoord);
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapProbeCoordToWorldCenterId, clipMapState.ProbeCoordToWorldCenter);
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapClipmapCenterExtentId, clipMapState.ClipmapCenterExtent);
            cmd.SetGlobalVector(BurtGISceneVoxelCenterExtentId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(camera, settings, clipMapState, sceneVoxelResolution));
            cmd.SetGlobalVectorArray(BurtGIRadianceCacheClipMapClipmapParamsId, clipMapState.ClipmapParams);
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationTracePass : BurtScreenSpaceGlobalIlluminationPass
    {
        public override string Name => "Burt Screen Space Global Illumination Trace";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIllumination(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadGBuffer1();
            builder.ReadGBuffer2();
            builder.ReadGBuffer3();
            builder.ReadGBuffer4();
            builder.ReadGBuffer5();
            builder.WriteScreenSpaceGlobalIlluminationRaw();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(context, out var cameraDepthTarget, out var gbuffer0Target, out var gbuffer1Target, out var gbuffer2Target, out var gbuffer3Target, out var gbuffer4Target, out var gbuffer5Target, out var rawTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            if (!settings.Enabled)
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            var camera = context.Request != null ? context.Request.Camera : null;
            if (material == null || camera == null)
            {
                return;
            }

            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetRenderTarget(rawTarget.Identifier);
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, descriptor.width, descriptor.height);
            cmd.SetGlobalTexture(CameraDepthTextureId, cameraDepthTarget.Identifier);
            BurtDeferredStencilTextureUtility.BindGlobal(cmd, cameraDepthTarget, camera);
            BindGBufferInputs(cmd, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, gbuffer4Target, gbuffer5Target);
            UploadCameraGlobals(cmd, context.Request, camera, descriptor);
            UploadSettings(cmd, settings);
            cmd.DrawProcedural(Matrix4x4.identity, material, 0, MeshTopology.Triangles, 3, 1);
            cmd.SetGlobalTexture(BurtGIRawTextureId, rawTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle cameraDepthTarget,
            out BurtRenderTargetHandle gbuffer0Target,
            out BurtRenderTargetHandle gbuffer1Target,
            out BurtRenderTargetHandle gbuffer2Target,
            out BurtRenderTargetHandle gbuffer3Target,
            out BurtRenderTargetHandle gbuffer4Target,
            out BurtRenderTargetHandle gbuffer5Target,
            out BurtRenderTargetHandle rawTarget)
        {
            cameraDepthTarget = context != null ? context.CameraDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.CameraDepthName);
            gbuffer0Target = context != null ? context.GBuffer0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer0Name);
            gbuffer1Target = context != null ? context.GBuffer1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer1Name);
            gbuffer2Target = context != null ? context.GBuffer2Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer2Name);
            gbuffer3Target = context != null ? context.GBuffer3Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer3Name);
            gbuffer4Target = context != null ? context.GBuffer4Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer4Name);
            gbuffer5Target = context != null ? context.GBuffer5Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer5Name);
            rawTarget = context != null ? context.ScreenSpaceGlobalIlluminationRawTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationRawName);

            return cameraDepthTarget.IsValid &&
                gbuffer0Target.IsValid &&
                gbuffer1Target.IsValid &&
                gbuffer2Target.IsValid &&
                gbuffer3Target.IsValid &&
                gbuffer4Target.IsValid &&
                gbuffer5Target.IsValid &&
                rawTarget.IsValid;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationTranslucencyVolumeGeneratePass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string TranslucencyVolumeTraceVoxelComputeShaderResourcePath = "BurtGITranslucencyVolumeTraceVoxel";
        private const string TranslucencyVolumeTraceVoxelOctreeComputeShaderResourcePath = "BurtGITranslucencyVolumeTraceVoxelOctree";
        private const string TranslucencyVolumeTraceVoxelKernelName = "TranslucencyVolumeTraceVoxelsCS";
        private const string TranslucencyVolumeTraceVoxelOctreeKernelName = "TranslucencyVolumeTraceVoxelOctreeCS";
        private static readonly int BurtHiZDepthTextureId = BurtRenderGraphResourceRegistry.HiZDepthTextureId;
        private static readonly int BurtGISceneVoxelGeometryReadTextureId = BurtRenderGraphResourceRegistry.BurtGISceneVoxelGeometryReadTextureId;
        private static readonly int BurtGISceneVoxelOccupancyMipReadTextureId = BurtRenderGraphResourceRegistry.BurtGISceneVoxelOccupancyMipReadTextureId;
        private static readonly int BurtGISceneVoxelLightingReadTextureId = BurtRenderGraphResourceRegistry.BurtGISceneVoxelLightingReadTextureId;
        private static readonly int BurtGITranslucencyVolumeHiZParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeHiZParams");
        private static readonly int BurtGITranslucencyVolumeTraceParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeTraceParams");
        private static readonly int BurtGITranslucencyVolumeTraceAtlasParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeTraceAtlasParams");
        private static readonly int BurtGISceneVoxelTraceControlsId = Shader.PropertyToID("_BurtGISceneVoxelTraceControls");
        private static ComputeShader translucencyVolumeTraceVoxelComputeShader;
        private static ComputeShader translucencyVolumeTraceVoxelOctreeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeTraceVoxelComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeTraceVoxelOctreeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeGenerateKernel;

        public override string Name => "Burt Screen Space Global Illumination Translucency Volume Generate";

        public override BurtRenderPassKind Kind => BurtRenderPassKind.GlobalState;

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(builder.Request, builder.Asset))
            {
                return;
            }

            if (BurtHiZDepthPassUtility.ShouldUseHiZDepth(builder.Request, builder.Asset))
            {
                builder.ReadHiZDepth();
            }

            builder.ReadBurtGISceneVoxelGeometry();
            builder.ReadBurtGISceneVoxelOccupancyMip();
            builder.ReadBurtGISceneVoxelLighting();
            builder.WriteBurtGITranslucencyVolumeTraceRadiance();
            builder.WriteBurtGITranslucencyVolumeTraceHitDistance();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(context.Request, context.Asset))
            {
                return;
            }

            if (!TryGetRequiredTargets(
                    context,
                    out var traceRadianceTarget,
                    out var traceHitDistanceTarget))
            {
                return;
            }

            if (!context.BurtGISceneVoxelGeometryTarget.IsValid ||
                !context.BurtGISceneVoxelOccupancyMipTarget.IsValid ||
                !context.BurtGISceneVoxelLightingTarget.IsValid)
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            if (!TryResolveTranslucencyVolumeTraceVoxelShader(screenProbeSettings, out var shader, out var kernel))
            {
                return;
            }

            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, screenProbeSettings);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, screenProbeSettings);
            var gridSize = new Vector4(
                descriptor.width,
                descriptor.height,
                descriptor.volumeDepth,
                BurtScreenSpaceGlobalIlluminationPassUtility.TranslucencyVolumeMaterialIntensityScale);
            var nearPlane = camera != null ? Mathf.Max(camera.nearClipPlane, 0.01f) : 0.1f;
            var cameraFarPlane = camera != null ? Mathf.Max(camera.farClipPlane, nearPlane + 1f) : 1000f;
            var farPlane = Mathf.Min(cameraFarPlane, nearPlane + screenProbeSettings.TranslucencyVolumeEndDistanceFromCamera);
            ResolveTranslucencyVolumeReprojectionMatrices(
                context.Request,
                camera,
                out var inverseCurrentViewProjection,
                out _,
                out var cameraWorldPosition);
            var gridZParams = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveTranslucencyVolumeGridZParams(screenProbeSettings);
            var jitterOffset = ResolveTranslucencyVolumeJitterOffset(screenProbeSettings, Time.frameCount);
            var hiZDepthTarget = context.HiZDepthTarget;
            var hiZDepthValid = hiZDepthTarget.IsValid && BurtHiZDepthPassUtility.ShouldUseHiZDepth(context.Request, context.Asset);
            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetComputeTextureParam(shader, kernel, BurtHiZDepthTextureId, hiZDepthValid ? hiZDepthTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            BindTranslucencySceneVoxelTexture(cmd, shader, kernel, BurtGISceneVoxelGeometryReadTextureId, context.BurtGISceneVoxelGeometryTarget);
            BindTranslucencySceneVoxelTexture(cmd, shader, kernel, BurtGISceneVoxelOccupancyMipReadTextureId, context.BurtGISceneVoxelOccupancyMipTarget);
            BindTranslucencySceneVoxelTexture(cmd, shader, kernel, BurtGISceneVoxelLightingReadTextureId, context.BurtGISceneVoxelLightingTarget);
            BurtGISceneVoxelOctreeUtility.BindCompute(cmd, shader, kernel);
            var sceneVoxelCenterExtent = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(camera, screenProbeSettings, clipMapState, settings.SceneVoxelClipMapResolution);
            BurtGISceneVoxelClipmapStateUtility.BindTranslucencyTraceCompute(
                cmd,
                shader,
                kernel,
                camera,
                sceneVoxelCenterExtent,
                ResolveTranslucencySceneVoxelFallback(context.BurtGISceneVoxelGeometryTarget),
                ResolveTranslucencySceneVoxelFallback(context.BurtGISceneVoxelLightingTarget));
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceRadianceTextureId, traceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceHitDistanceTextureId, traceHitDistanceTarget.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeGridSizeId, gridSize);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeParams0Id, new Vector4(nearPlane, farPlane, 0.75f, 0.65f));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeGridZParamsId, gridZParams);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeJitterParamsId, jitterOffset);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeHiZParamsId, new Vector4(
                hiZDepthValid ? 1f : 0f,
                screenProbeSettings.TranslucencyVolumeGridCenterOffsetFromDepthBuffer,
                screenProbeSettings.TranslucencyVolumeOffsetThresholdToAcceptDepthBufferOffset,
                0f));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeTraceParamsId, new Vector4(
                screenProbeSettings.TranslucencyVolumeMaxRayIntensity,
                screenProbeSettings.TranslucencyVolumeMaxTraceDistance,
                screenProbeSettings.TranslucencyVolumeTraceStepFactor,
                screenProbeSettings.TranslucencyVolumeVoxelTraceStartDistanceScale));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeTraceAtlasParamsId, new Vector4(
                screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution,
                jitterOffset.w,
                0f,
                0f));
            cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, inverseCurrentViewProjection);
            cmd.SetComputeVectorParam(shader, CameraWorldPositionId, cameraWorldPosition);
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelCenterExtentId, sceneVoxelCenterExtent);
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelTraceControlsId, new Vector4(
                settings.SceneVoxelTraceMaxSteps,
                settings.SceneVoxelTraceStepFactor,
                0f,
                0f));
            cmd.SetGlobalVector(BurtGITranslucencyVolumeGridSizeId, gridSize);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeGridZParamsId, gridZParams);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeParams0Id, new Vector4(nearPlane, farPlane, 0.75f, 0.65f));
            cmd.SetGlobalVector(BurtGITranslucencyVolumeJitterParamsId, jitterOffset);
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (descriptor.width * Mathf.Clamp(screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution, 1, 8) + 7) / 8),
                Mathf.Max(1, (descriptor.height * Mathf.Clamp(screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution, 1, 8) + 7) / 8),
                Mathf.Max(1, descriptor.volumeDepth));
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            BurtGITranslucencyVolumeRuntimeState.MarkTraceAtlasGenerated(
                descriptor.width * Mathf.Clamp(screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution, 1, 8),
                descriptor.height * Mathf.Clamp(screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution, 1, 8),
                descriptor.volumeDepth,
                Mathf.Clamp(screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution, 1, 8));
        }

        private static void BindTranslucencySceneVoxelTexture(CommandBuffer cmd, ComputeShader shader, int kernel, int textureId, BurtRenderTargetHandle target)
        {
            cmd.SetComputeTextureParam(shader, kernel, textureId, ResolveTranslucencySceneVoxelFallback(target));
        }

        private static RenderTargetIdentifier ResolveTranslucencySceneVoxelFallback(BurtRenderTargetHandle target)
        {
            return target.IsValid
                ? target.Identifier
                : new RenderTargetIdentifier(BurtGITranslucencyVolumeFallbackUtility.BlackVolumeRenderTexture);
        }

        internal static void ResolveTranslucencyVolumeReprojectionMatrices(
            BurtRenderRequest request,
            Camera camera,
            out Matrix4x4 inverseCurrentViewProjection,
            out Matrix4x4 previousViewProjection,
            out Vector4 cameraWorldPosition)
        {
            var temporalAA = request != null ? request.TemporalAA : null;
            if (temporalAA != null && temporalAA.Enabled)
            {
                inverseCurrentViewProjection = temporalAA.InverseCurrentNonJitteredViewProjectionMatrix;
                previousViewProjection = temporalAA.PreviousNonJitteredViewProjectionMatrix;
            }
            else if (camera != null)
            {
                var currentViewProjection = GL.GetGPUProjectionMatrix(camera.projectionMatrix, true) * camera.worldToCameraMatrix;
                inverseCurrentViewProjection = currentViewProjection.inverse;
                previousViewProjection = currentViewProjection;
            }
            else
            {
                inverseCurrentViewProjection = Matrix4x4.identity;
                previousViewProjection = Matrix4x4.identity;
            }

            var position = camera != null ? camera.transform.position : Vector3.zero;
            cameraWorldPosition = new Vector4(position.x, position.y, position.z, 1f);
        }

        internal static Vector4 ResolveTranslucencyVolumeJitterOffset(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings, int frameIndex)
        {
            if (!settings.TranslucencyVolumeJitter)
            {
                return new Vector4(0.5f, 0.5f, 0.5f, -1f);
            }

            var jitterFrameIndex = frameIndex % Mathf.Max(1, settings.TranslucencyVolumeTemporalMaxRayDirections);
            var haltonFrame = frameIndex & 1023;
            return new Vector4(
                Halton(haltonFrame, 2),
                Halton(haltonFrame, 3),
                Halton(haltonFrame, 5),
                jitterFrameIndex);
        }

        private static float Halton(int index, int radix)
        {
            var result = 0f;
            var invRadix = 1f / radix;
            var fraction = invRadix;
            while (index > 0)
            {
                result += (index % radix) * fraction;
                index /= radix;
                fraction *= invRadix;
            }

            return result;
        }

        private static bool TryGetRequiredTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle traceRadianceTarget,
            out BurtRenderTargetHandle traceHitDistanceTarget)
        {
            traceRadianceTarget = context != null ? context.BurtGITranslucencyVolumeTraceRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceRadianceName);
            traceHitDistanceTarget = context != null ? context.BurtGITranslucencyVolumeTraceHitDistanceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceHitDistanceName);
            return traceRadianceTarget.IsValid &&
                traceHitDistanceTarget.IsValid;
        }

        private static bool TryResolveTranslucencyVolumeTraceVoxelShader(
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            out ComputeShader shader,
            out int kernel)
        {
            if (settings.TraceVoxelOctree)
            {
                shader = GetTranslucencyVolumeTraceVoxelOctreeComputeShader();
                return TryFindTranslucencyVolumeGenerateKernel(shader, TranslucencyVolumeTraceVoxelOctreeKernelName, out kernel);
            }

            shader = GetTranslucencyVolumeTraceVoxelComputeShader();
            return TryFindTranslucencyVolumeGenerateKernel(shader, TranslucencyVolumeTraceVoxelKernelName, out kernel);
        }

        private static ComputeShader GetTranslucencyVolumeTraceVoxelComputeShader()
        {
            if (translucencyVolumeTraceVoxelComputeShader != null)
            {
                return translucencyVolumeTraceVoxelComputeShader;
            }

            translucencyVolumeTraceVoxelComputeShader = Resources.Load<ComputeShader>(TranslucencyVolumeTraceVoxelComputeShaderResourcePath);
            if (translucencyVolumeTraceVoxelComputeShader == null && !hasLoggedMissingTranslucencyVolumeTraceVoxelComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + TranslucencyVolumeTraceVoxelComputeShaderResourcePath);
                hasLoggedMissingTranslucencyVolumeTraceVoxelComputeShader = true;
            }

            return translucencyVolumeTraceVoxelComputeShader;
        }

        private static ComputeShader GetTranslucencyVolumeTraceVoxelOctreeComputeShader()
        {
            if (translucencyVolumeTraceVoxelOctreeComputeShader != null)
            {
                return translucencyVolumeTraceVoxelOctreeComputeShader;
            }

            translucencyVolumeTraceVoxelOctreeComputeShader = Resources.Load<ComputeShader>(TranslucencyVolumeTraceVoxelOctreeComputeShaderResourcePath);
            if (translucencyVolumeTraceVoxelOctreeComputeShader == null && !hasLoggedMissingTranslucencyVolumeTraceVoxelOctreeComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + TranslucencyVolumeTraceVoxelOctreeComputeShaderResourcePath);
                hasLoggedMissingTranslucencyVolumeTraceVoxelOctreeComputeShader = true;
            }

            return translucencyVolumeTraceVoxelOctreeComputeShader;
        }

        private static bool TryFindTranslucencyVolumeGenerateKernel(ComputeShader shader, string kernelName, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingTranslucencyVolumeGenerateKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + kernelName);
                    hasLoggedMissingTranslucencyVolumeGenerateKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationTranslucencyVolumeTraceSpatialFilterPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string TranslucencyVolumeComputeShaderResourcePath = "BurtGITranslucencyVolumeTraceSpatialFilter";
        private const string TranslucencyVolumeTraceSpatialFilterKernelName = "TranslucencyVolumeTraceSpatialFilterCS";
        private static readonly int BurtGITranslucencyVolumeTraceReadRadianceTextureId = Shader.PropertyToID("_BurtGITranslucencyVolumeTraceReadRadiance");
        private static readonly int BurtGITranslucencyVolumeSpatialFilterParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeSpatialFilterParams");
        private static readonly int BurtGITranslucencyVolumeSpatialFilterDirectionId = Shader.PropertyToID("_BurtGITranslucencyVolumeSpatialFilterDirection");
        private static readonly int BurtGITranslucencyVolumeTraceAtlasParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeTraceAtlasParams");
        private static ComputeShader translucencyVolumeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeTraceSpatialFilterKernel;

        public override string Name => "Burt Screen Space Global Illumination Translucency Volume Trace Spatial Filter";

        public override BurtRenderPassKind Kind => BurtRenderPassKind.GlobalState;

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGITranslucencyVolumeTraceHitDistance();
            builder.ReadBurtGITranslucencyVolumeTraceRadiance();
            builder.WriteBurtGITranslucencyVolumeTraceRadiance();
            builder.WriteBurtGITranslucencyVolumeTraceFilteredRadiance();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(context.Request, context.Asset))
            {
                return;
            }

            var rawTraceRadianceTarget = context.BurtGITranslucencyVolumeTraceRadianceTarget;
            var filteredTraceRadianceTarget = context.BurtGITranslucencyVolumeTraceFilteredRadianceTarget;
            if (!rawTraceRadianceTarget.IsValid || !filteredTraceRadianceTarget.IsValid)
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeTraceAtlasDescriptor(camera, screenProbeSettings, RenderTextureFormat.ARGBHalf);
            var volumeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, screenProbeSettings);
            var shader = GetTranslucencyVolumeComputeShader();
            if (!screenProbeSettings.TranslucencyVolumeSpatialFilter ||
                !TryFindTranslucencyVolumeTraceSpatialFilterKernel(shader, out var kernel))
            {
                CopyPassthroughTraceRadiance(context, rawTraceRadianceTarget, filteredTraceRadianceTarget, traceDescriptor);
                return;
            }

            var cmd = context.AcquireCommandBuffer(Name);
            var gridSize = new Vector4(
                volumeDescriptor.width,
                volumeDescriptor.height,
                volumeDescriptor.volumeDepth,
                BurtScreenSpaceGlobalIlluminationPassUtility.TranslucencyVolumeMaterialIntensityScale);
            var spatialFilterParams = new Vector4(
                screenProbeSettings.TranslucencyVolumeSpatialFilterSampleCount,
                screenProbeSettings.TranslucencyVolumeSpatialFilterStandardDeviation,
                1f,
                0.65f);
            var traceAtlasParams = new Vector4(
                screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution,
                0f,
                0f,
                0f);
            DispatchTraceSpatialFilterAxis(
                cmd,
                shader,
                kernel,
                traceDescriptor,
                gridSize,
                spatialFilterParams,
                traceAtlasParams,
                rawTraceRadianceTarget,
                filteredTraceRadianceTarget,
                0);
            DispatchTraceSpatialFilterAxis(
                cmd,
                shader,
                kernel,
                traceDescriptor,
                gridSize,
                spatialFilterParams,
                traceAtlasParams,
                filteredTraceRadianceTarget,
                rawTraceRadianceTarget,
                1);
            DispatchTraceSpatialFilterAxis(
                cmd,
                shader,
                kernel,
                traceDescriptor,
                gridSize,
                spatialFilterParams,
                traceAtlasParams,
                rawTraceRadianceTarget,
                filteredTraceRadianceTarget,
                2);
            cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceFilteredRadianceTextureId, filteredTraceRadianceTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            BurtGITranslucencyVolumeRuntimeState.MarkTraceAtlasFiltered(
                traceDescriptor.width,
                traceDescriptor.height,
                traceDescriptor.volumeDepth,
                Mathf.Clamp(screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution, 1, 8));
        }

        private static void DispatchTraceSpatialFilterAxis(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            RenderTextureDescriptor traceDescriptor,
            Vector4 gridSize,
            Vector4 spatialFilterParams,
            Vector4 traceAtlasParams,
            BurtRenderTargetHandle source,
            BurtRenderTargetHandle destination,
            int axis)
        {
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolumeTraceReadRadianceTextureId, source.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceFilteredRadianceTextureId, destination.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeGridSizeId, gridSize);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeSpatialFilterParamsId, spatialFilterParams);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeSpatialFilterDirectionId, ResolveSpatialFilterDirection(axis));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeTraceAtlasParamsId, traceAtlasParams);
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (traceDescriptor.width + 7) / 8),
                Mathf.Max(1, (traceDescriptor.height + 7) / 8),
                Mathf.Max(1, traceDescriptor.volumeDepth));
        }

        private static Vector4 ResolveSpatialFilterDirection(int axis)
        {
            switch (axis)
            {
                case 1:
                    return new Vector4(0f, 1f, 0f, 0f);
                case 2:
                    return new Vector4(0f, 0f, 1f, 0f);
                default:
                    return new Vector4(1f, 0f, 0f, 0f);
            }
        }

        private void CopyPassthroughTraceRadiance(
            BurtRenderGraphContext context,
            BurtRenderTargetHandle rawTraceRadianceTarget,
            BurtRenderTargetHandle filteredTraceRadianceTarget,
            RenderTextureDescriptor traceDescriptor)
        {
            var cmd = context.AcquireCommandBuffer(Name + " Passthrough");
            if (!TryCopyTexture3DFloat4(cmd, rawTraceRadianceTarget.Identifier, filteredTraceRadianceTarget.Identifier, traceDescriptor.width, traceDescriptor.height, traceDescriptor.volumeDepth))
            {
                cmd.CopyTexture(rawTraceRadianceTarget.Identifier, filteredTraceRadianceTarget.Identifier);
            }

            cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceFilteredRadianceTextureId, filteredTraceRadianceTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            BurtGITranslucencyVolumeRuntimeState.MarkTraceAtlasFiltered(
                traceDescriptor.width,
                traceDescriptor.height,
                traceDescriptor.volumeDepth,
                Mathf.Clamp(BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset).TranslucencyVolumeTracingOctahedronResolution, 1, 8));
        }

        private static ComputeShader GetTranslucencyVolumeComputeShader()
        {
            if (translucencyVolumeComputeShader != null)
            {
                return translucencyVolumeComputeShader;
            }

            translucencyVolumeComputeShader = Resources.Load<ComputeShader>(TranslucencyVolumeComputeShaderResourcePath);
            if (translucencyVolumeComputeShader == null && !hasLoggedMissingTranslucencyVolumeComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + TranslucencyVolumeComputeShaderResourcePath);
                hasLoggedMissingTranslucencyVolumeComputeShader = true;
            }

            return translucencyVolumeComputeShader;
        }

        private static bool TryFindTranslucencyVolumeTraceSpatialFilterKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(TranslucencyVolumeTraceSpatialFilterKernelName))
            {
                if (!hasLoggedMissingTranslucencyVolumeTraceSpatialFilterKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + TranslucencyVolumeTraceSpatialFilterKernelName);
                    hasLoggedMissingTranslucencyVolumeTraceSpatialFilterKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(TranslucencyVolumeTraceSpatialFilterKernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationTranslucencyVolumeIntegratePass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string TranslucencyVolumeComputeShaderResourcePath = "BurtGITranslucencyVolumeIntegrate";
        private const string TranslucencyVolumeIntegrateKernelName = "TranslucencyVolumeIntegratesCS";
        private static readonly int BurtHiZDepthTextureId = BurtRenderGraphResourceRegistry.HiZDepthTextureId;
        private static readonly int BurtGISceneVoxelGeometryReadTextureId = BurtRenderGraphResourceRegistry.BurtGISceneVoxelGeometryReadTextureId;
        private static readonly int BurtGISceneVoxelOccupancyMipReadTextureId = BurtRenderGraphResourceRegistry.BurtGISceneVoxelOccupancyMipReadTextureId;
        private static readonly int BurtGISceneVoxelLightingReadTextureId = BurtRenderGraphResourceRegistry.BurtGISceneVoxelLightingReadTextureId;
        private static readonly int BurtGITranslucencyVolumeHiZParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeHiZParams");
        private static readonly int BurtGITranslucencyVolumeExposureParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeExposureParams");
        private static readonly int BurtGITranslucencyVolumeTraceParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeTraceParams");
        private static readonly int BurtGITranslucencyVolumeTraceAtlasParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeTraceAtlasParams");
        private static readonly int BurtGITranslucencyVolumeTraceReadRadianceTextureId = Shader.PropertyToID("_BurtGITranslucencyVolumeTraceReadRadiance");
        private static readonly int BurtGISceneVoxelTraceControlsId = Shader.PropertyToID("_BurtGISceneVoxelTraceControls");
        private static ComputeShader translucencyVolumeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeIntegrateKernel;

        public override string Name => "Burt Screen Space Global Illumination Translucency Volume Integrate";

        public override BurtRenderPassKind Kind => BurtRenderPassKind.GlobalState;

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadScreenSpaceGlobalIllumination();
            builder.ReadBurtGIBackfaceDiffuseIndirect();
            builder.ReadBurtGIScreenProbeRadiance();
            builder.ReadBurtGIScreenProbeConfidence();
            builder.ReadBurtGITranslucencyVolumeTraceFilteredRadiance();
            if (BurtHiZDepthPassUtility.ShouldUseHiZDepth(builder.Request, builder.Asset))
            {
                builder.ReadHiZDepth();
            }

            builder.WriteBurtGITranslucencyVolume0();
            builder.WriteBurtGITranslucencyVolume1();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(context.Request, context.Asset))
            {
                return;
            }

            if (!TryGetRequiredTargets(
                    context,
                    out var diffuseTarget,
                    out var backfaceTarget,
                    out var screenProbeRadianceTarget,
                    out var screenProbeConfidenceTarget,
                    out var filteredTraceRadianceTarget,
                    out var volume0Target,
                    out var volume1Target))
            {
                return;
            }

            var shader = GetTranslucencyVolumeComputeShader();
            if (!TryFindTranslucencyVolumeIntegrateKernel(shader, out var kernel))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, screenProbeSettings);
            var history = BurtGITranslucencyVolumeHistoryUtility.EnsureHistoryTextures(context.Request, context.Asset, settings, screenProbeSettings, out var historyValid);
            var gridSize = new Vector4(
                descriptor.width,
                descriptor.height,
                descriptor.volumeDepth,
                BurtScreenSpaceGlobalIlluminationPassUtility.TranslucencyVolumeMaterialIntensityScale);
            var nearPlane = camera != null ? Mathf.Max(camera.nearClipPlane, 0.01f) : 0.1f;
            var cameraFarPlane = camera != null ? Mathf.Max(camera.farClipPlane, nearPlane + 1f) : 1000f;
            var farPlane = Mathf.Min(cameraFarPlane, nearPlane + screenProbeSettings.TranslucencyVolumeEndDistanceFromCamera);
            BurtScreenSpaceGlobalIlluminationTranslucencyVolumeGeneratePass.ResolveTranslucencyVolumeReprojectionMatrices(
                context.Request,
                camera,
                out var inverseCurrentViewProjection,
                out var previousViewProjection,
                out var cameraWorldPosition);
            var gridZParams = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveTranslucencyVolumeGridZParams(screenProbeSettings);
            var translucencyHistoryValid = historyValid && screenProbeSettings.TranslucencyVolumeUseTemporalReprojection;
            var translucencyHistoryWeight = screenProbeSettings.TranslucencyVolumeUseTemporalReprojection ? screenProbeSettings.TranslucencyVolumeHistoryWeight : 0f;
            var jitterOffset = BurtScreenSpaceGlobalIlluminationTranslucencyVolumeGeneratePass.ResolveTranslucencyVolumeJitterOffset(screenProbeSettings, Time.frameCount);
            var previousJitterOffset = BurtScreenSpaceGlobalIlluminationTranslucencyVolumeGeneratePass.ResolveTranslucencyVolumeJitterOffset(screenProbeSettings, Time.frameCount - (translucencyHistoryValid ? 1 : 0));
            var hiZDepthTarget = context.HiZDepthTarget;
            var hiZDepthValid = hiZDepthTarget.IsValid && BurtHiZDepthPassUtility.ShouldUseHiZDepth(context.Request, context.Asset);
            var fallbackVolumeTexture = BurtGITranslucencyVolumeFallbackUtility.BlackVolumeTexture;
            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIApplyIndirectDiffuseTextureId, diffuseTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIApplyIndirectBackfaceDiffuseTextureId, backfaceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeRadianceTextureId, screenProbeRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeConfidenceTextureId, screenProbeConfidenceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtHiZDepthTextureId, hiZDepthValid ? hiZDepthTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolumeHistory0TextureId, history.Volume0 != null ? (Texture)history.Volume0 : fallbackVolumeTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolumeHistory1TextureId, history.Volume1 != null ? (Texture)history.Volume1 : fallbackVolumeTexture);
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolumeTraceReadRadianceTextureId, filteredTraceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolume0TextureId, volume0Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolume1TextureId, volume1Target.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeGridSizeId, gridSize);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeParams0Id, new Vector4(nearPlane, farPlane, 0.75f, 0.65f));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeGridZParamsId, gridZParams);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeTemporalParamsId, new Vector4(translucencyHistoryWeight, translucencyHistoryValid ? 1f : 0f, 0.65f, 1f));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeJitterParamsId, jitterOffset);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumePreviousJitterParamsId, previousJitterOffset);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeHiZParamsId, new Vector4(
                hiZDepthValid ? 1f : 0f,
                screenProbeSettings.TranslucencyVolumeGridCenterOffsetFromDepthBuffer,
                screenProbeSettings.TranslucencyVolumeOffsetThresholdToAcceptDepthBufferOffset,
                0f));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeExposureParamsId, new Vector4(history.HistoryExposureCorrection, 0f, 0f, 0f));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeTraceParamsId, new Vector4(
                screenProbeSettings.TranslucencyVolumeMaxRayIntensity,
                screenProbeSettings.TranslucencyVolumeMaxTraceDistance,
                screenProbeSettings.TranslucencyVolumeTraceStepFactor,
                screenProbeSettings.TranslucencyVolumeVoxelTraceStartDistanceScale));
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeTraceAtlasParamsId, new Vector4(
                screenProbeSettings.TranslucencyVolumeTracingOctahedronResolution,
                jitterOffset.w,
                1f,
                0f));
            cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, inverseCurrentViewProjection);
            cmd.SetComputeMatrixParam(shader, BurtGIScreenProbePreviousViewProjectionMatrixId, previousViewProjection);
            cmd.SetComputeVectorParam(shader, CameraWorldPositionId, cameraWorldPosition);
            cmd.SetGlobalTexture(BurtGITranslucencyVolume0TextureId, volume0Target.Identifier);
            cmd.SetGlobalTexture(BurtGITranslucencyVolume1TextureId, volume1Target.Identifier);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeGridSizeId, gridSize);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeGridZParamsId, gridZParams);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeParams0Id, new Vector4(nearPlane, farPlane, 0.75f, 0.65f));
            cmd.SetGlobalVector(BurtGITranslucencyVolumeTemporalParamsId, new Vector4(translucencyHistoryWeight, translucencyHistoryValid ? 1f : 0f, 0.65f, 1f));
            cmd.SetGlobalVector(BurtGITranslucencyVolumeJitterParamsId, jitterOffset);
            cmd.SetGlobalVector(BurtGITranslucencyVolumePreviousJitterParamsId, previousJitterOffset);
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (descriptor.width + 3) / 4),
                Mathf.Max(1, (descriptor.height + 3) / 4),
                Mathf.Max(1, (descriptor.volumeDepth + 3) / 4));
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            BurtGITranslucencyVolumeRuntimeState.MarkVolumeIntegrated(
                descriptor.width,
                descriptor.height,
                descriptor.volumeDepth,
                "FilteredTraceAtlasSH2");
        }

        private static bool TryGetRequiredTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle diffuseTarget,
            out BurtRenderTargetHandle backfaceTarget,
            out BurtRenderTargetHandle screenProbeRadianceTarget,
            out BurtRenderTargetHandle screenProbeConfidenceTarget,
            out BurtRenderTargetHandle filteredTraceRadianceTarget,
            out BurtRenderTargetHandle volume0Target,
            out BurtRenderTargetHandle volume1Target)
        {
            diffuseTarget = context != null ? context.ScreenSpaceGlobalIlluminationTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationName);
            backfaceTarget = context != null ? context.BurtGIBackfaceDiffuseIndirectTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectName);
            screenProbeRadianceTarget = context != null ? context.BurtGIScreenProbeRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeRadianceName);
            screenProbeConfidenceTarget = context != null ? context.BurtGIScreenProbeConfidenceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIScreenProbeConfidenceName);
            filteredTraceRadianceTarget = context != null ? context.BurtGITranslucencyVolumeTraceFilteredRadianceTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeTraceFilteredRadianceName);
            volume0Target = context != null ? context.BurtGITranslucencyVolume0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume0Name);
            volume1Target = context != null ? context.BurtGITranslucencyVolume1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume1Name);
            return diffuseTarget.IsValid &&
                backfaceTarget.IsValid &&
                screenProbeRadianceTarget.IsValid &&
                screenProbeConfidenceTarget.IsValid &&
                filteredTraceRadianceTarget.IsValid &&
                volume0Target.IsValid &&
                volume1Target.IsValid;
        }

        private static ComputeShader GetTranslucencyVolumeComputeShader()
        {
            if (translucencyVolumeComputeShader != null)
            {
                return translucencyVolumeComputeShader;
            }

            translucencyVolumeComputeShader = Resources.Load<ComputeShader>(TranslucencyVolumeComputeShaderResourcePath);
            if (translucencyVolumeComputeShader == null && !hasLoggedMissingTranslucencyVolumeComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + TranslucencyVolumeComputeShaderResourcePath);
                hasLoggedMissingTranslucencyVolumeComputeShader = true;
            }

            return translucencyVolumeComputeShader;
        }

        private static bool TryFindTranslucencyVolumeIntegrateKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(TranslucencyVolumeIntegrateKernelName))
            {
                if (!hasLoggedMissingTranslucencyVolumeIntegrateKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + TranslucencyVolumeIntegrateKernelName);
                    hasLoggedMissingTranslucencyVolumeIntegrateKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(TranslucencyVolumeIntegrateKernelName);
            return kernel >= 0;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationTranslucencyVolumeSpatialFilterPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string TranslucencyVolumeComputeShaderResourcePath = "BurtGITranslucencyVolumeSpatialFilter";
        private const string TranslucencyVolumeSpatialFilterKernelName = "TranslucencyVolumeSpatialFilterCS";
        private const string TranslucencyVolumeSpatialFilterFallbackKernelName = "FilterTranslucencyVolumeSpatialCS";
        private static readonly int BurtGITranslucencyVolumeRead0TextureId = Shader.PropertyToID("_BurtGITranslucencyVolumeRead0");
        private static readonly int BurtGITranslucencyVolumeRead1TextureId = Shader.PropertyToID("_BurtGITranslucencyVolumeRead1");
        private static readonly int BurtGITranslucencyVolumeSpatialFilterParamsId = Shader.PropertyToID("_BurtGITranslucencyVolumeSpatialFilterParams");
        private static readonly int BurtGITranslucencyVolumeSpatialFilterDirectionId = Shader.PropertyToID("_BurtGITranslucencyVolumeSpatialFilterDirection");
        private static ComputeShader translucencyVolumeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeComputeShader;
        private static bool hasLoggedMissingTranslucencyVolumeSpatialFilterKernel;

        public override string Name => "Burt Screen Space Global Illumination Translucency Volume Spatial Filter";

        public override BurtRenderPassKind Kind => BurtRenderPassKind.GlobalState;

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGITranslucencyVolume0();
            builder.ReadBurtGITranslucencyVolume1();
            builder.WriteBurtGITranslucencyVolume0();
            builder.WriteBurtGITranslucencyVolume1();
            builder.WriteBurtGITranslucencyVolumeFilter0();
            builder.WriteBurtGITranslucencyVolumeFilter1();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(context.Request, context.Asset))
            {
                return;
            }

            if (!TryGetRequiredTargets(
                    context,
                    out var volume0Target,
                    out var volume1Target,
                    out var filter0Target,
                    out var filter1Target))
            {
                return;
            }

            var shader = GetTranslucencyVolumeComputeShader();
            if (!TryFindTranslucencyVolumeSpatialFilterKernel(shader, out var kernel))
            {
                CopyPassthroughTranslucencyVolume(context, volume0Target, volume1Target, filter0Target, filter1Target);
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            if (!screenProbeSettings.TranslucencyVolumeSpatialFilter)
            {
                CopyPassthroughTranslucencyVolume(context, volume0Target, volume1Target, filter0Target, filter1Target);
                return;
            }

            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, screenProbeSettings);
            var gridSize = new Vector4(
                descriptor.width,
                descriptor.height,
                descriptor.volumeDepth,
                BurtScreenSpaceGlobalIlluminationPassUtility.TranslucencyVolumeMaterialIntensityScale);
            var cmd = context.AcquireCommandBuffer(Name);
            var spatialFilterParams = new Vector4(
                screenProbeSettings.TranslucencyVolumeSpatialFilterSampleCount,
                screenProbeSettings.TranslucencyVolumeSpatialFilterStandardDeviation,
                1f,
                0.65f);
            DispatchSpatialFilterAxis(
                cmd,
                shader,
                kernel,
                descriptor,
                gridSize,
                spatialFilterParams,
                volume0Target,
                volume1Target,
                filter0Target,
                filter1Target,
                0);
            DispatchSpatialFilterAxis(
                cmd,
                shader,
                kernel,
                descriptor,
                gridSize,
                spatialFilterParams,
                filter0Target,
                filter1Target,
                volume0Target,
                volume1Target,
                1);
            DispatchSpatialFilterAxis(
                cmd,
                shader,
                kernel,
                descriptor,
                gridSize,
                spatialFilterParams,
                volume0Target,
                volume1Target,
                filter0Target,
                filter1Target,
                2);
            cmd.SetGlobalTexture(BurtGITranslucencyVolume0TextureId, filter0Target.Identifier);
            cmd.SetGlobalTexture(BurtGITranslucencyVolume1TextureId, filter1Target.Identifier);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeGridSizeId, gridSize);
            CopyFilteredVolumeHistory(cmd, context, filter0Target, filter1Target);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            BurtGITranslucencyVolumeRuntimeState.MarkFilteredVolumeAvailable();
        }

        private static void DispatchSpatialFilterAxis(
            CommandBuffer cmd,
            ComputeShader shader,
            int kernel,
            RenderTextureDescriptor descriptor,
            Vector4 gridSize,
            Vector4 spatialFilterParams,
            BurtRenderTargetHandle source0,
            BurtRenderTargetHandle source1,
            BurtRenderTargetHandle destination0,
            BurtRenderTargetHandle destination1,
            int axis)
        {
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolumeRead0TextureId, source0.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGITranslucencyVolumeRead1TextureId, source1.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter0TextureId, destination0.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter1TextureId, destination1.Identifier);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeGridSizeId, gridSize);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeSpatialFilterParamsId, spatialFilterParams);
            cmd.SetComputeVectorParam(shader, BurtGITranslucencyVolumeSpatialFilterDirectionId, ResolveSpatialFilterDirection(axis));
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (descriptor.width + 3) / 4),
                Mathf.Max(1, (descriptor.height + 3) / 4),
                Mathf.Max(1, (descriptor.volumeDepth + 3) / 4));
        }

        private static Vector4 ResolveSpatialFilterDirection(int axis)
        {
            switch (axis)
            {
                case 1:
                    return new Vector4(0f, 1f, 0f, 0f);
                case 2:
                    return new Vector4(0f, 0f, 1f, 0f);
                default:
                    return new Vector4(1f, 0f, 0f, 0f);
            }
        }

        private void CopyPassthroughTranslucencyVolume(
            BurtRenderGraphContext context,
            BurtRenderTargetHandle volume0Target,
            BurtRenderTargetHandle volume1Target,
            BurtRenderTargetHandle filter0Target,
            BurtRenderTargetHandle filter1Target)
        {
            if (context == null ||
                !volume0Target.IsValid ||
                !volume1Target.IsValid ||
                !filter0Target.IsValid ||
                !filter1Target.IsValid)
            {
                return;
            }

            var cmd = context.AcquireCommandBuffer(Name + " Passthrough");
            var camera = context.Request != null ? context.Request.Camera : null;
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, screenProbeSettings);
            if (!TryCopyTexture3DFloat4(cmd, volume0Target.Identifier, filter0Target.Identifier, descriptor.width, descriptor.height, descriptor.volumeDepth))
            {
                cmd.CopyTexture(volume0Target.Identifier, filter0Target.Identifier);
            }

            if (!TryCopyTexture3DFloat4(cmd, volume1Target.Identifier, filter1Target.Identifier, descriptor.width, descriptor.height, descriptor.volumeDepth))
            {
                cmd.CopyTexture(volume1Target.Identifier, filter1Target.Identifier);
            }

            cmd.SetGlobalTexture(BurtGITranslucencyVolume0TextureId, filter0Target.Identifier);
            cmd.SetGlobalTexture(BurtGITranslucencyVolume1TextureId, filter1Target.Identifier);
            CopyFilteredVolumeHistory(cmd, context, filter0Target, filter1Target);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
            BurtGITranslucencyVolumeRuntimeState.MarkFilteredVolumeAvailable();
        }

        private static void CopyFilteredVolumeHistory(
            CommandBuffer cmd,
            BurtRenderGraphContext context,
            BurtRenderTargetHandle filter0Target,
            BurtRenderTargetHandle filter1Target)
        {
            var camera = context != null && context.Request != null ? context.Request.Camera : null;
            if (!BurtGITranslucencyVolumeHistoryUtility.TryGetAllocatedHistoryTextures(camera, out var history))
            {
                return;
            }

            CopyTranslucencyVolumeHistory(cmd, camera, filter0Target, filter1Target, history);
        }

        private static bool TryGetRequiredTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle volume0Target,
            out BurtRenderTargetHandle volume1Target,
            out BurtRenderTargetHandle filter0Target,
            out BurtRenderTargetHandle filter1Target)
        {
            volume0Target = context != null ? context.BurtGITranslucencyVolume0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume0Name);
            volume1Target = context != null ? context.BurtGITranslucencyVolume1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume1Name);
            filter0Target = context != null ? context.BurtGITranslucencyVolumeFilter0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter0Name);
            filter1Target = context != null ? context.BurtGITranslucencyVolumeFilter1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter1Name);
            return volume0Target.IsValid &&
                volume1Target.IsValid &&
                filter0Target.IsValid &&
                filter1Target.IsValid;
        }

        private static ComputeShader GetTranslucencyVolumeComputeShader()
        {
            if (translucencyVolumeComputeShader != null)
            {
                return translucencyVolumeComputeShader;
            }

            translucencyVolumeComputeShader = Resources.Load<ComputeShader>(TranslucencyVolumeComputeShaderResourcePath);
            if (translucencyVolumeComputeShader == null && !hasLoggedMissingTranslucencyVolumeComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + TranslucencyVolumeComputeShaderResourcePath);
                hasLoggedMissingTranslucencyVolumeComputeShader = true;
            }

            return translucencyVolumeComputeShader;
        }

        private static bool TryFindTranslucencyVolumeSpatialFilterKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(TranslucencyVolumeSpatialFilterKernelName))
            {
                if (shader.HasKernel(TranslucencyVolumeSpatialFilterFallbackKernelName))
                {
                    kernel = shader.FindKernel(TranslucencyVolumeSpatialFilterFallbackKernelName);
                    return kernel >= 0;
                }

                if (!hasLoggedMissingTranslucencyVolumeSpatialFilterKernel)
                {
                    Debug.LogWarning("BurtRP compute shader is missing kernel: " + TranslucencyVolumeSpatialFilterKernelName);
                    hasLoggedMissingTranslucencyVolumeSpatialFilterKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(TranslucencyVolumeSpatialFilterKernelName);
            return kernel >= 0;
        }
    }

    internal static class BurtGITranslucencyVolumeRuntimeState
    {
        private static int traceAtlasFrameIndex = -1;
        private static int traceAtlasWidth;
        private static int traceAtlasHeight;
        private static int traceAtlasDepth;
        private static int traceAtlasOctResolution;
        private static int traceAtlasFilteredFrameIndex = -1;
        private static int integratedVolumeFrameIndex = -1;
        private static int integratedVolumeWidth;
        private static int integratedVolumeHeight;
        private static int integratedVolumeDepth;
        private static string integratedVolumeMode = "Never";
        private static int filteredVolumeFrameIndex = -1;

        public static bool HasTraceAtlasThisFrame => traceAtlasFrameIndex == Time.frameCount;
        public static bool HasFilteredTraceAtlasThisFrame => traceAtlasFilteredFrameIndex == Time.frameCount;
        public static bool HasIntegratedVolumeThisFrame => integratedVolumeFrameIndex == Time.frameCount;
        public static bool HasFilteredVolumeThisFrame => filteredVolumeFrameIndex == Time.frameCount;

        public static void MarkTraceAtlasGenerated(int width, int height, int depth, int octResolution)
        {
            traceAtlasFrameIndex = Time.frameCount;
            traceAtlasWidth = Mathf.Max(1, width);
            traceAtlasHeight = Mathf.Max(1, height);
            traceAtlasDepth = Mathf.Max(1, depth);
            traceAtlasOctResolution = Mathf.Clamp(octResolution, 1, 8);
        }

        public static void MarkTraceAtlasFiltered(int width, int height, int depth, int octResolution)
        {
            traceAtlasFilteredFrameIndex = Time.frameCount;
            traceAtlasWidth = Mathf.Max(1, width);
            traceAtlasHeight = Mathf.Max(1, height);
            traceAtlasDepth = Mathf.Max(1, depth);
            traceAtlasOctResolution = Mathf.Clamp(octResolution, 1, 8);
        }

        public static void MarkVolumeIntegrated(int width, int height, int depth, string mode)
        {
            integratedVolumeFrameIndex = Time.frameCount;
            integratedVolumeWidth = Mathf.Max(1, width);
            integratedVolumeHeight = Mathf.Max(1, height);
            integratedVolumeDepth = Mathf.Max(1, depth);
            integratedVolumeMode = string.IsNullOrEmpty(mode) ? "Unknown" : mode;
        }

        public static void MarkFilteredVolumeAvailable()
        {
            filteredVolumeFrameIndex = Time.frameCount;
        }

        public static string ResolveStatusLabel()
        {
            return "TraceAtlas=" + (HasTraceAtlasThisFrame ? "Generated" : "Missing") +
                "(" + traceAtlasWidth + "x" + traceAtlasHeight + "x" + traceAtlasDepth + ",Oct=" + traceAtlasOctResolution + ")" +
                ";FilteredTraceAtlas=" + (HasFilteredTraceAtlasThisFrame ? "Ready" : "Missing") +
                ";Integrate=" + (HasIntegratedVolumeThisFrame ? integratedVolumeMode : "Missing") +
                "(" + integratedVolumeWidth + "x" + integratedVolumeHeight + "x" + integratedVolumeDepth + ")" +
                ";FilteredVolume=" + (HasFilteredVolumeThisFrame ? "Ready" : "Missing");
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationBilateralUpsamplePass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const string ComputeShaderResourcePath = "BurtGIScreenProbeBilateralUpsample";
        private const int ThreadGroupSize = 8;
        private static readonly int FullSizeAndInvSizeId = Shader.PropertyToID("_BurtGIScreenProbeBilateralUpsampleFullSizeAndInvSize");
        private static readonly int HalfSizeAndInvSizeId = Shader.PropertyToID("_BurtGIScreenProbeBilateralUpsampleHalfSizeAndInvSize");
        private static readonly int DepthWeightScaleId = Shader.PropertyToID("_BurtGIScreenProbeBilateralUpsampleDepthWeightScale");
        private static readonly int BurtGIDiffuseIndirectUpsampledTextureId = Shader.PropertyToID("_BurtGIDiffuseIndirectUpsampledTexture");
        private static readonly int BurtGIBackfaceDiffuseIndirectUpsampledTextureId = Shader.PropertyToID("_BurtGIBackfaceDiffuseIndirectUpsampledTexture");
        private static readonly int BurtGIRoughSpecularIndirectUpsampledTextureId = Shader.PropertyToID("_BurtGIRoughSpecularIndirectUpsampledTexture");
        private static ComputeShader computeShader;
        private static bool hasLoggedMissingShader;
        private static bool hasLoggedMissingKernel;

        public override string Name => "Burt ScreenProbe Bilateral Upsample";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationBilateralUpsample(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadScreenSpaceGlobalIllumination();
            builder.ReadBurtGIBackfaceDiffuseIndirect();
            builder.ReadBurtGIRoughSpecularIndirect();
            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadBurtGIScreenProbeScreenDepth();
            builder.ReadBurtGIScreenProbeWorldNormal();
            builder.WriteScreenSpaceGlobalIlluminationUpsampled();
            builder.WriteBurtGIBackfaceDiffuseIndirectUpsampled();
            builder.WriteBurtGIRoughSpecularIndirectUpsampled();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationBilateralUpsample(context.Request, context.Asset))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            if (camera == null)
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            var shader = GetComputeShader();
            if (!TryFindKernel(shader, settings.EnableBackfaceDiffuse, settings.EnableRoughSpecular, out var kernel))
            {
                return;
            }

            var sourceTarget = context.ScreenSpaceGlobalIlluminationTarget;
            var backfaceTarget = context.BurtGIBackfaceDiffuseIndirectTarget;
            var roughSpecularTarget = context.BurtGIRoughSpecularIndirectTarget;
            var sourceUpsampledTarget = context.ScreenSpaceGlobalIlluminationUpsampledTarget;
            var backfaceUpsampledTarget = context.BurtGIBackfaceDiffuseIndirectUpsampledTarget;
            var roughSpecularUpsampledTarget = context.BurtGIRoughSpecularIndirectUpsampledTarget;
            var cameraDepthTarget = context.CameraDepthTarget;
            var gbuffer0Target = context.GBuffer0Target;
            var screenProbeDepthTarget = context.BurtGIScreenProbeScreenDepthTarget;
            var screenProbeWorldNormalTarget = context.BurtGIScreenProbeWorldNormalTarget;
            if (!sourceTarget.IsValid ||
                !backfaceTarget.IsValid ||
                !roughSpecularTarget.IsValid ||
                !sourceUpsampledTarget.IsValid ||
                !backfaceUpsampledTarget.IsValid ||
                !roughSpecularUpsampledTarget.IsValid ||
                !cameraDepthTarget.IsValid ||
                !gbuffer0Target.IsValid ||
                !screenProbeDepthTarget.IsValid ||
                !screenProbeWorldNormalTarget.IsValid)
            {
                return;
            }

            var halfDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var fullDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationFullResolutionDescriptor(camera);
            var fullWidth = Mathf.Max(1, fullDescriptor.width);
            var fullHeight = Mathf.Max(1, fullDescriptor.height);
            var halfWidth = Mathf.Max(1, halfDescriptor.width);
            var halfHeight = Mathf.Max(1, halfDescriptor.height);

            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetComputeTextureParam(shader, kernel, CameraDepthTextureId, cameraDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer0Id, gbuffer0Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeScreenDepthTextureId, screenProbeDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIScreenProbeWorldNormalTextureId, screenProbeWorldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIApplyIndirectDiffuseTextureId, sourceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIApplyIndirectBackfaceDiffuseTextureId, backfaceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIApplyIndirectRoughSpecularTextureId, roughSpecularTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIDiffuseIndirectUpsampledTextureId, sourceUpsampledTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIBackfaceDiffuseIndirectUpsampledTextureId, backfaceUpsampledTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRoughSpecularIndirectUpsampledTextureId, roughSpecularUpsampledTarget.Identifier);
            cmd.SetComputeVectorParam(shader, FullSizeAndInvSizeId, new Vector4(fullWidth, fullHeight, 1f / fullWidth, 1f / fullHeight));
            cmd.SetComputeVectorParam(shader, HalfSizeAndInvSizeId, new Vector4(halfWidth, halfHeight, 1f / halfWidth, 1f / halfHeight));
            cmd.SetComputeFloatParam(shader, DepthWeightScaleId, 1f);
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, Mathf.CeilToInt(fullWidth / (float)ThreadGroupSize)),
                Mathf.Max(1, Mathf.CeilToInt(fullHeight / (float)ThreadGroupSize)),
                1);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static ComputeShader GetComputeShader()
        {
            if (computeShader != null)
            {
                return computeShader;
            }

            computeShader = Resources.Load<ComputeShader>(ComputeShaderResourcePath);
            if (computeShader == null && !hasLoggedMissingShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ComputeShaderResourcePath);
                hasLoggedMissingShader = true;
            }

            return computeShader;
        }

        private static bool TryFindKernel(ComputeShader shader, bool backfaceDiffuse, bool roughSpecular, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            var kernelName = GetKernelName(backfaceDiffuse, roughSpecular);
            if (!shader.HasKernel(kernelName))
            {
                if (!hasLoggedMissingKernel)
                {
                    Debug.LogWarning("BurtRP screen probe bilateral upsample compute shader missing kernel: " + kernelName);
                    hasLoggedMissingKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(kernelName);
            return kernel >= 0;
        }

        private static string GetKernelName(bool backfaceDiffuse, bool roughSpecular)
        {
            if (backfaceDiffuse && roughSpecular)
            {
                return "MainCS_All";
            }

            if (backfaceDiffuse)
            {
                return "MainCS_DiffuseBackface";
            }

            return roughSpecular ? "MainCS_DiffuseSpecular" : "MainCS_Diffuse";
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationApplyIndirectPass : BurtScreenSpaceGlobalIlluminationPass
    {
        public override string Name => "Burt Screen Space Global Illumination Apply Indirect";

        public override BurtRenderPassKind Kind => BurtRenderPassKind.GlobalState;

        public override void Configure(BurtRenderPassBuilder builder)
        {
            var firstFrameSkip = BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationFirstFrameSkip(builder.Request);
            if (!firstFrameSkip && !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIllumination(builder.Request, builder.Asset))
            {
                return;
            }

            if (firstFrameSkip)
            {
                builder.WriteGlobalResource(BurtRenderGraphResourceRegistry.BurtGIApplyIndirectGlobalsName);
                return;
            }

            builder.ReadScreenSpaceGlobalIllumination();
            if (builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectName))
            {
                builder.ReadBurtGIBackfaceDiffuseIndirect();
            }

            if (builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectName))
            {
                builder.ReadBurtGIRoughSpecularIndirect();
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationBilateralUpsample(builder.Request, builder.Asset))
            {
                if (builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationUpsampledName))
                {
                    builder.ReadScreenSpaceGlobalIlluminationUpsampled();
                }

                if (builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectUpsampledName))
                {
                    builder.ReadBurtGIBackfaceDiffuseIndirectUpsampled();
                }

                if (builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectUpsampledName))
                {
                    builder.ReadBurtGIRoughSpecularIndirectUpsampled();
                }
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(builder.Request, builder.Asset))
            {
                if (builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter0Name) &&
                    builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter1Name))
                {
                    builder.ReadBurtGITranslucencyVolumeFilter0();
                    builder.ReadBurtGITranslucencyVolumeFilter1();
                }
                else if (builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume0Name) &&
                    builder.ResourceRegistry.ContainsRenderTarget(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume1Name))
                {
                    builder.ReadBurtGITranslucencyVolume0();
                    builder.ReadBurtGITranslucencyVolume1();
                }
            }

            builder.WriteGlobalResource(BurtRenderGraphResourceRegistry.BurtGIApplyIndirectGlobalsName);
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            var enabled = false;
            var intensity = 0f;
            var backfaceDiffuseEnabled = false;
            var roughSpecularEnabled = false;
            var translucencyVolumeEnabled = false;
            var characterIntensity = 1f;
            var diffuseColorBoost = 1f;
            var xgiScreenRatio = 1f;
            var xgiScreenRatioSpeed = 0.1f;
            var shortRangeAOParams = Vector4.zero;
            var translucencyVolumeParams = Vector4.zero;
            var burtGITarget = context != null
                ? context.ScreenSpaceGlobalIlluminationTarget
                : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationName);
            var backfaceDiffuseTarget = context != null
                ? context.BurtGIBackfaceDiffuseIndirectTarget
                : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectName);
            var roughSpecularTarget = context != null
                ? context.BurtGIRoughSpecularIndirectTarget
                : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectName);
            var translucencyVolume0Target = context != null
                ? context.BurtGITranslucencyVolume0Target
                : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume0Name);
            var translucencyVolume1Target = context != null
                ? context.BurtGITranslucencyVolume1Target
                : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolume1Name);
            var translucencyVolumeFilter0Target = context != null
                ? context.BurtGITranslucencyVolumeFilter0Target
                : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter0Name);
            var translucencyVolumeFilter1Target = context != null
                ? context.BurtGITranslucencyVolumeFilter1Target
                : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITranslucencyVolumeFilter1Name);
            if (BurtGITranslucencyVolumeRuntimeState.HasFilteredVolumeThisFrame &&
                translucencyVolumeFilter0Target.IsValid &&
                translucencyVolumeFilter1Target.IsValid)
            {
                translucencyVolume0Target = translucencyVolumeFilter0Target;
                translucencyVolume1Target = translucencyVolumeFilter1Target;
            }

            if (context != null &&
                BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationBilateralUpsample(context.Request, context.Asset))
            {
                var burtGIUpsampledTarget = context.ScreenSpaceGlobalIlluminationUpsampledTarget;
                var backfaceDiffuseUpsampledTarget = context.BurtGIBackfaceDiffuseIndirectUpsampledTarget;
                var roughSpecularUpsampledTarget = context.BurtGIRoughSpecularIndirectUpsampledTarget;
                if (burtGIUpsampledTarget.IsValid)
                {
                    burtGITarget = burtGIUpsampledTarget;
                }

                if (backfaceDiffuseUpsampledTarget.IsValid)
                {
                    backfaceDiffuseTarget = backfaceDiffuseUpsampledTarget;
                }

                if (roughSpecularUpsampledTarget.IsValid)
                {
                    roughSpecularTarget = roughSpecularUpsampledTarget;
                }
            }

            if (context != null &&
                burtGITarget.IsValid &&
                !BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationFirstFrameSkip(context.Request) &&
                BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIllumination(context.Request, context.Asset))
            {
                var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
                enabled = settings.Enabled;
                intensity = settings.Intensity;
                backfaceDiffuseEnabled = settings.EnableBackfaceDiffuse && backfaceDiffuseTarget.IsValid;
                roughSpecularEnabled = settings.EnableRoughSpecular && roughSpecularTarget.IsValid;
                translucencyVolumeEnabled = settings.UseTranslucencyVolume;
                characterIntensity = settings.XGICharacterIntensity;
                diffuseColorBoost = 1f / Mathf.Clamp(settings.SceneVoxelDiffuseColorBoost, 1f, 4f);
                xgiScreenRatio = settings.XGIScreenRatio;
                xgiScreenRatioSpeed = settings.XGIScreenRatioSpeed;
                shortRangeAOParams = new Vector4(
                    settings.ShortRangeAO ? 1f : 0f,
                    settings.ShortRangeAOApplyWeight,
                    settings.ShortRangeAOSlopeCompareToleranceScale,
                    2f);
                translucencyVolumeParams = new Vector4(1f, BurtScreenSpaceGlobalIlluminationPassUtility.TranslucencyVolumeApplyIntensityScale, 0.55f, 1f);
            }

            var cmd = context.AcquireCommandBuffer(Name);
            if (enabled)
            {
                cmd.SetGlobalTexture(BurtGIApplyIndirectDiffuseTextureId, burtGITarget.Identifier);
            }
            else
            {
                cmd.SetGlobalTexture(BurtGIApplyIndirectDiffuseTextureId, Texture2D.blackTexture);
            }

            cmd.SetGlobalTexture(BurtGIApplyIndirectBackfaceDiffuseTextureId, enabled && backfaceDiffuseEnabled && backfaceDiffuseTarget.IsValid ? backfaceDiffuseTarget.Identifier : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIApplyIndirectRoughSpecularTextureId, enabled && roughSpecularEnabled && roughSpecularTarget.IsValid ? roughSpecularTarget.Identifier : Texture2D.blackTexture);
            var volumeEnabled = enabled &&
                translucencyVolumeEnabled &&
                BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(context != null ? context.Request : null, context != null ? context.Asset : null) &&
                translucencyVolume0Target.IsValid &&
                translucencyVolume1Target.IsValid;
            var fallbackVolumeTexture = BurtGITranslucencyVolumeFallbackUtility.BlackVolumeTexture;
            cmd.SetGlobalTexture(BurtGITranslucencyVolume0TextureId, volumeEnabled ? translucencyVolume0Target.Identifier : fallbackVolumeTexture);
            cmd.SetGlobalTexture(BurtGITranslucencyVolume1TextureId, volumeEnabled ? translucencyVolume1Target.Identifier : fallbackVolumeTexture);
            cmd.SetGlobalVector(BurtGIApplyIndirectParamsId, new Vector4(
                enabled ? 1f : 0f,
                intensity,
                enabled && backfaceDiffuseEnabled ? 1f : 0f,
                enabled && roughSpecularEnabled ? 1f : 0f));
            cmd.SetGlobalVector(BurtGIApplyIndirectParams1Id, new Vector4(
                enabled ? characterIntensity : 1f,
                enabled ? diffuseColorBoost : 1f,
                enabled ? xgiScreenRatio : 1f,
                enabled ? xgiScreenRatioSpeed : 0.1f));
            cmd.SetGlobalVector(BurtGIShortRangeAOParamsId, enabled ? shortRangeAOParams : Vector4.zero);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeParamsId, volumeEnabled ? translucencyVolumeParams : Vector4.zero);
            UploadTranslucencyVolumeGlobals(context, cmd, volumeEnabled);
            if (context != null)
            {
                context.ExecuteLegacyCommandBuffer(cmd);
            }

            context.ReleaseCommandBuffer(cmd);
        }

        private static void UploadTranslucencyVolumeGlobals(BurtRenderGraphContext context, CommandBuffer cmd, bool enabled)
        {
            if (!enabled)
            {
                cmd.SetGlobalVector(BurtGITranslucencyVolumeGridSizeId, Vector4.zero);
                cmd.SetGlobalVector(BurtGITranslucencyVolumeGridZParamsId, Vector4.zero);
                cmd.SetGlobalVector(BurtGITranslucencyVolumeParams0Id, Vector4.zero);
                return;
            }

            var camera = context != null && context.Request != null ? context.Request.Camera : null;
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context != null ? context.Request : null, context != null ? context.Asset : null);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, settings);
            var nearPlane = camera != null ? Mathf.Max(camera.nearClipPlane, 0.01f) : 0.1f;
            var cameraFarPlane = camera != null ? Mathf.Max(camera.farClipPlane, nearPlane + 1f) : 1000f;
            var farPlane = Mathf.Min(cameraFarPlane, nearPlane + settings.TranslucencyVolumeEndDistanceFromCamera);
            cmd.SetGlobalVector(BurtGITranslucencyVolumeGridSizeId, new Vector4(
                descriptor.width,
                descriptor.height,
                descriptor.volumeDepth,
                BurtScreenSpaceGlobalIlluminationPassUtility.TranslucencyVolumeMaterialIntensityScale));
            cmd.SetGlobalVector(BurtGITranslucencyVolumeGridZParamsId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveTranslucencyVolumeGridZParams(settings));
            cmd.SetGlobalVector(BurtGITranslucencyVolumeParams0Id, new Vector4(nearPlane, farPlane, 0.75f, 0.65f));
        }
    }

    internal static class BurtGITranslucencyVolumeFallbackUtility
    {
        private static Texture3D blackVolumeTexture;
        private static RenderTexture blackVolumeRenderTexture;

        public static Texture3D BlackVolumeTexture
        {
            get
            {
                if (blackVolumeTexture != null)
                {
                    return blackVolumeTexture;
                }

                blackVolumeTexture = new Texture3D(1, 1, 1, TextureFormat.RGBA32, false, true)
                {
                    name = "BurtGI Black Translucency Volume",
                    filterMode = FilterMode.Bilinear,
                    wrapMode = TextureWrapMode.Clamp
                };
                blackVolumeTexture.SetPixel(0, 0, 0, Color.clear);
                blackVolumeTexture.Apply(false, true);
                return blackVolumeTexture;
            }
        }

        public static RenderTexture BlackVolumeRenderTexture
        {
            get
            {
                if (blackVolumeRenderTexture != null && blackVolumeRenderTexture.IsCreated())
                {
                    return blackVolumeRenderTexture;
                }

                if (blackVolumeRenderTexture != null)
                {
                    blackVolumeRenderTexture.Release();
                }

                blackVolumeRenderTexture = new RenderTexture(new RenderTextureDescriptor(1, 1, RenderTextureFormat.ARGBHalf, 0)
                {
                    dimension = TextureDimension.Tex3D,
                    volumeDepth = 1,
                    msaaSamples = 1,
                    useMipMap = false,
                    autoGenerateMips = false,
                    enableRandomWrite = true,
                    sRGB = false
                })
                {
                    name = "BurtGI Black Volume Fallback RT",
                    filterMode = FilterMode.Bilinear,
                    wrapMode = TextureWrapMode.Clamp
                };
                blackVolumeRenderTexture.Create();
                return blackVolumeRenderTexture;
            }
        }
    }

    internal readonly struct BurtGITranslucencyVolumeHistoryTextures
    {
        public RenderTexture Volume0 { get; }
        public RenderTexture Volume1 { get; }
        public float HistoryExposureCorrection { get; }

        public BurtGITranslucencyVolumeHistoryTextures(RenderTexture volume0, RenderTexture volume1, float historyExposureCorrection = 1f)
        {
            Volume0 = volume0;
            Volume1 = volume1;
            HistoryExposureCorrection = Mathf.Max(historyExposureCorrection, 0f);
        }

        public static BurtGITranslucencyVolumeHistoryTextures Invalid => new BurtGITranslucencyVolumeHistoryTextures(null, null);
    }

    internal readonly struct BurtGITranslucencyVolumeHistoryStatus
    {
        public bool HasHistory { get; }
        public bool DescriptorMatches { get; }
        public int Width { get; }
        public int Height { get; }
        public int Depth { get; }
        public int FrameIndex { get; }
        public string LastInvalidationReason { get; }

        public BurtGITranslucencyVolumeHistoryStatus(
            bool hasHistory,
            bool descriptorMatches,
            int width,
            int height,
            int depth,
            int frameIndex,
            string lastInvalidationReason)
        {
            HasHistory = hasHistory;
            DescriptorMatches = descriptorMatches;
            Width = width;
            Height = height;
            Depth = depth;
            FrameIndex = frameIndex;
            LastInvalidationReason = lastInvalidationReason;
        }
    }

    internal static class BurtGITranslucencyVolumeHistoryUtility
    {
        private const int HistoryAlgorithmVersion = 1;
        private const int CameraStatePruneInterval = 128;
        private const float ProjectionChangeEpsilon = 0.0001f;

        private sealed class CameraState
        {
            public Camera Camera;
            public RenderTexture Volume0History;
            public RenderTexture Volume1History;
            public RenderTextureDescriptor Descriptor;
            public int AlgorithmVersion;
            public bool HasValidHistory;
            public bool HasPreviousCameraState;
            public bool HasSettingsSignature;
            public int SettingsSignature;
            public int FrameIndex;
            public Matrix4x4 CurrentNonJitteredProjectionMatrix = Matrix4x4.identity;
            public Matrix4x4 PreviousNonJitteredProjectionMatrix = Matrix4x4.identity;
            public BurtRendererMode CurrentRendererMode = BurtRendererMode.Forward;
            public BurtRendererMode PreviousRendererMode = BurtRendererMode.Forward;
            public bool CurrentOrthographic;
            public bool PreviousOrthographic;
            public float CurrentFieldOfView;
            public float PreviousFieldOfView;
            public float CurrentOrthographicSize;
            public float PreviousOrthographicSize;
            public float CurrentNearClipPlane;
            public float PreviousNearClipPlane;
            public float CurrentFarClipPlane;
            public float PreviousFarClipPlane;
            public int CurrentTargetTextureId;
            public int PreviousTargetTextureId;
            public int CurrentTargetWidth;
            public int CurrentTargetHeight;
            public int PreviousTargetWidth;
            public int PreviousTargetHeight;
            public float CurrentPreExposure = 1f;
            public float PreviousPreExposure = 1f;
            public string LastInvalidationReason = "NeverAllocated";
        }

        private static readonly System.Collections.Generic.Dictionary<int, CameraState> CameraStates = new System.Collections.Generic.Dictionary<int, CameraState>();
        private static readonly System.Collections.Generic.List<int> CameraStateRemovalKeys = new System.Collections.Generic.List<int>();
        private static int cameraStatePruneCounter;

        public static BurtGITranslucencyVolumeHistoryTextures EnsureHistoryTextures(
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            out bool historyValid)
        {
            historyValid = false;
            var camera = request != null ? request.Camera : null;
            if (camera == null)
            {
                return BurtGITranslucencyVolumeHistoryTextures.Invalid;
            }

            if (!settings.Enabled ||
                !settings.UseTranslucencyVolume ||
                !settings.TemporalAccumulation ||
                !screenProbeSettings.Enabled ||
                screenProbeSettings.TemporalFeedback <= 0.0001f)
            {
                if (!settings.UseTranslucencyVolume)
                {
                    ReleaseHistory(camera, "TranslucencyVolumeDisabled");
                }
                else
                {
                    InvalidateHistory(camera, "TemporalDisabled");
                }

                return BurtGITranslucencyVolumeHistoryTextures.Invalid;
            }

            var state = GetOrCreateState(camera.GetInstanceID());
            state.Camera = camera;
            PruneDisposedCameraStates();
            if (state.AlgorithmVersion != HistoryAlgorithmVersion)
            {
                ReleaseHistory(state);
                state.AlgorithmVersion = HistoryAlgorithmVersion;
                SetAllocationInvalidationReason(state, "AlgorithmChanged");
            }

            var matrices = BurtScreenSpaceGlobalIlluminationHistoryUtility.CreateCurrentMatrices(request);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, screenProbeSettings);
            var descriptorMatches = state.Volume0History != null &&
                state.Volume1History != null &&
                Matches(state.Descriptor, descriptor);
            BurtScreenSpaceGlobalIlluminationPassUtility.GetCameraTargetSize(camera, out var targetWidth, out var targetHeight);
            var rendererMode = asset != null ? asset.RendererMode : BurtRendererMode.Forward;
            var currentPreExposure = PreExposureUtility.ResolveForFrame(request, asset).PreExposure;
            var invalidationReason = ResolveHistoryInvalidationReason(
                camera,
                state,
                rendererMode,
                matrices.NonJitteredProjectionMatrix,
                targetWidth,
                targetHeight,
                descriptorMatches,
                screenProbeSettings,
                currentPreExposure);
            var settingsSignature = CreateSettingsSignature(settings, screenProbeSettings);
            if (string.IsNullOrEmpty(invalidationReason) && state.HasSettingsSignature && state.SettingsSignature != settingsSignature)
            {
                invalidationReason = "SettingsChanged";
            }

            if (!descriptorMatches)
            {
                ReleaseHistory(state);
            }

            if (state.Volume0History == null)
            {
                state.Descriptor = descriptor;
                state.Volume0History = CreateHistoryTexture(descriptor, "BurtGI Translucency Volume0 History " + camera.GetInstanceID(), FilterMode.Bilinear);
                SetAllocationInvalidationReason(state, "Volume0HistoryAllocated");
            }

            if (state.Volume1History == null)
            {
                state.Volume1History = CreateHistoryTexture(descriptor, "BurtGI Translucency Volume1 History " + camera.GetInstanceID(), FilterMode.Bilinear);
                SetAllocationInvalidationReason(state, "Volume1HistoryAllocated");
            }

            if (!string.IsNullOrEmpty(invalidationReason))
            {
                InvalidateState(state, invalidationReason);
            }

            state.FrameIndex++;
            state.CurrentRendererMode = rendererMode;
            state.CurrentNonJitteredProjectionMatrix = matrices.NonJitteredProjectionMatrix;
            state.SettingsSignature = settingsSignature;
            state.HasSettingsSignature = true;
            CaptureCurrentCameraState(camera, state, targetWidth, targetHeight, currentPreExposure);

            historyValid = state.HasValidHistory &&
                state.HasPreviousCameraState &&
                state.Volume0History != null &&
                state.Volume1History != null;
            return new BurtGITranslucencyVolumeHistoryTextures(state.Volume0History, state.Volume1History, ResolveHistoryExposureCorrection(state, historyValid));
        }

        public static bool TryGetAllocatedHistoryTextures(Camera camera, out BurtGITranslucencyVolumeHistoryTextures history)
        {
            history = BurtGITranslucencyVolumeHistoryTextures.Invalid;
            if (camera == null || !CameraStates.TryGetValue(camera.GetInstanceID(), out var state))
            {
                return false;
            }

            if (state.Volume0History == null || state.Volume1History == null)
            {
                return false;
            }

            history = new BurtGITranslucencyVolumeHistoryTextures(state.Volume0History, state.Volume1History);
            return true;
        }

        public static void MarkHistoryValid(Camera camera)
        {
            if (camera == null || !CameraStates.TryGetValue(camera.GetInstanceID(), out var state))
            {
                return;
            }

            state.HasValidHistory = state.Volume0History != null && state.Volume1History != null;
            if (!state.HasValidHistory)
            {
                return;
            }

            state.PreviousRendererMode = state.CurrentRendererMode;
            state.PreviousNonJitteredProjectionMatrix = state.CurrentNonJitteredProjectionMatrix;
            state.PreviousOrthographic = state.CurrentOrthographic;
            state.PreviousFieldOfView = state.CurrentFieldOfView;
            state.PreviousOrthographicSize = state.CurrentOrthographicSize;
            state.PreviousNearClipPlane = state.CurrentNearClipPlane;
            state.PreviousFarClipPlane = state.CurrentFarClipPlane;
            state.PreviousTargetTextureId = state.CurrentTargetTextureId;
            state.PreviousTargetWidth = state.CurrentTargetWidth;
            state.PreviousTargetHeight = state.CurrentTargetHeight;
            state.PreviousPreExposure = state.CurrentPreExposure;
            state.HasPreviousCameraState = true;
            state.LastInvalidationReason = "Valid";
        }

        public static void InvalidateHistory(Camera camera, string reason)
        {
            if (camera == null || !CameraStates.TryGetValue(camera.GetInstanceID(), out var state))
            {
                return;
            }

            InvalidateState(state, reason);
        }

        public static void ReleaseHistory(Camera camera, string reason)
        {
            if (camera == null || !CameraStates.TryGetValue(camera.GetInstanceID(), out var state))
            {
                return;
            }

            ReleaseHistory(state);
            state.LastInvalidationReason = string.IsNullOrEmpty(reason) ? "Released" : reason;
        }

        public static BurtGITranslucencyVolumeHistoryStatus GetHistoryStatus(
            BurtRenderRequest request,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings)
        {
            if (!settings.Enabled)
            {
                return new BurtGITranslucencyVolumeHistoryStatus(false, false, 0, 0, 0, 0, "Disabled");
            }

            if (!settings.UseTranslucencyVolume)
            {
                return new BurtGITranslucencyVolumeHistoryStatus(false, false, 0, 0, 0, 0, "TranslucencyVolumeDisabled");
            }

            if (!settings.TemporalAccumulation || !screenProbeSettings.Enabled)
            {
                return new BurtGITranslucencyVolumeHistoryStatus(false, false, 0, 0, 0, 0, "TemporalDisabled");
            }

            var camera = request != null ? request.Camera : null;
            if (camera == null || !CameraStates.TryGetValue(camera.GetInstanceID(), out var state))
            {
                return new BurtGITranslucencyVolumeHistoryStatus(false, false, 0, 0, 0, 0, "NoCameraOrHistory");
            }

            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, screenProbeSettings);
            var hasHistory = state.Volume0History != null && state.Volume1History != null;
            return new BurtGITranslucencyVolumeHistoryStatus(
                state.HasValidHistory && hasHistory,
                hasHistory && Matches(state.Descriptor, descriptor),
                state.Volume0History != null ? state.Volume0History.width : 0,
                state.Volume0History != null ? state.Volume0History.height : 0,
                state.Volume0History != null ? state.Volume0History.volumeDepth : 0,
                state.FrameIndex,
                state.LastInvalidationReason);
        }

        private static CameraState GetOrCreateState(int cameraId)
        {
            if (!CameraStates.TryGetValue(cameraId, out var state))
            {
                state = new CameraState();
                CameraStates.Add(cameraId, state);
            }

            return state;
        }

        private static void PruneDisposedCameraStates()
        {
            cameraStatePruneCounter++;
            if (cameraStatePruneCounter < CameraStatePruneInterval)
            {
                return;
            }

            cameraStatePruneCounter = 0;
            CameraStateRemovalKeys.Clear();
            foreach (var pair in CameraStates)
            {
                if (pair.Value.Camera != null)
                {
                    continue;
                }

                ReleaseHistory(pair.Value);
                CameraStateRemovalKeys.Add(pair.Key);
            }

            for (var i = 0; i < CameraStateRemovalKeys.Count; i++)
            {
                CameraStates.Remove(CameraStateRemovalKeys[i]);
            }

            CameraStateRemovalKeys.Clear();
        }

        private static RenderTexture CreateHistoryTexture(RenderTextureDescriptor descriptor, string name, FilterMode filterMode)
        {
            var texture = new RenderTexture(descriptor)
            {
                name = name,
                hideFlags = HideFlags.HideAndDontSave,
                filterMode = filterMode,
                wrapMode = TextureWrapMode.Clamp
            };
            texture.Create();
            return texture;
        }

        private static bool Matches(RenderTextureDescriptor left, RenderTextureDescriptor right)
        {
            return left.width == right.width &&
                left.height == right.height &&
                left.volumeDepth == right.volumeDepth &&
                left.dimension == right.dimension &&
                left.colorFormat == right.colorFormat &&
                left.depthBufferBits == right.depthBufferBits &&
                left.msaaSamples == right.msaaSamples &&
                left.enableRandomWrite == right.enableRandomWrite &&
                left.useMipMap == right.useMipMap &&
                left.autoGenerateMips == right.autoGenerateMips &&
                left.mipCount == right.mipCount &&
                left.sRGB == right.sRGB;
        }

        private static string ResolveHistoryInvalidationReason(
            Camera camera,
            CameraState state,
            BurtRendererMode rendererMode,
            Matrix4x4 nonJitteredProjectionMatrix,
            int targetWidth,
            int targetHeight,
            bool descriptorsMatch,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            float currentPreExposure)
        {
            if (!descriptorsMatch)
            {
                return "DescriptorChanged";
            }

            if (!state.HasPreviousCameraState)
            {
                return state.HasValidHistory ? "MissingPreviousCameraState" : null;
            }

            if (state.PreviousRendererMode != rendererMode)
            {
                return "RendererModeChanged";
            }

            if (state.PreviousTargetTextureId != GetTargetTextureId(camera) ||
                state.PreviousTargetWidth != targetWidth ||
                state.PreviousTargetHeight != targetHeight)
            {
                return "TargetChanged";
            }

            if (state.PreviousOrthographic != camera.orthographic)
            {
                return "ProjectionModeChanged";
            }

            if (camera.orthographic)
            {
                if (Mathf.Abs(state.PreviousOrthographicSize - camera.orthographicSize) > ProjectionChangeEpsilon)
                {
                    return "OrthographicSizeChanged";
                }
            }
            else if (Mathf.Abs(state.PreviousFieldOfView - camera.fieldOfView) > ProjectionChangeEpsilon)
            {
                return "FieldOfViewChanged";
            }

            if (Mathf.Abs(state.PreviousNearClipPlane - camera.nearClipPlane) > ProjectionChangeEpsilon)
            {
                return "NearClipChanged";
            }

            if (Mathf.Abs(state.PreviousFarClipPlane - camera.farClipPlane) > ProjectionChangeEpsilon)
            {
                return "FarClipChanged";
            }

            if (!Approximately(state.PreviousNonJitteredProjectionMatrix, nonJitteredProjectionMatrix))
            {
                return "ProjectionMatrixChanged";
            }

            var previousPreExposure = PreExposureUtility.SanitizeExposure(state.PreviousPreExposure, 1f);
            var safeCurrentPreExposure = PreExposureUtility.SanitizeExposure(currentPreExposure, 1f);
            var exposureRatio = Mathf.Max(safeCurrentPreExposure / previousPreExposure, previousPreExposure / safeCurrentPreExposure);
            if (Mathf.Log(exposureRatio, 2f) > screenProbeSettings.TemporalExposureCheckThreshold)
            {
                return "ExposureChanged";
            }

            return null;
        }

        private static int CreateSettingsSignature(
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings)
        {
            unchecked
            {
                return (settings.CreateHistorySignature() * 397) ^ screenProbeSettings.CreateHistorySignature();
            }
        }

        private static void CaptureCurrentCameraState(Camera camera, CameraState state, int targetWidth, int targetHeight, float currentPreExposure)
        {
            state.CurrentOrthographic = camera.orthographic;
            state.CurrentFieldOfView = camera.fieldOfView;
            state.CurrentOrthographicSize = camera.orthographicSize;
            state.CurrentNearClipPlane = camera.nearClipPlane;
            state.CurrentFarClipPlane = camera.farClipPlane;
            state.CurrentTargetTextureId = GetTargetTextureId(camera);
            state.CurrentTargetWidth = targetWidth;
            state.CurrentTargetHeight = targetHeight;
            state.CurrentPreExposure = PreExposureUtility.SanitizeExposure(currentPreExposure, 1f);
        }

        private static float ResolveHistoryExposureCorrection(CameraState state, bool historyValid)
        {
            if (state == null || !historyValid)
            {
                return 1f;
            }

            var previousPreExposure = PreExposureUtility.SanitizeExposure(state.PreviousPreExposure, 1f);
            var currentPreExposure = PreExposureUtility.SanitizeExposure(state.CurrentPreExposure, 1f);
            return currentPreExposure / previousPreExposure;
        }

        private static bool Approximately(Matrix4x4 a, Matrix4x4 b)
        {
            for (var i = 0; i < 16; i++)
            {
                if (Mathf.Abs(a[i] - b[i]) > ProjectionChangeEpsilon)
                {
                    return false;
                }
            }

            return true;
        }

        private static int GetTargetTextureId(Camera camera)
        {
            return camera != null && camera.targetTexture != null ? camera.targetTexture.GetInstanceID() : 0;
        }

        private static void SetAllocationInvalidationReason(CameraState state, string reason)
        {
            if (state == null || state.HasValidHistory)
            {
                return;
            }

            state.LastInvalidationReason = reason;
        }

        private static void InvalidateState(CameraState state, string reason)
        {
            if (state == null)
            {
                return;
            }

            state.HasValidHistory = false;
            state.LastInvalidationReason = string.IsNullOrEmpty(reason) ? "Manual" : reason;
        }

        private static void ReleaseHistory(CameraState state)
        {
            if (state == null)
            {
                return;
            }

            ReleaseTexture(state.Volume0History);
            ReleaseTexture(state.Volume1History);
            state.Volume0History = null;
            state.Volume1History = null;
            state.HasValidHistory = false;
            state.HasSettingsSignature = false;
        }

        private static void ReleaseTexture(RenderTexture texture)
        {
            if (texture == null)
            {
                return;
            }

            texture.Release();
            Object.DestroyImmediate(texture);
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationResolveIndirectChannelsPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const int ResolveIndirectChannelsPassIndex = 8;
        private const int CopyDepthNormalPassIndex = 5;
        private static readonly int BurtGIBackfaceDiffuseIndirectHistoryTextureId = Shader.PropertyToID("_BurtGIBackfaceDiffuseIndirectHistoryTexture");
        private static readonly int BurtGIRoughSpecularIndirectHistoryTextureId = Shader.PropertyToID("_BurtGIRoughSpecularIndirectHistoryTexture");
        private static readonly int BurtGIHistoryDepthNormalTextureId = Shader.PropertyToID("_BurtGIHistoryDepthNormalTexture");
        private static readonly int BurtGIIndirectHistoryDepthNormalTextureId = Shader.PropertyToID("_BurtGIIndirectHistoryDepthNormalTexture");
        private static readonly int BurtGIPreviousViewProjectionMatrixId = Shader.PropertyToID("_BurtGIPreviousViewProjectionMatrix");
        private static readonly int BurtGITemporalParamsId = Shader.PropertyToID("_BurtGITemporalParams");
        private static readonly int BurtGITemporalParams1Id = Shader.PropertyToID("_BurtGITemporalParams1");

        public override string Name => "Burt Screen Space Global Illumination Resolve Indirect Channels";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIllumination(builder.Request, builder.Asset))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(builder.Request, builder.Asset);
            if (settings.FinalGather == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField)
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadScreenSpaceGlobalIllumination();
            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadGBuffer1();
            builder.ReadGBuffer2();
            builder.ReadGBuffer3();
            builder.ReadGBuffer4();
            builder.ReadGBuffer5();
            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                builder.ReadBurtGIScreenProbeFixupIrradiance();
                builder.ReadBurtGIScreenProbeFixupConfidence();
                builder.ReadBurtGIScreenProbeMipIrradiance();
                builder.ReadBurtGIScreenProbeMipConfidence();
                builder.ReadBurtGIScreenProbeMip2Irradiance();
                builder.ReadBurtGIScreenProbeMip2Confidence();
                builder.ReadBurtGIScreenProbeMip3Irradiance();
                builder.ReadBurtGIScreenProbeMip3Confidence();
                builder.ReadBurtGIScreenProbeRadianceSHAmbient();
                builder.ReadBurtGIScreenProbeRadianceSHDirectional();
                builder.ReadBurtGIScreenProbeIrradianceOct();
                builder.ReadBurtGIScreenProbeRadianceOct();
                builder.ReadBurtGIScreenProbeTraceRadiance();
                builder.ReadBurtGIScreenProbeTraceHit();
                builder.ReadBurtGIScreenProbeHitDistance();
                builder.ReadBurtGIScreenProbeBentNormal();
                builder.ReadBurtGIScreenProbeWorldNormal();
                builder.ReadBurtGIScreenProbeWorldPosition();
                if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(builder.Request, builder.Asset))
                {
                    builder.ReadBurtGIRadianceCacheClipMapIndirection();
                    builder.ReadBurtGIRadianceCacheClipMapFinalRadianceAtlas();
                    builder.ReadBurtGIRadianceCacheClipMapFinalIrradianceAtlas();
                    builder.ReadBurtGIRadianceCacheClipMapProbeOcclusionAtlas();
                    builder.ReadBurtGIRadianceCacheClipMapProbeSkyAOAtlas();
                    builder.ReadBurtGIRadianceCacheClipMapProbeWorldOffsetBuffer();
                }
            }

            builder.WriteBurtGIBackfaceDiffuseIndirect();
            builder.WriteBurtGIRoughSpecularIndirect();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(
                    context,
                    out var cameraDepthTarget,
                    out var gbuffer0Target,
                    out var gbuffer1Target,
                    out var gbuffer2Target,
                    out var gbuffer3Target,
                    out var gbuffer4Target,
                    out var gbuffer5Target,
                    out var burtGITarget,
                    out var backfaceDiffuseTarget,
                    out var roughSpecularTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            if (!settings.Enabled || settings.FinalGather == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField)
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(context.Request, context.Asset))
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            var camera = context.Request != null ? context.Request.Camera : null;
            if (material == null || camera == null)
            {
                return;
            }

            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var indirectHistory = BurtScreenSpaceGlobalIlluminationIndirectChannelHistoryUtility.EnsureHistoryTextures(context.Request, context.Asset, settings, out var indirectHistoryValid);
            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetRenderTarget(
                new[]
                {
                    backfaceDiffuseTarget.Identifier,
                    roughSpecularTarget.Identifier,
                },
                new RenderTargetIdentifier(BuiltinRenderTextureType.None));
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, descriptor.width, descriptor.height);
            cmd.SetGlobalTexture(CameraDepthTextureId, cameraDepthTarget.Identifier);
            BurtDeferredStencilTextureUtility.BindGlobal(cmd, cameraDepthTarget, camera);
            cmd.SetGlobalTexture(BurtGITextureId, burtGITarget.Identifier);
            var screenProbeBentNormalTarget = context.BurtGIScreenProbeBentNormalTarget;
            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(context.Request, context.Asset) && screenProbeBentNormalTarget.IsValid)
            {
                cmd.SetGlobalTexture(BurtGIScreenProbeBentNormalTextureId, screenProbeBentNormalTarget.Identifier);
            }
            else
            {
                cmd.SetGlobalTexture(BurtGIScreenProbeBentNormalTextureId, Texture2D.blackTexture);
            }

            BindGBufferInputs(cmd, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, gbuffer4Target, gbuffer5Target);
            UploadCameraGlobals(cmd, context.Request, camera, descriptor);
            UploadSettings(cmd, settings);
            cmd.SetGlobalVector(BurtGIIndirectChannelParamsId, new Vector4(
                settings.EnableBackfaceDiffuse ? 1f : 0f,
                settings.EnableRoughSpecular ? 1f : 0f,
                indirectHistory.HistoryExposureCorrection,
                settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular));
            BindScreenProbeIndirectChannelInputs(cmd, context, camera, descriptor);
            BindIndirectChannelHistory(cmd, indirectHistory, indirectHistoryValid, settings);
            cmd.DrawProcedural(Matrix4x4.identity, material, ResolveIndirectChannelsPassIndex, MeshTopology.Triangles, 3, 1);
            cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectTextureId, backfaceDiffuseTarget.Identifier);
            cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectTextureId, roughSpecularTarget.Identifier);
            CopyIndirectChannelHistory(cmd, material, camera, settings, descriptor, backfaceDiffuseTarget, roughSpecularTarget, indirectHistory);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static void BindScreenProbeIndirectChannelInputs(
            CommandBuffer cmd,
            BurtRenderGraphContext context,
            Camera camera,
            RenderTextureDescriptor fallbackDescriptor)
        {
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var screenProbeFixupIrradianceTarget = context.BurtGIScreenProbeFixupIrradianceTarget;
            var screenProbeFixupConfidenceTarget = context.BurtGIScreenProbeFixupConfidenceTarget;
            var screenProbeMipIrradianceTarget = context.BurtGIScreenProbeMipIrradianceTarget;
            var screenProbeMipConfidenceTarget = context.BurtGIScreenProbeMipConfidenceTarget;
            var screenProbeMip2IrradianceTarget = context.BurtGIScreenProbeMip2IrradianceTarget;
            var screenProbeMip2ConfidenceTarget = context.BurtGIScreenProbeMip2ConfidenceTarget;
            var screenProbeMip3IrradianceTarget = context.BurtGIScreenProbeMip3IrradianceTarget;
            var screenProbeMip3ConfidenceTarget = context.BurtGIScreenProbeMip3ConfidenceTarget;
            var screenProbeRadianceSHAmbientTarget = context.BurtGIScreenProbeRadianceSHAmbientTarget;
            var screenProbeRadianceSHDirectionalTarget = context.BurtGIScreenProbeRadianceSHDirectionalTarget;
            var screenProbeIrradianceOctTarget = context.BurtGIScreenProbeIrradianceOctTarget;
            var screenProbeRadianceOctTarget = context.BurtGIScreenProbeRadianceOctTarget;
            var screenProbeTraceRadianceTarget = context.BurtGIScreenProbeTraceRadianceTarget;
            var screenProbeTraceHitTarget = context.BurtGIScreenProbeTraceHitTarget;
            var screenProbeHitDistanceTarget = context.BurtGIScreenProbeHitDistanceTarget;
            var screenProbeBentNormalTarget = context.BurtGIScreenProbeBentNormalTarget;
            var screenProbeWorldNormalTarget = context.BurtGIScreenProbeWorldNormalTarget;
            var screenProbeWorldPositionTarget = context.BurtGIScreenProbeWorldPositionTarget;
            var radianceCacheIndirectionTarget = context.BurtGIRadianceCacheClipMapIndirectionTarget;
            var radianceCacheFinalRadianceAtlasTarget = context.BurtGIRadianceCacheClipMapFinalRadianceAtlasTarget;
            var radianceCacheFinalIrradianceAtlasTarget = context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget;
            var radianceCacheProbeOcclusionAtlasTarget = context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget;
            var radianceCacheProbeSkyAOAtlasTarget = context.BurtGIRadianceCacheClipMapProbeSkyAOAtlasTarget;
            var radianceCacheProbeWorldOffsetBuffer = context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer;
            var hasScreenProbeTargets = screenProbeSettings.Enabled &&
                screenProbeFixupIrradianceTarget.IsValid &&
                screenProbeFixupConfidenceTarget.IsValid &&
                screenProbeMipIrradianceTarget.IsValid &&
                screenProbeMipConfidenceTarget.IsValid &&
                screenProbeMip2IrradianceTarget.IsValid &&
                screenProbeMip2ConfidenceTarget.IsValid &&
                screenProbeMip3IrradianceTarget.IsValid &&
                screenProbeMip3ConfidenceTarget.IsValid &&
                screenProbeRadianceSHAmbientTarget.IsValid &&
                screenProbeRadianceSHDirectionalTarget.IsValid &&
                screenProbeIrradianceOctTarget.IsValid &&
                screenProbeRadianceOctTarget.IsValid &&
                screenProbeTraceRadianceTarget.IsValid &&
                screenProbeTraceHitTarget.IsValid &&
                screenProbeHitDistanceTarget.IsValid &&
                screenProbeBentNormalTarget.IsValid &&
                screenProbeWorldNormalTarget.IsValid &&
                screenProbeWorldPositionTarget.IsValid;
            var hasRadianceCacheTargets = hasScreenProbeTargets &&
                BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(context.Request, context.Asset) &&
                radianceCacheIndirectionTarget.IsValid &&
                radianceCacheFinalRadianceAtlasTarget.IsValid &&
                radianceCacheFinalIrradianceAtlasTarget.IsValid &&
                radianceCacheProbeOcclusionAtlasTarget.IsValid &&
                radianceCacheProbeSkyAOAtlasTarget.IsValid &&
                radianceCacheProbeWorldOffsetBuffer.HasBuffer;

            if (hasScreenProbeTargets)
            {
                var screenProbeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
                cmd.SetGlobalTexture(BurtGIScreenProbeFixupIrradianceTextureId, screenProbeFixupIrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeFixupConfidenceTextureId, screenProbeFixupConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMipIrradianceTextureId, screenProbeMipIrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMipConfidenceTextureId, screenProbeMipConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip2IrradianceTextureId, screenProbeMip2IrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip2ConfidenceTextureId, screenProbeMip2ConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip3IrradianceTextureId, screenProbeMip3IrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip3ConfidenceTextureId, screenProbeMip3ConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHAmbientTextureId, screenProbeRadianceSHAmbientTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHDirectionalTextureId, screenProbeRadianceSHDirectionalTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeIrradianceOctTextureId, screenProbeIrradianceOctTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeRadianceOctTextureId, screenProbeRadianceOctTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeTraceRadianceTextureId, screenProbeTraceRadianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeTraceHitTextureId, screenProbeTraceHitTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeHitDistanceTextureId, screenProbeHitDistanceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeBentNormalTextureId, screenProbeBentNormalTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeWorldNormalTextureId, screenProbeWorldNormalTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeWorldPositionTextureId, screenProbeWorldPositionTarget.Identifier);
                UploadScreenProbeSettings(cmd, screenProbeSettings, screenProbeDescriptor);

                if (hasRadianceCacheTargets)
                {
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, radianceCacheIndirectionTarget.Identifier);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, radianceCacheFinalRadianceAtlasTarget.Identifier);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, radianceCacheFinalIrradianceAtlasTarget.Identifier);
                    cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, radianceCacheProbeOcclusionAtlasTarget.Identifier);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, radianceCacheProbeSkyAOAtlasTarget.Identifier);
                    cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, radianceCacheProbeWorldOffsetBuffer.Buffer);
                    UploadRadianceCacheClipMapSettings(cmd, camera, screenProbeSettings);
                }
                else
                {
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, Texture2D.blackTexture);
                    UploadRadianceCacheClipMapSettings(cmd, camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled);
                }

                return;
            }

            cmd.SetGlobalTexture(BurtGIScreenProbeFixupIrradianceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeFixupConfidenceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeMipIrradianceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeMipConfidenceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeMip2IrradianceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeMip2ConfidenceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeMip3IrradianceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeMip3ConfidenceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHAmbientTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHDirectionalTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeIrradianceOctTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeRadianceOctTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeTraceRadianceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeTraceHitTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeHitDistanceTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeBentNormalTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeWorldNormalTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIScreenProbeWorldPositionTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, Texture2D.blackTexture);
            UploadScreenProbeSettings(cmd, BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled, fallbackDescriptor);
            UploadRadianceCacheClipMapSettings(cmd, camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled);
        }

        private static void BindIndirectChannelHistory(
            CommandBuffer cmd,
            BurtScreenSpaceGlobalIlluminationIndirectChannelHistoryTextures history,
            bool historyValid,
            BurtScreenSpaceGlobalIlluminationSettings settings)
        {
            cmd.SetGlobalTexture(BurtGIBackfaceDiffuseIndirectHistoryTextureId, history.BackfaceDiffuse != null ? (Texture)history.BackfaceDiffuse : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRoughSpecularIndirectHistoryTextureId, history.RoughSpecular != null ? (Texture)history.RoughSpecular : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIHistoryDepthNormalTextureId, history.DepthNormal != null ? (Texture)history.DepthNormal : Texture2D.blackTexture);
            cmd.SetGlobalMatrix(BurtGIPreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
            cmd.SetGlobalMatrix(InverseViewProjectionMatrixId, history.CurrentInverseViewProjectionMatrix);
            cmd.SetGlobalVector(BurtGITemporalParamsId, new Vector4(settings.TemporalFeedback, historyValid ? 1f : 0f, settings.TemporalDepthRejection, settings.TemporalNormalRejection));
            cmd.SetGlobalVector(BurtGITemporalParams1Id, new Vector4(settings.TemporalClamp, settings.TemporalVarianceClamp, settings.TemporalHitRejection, settings.SpatialDenoiseStrength));
        }

        private static void CopyIndirectChannelHistory(
            CommandBuffer cmd,
            Material material,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            RenderTextureDescriptor descriptor,
            BurtRenderTargetHandle backfaceDiffuseTarget,
            BurtRenderTargetHandle roughSpecularTarget,
            BurtScreenSpaceGlobalIlluminationIndirectChannelHistoryTextures history)
        {
            if (cmd == null ||
                material == null ||
                camera == null ||
                history.BackfaceDiffuse == null ||
                history.RoughSpecular == null ||
                history.DepthNormal == null)
            {
                return;
            }

            cmd.CopyTexture(backfaceDiffuseTarget.Identifier, new RenderTargetIdentifier(history.BackfaceDiffuse));
            cmd.CopyTexture(roughSpecularTarget.Identifier, new RenderTargetIdentifier(history.RoughSpecular));
            var depthNormalDescriptor = BurtScreenSpaceGlobalIlluminationHistoryUtility.CreateDepthNormalHistoryDescriptor(camera, settings);
            cmd.GetTemporaryRT(BurtGIIndirectHistoryDepthNormalTextureId, depthNormalDescriptor, FilterMode.Point);
            cmd.SetRenderTarget(new RenderTargetIdentifier(BurtGIIndirectHistoryDepthNormalTextureId));
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, descriptor.width, descriptor.height);
            cmd.DrawProcedural(Matrix4x4.identity, material, CopyDepthNormalPassIndex, MeshTopology.Triangles, 3, 1);
            cmd.CopyTexture(new RenderTargetIdentifier(BurtGIIndirectHistoryDepthNormalTextureId), new RenderTargetIdentifier(history.DepthNormal));
            cmd.ReleaseTemporaryRT(BurtGIIndirectHistoryDepthNormalTextureId);
            BurtScreenSpaceGlobalIlluminationIndirectChannelHistoryUtility.MarkHistoryValid(camera);
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle cameraDepthTarget,
            out BurtRenderTargetHandle gbuffer0Target,
            out BurtRenderTargetHandle gbuffer1Target,
            out BurtRenderTargetHandle gbuffer2Target,
            out BurtRenderTargetHandle gbuffer3Target,
            out BurtRenderTargetHandle gbuffer4Target,
            out BurtRenderTargetHandle gbuffer5Target,
            out BurtRenderTargetHandle burtGITarget,
            out BurtRenderTargetHandle backfaceDiffuseTarget,
            out BurtRenderTargetHandle roughSpecularTarget)
        {
            cameraDepthTarget = context != null ? context.CameraDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.CameraDepthName);
            gbuffer0Target = context != null ? context.GBuffer0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer0Name);
            gbuffer1Target = context != null ? context.GBuffer1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer1Name);
            gbuffer2Target = context != null ? context.GBuffer2Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer2Name);
            gbuffer3Target = context != null ? context.GBuffer3Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer3Name);
            gbuffer4Target = context != null ? context.GBuffer4Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer4Name);
            gbuffer5Target = context != null ? context.GBuffer5Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer5Name);
            burtGITarget = context != null ? context.ScreenSpaceGlobalIlluminationTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationName);
            backfaceDiffuseTarget = context != null ? context.BurtGIBackfaceDiffuseIndirectTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectName);
            roughSpecularTarget = context != null ? context.BurtGIRoughSpecularIndirectTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectName);

            return cameraDepthTarget.IsValid &&
                gbuffer0Target.IsValid &&
                gbuffer1Target.IsValid &&
                gbuffer2Target.IsValid &&
                gbuffer3Target.IsValid &&
                gbuffer4Target.IsValid &&
                gbuffer5Target.IsValid &&
                burtGITarget.IsValid &&
                backfaceDiffuseTarget.IsValid &&
                roughSpecularTarget.IsValid;
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationBlurPass : BurtScreenSpaceGlobalIlluminationPass
    {
        private const int BlurPassIndex = 1;
        private const int TemporalPassIndex = 4;
        private const int CopyDepthNormalPassIndex = 5;
        private const int CopyTemporalFinalPassIndex = 6;
        private const int CopyTemporalDiagnosticsPassIndex = 7;
        private const int IrradianceFieldIntegratePassIndex = 18;
        private const string IrradianceFieldIntegrateComputeShaderResourcePath = "BurtGIRadianceCacheClipMapIrradianceIntegrate";
        private const string IrradianceFieldIntegrateKernelName = "IrradianceIntegrateCS";
        private const int IrradianceFieldIntegrateThreadGroupSize = 8;
        private const float IrradianceFieldProbeOcclusionViewBias = 20f;
        private const float IrradianceFieldProbeOcclusionNormalBias = 20f;
        private static readonly int BurtGISpatialFinalTextureId = Shader.PropertyToID("_BurtScreenSpaceGlobalIlluminationSpatialFinalTexture");
        private static readonly int BurtGISpatialFinalInputTextureId = Shader.PropertyToID("_BurtGISpatialFinalTexture");
        private static readonly int BurtGITemporalFinalTextureId = Shader.PropertyToID("_BurtScreenSpaceGlobalIlluminationTemporalFinalTexture");
        private static readonly int BurtGITemporalFinalInputTextureId = Shader.PropertyToID("_BurtGITemporalFinalTexture");
        private static readonly int BurtGIDepthNormalTextureId = Shader.PropertyToID("_BurtGIDepthNormalTexture");
        private static readonly int BurtGIHistoryTextureId = Shader.PropertyToID("_BurtGIHistoryTexture");
        private static readonly int BurtGIHistoryDepthNormalTextureId = Shader.PropertyToID("_BurtGIHistoryDepthNormalTexture");
        private static readonly int BurtGIPreviousHistoryTextureId = Shader.PropertyToID("_BurtGIPreviousHistoryTexture");
        private static readonly int BurtGIPreviousHistoryDepthNormalTextureId = Shader.PropertyToID("_BurtGIPreviousHistoryDepthNormalTexture");
        private static readonly int BurtGIPreviousViewProjectionMatrixId = Shader.PropertyToID("_BurtGIPreviousViewProjectionMatrix");
        private static readonly int BurtGIHistoryParamsId = Shader.PropertyToID("_BurtGIHistoryParams");
        private static readonly int BurtGITemporalParamsId = Shader.PropertyToID("_BurtGITemporalParams");
        private static readonly int BurtGITemporalParams1Id = Shader.PropertyToID("_BurtGITemporalParams1");
        private static readonly int BurtGIScreenProbeAdaptiveParamsId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveParams");
        private static readonly int BurtGIScreenProbeAdaptiveProbeHeaderTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeAdaptiveProbeHeaderTextureId;
        private static readonly int BurtGIScreenProbeAdaptiveProbeIndicesTextureId = BurtRenderGraphResourceRegistry.BurtGIScreenProbeAdaptiveProbeIndicesTextureId;
        private static readonly int BurtGIScreenProbeAdaptiveProbeNumBufferId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeNumBuffer");
        private static readonly int BurtGIScreenProbeAdaptiveProbeDataBufferId = Shader.PropertyToID("_BurtGIScreenProbeAdaptiveProbeDataBuffer");
        private static readonly int BurtGIIrradianceFieldParamsId = Shader.PropertyToID("_BurtGIIrradianceFieldParams");
        private static readonly int BurtGIRadianceCacheClipMapFrameIndexId = Shader.PropertyToID("_BurtGIRadianceCacheClipMapFrameIndex");
        private static readonly int XGIIrradianceIntegrateDiffuseIndirectTextureId = Shader.PropertyToID("_RW_XGIIrradianceIntegratePass_DiffuseIndirect");
        private static readonly int XGIIrradianceIntegrateBackfaceDiffuseIndirectTextureId = Shader.PropertyToID("_RW_XGIIrradianceIntegratePass_BackfaceDiffuseIndirect");
        private static readonly int XGIIrradianceIntegrateRoughSpecularIndirectTextureId = Shader.PropertyToID("_RW_XGIIrradianceIntegratePass_RoughSpecularIndirect");
        private static ComputeShader irradianceFieldIntegrateComputeShader;
        private static bool hasLoggedMissingIrradianceFieldIntegrateComputeShader;
        private static bool hasLoggedMissingIrradianceFieldIntegrateKernel;

        public override string Name => "Burt Screen Space Global Illumination Blur";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIllumination(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadScreenSpaceGlobalIlluminationRaw();
            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            builder.ReadGBuffer1();
            builder.ReadGBuffer2();
            builder.ReadGBuffer3();
            builder.ReadGBuffer4();
            builder.ReadGBuffer5();
            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(builder.Request, builder.Asset);
            var useIrradianceFieldGather = settings.FinalGather == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField;
            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset))
            {
                builder.ReadBurtGIScreenProbeFixupIrradiance();
                builder.ReadBurtGIScreenProbeFixupConfidence();
                builder.ReadBurtGIScreenProbeMipIrradiance();
                builder.ReadBurtGIScreenProbeMipConfidence();
                builder.ReadBurtGIScreenProbeMip2Irradiance();
                builder.ReadBurtGIScreenProbeMip2Confidence();
                builder.ReadBurtGIScreenProbeMip3Irradiance();
                builder.ReadBurtGIScreenProbeMip3Confidence();
                builder.ReadBurtGIScreenProbeRadianceSHAmbient();
                builder.ReadBurtGIScreenProbeRadianceSHDirectional();
                builder.ReadBurtGIScreenProbeIrradianceOct();
                builder.ReadBurtGIScreenProbeBentNormal();
                builder.ReadBurtGIScreenProbeWorldNormal();
                builder.ReadBurtGIScreenProbeWorldPosition();
                builder.ReadBurtGIScreenProbeTraceRadiance();
                builder.ReadBurtGIScreenProbeTraceHit();
                builder.ReadBurtGIScreenProbeHitDistance();
                builder.ReadBurtGIScreenProbeAdaptiveProbeHeader();
                builder.ReadBurtGIScreenProbeAdaptiveProbeIndices();
                builder.ReadBurtGIScreenProbeAdaptiveProbeNumBuffer();
                builder.ReadBurtGIScreenProbeAdaptiveProbeDataBuffer();
            }

            if ((BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(builder.Request, builder.Asset) || useIrradianceFieldGather) &&
                BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(builder.Request, builder.Asset))
            {
                builder.ReadBurtGIRadianceCacheClipMapIndirection();
                builder.ReadBurtGIRadianceCacheClipMapFinalRadianceAtlas();
                builder.ReadBurtGIRadianceCacheClipMapFinalIrradianceAtlas();
                builder.ReadBurtGIRadianceCacheClipMapProbeOcclusionAtlas();
                builder.ReadBurtGIRadianceCacheClipMapProbeSkyAOAtlas();
                builder.ReadBurtGIRadianceCacheClipMapProbeWorldOffsetBuffer();
            }

            builder.WriteScreenSpaceGlobalIllumination();
            if (useIrradianceFieldGather)
            {
                builder.WriteBurtGIBackfaceDiffuseIndirect();
                builder.WriteBurtGIRoughSpecularIndirect();
            }
            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTemporalDiagnostics(builder.Request, builder.Asset))
            {
                builder.WriteBurtGITemporalDiagnostics();
            }
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(
                context,
                out var rawTarget,
                out var cameraDepthTarget,
                out var gbuffer0Target,
                out var gbuffer1Target,
                out var gbuffer2Target,
                out var gbuffer3Target,
                out var gbuffer4Target,
                out var gbuffer5Target,
                out var target,
                out var temporalDiagnosticsTarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            if (!settings.Enabled)
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            var camera = context.Request != null ? context.Request.Camera : null;
            if (material == null || camera == null)
            {
                return;
            }

            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var outputTarget = target.Identifier;
            var spatialFinalIdentifier = new RenderTargetIdentifier(BurtGISpatialFinalTextureId);
            var temporalFinalIdentifier = new RenderTargetIdentifier(BurtGITemporalFinalTextureId);
            var depthNormalIdentifier = new RenderTargetIdentifier(BurtGIDepthNormalTextureId);
            var cmd = context.AcquireCommandBuffer(Name);
            cmd.SetGlobalTexture(BurtGIRawTextureId, rawTarget.Identifier);
            cmd.SetGlobalTexture(CameraDepthTextureId, cameraDepthTarget.Identifier);
            BindGBufferInputs(cmd, gbuffer0Target, gbuffer1Target, gbuffer2Target, gbuffer3Target, gbuffer4Target, gbuffer5Target);
            UploadCameraGlobals(cmd, context.Request, camera, descriptor);
            UploadSettings(cmd, settings);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var screenProbeFixupIrradianceTarget = context.BurtGIScreenProbeFixupIrradianceTarget;
            var screenProbeFixupConfidenceTarget = context.BurtGIScreenProbeFixupConfidenceTarget;
            var screenProbeMipIrradianceTarget = context.BurtGIScreenProbeMipIrradianceTarget;
            var screenProbeMipConfidenceTarget = context.BurtGIScreenProbeMipConfidenceTarget;
            var screenProbeMip2IrradianceTarget = context.BurtGIScreenProbeMip2IrradianceTarget;
            var screenProbeMip2ConfidenceTarget = context.BurtGIScreenProbeMip2ConfidenceTarget;
            var screenProbeMip3IrradianceTarget = context.BurtGIScreenProbeMip3IrradianceTarget;
            var screenProbeMip3ConfidenceTarget = context.BurtGIScreenProbeMip3ConfidenceTarget;
            var screenProbeRadianceSHAmbientTarget = context.BurtGIScreenProbeRadianceSHAmbientTarget;
            var screenProbeRadianceSHDirectionalTarget = context.BurtGIScreenProbeRadianceSHDirectionalTarget;
            var screenProbeIrradianceOctTarget = context.BurtGIScreenProbeIrradianceOctTarget;
            var screenProbeBentNormalTarget = context.BurtGIScreenProbeBentNormalTarget;
            var screenProbeWorldNormalTarget = context.BurtGIScreenProbeWorldNormalTarget;
            var screenProbeWorldPositionTarget = context.BurtGIScreenProbeWorldPositionTarget;
            var screenProbeTraceRadianceTarget = context.BurtGIScreenProbeTraceRadianceTarget;
            var screenProbeTraceHitTarget = context.BurtGIScreenProbeTraceHitTarget;
            var screenProbeHitDistanceTarget = context.BurtGIScreenProbeHitDistanceTarget;
            var screenProbeAdaptiveProbeHeaderTarget = context.BurtGIScreenProbeAdaptiveProbeHeaderTarget;
            var screenProbeAdaptiveProbeIndicesTarget = context.BurtGIScreenProbeAdaptiveProbeIndicesTarget;
            var screenProbeAdaptiveProbeNumBuffer = context.BurtGIScreenProbeAdaptiveProbeNumBuffer;
            var screenProbeAdaptiveProbeDataBuffer = context.BurtGIScreenProbeAdaptiveProbeDataBuffer;
            var radianceCacheIndirectionTarget = context.BurtGIRadianceCacheClipMapIndirectionTarget;
            var radianceCacheFinalRadianceAtlasTarget = context.BurtGIRadianceCacheClipMapFinalRadianceAtlasTarget;
            var radianceCacheFinalIrradianceAtlasTarget = context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget;
            var radianceCacheProbeOcclusionAtlasTarget = context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget;
            var radianceCacheProbeSkyAOAtlasTarget = context.BurtGIRadianceCacheClipMapProbeSkyAOAtlasTarget;
            var radianceCacheProbeWorldOffsetBuffer = context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer;
            var hasScreenProbeTargets = screenProbeSettings.Enabled &&
                screenProbeFixupIrradianceTarget.IsValid &&
                screenProbeFixupConfidenceTarget.IsValid &&
                screenProbeMipIrradianceTarget.IsValid &&
                screenProbeMipConfidenceTarget.IsValid &&
                screenProbeMip2IrradianceTarget.IsValid &&
                screenProbeMip2ConfidenceTarget.IsValid &&
                screenProbeMip3IrradianceTarget.IsValid &&
                screenProbeMip3ConfidenceTarget.IsValid &&
                screenProbeRadianceSHAmbientTarget.IsValid &&
                screenProbeRadianceSHDirectionalTarget.IsValid &&
                screenProbeIrradianceOctTarget.IsValid &&
                screenProbeBentNormalTarget.IsValid &&
                screenProbeWorldNormalTarget.IsValid &&
                screenProbeWorldPositionTarget.IsValid &&
                screenProbeTraceRadianceTarget.IsValid &&
                screenProbeTraceHitTarget.IsValid &&
                screenProbeHitDistanceTarget.IsValid &&
                screenProbeAdaptiveProbeHeaderTarget.IsValid &&
                screenProbeAdaptiveProbeIndicesTarget.IsValid &&
                screenProbeAdaptiveProbeNumBuffer.HasBuffer &&
                screenProbeAdaptiveProbeDataBuffer.HasBuffer;
            var useIrradianceFieldGather = settings.FinalGather == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField;
            var hasRadianceCacheTargets =
                BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(context.Request, context.Asset) &&
                radianceCacheIndirectionTarget.IsValid &&
                radianceCacheFinalRadianceAtlasTarget.IsValid &&
                radianceCacheFinalIrradianceAtlasTarget.IsValid &&
                radianceCacheProbeOcclusionAtlasTarget.IsValid &&
                radianceCacheProbeSkyAOAtlasTarget.IsValid &&
                radianceCacheProbeWorldOffsetBuffer.HasBuffer;
            if (hasScreenProbeTargets)
            {
                var screenProbeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
                cmd.SetGlobalTexture(BurtGIScreenProbeFixupIrradianceTextureId, screenProbeFixupIrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeFixupConfidenceTextureId, screenProbeFixupConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMipIrradianceTextureId, screenProbeMipIrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMipConfidenceTextureId, screenProbeMipConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip2IrradianceTextureId, screenProbeMip2IrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip2ConfidenceTextureId, screenProbeMip2ConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip3IrradianceTextureId, screenProbeMip3IrradianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip3ConfidenceTextureId, screenProbeMip3ConfidenceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHAmbientTextureId, screenProbeRadianceSHAmbientTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHDirectionalTextureId, screenProbeRadianceSHDirectionalTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeIrradianceOctTextureId, screenProbeIrradianceOctTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeBentNormalTextureId, screenProbeBentNormalTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeWorldNormalTextureId, screenProbeWorldNormalTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeWorldPositionTextureId, screenProbeWorldPositionTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeTraceRadianceTextureId, screenProbeTraceRadianceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeTraceHitTextureId, screenProbeTraceHitTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeHitDistanceTextureId, screenProbeHitDistanceTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeAdaptiveProbeHeaderTextureId, screenProbeAdaptiveProbeHeaderTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIScreenProbeAdaptiveProbeIndicesTextureId, screenProbeAdaptiveProbeIndicesTarget.Identifier);
                cmd.SetGlobalBuffer(BurtGIScreenProbeAdaptiveProbeNumBufferId, screenProbeAdaptiveProbeNumBuffer.Buffer);
                cmd.SetGlobalBuffer(BurtGIScreenProbeAdaptiveProbeDataBufferId, screenProbeAdaptiveProbeDataBuffer.Buffer);
                cmd.SetGlobalVector(BurtGIScreenProbeAdaptiveParamsId, new Vector4(
                    screenProbeDescriptor.width,
                    screenProbeDescriptor.height,
                    BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeAdaptiveProbeIndexTileCapacity(screenProbeSettings),
                    Mathf.Max(1, screenProbeAdaptiveProbeDataBuffer.Buffer.count)));
                UploadScreenProbeSettings(cmd, screenProbeSettings, screenProbeDescriptor);
                if (hasRadianceCacheTargets)
                {
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, radianceCacheIndirectionTarget.Identifier);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, radianceCacheFinalRadianceAtlasTarget.Identifier);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, radianceCacheFinalIrradianceAtlasTarget.Identifier);
                    cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, radianceCacheProbeOcclusionAtlasTarget.Identifier);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, radianceCacheProbeSkyAOAtlasTarget.Identifier);
                    cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, radianceCacheProbeWorldOffsetBuffer.Buffer);
                    UploadRadianceCacheClipMapSettings(cmd, camera, screenProbeSettings);
                }
                else
                {
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, Texture2D.blackTexture);
                    cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, Texture2D.blackTexture);
                    UploadRadianceCacheClipMapSettings(cmd, camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled);
                }
            }
            else
            {
                cmd.SetGlobalTexture(BurtGIScreenProbeFixupIrradianceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeFixupConfidenceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeMipIrradianceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeMipConfidenceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip2IrradianceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip2ConfidenceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip3IrradianceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeMip3ConfidenceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHAmbientTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeRadianceSHDirectionalTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeIrradianceOctTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeBentNormalTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeWorldNormalTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeWorldPositionTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeTraceRadianceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeTraceHitTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIScreenProbeHitDistanceTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, Texture2D.blackTexture);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, Texture2D.blackTexture);
                UploadScreenProbeSettings(cmd, BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled, descriptor);
                UploadRadianceCacheClipMapSettings(cmd, camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled);
            }

            if (useIrradianceFieldGather && hasRadianceCacheTargets)
            {
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, radianceCacheIndirectionTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, radianceCacheFinalRadianceAtlasTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, radianceCacheFinalIrradianceAtlasTarget.Identifier);
                cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, radianceCacheProbeOcclusionAtlasTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, radianceCacheProbeSkyAOAtlasTarget.Identifier);
                cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, radianceCacheProbeWorldOffsetBuffer.Buffer);
                UploadRadianceCacheClipMapSettings(cmd, camera, screenProbeSettings, settings.SceneVoxelClipMapResolution);
            }

            if (useIrradianceFieldGather)
            {
                BurtScreenSpaceGlobalIlluminationHistoryUtility.InvalidateHistory(camera, "IrradianceFieldGather");
                cmd.SetGlobalVector(
                    BurtGIIrradianceFieldParamsId,
                    new Vector4(
                        settings.IrradianceFieldStrength,
                        IrradianceFieldProbeOcclusionNormalBias,
                        IrradianceFieldProbeOcclusionViewBias,
                        0f));
                cmd.SetGlobalVector(BurtGIIndirectChannelParamsId, new Vector4(
                    settings.EnableBackfaceDiffuse ? 1f : 0f,
                    settings.EnableRoughSpecular ? 1f : 0f,
                    1f,
                    settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular));
                if (!TryDispatchIrradianceFieldIntegrateCompute(
                        cmd,
                        context,
                        camera,
                        settings,
                        screenProbeSettings,
                        descriptor,
                        cameraDepthTarget,
                        gbuffer0Target,
                        gbuffer1Target,
                        gbuffer2Target,
                        gbuffer3Target,
                        target,
                        context.BurtGIBackfaceDiffuseIndirectTarget,
                        context.BurtGIRoughSpecularIndirectTarget,
                        radianceCacheIndirectionTarget,
                        radianceCacheFinalIrradianceAtlasTarget,
                        radianceCacheProbeOcclusionAtlasTarget,
                        radianceCacheProbeWorldOffsetBuffer,
                        hasRadianceCacheTargets))
                {
                    var irradianceFieldTargets = new[]
                    {
                        target.Identifier,
                        context.BurtGIBackfaceDiffuseIndirectTarget.Identifier,
                        context.BurtGIRoughSpecularIndirectTarget.Identifier
                    };
                    cmd.SetRenderTarget(irradianceFieldTargets, cameraDepthTarget.Identifier);
                    BurtRenderTargetDescriptorUtility.SetViewport(cmd, descriptor.width, descriptor.height);
                    cmd.DrawProcedural(Matrix4x4.identity, material, IrradianceFieldIntegratePassIndex, MeshTopology.Triangles, 3, 1);
                }
            }
            else
            {
                var shouldUseTemporal = settings.TemporalAccumulation;
                if (shouldUseTemporal)
                {
                    cmd.GetTemporaryRT(BurtGISpatialFinalTextureId, descriptor, FilterMode.Bilinear);
                    cmd.GetTemporaryRT(BurtGITemporalFinalTextureId, BurtScreenSpaceGlobalIlluminationHistoryUtility.CreateColorHistoryDescriptor(camera, settings), FilterMode.Bilinear);
                    outputTarget = spatialFinalIdentifier;
                }
                else
                {
                    BurtScreenSpaceGlobalIlluminationHistoryUtility.InvalidateHistory(camera, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationTemporalDisabledReason(context.Request, settings));
                }

                cmd.SetRenderTarget(outputTarget);
                BurtRenderTargetDescriptorUtility.SetViewport(cmd, descriptor.width, descriptor.height);
                cmd.DrawProcedural(Matrix4x4.identity, material, BlurPassIndex, MeshTopology.Triangles, 3, 1);

                if (shouldUseTemporal)
                {
                    ResolveTemporal(cmd, material, context.Request, context.Asset, settings, camera, descriptor, spatialFinalIdentifier, temporalFinalIdentifier, target.Identifier, temporalDiagnosticsTarget, depthNormalIdentifier);
                    cmd.ReleaseTemporaryRT(BurtGITemporalFinalTextureId);
                    cmd.ReleaseTemporaryRT(BurtGISpatialFinalTextureId);
                }
            }

            cmd.SetGlobalTexture(BurtGITextureId, target.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryDispatchIrradianceFieldIntegrateCompute(
            CommandBuffer cmd,
            BurtRenderGraphContext context,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            RenderTextureDescriptor descriptor,
            BurtRenderTargetHandle cameraDepthTarget,
            BurtRenderTargetHandle gbuffer0Target,
            BurtRenderTargetHandle gbuffer1Target,
            BurtRenderTargetHandle gbuffer2Target,
            BurtRenderTargetHandle gbuffer3Target,
            BurtRenderTargetHandle diffuseTarget,
            BurtRenderTargetHandle backfaceDiffuseTarget,
            BurtRenderTargetHandle roughSpecularTarget,
            BurtRenderTargetHandle radianceCacheIndirectionTarget,
            BurtRenderTargetHandle radianceCacheFinalIrradianceAtlasTarget,
            BurtRenderTargetHandle radianceCacheProbeOcclusionAtlasTarget,
            BurtRenderBufferHandle radianceCacheProbeWorldOffsetBuffer,
            bool hasRadianceCacheTargets)
        {
            if (cmd == null || context == null || camera == null || !hasRadianceCacheTargets ||
                !cameraDepthTarget.IsValid ||
                !gbuffer0Target.IsValid ||
                !gbuffer1Target.IsValid ||
                !gbuffer2Target.IsValid ||
                !gbuffer3Target.IsValid ||
                !diffuseTarget.IsValid ||
                !backfaceDiffuseTarget.IsValid ||
                !roughSpecularTarget.IsValid ||
                !radianceCacheIndirectionTarget.IsValid ||
                !radianceCacheFinalIrradianceAtlasTarget.IsValid ||
                !radianceCacheProbeOcclusionAtlasTarget.IsValid ||
                !radianceCacheProbeWorldOffsetBuffer.HasBuffer)
            {
                return false;
            }

            var shader = GetIrradianceFieldIntegrateComputeShader();
            if (shader == null || !TryFindIrradianceFieldIntegrateKernel(shader, out var kernel))
            {
                return false;
            }

            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            var temporalAA = context.Request != null ? context.Request.TemporalAA : null;
            var useTemporalAA = temporalAA != null && temporalAA.Enabled;
            var viewMatrix = useTemporalAA ? temporalAA.ViewMatrix : camera.worldToCameraMatrix;
            var viewProjectionMatrix = useTemporalAA
                ? temporalAA.CurrentViewProjectionMatrix
                : GL.GetGPUProjectionMatrix(camera.projectionMatrix, true) * viewMatrix;
            var inverseViewProjectionMatrix = useTemporalAA ? temporalAA.InverseCurrentViewProjectionMatrix : viewProjectionMatrix.inverse;
            var cameraPosition = camera.transform.position;
            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, screenProbeSettings);
            var indirectionDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationRadianceCacheClipMapIndirectionDescriptor(camera, screenProbeSettings);
            var indirectionWidth = Mathf.Max(1, indirectionDescriptor.width);
            var indirectionHeight = Mathf.Max(1, indirectionDescriptor.height);

            cmd.SetComputeTextureParam(shader, kernel, CameraDepthTextureId, cameraDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer0Id, gbuffer0Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer1Id, gbuffer1Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer2Id, gbuffer2Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, GBuffer3Id, gbuffer3Target.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapIndirectionTextureId, radianceCacheIndirectionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, radianceCacheFinalIrradianceAtlasTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, radianceCacheProbeOcclusionAtlasTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, XGIIrradianceIntegrateDiffuseIndirectTextureId, diffuseTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, XGIIrradianceIntegrateBackfaceDiffuseIndirectTextureId, backfaceDiffuseTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, XGIIrradianceIntegrateRoughSpecularIndirectTextureId, roughSpecularTarget.Identifier);
            cmd.SetComputeBufferParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, radianceCacheProbeWorldOffsetBuffer.Buffer);
            cmd.SetComputeVectorParam(shader, BurtGISourceTexelSizeId, new Vector4(1f / width, 1f / height, width, height));
            cmd.SetComputeVectorParam(shader, BurtGIIrradianceFieldParamsId, new Vector4(
                settings.IrradianceFieldStrength,
                IrradianceFieldProbeOcclusionNormalBias,
                IrradianceFieldProbeOcclusionViewBias,
                0f));
            cmd.SetComputeVectorParam(shader, BurtGIIndirectChannelParamsId, new Vector4(
                settings.EnableBackfaceDiffuse ? 1f : 0f,
                settings.EnableRoughSpecular ? 1f : 0f,
                1f,
                settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular));
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapParamsId, clipMapState.Params);
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapWorldParamsId, clipMapState.WorldParams);
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapIndirectionSizeId, new Vector4(indirectionWidth, indirectionHeight, 1f / indirectionWidth, 1f / indirectionHeight));
            cmd.SetComputeVectorArrayParam(shader, BurtGIRadianceCacheClipMapWorldPositionToProbeCoordId, clipMapState.WorldPositionToProbeCoord);
            cmd.SetComputeVectorParam(shader, BurtGIRadianceCacheClipMapApplyParamsGlobalId, new Vector4(1f, screenProbeSettings.RadianceCacheReprojectionRadiusScale, screenProbeSettings.RadianceCacheVisualizeClipmapIndex, screenProbeSettings.RadianceCacheVisualizeRadiusScale));
            cmd.SetComputeVectorParam(shader, CameraWorldPositionId, new Vector4(cameraPosition.x, cameraPosition.y, cameraPosition.z, 1f));
            cmd.SetComputeMatrixParam(shader, InverseViewProjectionMatrixId, inverseViewProjectionMatrix);
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalIrradianceProbeResolutionId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapFinalIrradianceProbeResolution(screenProbeSettings));
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalOcclusionProbeResolutionId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapFinalOcclusionProbeResolution(screenProbeSettings));
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFinalRadianceAtlasMaxMipGlobalId, BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheClipMapFinalRadianceAtlasMaxMip);
            cmd.SetComputeIntParam(shader, BurtGIRadianceCacheClipMapFrameIndexId, Time.frameCount);
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (width + IrradianceFieldIntegrateThreadGroupSize - 1) / IrradianceFieldIntegrateThreadGroupSize),
                Mathf.Max(1, (height + IrradianceFieldIntegrateThreadGroupSize - 1) / IrradianceFieldIntegrateThreadGroupSize),
                1);
            return true;
        }

        private static ComputeShader GetIrradianceFieldIntegrateComputeShader()
        {
            if (irradianceFieldIntegrateComputeShader != null)
            {
                return irradianceFieldIntegrateComputeShader;
            }

            irradianceFieldIntegrateComputeShader = Resources.Load<ComputeShader>(IrradianceFieldIntegrateComputeShaderResourcePath);
            if (irradianceFieldIntegrateComputeShader == null && !hasLoggedMissingIrradianceFieldIntegrateComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + IrradianceFieldIntegrateComputeShaderResourcePath);
                hasLoggedMissingIrradianceFieldIntegrateComputeShader = true;
            }

            return irradianceFieldIntegrateComputeShader;
        }

        private static bool TryFindIrradianceFieldIntegrateKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(IrradianceFieldIntegrateKernelName))
            {
                if (!hasLoggedMissingIrradianceFieldIntegrateKernel)
                {
                    Debug.LogWarning("BurtRP irradiance field integrate compute shader missing kernel: " + IrradianceFieldIntegrateKernelName);
                    hasLoggedMissingIrradianceFieldIntegrateKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(IrradianceFieldIntegrateKernelName);
            return kernel >= 0;
        }

        private static void ResolveTemporal(
            CommandBuffer cmd,
            Material material,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            Camera camera,
            RenderTextureDescriptor descriptor,
            RenderTargetIdentifier spatialFinal,
            RenderTargetIdentifier temporalFinalTarget,
            RenderTargetIdentifier finalTarget,
            BurtRenderTargetHandle temporalDiagnosticsTarget,
            RenderTargetIdentifier depthNormalTarget)
        {
            var history = BurtScreenSpaceGlobalIlluminationHistoryUtility.EnsureHistoryTextures(request, asset, settings, out var historyValid);
            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            cmd.SetGlobalTexture(BurtGISpatialFinalInputTextureId, spatialFinal);
            cmd.SetGlobalTexture(BurtGIHistoryTextureId, history.Color != null ? (Texture)history.Color : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIHistoryDepthNormalTextureId, history.DepthNormal != null ? (Texture)history.DepthNormal : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIPreviousHistoryTextureId, history.Color != null ? (Texture)history.Color : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIPreviousHistoryDepthNormalTextureId, history.DepthNormal != null ? (Texture)history.DepthNormal : Texture2D.blackTexture);
            cmd.SetGlobalMatrix(BurtGIPreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
            cmd.SetGlobalMatrix(InverseViewProjectionMatrixId, history.CurrentInverseViewProjectionMatrix);
            cmd.SetGlobalVector(BurtGISourceTexelSizeId, new Vector4(1f / width, 1f / height, width, height));
            cmd.SetGlobalVector(BurtGIHistoryParamsId, new Vector4(history.HistoryExposureCorrection, 0f, 0f, 0f));
            cmd.SetGlobalVector(BurtGITemporalParamsId, new Vector4(settings.TemporalFeedback, historyValid ? 1f : 0f, settings.TemporalDepthRejection, settings.TemporalNormalRejection));
            cmd.SetGlobalVector(BurtGITemporalParams1Id, new Vector4(settings.TemporalClamp, settings.TemporalVarianceClamp, settings.TemporalHitRejection, settings.SpatialDenoiseStrength));

            cmd.SetRenderTarget(temporalFinalTarget);
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, width, height);
            cmd.DrawProcedural(Matrix4x4.identity, material, TemporalPassIndex, MeshTopology.Triangles, 3, 1);

            cmd.SetGlobalTexture(BurtGITemporalFinalInputTextureId, temporalFinalTarget);
            cmd.SetRenderTarget(finalTarget);
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, width, height);
            cmd.DrawProcedural(Matrix4x4.identity, material, CopyTemporalFinalPassIndex, MeshTopology.Triangles, 3, 1);

            if (temporalDiagnosticsTarget.IsValid)
            {
                cmd.SetGlobalTexture(BurtGITemporalFinalInputTextureId, temporalFinalTarget);
                cmd.SetRenderTarget(temporalDiagnosticsTarget.Identifier);
                BurtRenderTargetDescriptorUtility.SetViewport(cmd, width, height);
                cmd.DrawProcedural(Matrix4x4.identity, material, CopyTemporalDiagnosticsPassIndex, MeshTopology.Triangles, 3, 1);
                cmd.SetGlobalTexture(BurtGITemporalDiagnosticsTextureId, temporalDiagnosticsTarget.Identifier);
            }

            if (history.Color == null || history.DepthNormal == null)
            {
                return;
            }

            BurtScreenSpaceGlobalIlluminationHistoryUtility.CopyHistoryToDebugSnapshot(cmd, camera);
            cmd.CopyTexture(temporalFinalTarget, new RenderTargetIdentifier(history.Color));
            var depthNormalDescriptor = BurtScreenSpaceGlobalIlluminationHistoryUtility.CreateDepthNormalHistoryDescriptor(camera, settings);
            cmd.GetTemporaryRT(BurtGIDepthNormalTextureId, depthNormalDescriptor, FilterMode.Point);
            cmd.SetRenderTarget(depthNormalTarget);
            BurtRenderTargetDescriptorUtility.SetViewport(cmd, width, height);
            cmd.DrawProcedural(Matrix4x4.identity, material, CopyDepthNormalPassIndex, MeshTopology.Triangles, 3, 1);
            cmd.CopyTexture(depthNormalTarget, new RenderTargetIdentifier(history.DepthNormal));
            cmd.ReleaseTemporaryRT(BurtGIDepthNormalTextureId);
            BurtScreenSpaceGlobalIlluminationHistoryUtility.MarkHistoryValid(camera);
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle rawTarget,
            out BurtRenderTargetHandle cameraDepthTarget,
            out BurtRenderTargetHandle gbuffer0Target,
            out BurtRenderTargetHandle gbuffer1Target,
            out BurtRenderTargetHandle gbuffer2Target,
            out BurtRenderTargetHandle gbuffer3Target,
            out BurtRenderTargetHandle gbuffer4Target,
            out BurtRenderTargetHandle gbuffer5Target,
            out BurtRenderTargetHandle target,
            out BurtRenderTargetHandle temporalDiagnosticsTarget)
        {
            rawTarget = context != null ? context.ScreenSpaceGlobalIlluminationRawTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationRawName);
            cameraDepthTarget = context != null ? context.CameraDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.CameraDepthName);
            gbuffer0Target = context != null ? context.GBuffer0Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer0Name);
            gbuffer1Target = context != null ? context.GBuffer1Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer1Name);
            gbuffer2Target = context != null ? context.GBuffer2Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer2Name);
            gbuffer3Target = context != null ? context.GBuffer3Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer3Name);
            gbuffer4Target = context != null ? context.GBuffer4Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer4Name);
            gbuffer5Target = context != null ? context.GBuffer5Target : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.GBuffer5Name);
            target = context != null ? context.ScreenSpaceGlobalIlluminationTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationName);
            temporalDiagnosticsTarget = context != null ? context.BurtGITemporalDiagnosticsTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.BurtGITemporalDiagnosticsName);

            return rawTarget.IsValid &&
                cameraDepthTarget.IsValid &&
                gbuffer0Target.IsValid &&
                gbuffer1Target.IsValid &&
                gbuffer2Target.IsValid &&
                gbuffer3Target.IsValid &&
                gbuffer4Target.IsValid &&
                gbuffer5Target.IsValid &&
                target.IsValid;
        }
    }

    internal static class BurtGIPreviousSceneColorHistoryUtility
    {
        private sealed class CameraState
        {
            public Camera Camera;
            public RenderTexture Texture;
            public int Width;
            public int Height;
            public float StoredPreExposure = 1f;
            public int LastStoredFrame = -1;
            public bool Valid;
        }

        private static readonly System.Collections.Generic.Dictionary<int, CameraState> CameraStates =
            new System.Collections.Generic.Dictionary<int, CameraState>();
        private static readonly System.Collections.Generic.List<int> RemovalKeys =
            new System.Collections.Generic.List<int>();

#if UNITY_EDITOR
        [UnityEditor.InitializeOnLoadMethod]
        private static void RegisterEditorCleanup()
        {
            UnityEditor.AssemblyReloadEvents.beforeAssemblyReload -= ReleaseAll;
            UnityEditor.AssemblyReloadEvents.beforeAssemblyReload += ReleaseAll;
        }
#endif

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetRuntimeState()
        {
            ReleaseAll();
        }

        public static RenderTexture GetPreviousSceneColor(
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            out bool valid,
            out float exposureCorrection)
        {
            valid = false;
            exposureCorrection = 1f;
            var camera = request != null ? request.Camera : null;
            if (camera == null)
            {
                return null;
            }

            var state = GetOrCreateState(camera);
            EnsureTexture(state, camera);
            var frameGap = state.LastStoredFrame >= 0 ? Time.frameCount - state.LastStoredFrame : int.MaxValue;
            valid = state.Valid && state.Texture != null && frameGap >= 0 && frameGap <= 2;
            if (valid)
            {
                var currentPreExposure = PreExposureUtility.SanitizeExposure(
                    PreExposureUtility.ResolveForFrame(request, asset).PreExposure,
                    1f);
                exposureCorrection = currentPreExposure /
                    PreExposureUtility.SanitizeExposure(state.StoredPreExposure, 1f);
            }

            return state.Texture;
        }

        public static void Store(
            CommandBuffer cmd,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            RenderTargetIdentifier source)
        {
            var camera = request != null ? request.Camera : null;
            if (cmd == null || camera == null)
            {
                return;
            }

            var state = GetOrCreateState(camera);
            EnsureTexture(state, camera);
            if (state.Texture == null)
            {
                return;
            }

            cmd.Blit(source, new RenderTargetIdentifier(state.Texture));
            state.StoredPreExposure = PreExposureUtility.SanitizeExposure(
                PreExposureUtility.ResolveForFrame(request, asset).PreExposure,
                1f);
            state.LastStoredFrame = Time.frameCount;
            state.Valid = true;
        }

        private static CameraState GetOrCreateState(Camera camera)
        {
            var key = camera.GetInstanceID();
            if (!CameraStates.TryGetValue(key, out var state))
            {
                state = new CameraState();
                CameraStates.Add(key, state);
            }

            state.Camera = camera;
            PruneDisposedCameras();
            return state;
        }

        private static void EnsureTexture(CameraState state, Camera camera)
        {
            var descriptor = BurtRenderTargetDescriptorUtility.CreateCameraColorDescriptor(camera);
            descriptor.colorFormat = RenderTextureFormat.ARGBHalf;
            descriptor.depthBufferBits = 0;
            descriptor.msaaSamples = 1;
            descriptor.useMipMap = false;
            descriptor.autoGenerateMips = false;
            descriptor.enableRandomWrite = false;
            descriptor.sRGB = false;
            var width = Mathf.Max(1, descriptor.width);
            var height = Mathf.Max(1, descriptor.height);
            if (state.Texture != null &&
                state.Texture.IsCreated() &&
                state.Width == width &&
                state.Height == height)
            {
                return;
            }

            ReleaseTexture(state);
            state.Texture = new RenderTexture(descriptor)
            {
                name = "BurtGI Previous Scene Color " + camera.GetInstanceID(),
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
                hideFlags = HideFlags.HideAndDontSave
            };
            state.Texture.Create();
            state.Width = width;
            state.Height = height;
            state.Valid = false;
            state.LastStoredFrame = -1;
        }

        private static void PruneDisposedCameras()
        {
            RemovalKeys.Clear();
            foreach (var pair in CameraStates)
            {
                if (pair.Value.Camera == null)
                {
                    ReleaseTexture(pair.Value);
                    RemovalKeys.Add(pair.Key);
                }
            }

            for (var index = 0; index < RemovalKeys.Count; index++)
            {
                CameraStates.Remove(RemovalKeys[index]);
            }
        }

        private static void ReleaseTexture(CameraState state)
        {
            if (state.Texture != null)
            {
                state.Texture.Release();
                Object.DestroyImmediate(state.Texture);
                state.Texture = null;
            }

            state.Valid = false;
        }

        private static void ReleaseAll()
        {
            foreach (var pair in CameraStates)
            {
                ReleaseTexture(pair.Value);
            }

            CameraStates.Clear();
            RemovalKeys.Clear();
        }
    }

    internal sealed class BurtStoreGIPreviousSceneColorPass : BurtRenderPass
    {
        public override string Name => "Burt Store GI Previous Scene Color";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(
                builder.Request,
                builder.Asset))
            {
                return;
            }

            builder.ReadCameraColor();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(
                    context.Request,
                    context.Asset))
            {
                return;
            }

            var cameraColorTarget = context.CameraColorTarget;
            if (!cameraColorTarget.IsValid)
            {
                return;
            }

            var cmd = context.AcquireCommandBuffer(Name);
            BurtGIPreviousSceneColorHistoryUtility.Store(
                cmd,
                context.Request,
                context.Asset,
                cameraColorTarget.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }
    }

    internal sealed class BurtScreenSpaceGlobalIlluminationCompositePass : BurtScreenSpaceGlobalIlluminationPass
    {
        public override string Name => "Burt Screen Space Global Illumination Composite";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIllumination(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadCameraColor();
            builder.ReadCameraDepth();
            builder.ReadScreenSpaceGlobalIllumination();
            builder.WriteCameraColor();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (!TryGetTargets(context, out var cameraColorTarget, out var cameraDepthTarget, out var burtGITarget))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            if (!settings.Enabled)
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            var camera = context.Request != null ? context.Request.Camera : null;
            if (material == null || camera == null)
            {
                return;
            }

            var burtGIDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var cameraColorDescriptor = BurtRenderTargetDescriptorUtility.CreateCameraColorDescriptor(camera);
            var cmd = context.AcquireCommandBuffer(Name);
            cmd.GetTemporaryRT(BurtGICameraColorCopyTextureId, cameraColorDescriptor, FilterMode.Bilinear);
            cmd.Blit(cameraColorTarget.Identifier, new RenderTargetIdentifier(BurtGICameraColorCopyTextureId));
            cmd.SetRenderTarget(cameraColorTarget.Identifier);
            BurtRenderTargetDescriptorUtility.SetCameraTargetViewport(cmd, camera);
            cmd.SetGlobalTexture(BurtGICameraColorCopyTextureId, new RenderTargetIdentifier(BurtGICameraColorCopyTextureId));
            cmd.SetGlobalTexture(CameraDepthTextureId, cameraDepthTarget.Identifier);
            BurtDeferredStencilTextureUtility.BindGlobal(cmd, cameraDepthTarget, camera);
            cmd.SetGlobalTexture(BurtGITextureId, burtGITarget.Identifier);
            UploadCameraGlobals(cmd, context.Request, camera, burtGIDescriptor);
            UploadSettings(cmd, settings);
            cmd.DrawProcedural(Matrix4x4.identity, material, 2, MeshTopology.Triangles, 3, 1);
            cmd.ReleaseTemporaryRT(BurtGICameraColorCopyTextureId);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static bool TryGetTargets(
            BurtRenderGraphContext context,
            out BurtRenderTargetHandle cameraColorTarget,
            out BurtRenderTargetHandle cameraDepthTarget,
            out BurtRenderTargetHandle burtGITarget)
        {
            cameraColorTarget = context != null ? context.CameraColorTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.CameraColorName);
            cameraDepthTarget = context != null ? context.CameraDepthTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.CameraDepthName);
            burtGITarget = context != null ? context.ScreenSpaceGlobalIlluminationTarget : BurtRenderTargetHandle.Invalid(BurtRenderGraphResourceRegistry.ScreenSpaceGlobalIlluminationName);
            return cameraColorTarget.IsValid && cameraDepthTarget.IsValid && burtGITarget.IsValid;
        }
    }

