        private static readonly uint[] SceneVoxelDebugProbePlaceProbeIndexClearData = new uint[SceneVoxelDebugProbeAllocatorOffset];
        private static readonly Vector4[] SceneVoxelDebugProbeClipmapCenterExtents = new Vector4[BurtGISceneVoxelClipmapStateUtility.ClipmapCount];

        public override string Name => "Burt Debug Screen Space Global Illumination";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationDebugView(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadScreenSpaceGlobalIlluminationRaw();
            builder.ReadScreenSpaceGlobalIllumination();
            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationIndirectChannelDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadBurtGIBackfaceDiffuseIndirect();
                builder.ReadBurtGIRoughSpecularIndirect();
            }
            builder.ReadCameraDepth();
            builder.ReadGBuffer0();
            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationHashGridDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridValueBufferName);
                builder.ReadBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridTileBufferName);
                builder.ReadBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridDebugCellBufferName);
                builder.ReadBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridDebugDrawArgsBufferName);
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationScreenProbeDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadBurtGIScreenProbeScreenDepth();
                builder.ReadBurtGIScreenProbeWorldNormal();
                builder.ReadBurtGIScreenProbeWorldPosition();
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadBurtGISceneVoxelOccupancyMip();
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationScreenProbeTraceVisualizeDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadBurtGIScreenProbeTraceRadiance();
                builder.ReadBurtGIScreenProbeTraceHit();
                builder.ReadBurtGIScreenProbeAdaptiveProbeNumBuffer();
                builder.ReadBurtGIScreenProbeAdaptiveProbeDataBuffer();
            }

            if ((BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheSkyAODebugMode(BurtShadingDebugSettings.Mode) ||
                    BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheProbeDebugMode(BurtShadingDebugSettings.Mode)) &&
                BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(builder.Request, builder.Asset))
            {
                builder.ReadBurtGIRadianceCacheClipMapIndirection();
                builder.ReadBurtGIRadianceCacheClipMapFinalRadianceAtlas();
                builder.ReadBurtGIRadianceCacheClipMapFinalIrradianceAtlas();
                builder.ReadBurtGIRadianceCacheClipMapProbeOcclusionAtlas();
                builder.ReadBurtGIRadianceCacheClipMapProbeSkyAOAtlas();
                builder.ReadBurtGIRadianceCacheClipMapProbeWorldOffsetBuffer();
                builder.ReadBurtGIRadianceCacheClipMapProbeLastUsedFrameBuffer();
                builder.ReadBurtGIRadianceCacheClipMapProbeLastTracedFrameBuffer();
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheStatsDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadBurtGIRadianceCacheStats();
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationTemporalDiagnosticDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadBurtGITemporalDiagnostics();
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationOverlayDebugMode(BurtShadingDebugSettings.Mode))
            {
                builder.ReadCameraColor();
            }

            builder.WriteCameraColor();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationDebugView(context.Request, context.Asset))
            {
                return;
            }

            var cameraColorTarget = context.CameraColorTarget;
            var cameraDepthTarget = context.CameraDepthTarget;
            var gbuffer0Target = context.GBuffer0Target;
            var rawTarget = context.ScreenSpaceGlobalIlluminationRawTarget;
            var burtGITarget = context.ScreenSpaceGlobalIlluminationTarget;
            var backfaceDiffuseTarget = context.BurtGIBackfaceDiffuseIndirectTarget;
            var roughSpecularTarget = context.BurtGIRoughSpecularIndirectTarget;
            var temporalDiagnosticsTarget = context.BurtGITemporalDiagnosticsTarget;
            var radianceCacheStatsTarget = context.BurtGIRadianceCacheStatsTarget;
            var hashGridValueBuffer = context.GetBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridValueBufferName);
            var hashGridTileBuffer = context.GetBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridTileBufferName);
            var hashGridDebugCellBuffer = context.GetBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridDebugCellBufferName);
            var hashGridDebugDrawArgsBuffer = context.GetBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridDebugDrawArgsBufferName);
            var screenProbeScreenDepthTarget = context.BurtGIScreenProbeScreenDepthTarget;
            var screenProbeWorldNormalTarget = context.BurtGIScreenProbeWorldNormalTarget;
            var screenProbeWorldPositionTarget = context.BurtGIScreenProbeWorldPositionTarget;
            var screenProbeTraceRadianceTarget = context.BurtGIScreenProbeTraceRadianceTarget;
            var screenProbeTraceHitTarget = context.BurtGIScreenProbeTraceHitTarget;
            var screenProbeAdaptiveProbeNumBuffer = context.BurtGIScreenProbeAdaptiveProbeNumBuffer;
            var screenProbeAdaptiveProbeDataBuffer = context.BurtGIScreenProbeAdaptiveProbeDataBuffer;
            var sceneVoxelOccupancyMipTarget = context.BurtGISceneVoxelOccupancyMipTarget;
            var radianceCacheIndirectionTarget = context.BurtGIRadianceCacheClipMapIndirectionTarget;
            var radianceCacheFinalRadianceAtlasTarget = context.BurtGIRadianceCacheClipMapFinalRadianceAtlasTarget;
            var radianceCacheFinalIrradianceAtlasTarget = context.BurtGIRadianceCacheClipMapFinalIrradianceAtlasTarget;
            var radianceCacheProbeOcclusionAtlasTarget = context.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTarget;
            var radianceCacheProbeSkyAOAtlasTarget = context.BurtGIRadianceCacheClipMapProbeSkyAOAtlasTarget;
            var radianceCacheProbeWorldOffsetBuffer = context.BurtGIRadianceCacheClipMapProbeWorldOffsetBuffer;
            var radianceCacheProbeLastUsedFrameBuffer = context.BurtGIRadianceCacheClipMapProbeLastUsedFrameBuffer;
            var radianceCacheProbeLastTracedFrameBuffer = context.BurtGIRadianceCacheClipMapProbeLastTracedFrameBuffer;
            if (!cameraColorTarget.IsValid || !cameraDepthTarget.IsValid || !gbuffer0Target.IsValid || !rawTarget.IsValid || !burtGITarget.IsValid)
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationIndirectChannelDebugMode(BurtShadingDebugSettings.Mode) &&
                (!backfaceDiffuseTarget.IsValid || !roughSpecularTarget.IsValid))
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationTemporalDiagnosticDebugMode(BurtShadingDebugSettings.Mode) && !temporalDiagnosticsTarget.IsValid)
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheStatsDebugMode(BurtShadingDebugSettings.Mode) && !radianceCacheStatsTarget.IsValid)
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationHashGridDebugMode(BurtShadingDebugSettings.Mode) &&
                (!hashGridValueBuffer.HasBuffer || !hashGridTileBuffer.HasBuffer || !hashGridDebugCellBuffer.HasBuffer || !hashGridDebugDrawArgsBuffer.HasBuffer))
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationScreenProbeDebugMode(BurtShadingDebugSettings.Mode) &&
                (!screenProbeScreenDepthTarget.IsValid ||
                    !screenProbeWorldNormalTarget.IsValid ||
                    !screenProbeWorldPositionTarget.IsValid))
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationScreenProbeTraceVisualizeDebugMode(BurtShadingDebugSettings.Mode) &&
                (!screenProbeTraceRadianceTarget.IsValid ||
                    !screenProbeTraceHitTarget.IsValid ||
                    !screenProbeAdaptiveProbeNumBuffer.HasBuffer ||
                    !screenProbeAdaptiveProbeDataBuffer.HasBuffer))
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(BurtShadingDebugSettings.Mode) &&
                !sceneVoxelOccupancyMipTarget.IsValid)
            {
                return;
            }

            if (BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheProbeDebugMode(BurtShadingDebugSettings.Mode) &&
                (!radianceCacheIndirectionTarget.IsValid ||
                    !radianceCacheFinalRadianceAtlasTarget.IsValid ||
                    !radianceCacheFinalIrradianceAtlasTarget.IsValid ||
                    !radianceCacheProbeOcclusionAtlasTarget.IsValid ||
                    !radianceCacheProbeSkyAOAtlasTarget.IsValid ||
                    !radianceCacheProbeWorldOffsetBuffer.HasBuffer ||
                    !radianceCacheProbeLastUsedFrameBuffer.HasBuffer ||
                    !radianceCacheProbeLastTracedFrameBuffer.HasBuffer))
            {
                return;
            }

            var material = GetScreenSpaceGlobalIlluminationMaterial();
            var camera = context.Request != null ? context.Request.Camera : null;
            if (material == null || camera == null)
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(context.Request, context.Asset);
            if (!settings.Enabled)
            {
                return;
            }

            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(context.Request, context.Asset);
            var descriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera, settings);
            var cmd = context.AcquireCommandBuffer(Name);
            var isOverlay = BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationOverlayDebugMode(BurtShadingDebugSettings.Mode);
            if (isOverlay)
            {
                var cameraColorDescriptor = BurtRenderTargetDescriptorUtility.CreateCameraColorDescriptor(camera);
                cmd.GetTemporaryRT(BurtGIDebugCameraColorCopyTextureId, cameraColorDescriptor, FilterMode.Bilinear);
                cmd.Blit(cameraColorTarget.Identifier, new RenderTargetIdentifier(BurtGIDebugCameraColorCopyTextureId));
                cmd.SetGlobalTexture(BurtGIDebugCameraColorTextureId, new RenderTargetIdentifier(BurtGIDebugCameraColorCopyTextureId));
            }

            cmd.SetRenderTarget(cameraColorTarget.Identifier);
            BurtRenderTargetDescriptorUtility.SetCameraTargetViewport(cmd, camera);
            cmd.SetGlobalTexture(CameraDepthTextureId, cameraDepthTarget.Identifier);
            BurtDeferredStencilTextureUtility.BindGlobal(cmd, cameraDepthTarget, camera);
            cmd.SetGlobalTexture(GBuffer0Id, gbuffer0Target.Identifier);
            cmd.SetGlobalTexture(BurtGIRawTextureId, rawTarget.Identifier);
            cmd.SetGlobalTexture(BurtGITextureId, burtGITarget.Identifier);
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIBackfaceDiffuseIndirectTextureId,
                backfaceDiffuseTarget.IsValid ? backfaceDiffuseTarget.Identifier : Texture2D.blackTexture);
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIRoughSpecularIndirectTextureId,
                roughSpecularTarget.IsValid ? roughSpecularTarget.Identifier : Texture2D.blackTexture);
            var isHashGridDebug = BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationHashGridDebugMode(BurtShadingDebugSettings.Mode);
            if (hashGridValueBuffer.HasBuffer)
            {
                cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridValueBufferId, hashGridValueBuffer.Buffer);
            }

            if (hashGridTileBuffer.HasBuffer)
            {
                cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridTileBufferId, hashGridTileBuffer.Buffer);
            }

            if (hashGridDebugCellBuffer.HasBuffer)
            {
                cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheHashGridDebugCellBufferId, hashGridDebugCellBuffer.Buffer);
            }

            if (temporalDiagnosticsTarget.IsValid)
            {
                cmd.SetGlobalTexture(BurtGITemporalDiagnosticsTextureId, temporalDiagnosticsTarget.Identifier);
            }
            else
            {
                cmd.SetGlobalTexture(BurtGITemporalDiagnosticsTextureId, Texture2D.blackTexture);
            }

            if (radianceCacheStatsTarget.IsValid)
            {
                cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheStatsTextureId, radianceCacheStatsTarget.Identifier);
            }
            else
            {
                cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheStatsTextureId, Texture2D.blackTexture);
            }

            BindRadianceCacheDebugInputs(
                cmd,
                context.Request,
                context.Asset,
                camera,
                radianceCacheIndirectionTarget,
                radianceCacheFinalRadianceAtlasTarget,
                radianceCacheFinalIrradianceAtlasTarget,
                radianceCacheProbeOcclusionAtlasTarget,
                radianceCacheProbeSkyAOAtlasTarget,
                radianceCacheProbeWorldOffsetBuffer,
                radianceCacheProbeLastUsedFrameBuffer,
                radianceCacheProbeLastTracedFrameBuffer);
            BindScreenProbeDebugInputs(
                cmd,
                context.Request,
                context.Asset,
                camera,
                screenProbeScreenDepthTarget,
                screenProbeWorldNormalTarget,
                screenProbeWorldPositionTarget,
                screenProbeTraceRadianceTarget,
                screenProbeTraceHitTarget);
            UploadScreenProbeTraceDebugGlobals(
                cmd,
                camera,
                screenProbeSettings,
                screenProbeTraceRadianceTarget,
                screenProbeTraceHitTarget);
            BindSceneVoxelDebugInputs(
                cmd,
                context.Request,
                context.Asset,
                camera,
                sceneVoxelOccupancyMipTarget);
            UploadTemporalDebugGlobals(cmd, context.Request, settings);
            if (TryDrawSdfDebugView(cmd, camera, settings, cameraColorTarget))
            {
                if (isOverlay)
                {
                    cmd.ReleaseTemporaryRT(BurtGIDebugCameraColorCopyTextureId);
                }

                context.ExecuteLegacyCommandBuffer(cmd);
                context.ReleaseCommandBuffer(cmd);
                return;
            }

            if (TryDrawSceneVoxelTraceDebugView(
                    cmd,
                    context.Request,
                    context.Asset,
                    camera,
                    settings,
                    screenProbeSettings,
                    sceneVoxelOccupancyMipTarget,
                    cameraColorTarget))
            {
                DrawSceneVoxelDebugProbeGeometry(
                    cmd,
                    context.Request,
                    context.Asset,
                    camera,
                    settings,
                    screenProbeSettings,
                    sceneVoxelOccupancyMipTarget);
                if (isOverlay)
                {
                    cmd.ReleaseTemporaryRT(BurtGIDebugCameraColorCopyTextureId);
                }

                context.ExecuteLegacyCommandBuffer(cmd);
                context.ReleaseCommandBuffer(cmd);
                return;
            }

            cmd.SetGlobalFloat(BurtGIDebugModeId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationShaderDebugMode());
            cmd.SetGlobalVector(BurtGIIndirectChannelParamsId, new Vector4(
                settings.EnableBackfaceDiffuse ? 1f : 0f,
                settings.EnableRoughSpecular ? 1f : 0f,
                1f,
                settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular));
            UploadCameraGlobals(cmd, context.Request, camera, descriptor);
            UploadSettings(cmd, settings);
            cmd.DrawProcedural(Matrix4x4.identity, material, DebugPassIndex, MeshTopology.Triangles, 3, 1);
            DrawScreenProbeTraceVisualizeGeometry(
                cmd,
                material,
                context.Request,
                context.Asset,
                camera,
                screenProbeScreenDepthTarget,
                screenProbeWorldNormalTarget,
                screenProbeWorldPositionTarget,
                screenProbeTraceRadianceTarget,
                screenProbeTraceHitTarget,
                screenProbeAdaptiveProbeNumBuffer,
                screenProbeAdaptiveProbeDataBuffer);
            DrawRadianceCacheVisualizeGeometry(
                cmd,
                material,
                context.Request,
                context.Asset,
                camera,
                radianceCacheIndirectionTarget,
                radianceCacheFinalRadianceAtlasTarget,
                radianceCacheFinalIrradianceAtlasTarget,
                radianceCacheProbeOcclusionAtlasTarget,
                radianceCacheProbeSkyAOAtlasTarget,
                radianceCacheProbeWorldOffsetBuffer,
                radianceCacheProbeLastUsedFrameBuffer,
                radianceCacheProbeLastTracedFrameBuffer);
            if (isHashGridDebug)
            {
                UploadHashGridDebugGeometryGlobals(cmd, screenProbeSettings);
                cmd.DrawProceduralIndirect(
                    Matrix4x4.identity,
                    material,
                    HashGridDebugGeometryPassIndex,
                    MeshTopology.Triangles,
                    hashGridDebugDrawArgsBuffer.Buffer,
                    0);
            }

            DrawSceneVoxelDebugProbeGeometry(
                cmd,
                context.Request,
                context.Asset,
                camera,
                settings,
                screenProbeSettings,
                sceneVoxelOccupancyMipTarget);

            if (isOverlay)
            {
                cmd.ReleaseTemporaryRT(BurtGIDebugCameraColorCopyTextureId);
            }

            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static ComputeShader GetXGISdfDebugComputeShader()
        {
            if (xgiSdfDebugComputeShader != null)
            {
                return xgiSdfDebugComputeShader;
            }

            xgiSdfDebugComputeShader = Resources.Load<ComputeShader>(XGISdfDebugComputeShaderResourcePath);
            if (xgiSdfDebugComputeShader == null && !hasLoggedMissingXGISdfDebugComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + XGISdfDebugComputeShaderResourcePath);
                hasLoggedMissingXGISdfDebugComputeShader = true;
            }

            return xgiSdfDebugComputeShader;
        }

        private static void BindRadianceCacheDebugInputs(
            CommandBuffer cmd,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            Camera camera,
            BurtRenderTargetHandle radianceCacheIndirectionTarget,
            BurtRenderTargetHandle radianceCacheFinalRadianceAtlasTarget,
            BurtRenderTargetHandle radianceCacheFinalIrradianceAtlasTarget,
            BurtRenderTargetHandle radianceCacheProbeOcclusionAtlasTarget,
            BurtRenderTargetHandle radianceCacheProbeSkyAOAtlasTarget,
            BurtRenderBufferHandle radianceCacheProbeWorldOffsetBuffer,
            BurtRenderBufferHandle radianceCacheProbeLastUsedFrameBuffer,
            BurtRenderBufferHandle radianceCacheProbeLastTracedFrameBuffer)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheSkyAODebugMode(BurtShadingDebugSettings.Mode) &&
                !BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheProbeDebugMode(BurtShadingDebugSettings.Mode))
            {
                return;
            }

            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            if (BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(request, asset) &&
                screenProbeSettings.Enabled &&
                radianceCacheIndirectionTarget.IsValid &&
                radianceCacheFinalRadianceAtlasTarget.IsValid &&
                radianceCacheFinalIrradianceAtlasTarget.IsValid &&
                radianceCacheProbeOcclusionAtlasTarget.IsValid &&
                radianceCacheProbeSkyAOAtlasTarget.IsValid &&
                radianceCacheProbeWorldOffsetBuffer.HasBuffer &&
                radianceCacheProbeLastUsedFrameBuffer.HasBuffer &&
                radianceCacheProbeLastTracedFrameBuffer.HasBuffer)
            {
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, radianceCacheIndirectionTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, radianceCacheFinalRadianceAtlasTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, radianceCacheFinalIrradianceAtlasTarget.Identifier);
                cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, radianceCacheProbeOcclusionAtlasTarget.Identifier);
                cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, radianceCacheProbeSkyAOAtlasTarget.Identifier);
                cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeWorldOffsetBufferId, radianceCacheProbeWorldOffsetBuffer.Buffer);
                cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeLastUsedFrameBufferId, radianceCacheProbeLastUsedFrameBuffer.Buffer);
                cmd.SetGlobalBuffer(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeLastTracedFrameBufferId, radianceCacheProbeLastTracedFrameBuffer.Buffer);
                UploadRadianceCacheClipMapSettings(cmd, camera, screenProbeSettings);
                cmd.SetGlobalVector(BurtGIRadianceCacheClipMapStageParamsId, new Vector4(0f, 0f, Time.frameCount, 0f));
                return;
            }

            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapIndirectionTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalRadianceAtlasTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapFinalIrradianceAtlasTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtRenderGraphResourceRegistry.BurtGIRadianceCacheClipMapProbeOcclusionAtlasTextureId, Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIRadianceCacheClipMapProbeSkyAOAtlasTextureId, Texture2D.blackTexture);
            UploadRadianceCacheClipMapSettings(cmd, camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled);
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapStageParamsId, Vector4.zero);
        }

        private static void BindScreenProbeDebugInputs(
            CommandBuffer cmd,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            Camera camera,
            BurtRenderTargetHandle screenProbeScreenDepthTarget,
            BurtRenderTargetHandle screenProbeWorldNormalTarget,
            BurtRenderTargetHandle screenProbeWorldPositionTarget,
            BurtRenderTargetHandle screenProbeTraceRadianceTarget,
            BurtRenderTargetHandle screenProbeTraceHitTarget)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationScreenProbeDebugMode(BurtShadingDebugSettings.Mode))
            {
                return;
            }

            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            var screenProbeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, screenProbeSettings);
            UploadScreenProbeSettings(cmd, screenProbeSettings, screenProbeDescriptor);

            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthTextureId,
                screenProbeScreenDepthTarget.IsValid ? screenProbeScreenDepthTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalTextureId,
                screenProbeWorldNormalTarget.IsValid ? screenProbeWorldNormalTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionTextureId,
                screenProbeWorldPositionTarget.IsValid ? screenProbeWorldPositionTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceRadianceTextureId,
                screenProbeTraceRadianceTarget.IsValid ? screenProbeTraceRadianceTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceHitTextureId,
                screenProbeTraceHitTarget.IsValid ? screenProbeTraceHitTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
        }

        private static void UploadScreenProbeTraceDebugGlobals(
            CommandBuffer cmd,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            BurtRenderTargetHandle screenProbeTraceRadianceTarget,
            BurtRenderTargetHandle screenProbeTraceHitTarget)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationScreenProbeTraceVisualizeDebugMode(BurtShadingDebugSettings.Mode))
            {
                return;
            }

            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeTraceDescriptor(camera, screenProbeSettings);
            var traceResolution = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(screenProbeSettings);
            cmd.SetGlobalVector(
                BurtGIScreenProbeTraceParamsGlobalId,
                new Vector4(
                    traceResolution,
                    Mathf.Max(1, traceDescriptor.width),
                    Mathf.Max(1, traceDescriptor.height),
                    Mathf.Max(screenProbeSettings.TraceDistance, 0.001f)));
            cmd.SetGlobalFloat(BurtGIDebugModeId, BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationShaderDebugMode());
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceRadianceTextureId,
                screenProbeTraceRadianceTarget.IsValid ? screenProbeTraceRadianceTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceHitTextureId,
                screenProbeTraceHitTarget.IsValid ? screenProbeTraceHitTarget.Identifier : new RenderTargetIdentifier(Texture2D.blackTexture));
        }

        private static void BindSceneVoxelDebugInputs(
            CommandBuffer cmd,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            Camera camera,
            BurtRenderTargetHandle sceneVoxelOccupancyMipTarget)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(BurtShadingDebugSettings.Mode))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationSettings(request, asset);
            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, screenProbeSettings);
            var sceneVoxelResolution = settings.SceneVoxelClipMapResolution;
            cmd.SetGlobalTexture(
                BurtRenderGraphResourceRegistry.BurtGISceneVoxelOccupancyMipReadTextureId,
                sceneVoxelOccupancyMipTarget.IsValid ? sceneVoxelOccupancyMipTarget.Identifier : new RenderTargetIdentifier(BurtGITranslucencyVolumeFallbackUtility.BlackVolumeTexture));
            cmd.SetGlobalVector(
                BurtGISceneVoxelCenterExtentId,
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(camera, screenProbeSettings, clipMapState, sceneVoxelResolution));
            cmd.SetGlobalVector(
                BurtGISceneVoxelDebugParamsId,
                new Vector4(
                    BurtScreenSpaceGlobalIlluminationPassUtility.NormalizeSceneVoxelRadianceResolution(sceneVoxelResolution),
                    settings.SceneVoxelClipMapCount,
                    settings.SceneVoxelDebugShowMipmapID,
                    sceneVoxelOccupancyMipTarget.IsValid ? 1f : 0f));
            cmd.SetGlobalInt(BurtGISceneVoxelDebugLayerId, settings.SceneVoxelDebugLayer);
            cmd.SetGlobalVector(
                BurtGISceneVoxelDebugProbeParamsId,
                new Vector4(settings.SceneVoxelDebugDrawProbe ? 1f : 0f, settings.SceneVoxelDebugProbeSizeWS, 0f, 0f));
        }

        private static bool TryDrawSceneVoxelTraceDebugView(
            CommandBuffer cmd,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            BurtRenderTargetHandle sceneVoxelOccupancyMipTarget,
            BurtRenderTargetHandle cameraColorTarget)
        {
            if (cmd == null ||
                camera == null ||
                !settings.SceneVoxelDebugByTrace ||
                !cameraColorTarget.IsValid ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(BurtShadingDebugSettings.Mode))
            {
                return false;
            }

            var shader = GetSceneVoxelDebugComputeShader();
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(SceneVoxelDebugTraceKernelName))
            {
                if (!hasLoggedMissingSceneVoxelTraceKernel)
                {
                    Debug.LogWarning("BurtRP compute shader " + SceneVoxelDebugComputeShaderResourcePath + " is missing kernel " + SceneVoxelDebugTraceKernelName + ".");
                    hasLoggedMissingSceneVoxelTraceKernel = true;
                }

                return false;
            }

            var kernel = shader.FindKernel(SceneVoxelDebugTraceKernelName);
            var descriptor = BurtRenderTargetDescriptorUtility.CreateCameraColorDescriptor(camera);
            descriptor.depthBufferBits = 0;
            descriptor.msaaSamples = 1;
            descriptor.graphicsFormat = GraphicsFormat.R16G16B16A16_SFloat;
            descriptor.enableRandomWrite = true;
            cmd.GetTemporaryRT(BurtGISceneVoxelTraceDebugTextureId, descriptor, FilterMode.Point);
            var traceTarget = new RenderTargetIdentifier(BurtGISceneVoxelTraceDebugTextureId);
            cmd.SetComputeTextureParam(shader, kernel, RWDebugOccupyPassRenderTargetId, traceTarget);
            cmd.SetComputeTextureParam(
                shader,
                kernel,
                BurtRenderGraphResourceRegistry.BurtGISceneVoxelOccupancyMipReadTextureId,
                sceneVoxelOccupancyMipTarget.IsValid ? sceneVoxelOccupancyMipTarget.Identifier : new RenderTargetIdentifier(BurtGITranslucencyVolumeFallbackUtility.BlackVolumeTexture));

            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, screenProbeSettings);
            var centerExtent = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(camera, screenProbeSettings, clipMapState, settings.SceneVoxelClipMapResolution);
            var cameraPosition = camera.transform.position;
            UploadCameraGlobals(cmd, request, camera, descriptor);
            cmd.SetComputeVectorParam(shader, BurtGISceneVoxelCenterExtentId, centerExtent);
            cmd.SetComputeVectorParam(shader, CameraWorldPositionId, new Vector4(cameraPosition.x, cameraPosition.y, cameraPosition.z, 1f));
            cmd.SetComputeVectorParam(
                shader,
                BurtGISceneVoxelDebugProbeParamsId,
                new Vector4(settings.SceneVoxelDebugDrawProbe ? 1f : 0f, settings.SceneVoxelDebugProbeSizeWS, 0f, 0f));
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (descriptor.width + SceneVoxelDebugTraceThreadGroupSize - 1) / SceneVoxelDebugTraceThreadGroupSize),
                Mathf.Max(1, (descriptor.height + SceneVoxelDebugTraceThreadGroupSize - 1) / SceneVoxelDebugTraceThreadGroupSize),
                1);
            cmd.Blit(traceTarget, cameraColorTarget.Identifier);
            cmd.ReleaseTemporaryRT(BurtGISceneVoxelTraceDebugTextureId);
            return true;
        }

        private static ComputeShader GetSceneVoxelDebugComputeShader()
        {
            if (sceneVoxelDebugComputeShader != null)
            {
                return sceneVoxelDebugComputeShader;
            }

            sceneVoxelDebugComputeShader = Resources.Load<ComputeShader>(SceneVoxelDebugComputeShaderResourcePath);
            if (sceneVoxelDebugComputeShader == null && !hasLoggedMissingSceneVoxelDebugComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + SceneVoxelDebugComputeShaderResourcePath);
                hasLoggedMissingSceneVoxelDebugComputeShader = true;
            }

            return sceneVoxelDebugComputeShader;
        }

        private static void DrawSceneVoxelDebugProbeGeometry(
            CommandBuffer cmd,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings,
            BurtRenderTargetHandle sceneVoxelOccupancyMipTarget)
        {
            if (cmd == null ||
                camera == null ||
                !settings.SceneVoxelDebugDrawProbe ||
                !sceneVoxelOccupancyMipTarget.IsValid ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(BurtShadingDebugSettings.Mode))
            {
                return;
            }

            var material = GetSceneVoxelDebugProbeMaterial();
            if (material == null)
            {
                return;
            }

            var probeNodeSize = Mathf.Max(1, settings.SceneVoxelClipMapResolution >> 2);
            var activeClipmapCount = 1;
            if (!PrepareSceneVoxelDebugProbeArgs(
                    cmd,
                    sceneVoxelOccupancyMipTarget,
                    probeNodeSize,
                    activeClipmapCount,
                    out var instanceCount))
            {
                return;
            }

            var descriptor = BurtRenderTargetDescriptorUtility.CreateCameraColorDescriptor(camera);
            UploadCameraGlobals(cmd, request, camera, descriptor);
            UploadSettings(cmd, settings);
            BindSceneVoxelDebugInputs(cmd, request, asset, camera, sceneVoxelOccupancyMipTarget);
            ResolveSceneVoxelDebugProbeClipmapCenterExtents(camera, settings, screenProbeSettings);
            cmd.SetGlobalVectorArray(BurtGISceneVoxelDebugProbeClipmapCenterExtentId, SceneVoxelDebugProbeClipmapCenterExtents);
            cmd.SetGlobalVector(
                BurtGISceneVoxelDebugProbeDrawParamsId,
                new Vector4(probeNodeSize, activeClipmapCount, instanceCount, sceneVoxelOccupancyMipTarget.IsValid ? 1f : 0f));

            material.SetBuffer(DebugProbeArgsBufferParamsId, sceneVoxelDebugProbeArgsParamsBuffer);
            material.SetBuffer(DebugProbePlaceProbeIndexId, sceneVoxelDebugProbePlaceProbeIndexBuffer);
            material.SetFloat(DebugProbeSizeWSId, Mathf.Max(settings.SceneVoxelDebugProbeSizeWS, 0.01f));
            cmd.DrawProceduralIndirect(
                Matrix4x4.identity,
                material,
                0,
                MeshTopology.Triangles,
                sceneVoxelDebugProbeArgsBuffer,
                0);
        }

        private static bool PrepareSceneVoxelDebugProbeArgs(
            CommandBuffer cmd,
            BurtRenderTargetHandle sceneVoxelOccupancyMipTarget,
            int probeNodeSize,
            int activeClipmapCount,
            out int instanceCount)
        {
            instanceCount = SceneVoxelDebugProbeMaxInstances;
            if (cmd == null || probeNodeSize <= 0 || activeClipmapCount <= 0 || !sceneVoxelOccupancyMipTarget.IsValid)
            {
                return false;
            }

            var shader = GetSceneVoxelDebugComputeShader();
            if (shader == null ||
                !TryFindSceneVoxelDebugProbeCompactKernel(shader, out var compactKernel) ||
                !TryFindSceneVoxelDebugProbeGenArgsKernel(shader, out var genArgsKernel))
            {
                return false;
            }

            EnsureSceneVoxelDebugProbeBuffers();
            if (sceneVoxelDebugProbeArgsBuffer == null ||
                sceneVoxelDebugProbeArgsParamsBuffer == null ||
                sceneVoxelDebugProbePlaceProbeIndexBuffer == null)
            {
                return false;
            }

            sceneVoxelDebugProbePlaceProbeIndexBuffer.SetData(SceneVoxelDebugProbePlaceProbeIndexClearData, 0, 0, SceneVoxelDebugProbePlaceProbeIndexClearData.Length);
            cmd.SetComputeTextureParam(shader, compactKernel, BurtRenderGraphResourceRegistry.BurtGISceneVoxelOccupancyMipReadTextureId, sceneVoxelOccupancyMipTarget.Identifier);
            cmd.SetComputeBufferParam(shader, compactKernel, RWDebugProbePlaceProbeIndexId, sceneVoxelDebugProbePlaceProbeIndexBuffer);
            cmd.SetComputeVectorParam(
                shader,
                DebugProbeCompactParamsId,
                new Vector4(probeNodeSize, SceneVoxelDebugProbeMaxInstances, SceneVoxelDebugProbeAllocatorOffset, 0.0001f));
            cmd.DispatchCompute(
                shader,
                compactKernel,
                Mathf.Max(1, (probeNodeSize + SceneVoxelDebugProbeCompactThreadGroupSize - 1) / SceneVoxelDebugProbeCompactThreadGroupSize),
                Mathf.Max(1, (probeNodeSize + SceneVoxelDebugProbeCompactThreadGroupSize - 1) / SceneVoxelDebugProbeCompactThreadGroupSize),
                Mathf.Max(1, (probeNodeSize + SceneVoxelDebugProbeCompactThreadGroupSize - 1) / SceneVoxelDebugProbeCompactThreadGroupSize));

            cmd.SetComputeBufferParam(shader, genArgsKernel, RWDebugProbeArgsBufferId, sceneVoxelDebugProbeArgsBuffer);
            cmd.SetComputeVectorParam(shader, DebugProbeArgsDataId, new Vector4(SceneVoxelDebugProbeVertexCount, 0f, 0f, 0f));
            cmd.SetComputeBufferParam(shader, genArgsKernel, RWDebugProbeArgsBufferParamsId, sceneVoxelDebugProbeArgsParamsBuffer);
            cmd.SetComputeBufferParam(shader, genArgsKernel, DebugProbePlaceProbeIndexId, sceneVoxelDebugProbePlaceProbeIndexBuffer);
            cmd.SetComputeIntParam(shader, DebugProbeArgsClipmapCountId, activeClipmapCount);
            cmd.SetComputeIntParam(shader, DebugProbeArgsMaxCountId, SceneVoxelDebugProbeMaxInstances);
            cmd.DispatchCompute(shader, genArgsKernel, 1, 1, 1);
            return true;
        }

        private static void EnsureSceneVoxelDebugProbeBuffers()
        {
            if (sceneVoxelDebugProbeArgsBuffer == null || !sceneVoxelDebugProbeArgsBuffer.IsValid())
            {
                sceneVoxelDebugProbeArgsBuffer?.Release();
                sceneVoxelDebugProbeArgsBuffer = new GraphicsBuffer(
                    GraphicsBuffer.Target.IndirectArguments | GraphicsBuffer.Target.Structured,
                    SceneVoxelDebugProbeArgsCount,
                    sizeof(uint))
                {
                    name = "BurtGI Scene Voxel Debug Probe Args"
                };
            }

            if (sceneVoxelDebugProbeArgsParamsBuffer == null || !sceneVoxelDebugProbeArgsParamsBuffer.IsValid())
            {
                sceneVoxelDebugProbeArgsParamsBuffer?.Release();
                sceneVoxelDebugProbeArgsParamsBuffer = new GraphicsBuffer(
                    GraphicsBuffer.Target.Structured,
                    SceneVoxelDebugProbeParamsCount,
                    sizeof(uint))
                {
                    name = "BurtGI Scene Voxel Debug Probe Args Params"
                };
            }

            if (sceneVoxelDebugProbePlaceProbeIndexBuffer == null || !sceneVoxelDebugProbePlaceProbeIndexBuffer.IsValid())
            {
                sceneVoxelDebugProbePlaceProbeIndexBuffer?.Release();
                sceneVoxelDebugProbePlaceProbeIndexBuffer = new GraphicsBuffer(
                    GraphicsBuffer.Target.Structured,
                    SceneVoxelDebugProbeAllocatorOffset + SceneVoxelDebugProbeMaxInstances,
                    sizeof(uint))
                {
                    name = "BurtGI Scene Voxel Debug Probe Place Probe Index"
                };
            }
        }

        private static bool TryFindSceneVoxelDebugProbeCompactKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(SceneVoxelDebugProbeCompactKernelName))
            {
                if (!hasLoggedMissingSceneVoxelDebugProbeCompactKernel)
                {
                    Debug.LogWarning("BurtRP compute shader " + SceneVoxelDebugComputeShaderResourcePath + " is missing kernel " + SceneVoxelDebugProbeCompactKernelName + ".");
                    hasLoggedMissingSceneVoxelDebugProbeCompactKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(SceneVoxelDebugProbeCompactKernelName);
            return kernel >= 0;
        }

        private static bool TryFindSceneVoxelDebugProbeGenArgsKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(SceneVoxelDebugProbeGenArgsKernelName))
            {
                if (!hasLoggedMissingSceneVoxelDebugProbeGenArgsKernel)
                {
                    Debug.LogWarning("BurtRP compute shader " + SceneVoxelDebugComputeShaderResourcePath + " is missing kernel " + SceneVoxelDebugProbeGenArgsKernelName + ".");
                    hasLoggedMissingSceneVoxelDebugProbeGenArgsKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(SceneVoxelDebugProbeGenArgsKernelName);
            return kernel >= 0;
        }

        private static Material GetSceneVoxelDebugProbeMaterial()
        {
            if (sceneVoxelDebugProbeMaterial != null)
            {
                return sceneVoxelDebugProbeMaterial;
            }

            var shader = Shader.Find(SceneVoxelDebugProbeShaderName);
            if (shader == null)
            {
                if (!hasLoggedMissingSceneVoxelDebugProbeShader)
                {
                    Debug.LogWarning("BurtRP could not find shader: " + SceneVoxelDebugProbeShaderName);
                    hasLoggedMissingSceneVoxelDebugProbeShader = true;
                }

                return null;
            }

            sceneVoxelDebugProbeMaterial = new Material(shader)
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            return sceneVoxelDebugProbeMaterial;
        }

        private static void ResolveSceneVoxelDebugProbeClipmapCenterExtents(
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings screenProbeSettings)
        {
            var clipMapState = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapState(camera, screenProbeSettings);
            var baseCenterExtent = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveSceneVoxelCenterExtent(
                camera,
                screenProbeSettings,
                clipMapState,
                settings.SceneVoxelClipMapResolution);
            for (var level = 0; level < BurtGISceneVoxelClipmapStateUtility.ClipmapCount; ++level)
            {
                if (level == 0)
                {
                    SceneVoxelDebugProbeClipmapCenterExtents[level] = baseCenterExtent;
                    continue;
                }

                if (BurtGISceneVoxelClipmapStateUtility.TryGetBounds(camera, level, out var bounds))
                {
                    SceneVoxelDebugProbeClipmapCenterExtents[level] = new Vector4(bounds.center.x, bounds.center.y, bounds.center.z, bounds.extents.x);
                }
                else
                {
                    var extent = baseCenterExtent.w * Mathf.Pow(Mathf.Max(1f, settings.SceneVoxelClipMapDistributionBase), level);
                    SceneVoxelDebugProbeClipmapCenterExtents[level] = new Vector4(baseCenterExtent.x, baseCenterExtent.y, baseCenterExtent.z, extent);
                }
            }
        }

        private static bool TryDrawSdfDebugView(
            CommandBuffer cmd,
            Camera camera,
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtRenderTargetHandle cameraColorTarget)
        {
            if (cmd == null ||
                camera == null ||
                !cameraColorTarget.IsValid ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(BurtShadingDebugSettings.Mode))
            {
                return false;
            }

            var debugComponent = BurtXGIToolsDebugComponent.Current;
            if (debugComponent == null || !debugComponent.drawSdf)
            {
                return false;
            }

            var shader = GetXGISdfDebugComputeShader();
            if (shader == null)
            {
                return false;
            }

            if (!BurtGISceneVoxelClipmapStateUtility.TryGetBaseSdfContext(
                    camera,
                    settings.SceneVoxelClipMapResolution,
                    debugComponent.drawSdfDebugUseOccupy,
                    out var sdfContext,
                    out _) ||
                sdfContext == null ||
                !sdfContext.IsValid)
            {
                return false;
            }

            var descriptor = BurtRenderTargetDescriptorUtility.CreateCameraColorDescriptor(camera);
            descriptor.depthBufferBits = 0;
            descriptor.msaaSamples = 1;
            descriptor.graphicsFormat = GraphicsFormat.R16G16B16A16_SFloat;
            descriptor.enableRandomWrite = true;

            cmd.GetTemporaryRT(BurtXGISdfDebugTextureId, descriptor, FilterMode.Point);
            var renderTarget = new RenderTargetIdentifier(BurtXGISdfDebugTextureId);
            var dispatched = BurtXGISdfGenDispatchUtility.TryDispatchDebugSdf(
                cmd,
                shader,
                renderTarget,
                sdfContext,
                descriptor.width,
                descriptor.height,
                debugComponent.drawSdfDebugLayer,
                32f,
                0.5f);
            if (dispatched)
            {
                cmd.Blit(renderTarget, cameraColorTarget.Identifier);
            }

            cmd.ReleaseTemporaryRT(BurtXGISdfDebugTextureId);
            return dispatched;
        }

        private static void DrawScreenProbeTraceVisualizeGeometry(
            CommandBuffer cmd,
            Material material,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            Camera camera,
            BurtRenderTargetHandle screenProbeScreenDepthTarget,
            BurtRenderTargetHandle screenProbeWorldNormalTarget,
            BurtRenderTargetHandle screenProbeWorldPositionTarget,
            BurtRenderTargetHandle screenProbeTraceRadianceTarget,
            BurtRenderTargetHandle screenProbeTraceHitTarget,
            BurtRenderBufferHandle screenProbeAdaptiveProbeNumBuffer,
            BurtRenderBufferHandle screenProbeAdaptiveProbeDataBuffer)
        {
            if (cmd == null ||
                material == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationScreenProbeTraceVisualizeDebugMode(BurtShadingDebugSettings.Mode) ||
                !screenProbeScreenDepthTarget.IsValid ||
                !screenProbeWorldNormalTarget.IsValid ||
                !screenProbeWorldPositionTarget.IsValid ||
                !screenProbeTraceRadianceTarget.IsValid ||
                !screenProbeTraceHitTarget.IsValid ||
                !screenProbeAdaptiveProbeNumBuffer.HasBuffer ||
                !screenProbeAdaptiveProbeDataBuffer.HasBuffer)
            {
                return;
            }

            var shader = GetScreenProbeTraceVisualizeComputeShader();
            if (shader == null || !shader.HasKernel(ScreenProbeTraceVisualizeKernelName))
            {
                return;
            }

            var settings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            if (!settings.Enabled)
            {
                return;
            }

            var screenProbeDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            var traceDescriptor = BurtScreenSpaceGlobalIlluminationPassUtility.CreateScreenSpaceGlobalIlluminationScreenProbeTraceDescriptor(camera, settings);
            var traceResolution = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeTracingOctahedronResolution(settings);
            var traceCount = Mathf.Max(1, traceResolution * traceResolution);
            var bufferCount = traceCount * 3;
            EnsureScreenProbeTraceVisualizeBuffer(bufferCount);
            if (screenProbeTraceVisualizeBuffer == null || !screenProbeTraceVisualizeBuffer.IsValid())
            {
                return;
            }

            var kernel = shader.FindKernel(ScreenProbeTraceVisualizeKernelName);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeScreenDepthTextureId, screenProbeScreenDepthTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldNormalTextureId, screenProbeWorldNormalTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeWorldPositionTextureId, screenProbeWorldPositionTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceRadianceTextureId, screenProbeTraceRadianceTarget.Identifier);
            cmd.SetComputeTextureParam(shader, kernel, BurtRenderGraphResourceRegistry.BurtGIScreenProbeTraceHitTextureId, screenProbeTraceHitTarget.Identifier);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeNumBufferId, screenProbeAdaptiveProbeNumBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeAdaptiveProbeDataBufferId, screenProbeAdaptiveProbeDataBuffer.Buffer);
            cmd.SetComputeBufferParam(shader, kernel, BurtGIScreenProbeTraceVisualizeRWTracesDataId, screenProbeTraceVisualizeBuffer);
            cmd.SetComputeVectorParam(
                shader,
                BurtGIScreenProbeGridParamsId,
                new Vector4(
                    Mathf.Max(1, screenProbeDescriptor.width),
                    Mathf.Max(1, screenProbeDescriptor.height),
                    1f / Mathf.Max(1, screenProbeDescriptor.width),
                    1f / Mathf.Max(1, screenProbeDescriptor.height)));
            cmd.SetComputeVectorParam(
                shader,
                BurtGIScreenProbeAdaptiveParamsId,
                new Vector4(
                    Mathf.Max(1, screenProbeDescriptor.width),
                    Mathf.Max(1, screenProbeDescriptor.height),
                    BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenProbeAdaptiveProbeIndexTileCapacity(settings),
                    Mathf.Max(1, screenProbeAdaptiveProbeDataBuffer.Buffer.count)));
            cmd.SetComputeVectorParam(
                shader,
                BurtGIScreenProbeTraceParamsGlobalId,
                new Vector4(
                    traceResolution,
                    Mathf.Max(1, traceDescriptor.width),
                    Mathf.Max(1, traceDescriptor.height),
                    Mathf.Max(settings.TraceDistance, 0.001f)));
            cmd.SetComputeVectorParam(shader, BurtGIScreenProbeTraceVisualizeParamsId, ResolveScreenProbeTraceVisualizeParams(camera, settings));
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (traceResolution + ScreenProbeTraceVisualizeThreadGroupSize - 1) / ScreenProbeTraceVisualizeThreadGroupSize),
                Mathf.Max(1, (traceResolution + ScreenProbeTraceVisualizeThreadGroupSize - 1) / ScreenProbeTraceVisualizeThreadGroupSize),
                1);

            cmd.SetGlobalBuffer(BurtGIScreenProbeTraceVisualizeTracesDataId, screenProbeTraceVisualizeBuffer);
            cmd.DrawProcedural(
                Matrix4x4.identity,
                material,
                ScreenProbeTraceVisualizeGeometryPassIndex,
                MeshTopology.Lines,
                traceCount * 2,
                1);
        }

        private static ComputeShader GetScreenProbeTraceVisualizeComputeShader()
        {
            if (screenProbeTraceVisualizeComputeShader == null)
            {
                screenProbeTraceVisualizeComputeShader = Resources.Load<ComputeShader>(ScreenProbeTraceVisualizeComputeShaderResourcePath);
            }

            return screenProbeTraceVisualizeComputeShader;
        }

        private static void EnsureScreenProbeTraceVisualizeBuffer(int count)
        {
            count = Mathf.Max(3, count);
            if (screenProbeTraceVisualizeBuffer != null &&
                screenProbeTraceVisualizeBuffer.IsValid() &&
                screenProbeTraceVisualizeBufferCount == count)
            {
                return;
            }

            screenProbeTraceVisualizeBuffer?.Release();
            screenProbeTraceVisualizeBuffer = new GraphicsBuffer(GraphicsBuffer.Target.Structured, count, sizeof(float) * 4);
            screenProbeTraceVisualizeBufferCount = count;
        }

        private static Vector4 ResolveScreenProbeTraceVisualizeParams(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            if (camera == null)
            {
                return Vector4.zero;
            }

            var mousePosition = Input.mousePosition;
            var pixelRect = camera.pixelRect;
            if (!pixelRect.Contains(mousePosition))
            {
                return Vector4.zero;
            }

            var spacingPixels = Mathf.Max(settings.SpacingPixels, 1f);
            var localX = mousePosition.x - pixelRect.x;
            var localY = pixelRect.height - 1f - (mousePosition.y - pixelRect.y);
            return new Vector4(
                Mathf.Max(0f, localX / spacingPixels),
                Mathf.Max(0f, localY / spacingPixels),
                1f,
                0f);
        }

        private static void DrawRadianceCacheVisualizeGeometry(
            CommandBuffer cmd,
            Material material,
            BurtRenderRequest request,
            BurtRenderPipelineAsset asset,
            Camera camera,
            BurtRenderTargetHandle radianceCacheIndirectionTarget,
            BurtRenderTargetHandle radianceCacheFinalRadianceAtlasTarget,
            BurtRenderTargetHandle radianceCacheFinalIrradianceAtlasTarget,
            BurtRenderTargetHandle radianceCacheProbeOcclusionAtlasTarget,
            BurtRenderTargetHandle radianceCacheProbeSkyAOAtlasTarget,
            BurtRenderBufferHandle radianceCacheProbeWorldOffsetBuffer,
            BurtRenderBufferHandle radianceCacheProbeLastUsedFrameBuffer,
            BurtRenderBufferHandle radianceCacheProbeLastTracedFrameBuffer)
        {
            if (cmd == null ||
                material == null ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.IsScreenSpaceGlobalIlluminationRadianceCacheProbeDebugMode(BurtShadingDebugSettings.Mode) ||
                !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(request, asset) ||
                !radianceCacheIndirectionTarget.IsValid ||
                !radianceCacheFinalRadianceAtlasTarget.IsValid ||
                !radianceCacheFinalIrradianceAtlasTarget.IsValid ||
                !radianceCacheProbeOcclusionAtlasTarget.IsValid ||
                !radianceCacheProbeSkyAOAtlasTarget.IsValid ||
                !radianceCacheProbeWorldOffsetBuffer.HasBuffer ||
                !radianceCacheProbeLastUsedFrameBuffer.HasBuffer ||
                !radianceCacheProbeLastTracedFrameBuffer.HasBuffer)
            {
                return;
            }

            var screenProbeSettings = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            if (!screenProbeSettings.Enabled)
            {
                return;
            }

            UploadRadianceCacheClipMapSettings(cmd, camera, screenProbeSettings);
            var clipmapCount = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapCount(screenProbeSettings);
            var clipmapResolution = BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheClipMapResolution(screenProbeSettings);
            var instanceCount = Mathf.Max(1, clipmapResolution * clipmapResolution * clipmapResolution);
            var requestedClipmapIndex = Mathf.Clamp(screenProbeSettings.RadianceCacheVisualizeClipmapIndex, -1, clipmapCount - 1);
            var statusMode = BurtShadingDebugSettings.Mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationRadianceCacheStatus ? 1f : 0f;
            for (var clipmapIndex = 0; clipmapIndex < clipmapCount; clipmapIndex++)
            {
                if (requestedClipmapIndex >= 0 && clipmapIndex != requestedClipmapIndex)
                {
                    continue;
                }

                cmd.SetGlobalVector(
                    BurtGIRadianceCacheClipMapVisualizeDrawParamsId,
                    new Vector4(
                        clipmapIndex,
                        screenProbeSettings.RadianceCacheVisualizeRadiusScale,
                        statusMode,
                        0f));
                cmd.DrawProcedural(
                    Matrix4x4.identity,
                    material,
                    RadianceCacheVisualizeGeometryPassIndex,
                    MeshTopology.Triangles,
                    36,
                    instanceCount);
            }
        }

        private static void UploadTemporalDebugGlobals(CommandBuffer cmd, BurtRenderRequest request, BurtScreenSpaceGlobalIlluminationSettings settings)
        {
            var history = BurtScreenSpaceGlobalIlluminationHistoryUtility.GetDebugSnapshotTextures(request);
            var status = BurtScreenSpaceGlobalIlluminationHistoryUtility.GetHistoryStatus(request, settings);
            cmd.SetGlobalTexture(BurtGIPreviousHistoryTextureId, history.Color != null ? (Texture)history.Color : Texture2D.blackTexture);
            cmd.SetGlobalTexture(BurtGIPreviousHistoryDepthNormalTextureId, history.DepthNormal != null ? (Texture)history.DepthNormal : Texture2D.blackTexture);
            cmd.SetGlobalMatrix(BurtGIPreviousViewProjectionMatrixId, history.PreviousViewProjectionMatrix);
            cmd.SetGlobalVector(BurtGITemporalParamsId, new Vector4(settings.TemporalFeedback, status.HasHistory ? 1f : 0f, settings.TemporalDepthRejection, settings.TemporalNormalRejection));
        }

        private static void UploadHashGridDebugGeometryGlobals(CommandBuffer cmd, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            cmd.SetGlobalVector(BurtGIRadianceCacheHashGridParams0Id, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridCellSize,
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridTileCellRatio,
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridBucketCount,
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridTilesPerBucket));
            cmd.SetGlobalVector(BurtGIRadianceCacheHashGridParams1Id, new Vector4(
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheHashGridTileCount(),
                BurtScreenSpaceGlobalIlluminationPassUtility.ResolveRadianceCacheHashGridCellCount(),
                BurtScreenSpaceGlobalIlluminationPassUtility.RadianceCacheHashGridCellsPerTile,
                settings.RadianceCacheHashGridDebugMaxCellDecay));
            cmd.SetGlobalVector(BurtGIRadianceCacheClipMapStageParamsId, new Vector4(0f, 0f, Time.frameCount, 0f));
        }
    }

    internal sealed class BurtGIProbeRuntimeInfoDebugPass : BurtRenderPass
    {
        private const string ComputeShaderResourcePath = "BurtGIProbePhysicalPoolUpload";
        private const string KernelName = "ProbeDebugRuntimeInfoCS";
        private const int ThreadGroupSize = 8;
        private static readonly int SourceTextureId = Shader.PropertyToID("_BurtGIProbeRuntimeInfoSourceTexture");
        private static readonly int OutputTextureId = Shader.PropertyToID("_BurtGIProbeRuntimeInfoOutputTexture");
        private static readonly int ProbeInfoSourceTextureId = Shader.PropertyToID("ProbeInfoSourceTexture");
        private static readonly int RWProbeInfoTextureId = Shader.PropertyToID("RWProbeInfoTexture");
        private static readonly int ProbeInfoPhysicalUsagePercentId = Shader.PropertyToID("ProbeInfoPhysicalUsagePercent");
        private static readonly int ProbeInfoPhysicalUsedId = Shader.PropertyToID("ProbeInfoPhysicalUsed");
        private static readonly int ProbeInfoPhysicalTotalId = Shader.PropertyToID("ProbeInfoPhysicalTotal");
        private static readonly int ProbeInfoPhysicalEstimatedMemCostId = Shader.PropertyToID("ProbeInfoPhysicalEstimatedMemCost");
        private static readonly int ProbeInfoVirtualUsagePercentId = Shader.PropertyToID("ProbeInfoVirtualUsagePercent");
        private static readonly int ProbeInfoVirtualUsedId = Shader.PropertyToID("ProbeInfoVirtualUsed");
        private static readonly int ProbeInfoVirtualTotalId = Shader.PropertyToID("ProbeInfoVirtualTotal");
        private static readonly int ProbeInfoVirtualEstimatedMemCostId = Shader.PropertyToID("ProbeInfoVirtualEstimatedMemCost");
        private static readonly int ProbeInfoVirtualFragmentationRateId = Shader.PropertyToID("ProbeInfoVirtualFragmentationRate");
        private static readonly int ProbeInfoIndirectionEntriesSizeId = Shader.PropertyToID("ProbeInfoIndirectionEntriesSize");
        private static readonly int ProbeInfoIndirectionUsagePercentId = Shader.PropertyToID("ProbeInfoIndirectionUsagePercent");
        private static readonly int ProbeInfoIndirectionUsedId = Shader.PropertyToID("ProbeInfoIndirectionUsed");
        private static readonly int ProbeInfoIndirectionTotalId = Shader.PropertyToID("ProbeInfoIndirectionTotal");
        private static readonly int ProbeInfoIndirectionEstimatedMemCostId = Shader.PropertyToID("ProbeInfoIndirectionEstimatedMemCost");
        private static ComputeShader computeShader;
        private static bool hasLoggedMissingComputeShader;
        private static bool hasLoggedMissingKernel;

        public override string Name => "Burt XGI Probe Runtime Info Debug";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseGIProbeRuntimeInfoDebugView(builder.Request))
            {
                return;
            }

            builder.ReadCameraColor();
            builder.WriteCameraColor();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseGIProbeRuntimeInfoDebugView(context.Request))
            {
                return;
            }

            var camera = context.Request != null ? context.Request.Camera : null;
            var cameraColorTarget = context.CameraColorTarget;
            if (camera == null || !cameraColorTarget.IsValid)
            {
                return;
            }

            var shader = GetComputeShader();
            if (shader == null || !TryFindKernel(shader, out var kernel))
            {
                return;
            }

            BurtGIProbeVolumeUtility.TryResolveRuntimeInfoMetrics(camera, out var metrics);
            var sourceDescriptor = BurtRenderTargetDescriptorUtility.CreateCameraColorDescriptor(camera);
            sourceDescriptor.depthBufferBits = 0;
            sourceDescriptor.msaaSamples = 1;
            var outputDescriptor = sourceDescriptor;
            outputDescriptor.graphicsFormat = GraphicsFormat.R16G16B16A16_SFloat;
            outputDescriptor.enableRandomWrite = true;

            var cmd = context.AcquireCommandBuffer(Name);
            cmd.GetTemporaryRT(SourceTextureId, sourceDescriptor, FilterMode.Bilinear);
            cmd.GetTemporaryRT(OutputTextureId, outputDescriptor, FilterMode.Bilinear);
            var source = new RenderTargetIdentifier(SourceTextureId);
            var output = new RenderTargetIdentifier(OutputTextureId);
            cmd.Blit(cameraColorTarget.Identifier, source);
            cmd.SetComputeTextureParam(shader, kernel, ProbeInfoSourceTextureId, source);
            cmd.SetComputeTextureParam(shader, kernel, RWProbeInfoTextureId, output);
            UploadMetrics(cmd, shader, metrics);
            cmd.DispatchCompute(
                shader,
                kernel,
                Mathf.Max(1, (outputDescriptor.width + ThreadGroupSize - 1) / ThreadGroupSize),
                Mathf.Max(1, (outputDescriptor.height + ThreadGroupSize - 1) / ThreadGroupSize),
                1);
            cmd.Blit(output, cameraColorTarget.Identifier);
            cmd.ReleaseTemporaryRT(OutputTextureId);
            cmd.ReleaseTemporaryRT(SourceTextureId);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        private static void UploadMetrics(CommandBuffer cmd, ComputeShader shader, BurtGIProbeRuntimeInfoMetrics metrics)
        {
            cmd.SetComputeFloatParam(shader, ProbeInfoPhysicalUsagePercentId, metrics.physicalUsagePercent);
            cmd.SetComputeFloatParam(shader, ProbeInfoPhysicalUsedId, metrics.physicalUsed);
            cmd.SetComputeFloatParam(shader, ProbeInfoPhysicalTotalId, metrics.physicalTotal);
            cmd.SetComputeFloatParam(shader, ProbeInfoPhysicalEstimatedMemCostId, metrics.physicalEstimatedMemCost);
            cmd.SetComputeFloatParam(shader, ProbeInfoVirtualUsagePercentId, metrics.virtualUsagePercent);
            cmd.SetComputeFloatParam(shader, ProbeInfoVirtualUsedId, metrics.virtualUsed);
            cmd.SetComputeFloatParam(shader, ProbeInfoVirtualTotalId, metrics.virtualTotal);
            cmd.SetComputeFloatParam(shader, ProbeInfoVirtualEstimatedMemCostId, metrics.virtualEstimatedMemCost);
            cmd.SetComputeFloatParam(shader, ProbeInfoVirtualFragmentationRateId, metrics.virtualFragmentationRate);
            cmd.SetComputeVectorParam(shader, ProbeInfoIndirectionEntriesSizeId, metrics.indirectionEntriesSize);
            cmd.SetComputeFloatParam(shader, ProbeInfoIndirectionUsagePercentId, metrics.indirectionUsagePercent);
            cmd.SetComputeFloatParam(shader, ProbeInfoIndirectionUsedId, metrics.indirectionUsed);
            cmd.SetComputeFloatParam(shader, ProbeInfoIndirectionTotalId, metrics.indirectionTotal);
            cmd.SetComputeFloatParam(shader, ProbeInfoIndirectionEstimatedMemCostId, metrics.indirectionEstimatedMemCost);
        }

        private static ComputeShader GetComputeShader()
        {
            if (computeShader != null)
            {
                return computeShader;
            }

            computeShader = Resources.Load<ComputeShader>(ComputeShaderResourcePath);
            if (computeShader == null && !hasLoggedMissingComputeShader)
            {
                Debug.LogWarning("BurtRP could not find compute shader resource: " + ComputeShaderResourcePath);
                hasLoggedMissingComputeShader = true;
            }

            return computeShader;
        }

        private static bool TryFindKernel(ComputeShader shader, out int kernel)
        {
            kernel = -1;
            if (shader == null)
            {
                return false;
            }

            if (!shader.HasKernel(KernelName))
            {
                if (!hasLoggedMissingKernel)
                {
                    Debug.LogWarning("BurtRP compute shader " + ComputeShaderResourcePath + " is missing kernel " + KernelName + ".");
                    hasLoggedMissingKernel = true;
                }

                return false;
            }

            kernel = shader.FindKernel(KernelName);
            return true;
        }
    }

    internal sealed class BurtReleaseBurtGITemporalDiagnosticsPass : BurtRenderPass
    {
        public override string Name => "Burt Release BurtGI Temporal Diagnostics";

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTemporalDiagnostics(builder.Request, builder.Asset))
            {
                return;
            }

            builder.ReadBurtGITemporalDiagnostics();
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationTemporalDiagnostics(context.Request, context.Asset))
            {
                return;
            }

            var target = context.BurtGITemporalDiagnosticsTarget;
            if (!target.IsValid)
            {
                return;
            }

            BurtScreenSpaceGlobalIlluminationRenderTargetUtility.Release(context, Name, BurtRenderGraphResourceRegistry.BurtGITemporalDiagnosticsTextureId);
        }
    }

    internal abstract class BurtReleaseScreenSpaceGlobalIlluminationScreenProbePass : BurtRenderPass
    {
        protected abstract int TextureId { get; }
        protected abstract BurtRenderTargetHandle GetTarget(BurtRenderGraphContext context);
        protected abstract void ReadTarget(BurtRenderPassBuilder builder);
        protected virtual bool ShouldRelease(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            return BurtScreenSpaceGlobalIlluminationPassUtility.ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(request, asset);
        }

        public override void Configure(BurtRenderPassBuilder builder)
        {
            if (!ShouldRelease(builder.Request, builder.Asset))
            {
                return;
            }

            ReadTarget(builder);
        }

        public override void Execute(BurtRenderGraphContext context)
        {
            if (context == null || !ShouldRelease(context.Request, context.Asset))
            {
                return;
            }

            var target = GetTarget(context);
            if (!target.IsValid)
            {
                return;
            }

            BurtScreenSpaceGlobalIlluminationRenderTargetUtility.Release(context, Name, TextureId);
        }
    }

