        private static int Quantize(float value, float scale)
        {
            return Mathf.RoundToInt(value * scale);
        }

        private static Vector4 ClampVector4(Vector4 value, float min, float max)
        {
            return new Vector4(
                Mathf.Clamp(value.x, min, max),
                Mathf.Clamp(value.y, min, max),
                Mathf.Clamp(value.z, min, max),
                Mathf.Clamp(value.w, min, max));
        }

        private static ScreenSpaceGlobalIlluminationQuality NormalizeQuality(ScreenSpaceGlobalIlluminationQuality quality)
        {
            switch (quality)
            {
                case ScreenSpaceGlobalIlluminationQuality.Custom:
                case ScreenSpaceGlobalIlluminationQuality.Low:
                case ScreenSpaceGlobalIlluminationQuality.Medium:
                case ScreenSpaceGlobalIlluminationQuality.High:
                case ScreenSpaceGlobalIlluminationQuality.Ultra:
                    return quality;
                default:
                    return ScreenSpaceGlobalIlluminationQuality.Medium;
            }
        }

        private static ScreenSpaceGlobalIlluminationResolution NormalizeResolution(ScreenSpaceGlobalIlluminationResolution resolution)
        {
            return resolution == ScreenSpaceGlobalIlluminationResolution.Full ? ScreenSpaceGlobalIlluminationResolution.Full : ScreenSpaceGlobalIlluminationResolution.Half;
        }

        private static ScreenSpaceGlobalIlluminationFinalGather NormalizeFinalGather(ScreenSpaceGlobalIlluminationFinalGather finalGather)
        {
            return finalGather == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField
                ? ScreenSpaceGlobalIlluminationFinalGather.IrradianceField
                : ScreenSpaceGlobalIlluminationFinalGather.ScreenProbe;
        }

        private static SceneVoxelMaterialMemoryBudget NormalizeSceneVoxelMaterialBudget(SceneVoxelMaterialMemoryBudget materialBudget)
        {
            switch (materialBudget)
            {
                case SceneVoxelMaterialMemoryBudget.None:
                case SceneVoxelMaterialMemoryBudget.Low:
                case SceneVoxelMaterialMemoryBudget.Medium:
                case SceneVoxelMaterialMemoryBudget.High:
                case SceneVoxelMaterialMemoryBudget.Ultra:
                    return materialBudget;
                default:
                    return SceneVoxelMaterialMemoryBudget.Medium;
            }
        }

        private static SceneVoxelMaterialGenerateMethod NormalizeSceneVoxelMaterialGenerateMethod(SceneVoxelMaterialGenerateMethod generateMethod)
        {
            // XRender's PendingList material path is retained only in disabled legacy sources.
            // Keep old scene data readable, but select the active Atomic implementation.
            return SceneVoxelMaterialGenerateMethod.Atomic;
        }

        private static SceneVoxelLightingType NormalizeSceneVoxelLightingType(SceneVoxelLightingType lightingType)
        {
            switch (lightingType)
            {
                case SceneVoxelLightingType.None:
                case SceneVoxelLightingType.Directional:
                case SceneVoxelLightingType.Direct:
                case SceneVoxelLightingType.Indirect:
                    return lightingType;
                default:
                    return SceneVoxelLightingType.Indirect;
            }
        }
    }

