                hash = hash * 31 + RadianceCacheIrradianceClipMapResolution;
                hash = hash * 31 + Quantize(RadianceCacheIrradianceClipMapWorldExtent, 1000f);
                hash = hash * 31 + RadianceCacheIrradianceNumProbesToTraceBudget;
                hash = hash * 31 + Quantize(RadianceCacheVisualizeRadiusScale, 10000f);
                hash = hash * 31 + TranslucencyVolumeGridPixelSize;
                hash = hash * 31 + Quantize(TranslucencyVolumeEndDistanceFromCamera, 100f);
                hash = hash * 31 + Quantize(TranslucencyVolumeGridDistributionZScale, 1000f);
                hash = hash * 31 + TranslucencyVolumeTracingOctahedronResolution;
                hash = hash * 31 + (TranslucencyVolumeJitter ? 1 : 0);
                hash = hash * 31 + (TranslucencyVolumeUseTemporalReprojection ? 1 : 0);
                hash = hash * 31 + Quantize(TranslucencyVolumeHistoryWeight, 1000f);
                hash = hash * 31 + TranslucencyVolumeTemporalMaxRayDirections;
                hash = hash * 31 + (TranslucencyVolumeSpatialFilter ? 1 : 0);
                hash = hash * 31 + TranslucencyVolumeSpatialFilterSampleCount;
                hash = hash * 31 + Quantize(TranslucencyVolumeSpatialFilterStandardDeviation, 1000f);
                hash = hash * 31 + Quantize(TranslucencyVolumeGridCenterOffsetFromDepthBuffer, 1000f);
                hash = hash * 31 + Quantize(TranslucencyVolumeOffsetThresholdToAcceptDepthBufferOffset, 1000f);
                hash = hash * 31 + Quantize(TranslucencyVolumeTraceStepFactor, 1000f);
                hash = hash * 31 + Quantize(TranslucencyVolumeMaxTraceDistance, 1000f);
                hash = hash * 31 + Quantize(TranslucencyVolumeVoxelTraceStartDistanceScale, 1000f);
                hash = hash * 31 + Quantize(TranslucencyVolumeMaxRayIntensity, 1000f);
                hash = hash * 31 + Quantize(SceneVoxelClipMapFirstWorldExtent, 1000f);
                hash = hash * 31 + Quantize(SceneVoxelClipMapDistributionBase, 1000f);
                hash = hash * 31 + (SceneVoxelFollowCamera ? 1 : 0);
                hash = hash * 31 + Quantize(SceneVoxelCameraForward, 1000f);
                hash = hash * 31 + Quantize(SceneVoxelOrigin.x, 1000f);
                hash = hash * 31 + Quantize(SceneVoxelOrigin.y, 1000f);
                hash = hash * 31 + Quantize(SceneVoxelOrigin.z, 1000f);
                return hash;
            }
        }

        private static int Quantize(float value, float scale)
        {
            return Mathf.RoundToInt(value * scale);
        }

        private static ScreenProbeRadianceCacheType NormalizeRadianceCacheType(ScreenProbeRadianceCacheType radianceCacheType)
        {
            switch (radianceCacheType)
            {
                case ScreenProbeRadianceCacheType.None:
                case ScreenProbeRadianceCacheType.HashGrid:
                case ScreenProbeRadianceCacheType.ClipMap:
                    return radianceCacheType;
                default:
                    return ScreenProbeRadianceCacheType.ClipMap;
            }
        }

        private static ScreenProbeIrradianceFormat NormalizeIrradianceFormat(ScreenProbeIrradianceFormat irradianceFormat)
        {
            return irradianceFormat == ScreenProbeIrradianceFormat.Octahedral
                ? ScreenProbeIrradianceFormat.Octahedral
                : ScreenProbeIrradianceFormat.SH3;
        }

        private static ScreenProbeIntegrateType NormalizeIntegrateType(ScreenProbeIntegrateType integrateType)
        {
            return integrateType == ScreenProbeIntegrateType.TileClassification
                ? ScreenProbeIntegrateType.TileClassification
                : ScreenProbeIntegrateType.SimpleIntegrate;
        }

        private static ScreenProbeIntegrateMethod NormalizeIntegrateMethod(ScreenProbeIntegrateMethod integrateMethod)
        {
            return ScreenProbeIntegrateMethod.SphericalHarmonic;
        }

        private static ScreenProbeTraceSource NormalizeTraceSources(ScreenProbeTraceSource traceSources)
        {
            traceSources &= ScreenProbeTraceSource.All;
            traceSources &= ~ScreenProbeTraceSource.RadianceCacheClipMap;
            return traceSources;
        }

        private bool HasTraceSource(ScreenProbeTraceSource traceSource)
        {
            return (TraceSources & traceSource) != 0;
        }
    }

