        public static int ResolveScreenProbeTracingOctahedronResolution(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return Mathf.Clamp(settings.TraceOctahedronResolution, ScreenProbeTracingOctahedronResolutionMin, ScreenProbeTracingOctahedronResolutionMax);
        }

        public static int ResolveScreenProbeRadianceOctResolutionWithBorder(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return ResolveScreenProbeTracingOctahedronResolution(settings) + ScreenProbeRadianceOctBorderSize * 2;
        }

        public static int ResolveScreenProbeImportancePDFResolutionWithBorder(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return ResolveScreenProbeTracingOctahedronResolution(settings) + ScreenProbeImportancePDFBorderSize * 2;
        }

        public static int NormalizeSceneVoxelRadianceResolution(int resolution)
        {
            var clamped = Mathf.Clamp(resolution, SceneVoxelRadianceResolutionMin, SceneVoxelRadianceResolutionMax);
            if (clamped >= 64)
            {
                return 64;
            }

            return clamped >= 32 ? 32 : 16;
        }

        public static int ResolveSceneVoxelRadianceResolution(BurtScreenSpaceGlobalIlluminationSettings settings)
        {
            return NormalizeSceneVoxelRadianceResolution(settings.SceneVoxelClipMapResolution);
        }

        public static int ResolveSceneVoxelOccupancyMipResolution(int radianceResolution)
        {
            return Mathf.Max(1, NormalizeSceneVoxelRadianceResolution(radianceResolution) / 4);
        }

        public static int ResolveSceneVoxelOccupancyMipCount(int radianceResolution)
        {
            var resolution = ResolveSceneVoxelOccupancyMipResolution(radianceResolution);
            var mipCount = 1;
            while (resolution > 1)
            {
                resolution >>= 1;
                mipCount++;
            }

            return Mathf.Clamp(mipCount, 1, SceneVoxelOccupancyMipCount);
        }

        private static int shaderAvailabilityFrame = -1;
        private static bool shaderAvailable;
        private sealed class RuntimeCameraState
        {
            public bool WasEnabledLastFrame;
            public bool PendingFirstFrameSkip = true;
            public int FirstFrameSkipFrame = -1;
            public string LastStatusReason = "NeverEvaluated";
        }

        private static readonly System.Collections.Generic.Dictionary<int, RuntimeCameraState> runtimeCameraStates = new System.Collections.Generic.Dictionary<int, RuntimeCameraState>();

        private static RuntimeCameraState GetRuntimeCameraState(Camera camera)
        {
            if (camera == null)
            {
                return null;
            }

            var key = camera.GetInstanceID();
            if (!runtimeCameraStates.TryGetValue(key, out var state))
            {
                state = new RuntimeCameraState();
                runtimeCameraStates.Add(key, state);
            }

            return state;
        }

        private static bool IsPrimarySceneRequest(BurtRenderRequest request)
        {
            return request != null &&
                request.IsValid &&
                (request.Type == BurtRenderRequestType.BaseCamera ||
                    request.Type == BurtRenderRequestType.SceneView);
        }

        private static void UpdateRuntimeEnabledState(BurtRenderRequest request, bool enabled, string reason)
        {
            if (!IsPrimarySceneRequest(request))
            {
                return;
            }

            var state = GetRuntimeCameraState(request.Camera);
            if (state == null)
            {
                return;
            }

            if (state.WasEnabledLastFrame && !enabled)
            {
                state.PendingFirstFrameSkip = true;
            }

            state.WasEnabledLastFrame = enabled;
            state.LastStatusReason = string.IsNullOrEmpty(reason) ? (enabled ? "Enabled" : "Disabled") : reason;
            if (!enabled && state.FirstFrameSkipFrame != Time.frameCount)
            {
                state.FirstFrameSkipFrame = -1;
            }
        }

        public static bool ConsumeScreenSpaceGlobalIlluminationFirstFrameSkip(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            if (!IsPrimarySceneRequest(request) || !ResolveScreenSpaceGlobalIlluminationSettings(request, asset).Enabled)
            {
                return false;
            }

            var state = GetRuntimeCameraState(request.Camera);
            if (state == null || !state.PendingFirstFrameSkip)
            {
                return false;
            }

            state.PendingFirstFrameSkip = false;
            state.FirstFrameSkipFrame = Time.frameCount;
            return true;
        }

        public static bool IsScreenSpaceGlobalIlluminationFirstFrameSkip(BurtRenderRequest request)
        {
            if (!IsPrimarySceneRequest(request))
            {
                return false;
            }

            var state = GetRuntimeCameraState(request.Camera);
            return state != null && state.FirstFrameSkipFrame == Time.frameCount;
        }

        public static string ResolveScreenSpaceGlobalIlluminationRuntimeStatusLabel(BurtRenderRequest request)
        {
            if (!IsPrimarySceneRequest(request))
            {
                return "NonPrimary";
            }

            var state = GetRuntimeCameraState(request.Camera);
            if (state == null)
            {
                return "NoCameraState";
            }

            var enabled = state.WasEnabledLastFrame ? "Enabled" : "Disabled";
            var reason = string.IsNullOrEmpty(state.LastStatusReason) ? "Unknown" : state.LastStatusReason;
            var firstFrameSkip = state.FirstFrameSkipFrame == Time.frameCount
                ? "FirstFrameSkip"
                : (state.PendingFirstFrameSkip ? "PendingFirstFrameSkip" : "NoFirstFrameSkip");
            return enabled + "(" + reason + "," + firstFrameSkip + ")";
        }

        public static bool ShouldUseScreenSpaceGlobalIllumination(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            return ResolveScreenSpaceGlobalIlluminationSettings(request, asset).Enabled;
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            return ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset).Enabled;
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var settings = ResolveScreenSpaceGlobalIlluminationSettings(request, asset);
            var screenProbeSettings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            return settings.Enabled &&
                settings.FinalGather != ScreenSpaceGlobalIlluminationFinalGather.IrradianceField &&
                screenProbeSettings.Enabled &&
                screenProbeSettings.IntegrateMethod == ScreenProbeIntegrateMethod.SphericalHarmonic &&
                SystemInfo.supportsComputeShaders;
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileClassification(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var screenProbeSettings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            return ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(request, asset) &&
                screenProbeSettings.IntegrateType == ScreenProbeIntegrateType.TileClassification;
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateSimpleSH(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var screenProbeSettings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            return ShouldUseScreenSpaceGlobalIlluminationScreenProbeIntegrateTileData(request, asset) &&
                screenProbeSettings.IntegrateType == ScreenProbeIntegrateType.SimpleIntegrate;
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var settings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            return settings.Enabled &&
                settings.RadianceCacheType == ScreenProbeRadianceCacheType.ClipMap &&
                SupportsRadianceCacheClipMapCompute();
        }

        public static bool ShouldCalculateScreenSpaceGlobalIlluminationRadianceCacheIrradiance(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            if (!ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(request, asset))
            {
                return false;
            }

            var settings = ResolveScreenSpaceGlobalIlluminationSettings(request, asset);
            var screenProbeSettings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            return screenProbeSettings.RadianceCacheCalculateIrradiance ||
                settings.FinalGather == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField ||
                (settings.SceneVoxelMultiBounce && screenProbeSettings.RadianceCacheEnableMultiBounceFromRadianceCache);
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationRadianceCacheHashGrid(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var settings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            return settings.Enabled &&
                settings.RadianceCacheType != ScreenProbeRadianceCacheType.None &&
                SupportsRadianceCacheHashGridCompute();
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationSceneVoxel(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var settings = ResolveScreenSpaceGlobalIlluminationSettings(request, asset);
            var screenProbeSettings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            if (!screenProbeSettings.Enabled)
            {
                return false;
            }

            var irradianceFieldNeedsVoxelScene = settings.FinalGather == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField;
            var traceVoxelScene = screenProbeSettings.TraceVoxelOctree ||
                screenProbeSettings.TraceSceneVoxel ||
                screenProbeSettings.TraceScreenGrid ||
                screenProbeSettings.TraceUseWorldRadianceClipMap;
            var radianceCacheNeedsVoxelScene = ShouldUseScreenSpaceGlobalIlluminationRadianceCacheClipMapContract(request, asset) &&
                (!screenProbeSettings.RadianceCacheTraceHardwareRay || asset == null || !asset.EnableXGIHardwareRayTracing);
            if (!traceVoxelScene && !irradianceFieldNeedsVoxelScene && !radianceCacheNeedsVoxelScene)
            {
                return false;
            }

            return (screenProbeSettings.TraceCompact && SupportsScreenProbeTraceCompactCompute()) ||
                irradianceFieldNeedsVoxelScene ||
                radianceCacheNeedsVoxelScene ||
                ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(request, asset);
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationTranslucencyVolume(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var screenProbeSettings = ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(request, asset);
            return ShouldUseScreenSpaceGlobalIlluminationScreenProbeLite(request, asset) &&
                ResolveScreenSpaceGlobalIlluminationSettings(request, asset).UseTranslucencyVolume &&
                (screenProbeSettings.TraceVoxelOctree || screenProbeSettings.TraceSceneVoxel) &&
                SupportsTranslucencyVolumeCompute();
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationBilateralUpsample(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            var settings = ResolveScreenSpaceGlobalIlluminationSettings(request, asset);
            return settings.Enabled &&
                settings.Resolution == ScreenSpaceGlobalIlluminationResolution.Half &&
                settings.FinalGather != ScreenSpaceGlobalIlluminationFinalGather.IrradianceField;
        }

        public static bool SupportsRadianceCacheClipMapCompute()
        {
            return SupportsWideComputeUAVSet();
        }

        private static bool SupportsRadianceCacheHashGridCompute()
        {
            return SupportsWideComputeUAVSet();
        }

        public static bool SupportsScreenProbeTraceCompactCompute()
        {
            return SupportsWideComputeUAVSet();
        }

        private static bool SupportsTranslucencyVolumeCompute()
        {
