        public static string ResolveXGISdfDebugStatusLabel()
        {
            var shader = Resources.Load<ComputeShader>("BurtGIXGISdfDebug");
            if (shader == null)
            {
                return "Missing(BurtGIXGISdfDebug)";
            }

            if (!shader.HasKernel("VisualizeSdfCS"))
            {
                return "Missing(BurtGIXGISdfDebug.VisualizeSdfCS)";
            }

            return "Ready(PersistentClipmapScheduled,BaseClipmapOnDemand,DebugViewSamplingReady)";
        }

        private static void AppendMissingComputeKernels(
            string resourcePath,
            string[] kernels,
            ref string missing,
            ref int missingCount,
            ref int kernelCount)
        {
            var shader = Resources.Load<ComputeShader>(resourcePath);
            if (shader == null)
            {
                AppendMissingComputeItem(resourcePath, ref missing, ref missingCount);
                return;
            }

            if (kernels == null)
            {
                return;
            }

            for (var i = 0; i < kernels.Length; i++)
            {
                var kernel = kernels[i];
                kernelCount++;
                if (!shader.HasKernel(kernel))
                {
                    AppendMissingComputeItem(resourcePath + "." + kernel, ref missing, ref missingCount);
                }
            }
        }

        private static void AppendMissingComputeItem(string item, ref string missing, ref int missingCount)
        {
            if (missingCount > 0)
            {
                missing += ",";
            }

            missing += item;
            missingCount++;
        }

        private static bool SupportsWideComputeUAVSet()
        {
            return SystemInfo.supportsComputeShaders;
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationDebugView(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            if (!IsScreenSpaceGlobalIlluminationDebugMode(BurtShadingDebugSettings.Mode))
            {
                return false;
            }

            if (IsScreenSpaceGlobalIlluminationTemporalDiagnosticDebugMode(BurtShadingDebugSettings.Mode))
            {
                return ShouldUseScreenSpaceGlobalIlluminationTemporalDiagnostics(request, asset);
            }

            if (IsScreenSpaceGlobalIlluminationRadianceCacheStatsDebugMode(BurtShadingDebugSettings.Mode))
            {
                return ShouldUseScreenSpaceGlobalIlluminationRadianceCacheStats(request, asset);
            }

            if (IsScreenSpaceGlobalIlluminationHashGridDebugMode(BurtShadingDebugSettings.Mode))
            {
                return ShouldUseScreenSpaceGlobalIlluminationRadianceCacheHashGrid(request, asset);
            }

            if (IsScreenSpaceGlobalIlluminationRadianceCacheProbeDebugMode(BurtShadingDebugSettings.Mode))
            {
                return ShouldUseScreenSpaceGlobalIlluminationRadianceCacheProbeDebug(request, asset);
            }

            if (IsScreenSpaceGlobalIlluminationScreenProbeDebugMode(BurtShadingDebugSettings.Mode))
            {
                return ShouldUseScreenSpaceGlobalIlluminationScreenProbeDebug(request, asset);
            }

            if (IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(BurtShadingDebugSettings.Mode))
            {
                return ShouldUseScreenSpaceGlobalIlluminationSceneVoxelDebug(request, asset);
            }

            return ShouldUseScreenSpaceGlobalIllumination(request, asset);
        }

        public static bool ShouldUseScreenSpaceGlobalIlluminationTemporalDiagnostics(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            if (!IsScreenSpaceGlobalIlluminationTemporalDiagnosticDebugMode(BurtShadingDebugSettings.Mode))
            {
                return false;
            }

            var settings = ResolveScreenSpaceGlobalIlluminationSettings(request, asset);
            return settings.Enabled && settings.TemporalAccumulation;
        }

        public static bool IsScreenSpaceGlobalIlluminationDebugMode(BurtShadingDebugMode mode)
        {
            return mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationRaw ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationFinal ||
                IsScreenSpaceGlobalIlluminationIndirectChannelDebugMode(mode) ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationHitRatio ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationOverlay ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationComposite ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationHistory ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationDifference ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationLeakGuard ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationDiagnosticCompare ||
                mode == BurtShadingDebugMode.ScreenSpaceGlobalIlluminationConfidence ||
                IsScreenSpaceGlobalIlluminationHashGridDebugMode(mode) ||
                IsScreenSpaceGlobalIlluminationRadianceCacheSkyAODebugMode(mode) ||
                IsScreenSpaceGlobalIlluminationRadianceCacheStatsDebugMode(mode) ||
                IsScreenSpaceGlobalIlluminationRadianceCacheProbeDebugMode(mode) ||
                IsScreenSpaceGlobalIlluminationScreenProbeDebugMode(mode) ||
                IsScreenSpaceGlobalIlluminationSceneVoxelDebugMode(mode) ||
                IsScreenSpaceGlobalIlluminationTemporalDiagnosticDebugMode(mode);
        }

