        public static BurtScreenSpaceGlobalIlluminationSettings ResolveScreenSpaceGlobalIlluminationSettings(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            if (request == null || !request.IsValid || request.Camera == null)
            {
                BurtLocalSkyProbe.SetCameraSelectionForwardDistance(BurtLocalSkyProbe.DefaultCameraSelectionForwardDistance);
                BurtLocalSkyProbe.SetGlobalDebugVisibility(false);
                return BurtScreenSpaceGlobalIlluminationSettings.Disabled;
            }

            if (request.Type == BurtRenderRequestType.Preview || request.Type == BurtRenderRequestType.Reflection)
            {
                return DisableAndInvalidateHistory(request, "PreviewOrReflection");
            }

            if (asset == null || asset.RendererMode != BurtRendererMode.Deferred)
            {
                return DisableAndInvalidateHistory(request, "RendererNotDeferred");
            }

            if (IsScreenSpaceGlobalIlluminationSuppressedByShadingDebug())
            {
                return DisableAndInvalidateHistory(request, "ShadingDebug");
            }

            var component = GetScreenSpaceGlobalIlluminationVolumeComponent();
            if (component == null || !component.IsEnabled())
            {
                return DisableAndInvalidateHistory(request, "BurtGIDisabled");
            }

            BurtXGILightComponent.TryGetBest(request.Camera, out var xgiLightComponent);
            if (xgiLightComponent != null && !xgiLightComponent.enable)
            {
                return DisableAndInvalidateHistory(request, "XGILightComponentDisabled");
            }

            if (ShouldUseScreenSpaceGlobalIlluminationProbeFirst(component, request, xgiLightComponent))
            {
                return DisableAndInvalidateHistory(request, "XGIProbeFirst");
            }

            if (!IsScreenSpaceGlobalIlluminationShaderAvailable())
            {
                return DisableAndInvalidateHistory(request, "ShaderMissing");
            }

            var localSkyProbeCameraDistance = component.localSkyProbeCameraDistance.value;
            var settings = ApplyTemporalAACompatibilityOverrides(CreateScreenSpaceGlobalIlluminationSettings(component), request);
            if (xgiLightComponent != null)
            {
                settings = xgiLightComponent.ApplyToSettings(settings);
                localSkyProbeCameraDistance = xgiLightComponent.localSkyProbeCameraDistance;
            }
            BurtLocalSkyProbe.SetCameraSelectionForwardDistance(localSkyProbeCameraDistance);
            BurtLocalSkyProbe.SetGlobalDebugVisibility(settings.LocalSkyProbeShowDebugSphere);

            if (!settings.UseTranslucencyVolume)
            {
                BurtGITranslucencyVolumeHistoryUtility.ReleaseHistory(request.Camera, "TranslucencyVolumeDisabled");
            }

            UpdateRuntimeEnabledState(request, true, "Enabled");
            return settings;
        }

        private static bool ShouldUseScreenSpaceGlobalIlluminationProbeFirst(
            ScreenSpaceGlobalIlluminationVolumeComponent component,
            BurtRenderRequest request,
            BurtXGILightComponent xgiLightComponent)
        {
            if (component == null || request == null || request.Camera == null)
            {
                return false;
            }

            var useProbeFirst = component.xgiUseProbeFirst.value ||
                (xgiLightComponent != null && xgiLightComponent.useProbeFirst) ||
                component.quality.value == ScreenSpaceGlobalIlluminationQuality.Low;
            return useProbeFirst &&
                BurtGIProbeVolume.TryGetBestForCamera(request.Camera, out var probeVolume) &&
                probeVolume.virtualEnableShading &&
                probeVolume.HasLoadedVirtualEntries;
        }

        public static BurtScreenSpaceGlobalIlluminationScreenProbeSettings ResolveScreenSpaceGlobalIlluminationScreenProbeSettings(BurtRenderRequest request, BurtRenderPipelineAsset asset)
        {
            if (!ResolveScreenSpaceGlobalIlluminationSettings(request, asset).Enabled)
            {
                return BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled;
            }

            var component = GetScreenSpaceGlobalIlluminationVolumeComponent();
            if (component == null ||
                (!component.screenProbeLite.value && component.finalGather.value != ScreenSpaceGlobalIlluminationFinalGather.IrradianceField))
            {
                BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, "ScreenProbeDisabled");
                BurtGITranslucencyVolumeHistoryUtility.ReleaseHistory(request != null ? request.Camera : null, "ScreenProbeDisabled");
                BurtRadianceCacheClipMapHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, "ScreenProbeDisabled");
                BurtRadianceCacheHashGridHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, "ScreenProbeDisabled");
                return BurtScreenSpaceGlobalIlluminationScreenProbeSettings.Disabled;
            }

            var useIrradianceFieldGather = component.finalGather.value == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField;
            var radianceCacheType = useIrradianceFieldGather
                ? ScreenProbeRadianceCacheType.ClipMap
                : component.screenProbeRadianceCacheType.value;
            var quality = component.quality.value;
            var screenProbeSpacingPixels = component.screenProbeSpacingPixels.value;
            var screenProbeAdaptiveMinDownSampleFactor = component.screenProbeAdaptiveMinDownSampleFactor.value;
            var screenProbeTraceOctahedronResolution = component.screenProbeTraceOctahedronResolution.value;
            var screenProbeTraceSources = component.screenProbeTraceSources.value;
            var screenProbeReprojectionMaxFramesAccumulated = component.screenProbeReprojectionMaxFramesAccumulated.value;
            var screenProbeHistoryDistanceThreshold = Mathf.Max(component.screenProbeHistoryDistanceThreshold.value, 0.02f);
            var screenProbeScreenTraceThicknessScaleWhenNoFallback = Mathf.Max(component.screenProbeScreenTraceThicknessScaleWhenNoFallback.value, 2f);
            var screenProbeTemporalPlayerVelocityThreshold = Mathf.Clamp(component.screenProbeTemporalPlayerVelocityThreshold.value, 0.1f, 1f);
            var radianceCacheNumProbesToTraceBudget = component.screenProbeRadianceCacheNumProbesToTraceBudget.value;
            var translucencyVolumeGridPixelSize = component.translucencyVolumeGridPixelSize.value;
            var translucencyVolumeEndDistanceFromCamera = component.translucencyVolumeEndDistanceFromCamera.value;
            var translucencyVolumeGridDistributionZScale = component.translucencyVolumeGridDistributionZScale.value;
            ApplyScreenSpaceGlobalIlluminationScreenProbeQualityPreset(
                quality,
                ref screenProbeSpacingPixels,
                ref screenProbeAdaptiveMinDownSampleFactor,
                ref screenProbeTraceOctahedronResolution,
                ref screenProbeTraceSources,
                ref screenProbeReprojectionMaxFramesAccumulated,
                ref screenProbeHistoryDistanceThreshold,
                ref radianceCacheNumProbesToTraceBudget,
                ref translucencyVolumeGridPixelSize,
                ref translucencyVolumeEndDistanceFromCamera,
                ref translucencyVolumeGridDistributionZScale);

            var settings = new BurtScreenSpaceGlobalIlluminationScreenProbeSettings(
                true,
                screenProbeSpacingPixels,
                component.screenProbeAdaptiveAllocationFraction.value,
                screenProbeAdaptiveMinDownSampleFactor,
                screenProbeTraceOctahedronResolution,
                component.screenProbeTraceDistance.value,
                component.screenProbeTraceScreenDistance.value,
                component.screenProbeTraceVoxelMaxTraceSteps.value,
                component.screenProbeTraceVoxelStepFactor.value,
                component.screenProbeTraceHierarchically.value,
                component.screenProbeTraceHierarchicalMaxIterations.value,
                component.screenProbeTraceRelativeDepthThickness.value,
                component.screenProbeTraceHistoryDepthTestRelativeThickness.value,
                screenProbeScreenTraceThicknessScaleWhenNoFallback,
                component.screenProbeGatherMaxRayIntensity.value,
                component.xgiIntensityScale.value,
                component.screenProbeSampleCount.value,
                component.screenProbeTemporalFeedback.value,
                component.screenProbeTemporalFilterHistoryWeight.value,
                component.screenProbeTemporalFilter.value,
                component.screenProbeTemporalReprojection.value,
                screenProbeReprojectionMaxFramesAccumulated,
                screenProbeHistoryDistanceThreshold,
                component.screenProbeTemporalHistoryNormalThreshold.value,
                component.screenProbeReprojectionDepthRejectParamsA.value,
                component.screenProbeReprojectionDepthRejectParamsB.value,
                component.screenProbeTemporalExposureCheckThreshold.value,
                screenProbeTemporalPlayerVelocityThreshold,
                component.finalGather.value == ScreenSpaceGlobalIlluminationFinalGather.IrradianceField ? 0f : component.screenProbeApplyStrength.value,
                (component.screenProbeTraceCompact.value || component.screenProbeTraceHardwareRay.value) &&
                    SupportsScreenProbeTraceCompactCompute(),
                component.screenProbeTraceHardwareRay.value,
                component.screenProbeTraceUseWorldRadianceClipMap.value && SupportsRadianceCacheClipMapCompute(),
                screenProbeTraceSources,
                component.screenProbeImportanceSampling.value,
                component.screenProbeImportanceSampleLighting.value,
                component.screenProbeImportanceSampleProbeRadianceHistory.value,
                component.screenProbeImportanceSamplingHistoryDistanceThreshold.value,
                component.screenProbeFixedJitterIndex.value,
                component.screenProbeSpatialFilter.value,
                component.screenProbeSpatialFilterPasses.value,
                component.screenProbeSpatialFilterHalfKernelSize.value,
                component.screenProbeSpatialFilterMaxRadianceHitAngle.value,
                component.screenProbeSpatialFilterPositionWeightScale.value,
                component.screenProbeFixupBorders.value,
                component.screenProbeIrradianceFormat.value,
                component.screenProbeIntegrateType.value,
                component.screenProbeIntegrateMethod.value,
                radianceCacheType,
                component.screenProbeRadianceCacheForceFullUpdate.value,
                component.screenProbeRadianceCacheTraceHardwareRay.value,
                component.screenProbeRadianceCacheCalculateIrradiance.value ||
                    useIrradianceFieldGather,
                component.screenProbeRadianceCacheEnableMultiBounceFromRadianceCache.value,
                component.screenProbeRadianceCacheRadianceProbeResolution.value,
                component.screenProbeRadianceCacheIrradianceProbeResolution.value,
                component.screenProbeRadianceCacheOcclusionProbeResolution.value,
                component.screenProbeRadianceCacheFilterProbes.value,
                component.screenProbeRadianceCacheFilterMaxRadianceHitAngle.value,
                component.screenProbeRadianceCacheReprojectionRadiusScale.value,
                component.screenProbeRadianceCacheClipMapCount.value,
                component.screenProbeRadianceCacheClipMapResolution.value,
                component.screenProbeRadianceCacheClipMapWorldExtent.value,
                radianceCacheNumProbesToTraceBudget,
                component.screenProbeRadianceCacheIrradianceRadianceProbeResolution.value,
                component.screenProbeRadianceCacheIrradianceClipMapCount.value,
                component.screenProbeRadianceCacheIrradianceClipMapResolution.value,
                component.screenProbeRadianceCacheIrradianceClipMapWorldExtent.value,
                component.screenProbeRadianceCacheIrradianceNumProbesToTraceBudget.value,
                component.screenProbeRadianceCacheVisualizeRadiusScale.value,
                component.screenProbeRadianceCacheVisualizeClipmapIndex.value,
                component.screenProbeRadianceCacheHashGridDebugMaxCellDecay.value,
                translucencyVolumeGridPixelSize,
                translucencyVolumeEndDistanceFromCamera,
                translucencyVolumeGridDistributionZScale,
                component.translucencyVolumeTracingOctahedronResolution.value,
                component.translucencyVolumeJitter.value,
                component.translucencyVolumeUseTemporalReprojection.value,
                component.translucencyVolumeHistoryWeight.value,
                component.translucencyVolumeTemporalMaxRayDirections.value,
                component.translucencyVolumeSpatialFilter.value,
                component.translucencyVolumeSpatialFilterSampleCount.value,
                component.translucencyVolumeSpatialFilterStandardDeviation.value,
                component.translucencyVolumeGridCenterOffsetFromDepthBuffer.value,
                component.translucencyVolumeOffsetThresholdToAcceptDepthBufferOffset.value,
                component.translucencyVolumeTraceStepFactor.value,
                component.translucencyVolumeMaxTraceDistance.value,
                component.translucencyVolumeVoxelTraceStartDistanceScale.value,
                component.translucencyVolumeMaxRayIntensity.value,
                component.sceneVoxelClipMapFirstWorldExtent.value,
                component.sceneVoxelClipMapDistributionBase.value,
                component.sceneVoxelFollowCamera.value,
                component.sceneVoxelCameraForward.value,
                component.sceneVoxelOrigin.value);

            return BurtXGILightComponent.TryGetBest(request != null ? request.Camera : null, out var xgiLightComponent)
                ? xgiLightComponent.ApplyToScreenProbeSettings(settings)
                : settings;
        }

        private static BurtScreenSpaceGlobalIlluminationSettings DisableAndInvalidateHistory(BurtRenderRequest request, string reason)
        {
            BurtScreenSpaceGlobalIlluminationHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, reason);
            BurtScreenSpaceGlobalIlluminationScreenProbeHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, reason);
            BurtGITranslucencyVolumeHistoryUtility.ReleaseHistory(request != null ? request.Camera : null, reason);
            BurtRadianceCacheClipMapHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, reason);
            BurtRadianceCacheHashGridHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, reason);
            BurtGISceneVoxelHistoryUtility.InvalidateHistory(request != null ? request.Camera : null, reason);
            BurtLocalSkyProbe.SetCameraSelectionForwardDistance(BurtLocalSkyProbe.DefaultCameraSelectionForwardDistance);
            BurtLocalSkyProbe.SetGlobalDebugVisibility(false);
            UpdateRuntimeEnabledState(request, false, reason);
            return BurtScreenSpaceGlobalIlluminationSettings.Disabled;
        }

        public static RenderTextureDescriptor CreateScreenSpaceGlobalIlluminationDescriptor(Camera camera, BurtScreenSpaceGlobalIlluminationSettings settings)
        {
            var descriptor = BurtRenderTargetDescriptorUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera);
            if (settings.FinalGather != ScreenSpaceGlobalIlluminationFinalGather.IrradianceField)
            {
                ApplyScreenSpaceGlobalIlluminationResolution(ref descriptor, settings);
            }

            return descriptor;
        }

