        public static RenderTextureDescriptor CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var descriptor = BurtRenderTargetDescriptorUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera);
            descriptor.width = Mathf.Max(1, (descriptor.width + settings.SpacingPixels - 1) / settings.SpacingPixels);
            descriptor.height = Mathf.Max(1, (descriptor.height + settings.SpacingPixels - 1) / settings.SpacingPixels);
            descriptor.colorFormat = RenderTextureFormat.ARGBHalf;
            descriptor.depthBufferBits = 0;
            descriptor.msaaSamples = 1;
            descriptor.useMipMap = false;
            descriptor.autoGenerateMips = false;
            descriptor.sRGB = false;
            return descriptor;
        }

        public static RenderTextureDescriptor CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var baseDescriptor = BurtRenderTargetDescriptorUtility.CreateScreenSpaceGlobalIlluminationDescriptor(camera);
            var gridPixelSize = settings.TranslucencyVolumeGridPixelSize;
            var nearPlane = camera != null ? Mathf.Max(camera.nearClipPlane, 0.01f) : 0.1f;
            var cameraFarPlane = camera != null ? Mathf.Max(camera.farClipPlane, nearPlane + 1f) : 1000f;
            var farPlane = Mathf.Min(cameraFarPlane, nearPlane + settings.TranslucencyVolumeEndDistanceFromCamera);
            var gridDepth = ResolveTranslucencyVolumeGridDepth(nearPlane, farPlane, settings);
            var descriptor = new RenderTextureDescriptor(
                Mathf.Max(1, (baseDescriptor.width + gridPixelSize - 1) / gridPixelSize),
                Mathf.Max(1, (baseDescriptor.height + gridPixelSize - 1) / gridPixelSize),
                RenderTextureFormat.ARGBHalf,
                0)
            {
                dimension = TextureDimension.Tex3D,
                volumeDepth = gridDepth,
                enableRandomWrite = true,
                msaaSamples = 1,
                useMipMap = true,
                autoGenerateMips = false,
                mipCount = SceneVoxelOccupancyMipCount,
                sRGB = false
            };
            return descriptor;
        }

        public static RenderTextureDescriptor CreateScreenSpaceGlobalIlluminationTranslucencyVolumeTraceAtlasDescriptor(
            Camera camera,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            RenderTextureFormat format)
        {
            var volumeDescriptor = CreateScreenSpaceGlobalIlluminationTranslucencyVolumeDescriptor(camera, settings);
            var octResolution = Mathf.Clamp(settings.TranslucencyVolumeTracingOctahedronResolution, 1, 8);
            var descriptor = new RenderTextureDescriptor(
                Mathf.Max(1, volumeDescriptor.width * octResolution),
                Mathf.Max(1, volumeDescriptor.height * octResolution),
                format,
                0)
            {
                dimension = TextureDimension.Tex3D,
                volumeDepth = Mathf.Max(1, volumeDescriptor.volumeDepth),
                enableRandomWrite = true,
                msaaSamples = 1,
                useMipMap = false,
                autoGenerateMips = false,
                sRGB = false
            };
            return descriptor;
        }

