        public static BurtRenderBufferDescriptor CreateScreenSpaceGlobalIlluminationScreenProbeImportancePDFSHBufferDescriptor(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var descriptor = CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            var screenProbeWidth = Mathf.Max(1, descriptor.width);
            var screenProbeHeight = Mathf.Max(1, descriptor.height);
            var uniformProbeCount = Mathf.Max(1, screenProbeWidth * screenProbeHeight);
            var maxAdaptiveProbes = ResolveScreenProbeAdaptiveProbeMaxCount(camera, settings);
            var atlasProbeHeight = Mathf.Max(screenProbeHeight, Mathf.CeilToInt((uniformProbeCount + maxAdaptiveProbes) / (float)screenProbeWidth));
            var coefficientCount = Mathf.Max(1, screenProbeWidth * atlasProbeHeight * ScreenProbeImportancePDFSHCoefficientCount);
            return new BurtRenderBufferDescriptor(
                coefficientCount,
                4,
                GraphicsBuffer.Target.Structured,
                BurtRenderGraphResourceRegistry.BurtGIScreenProbeImportancePDFSHBufferName);
        }

        public static int ResolveScreenProbeAdaptiveProbeMaxCount(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var descriptor = CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            var uniformProbeCount = Mathf.Max(1, descriptor.width * descriptor.height);
            return Mathf.Clamp(
                Mathf.FloorToInt(uniformProbeCount * settings.AdaptiveAllocationFraction),
                1,
                ScreenProbeAdaptiveMaxProbeIndexR16);
        }

