        }

        public static int ResolveRadianceCacheClipMapMaxProbeCount(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var atlasResolutionInProbes = ResolveRadianceCacheClipMapProbeAtlasResolutionInProbes(camera, settings);
            return Mathf.Clamp(
                atlasResolutionInProbes * atlasResolutionInProbes,
                1,
                RadianceCacheClipMapIndirectionMaxProbeCountR16);
        }

        public static int ResolveRadianceCacheClipMapTraceBudget(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings, int maxProbeCount)
        {
            var traceBudget = UseRadianceCacheClipMapIrradianceConfiguration(settings)
                ? settings.RadianceCacheIrradianceNumProbesToTraceBudget
                : settings.RadianceCacheNumProbesToTraceBudget;
            return settings.RadianceCacheForceFullUpdate
                ? Mathf.Max(1, maxProbeCount)
                : Mathf.Clamp(traceBudget, 1, Mathf.Max(1, maxProbeCount));
        }

        public static int ResolveRadianceCacheClipMapResolution(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return Mathf.Clamp(
                UseRadianceCacheClipMapIrradianceConfiguration(settings)
                    ? settings.RadianceCacheIrradianceClipMapResolution
                    : settings.RadianceCacheClipMapResolution,
                1,
                256);
        }

        public static int ResolveRadianceCacheClipMapCount(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return Mathf.Clamp(
                UseRadianceCacheClipMapIrradianceConfiguration(settings)
                    ? settings.RadianceCacheIrradianceClipMapCount
                    : settings.RadianceCacheClipMapCount,
                1,
                RadianceCacheClipMapMaxCount);
        }

        public static int ResolveRadianceCacheClipMapRadianceProbeResolution(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return Mathf.Clamp(
                UseRadianceCacheClipMapIrradianceConfiguration(settings)
                    ? settings.RadianceCacheIrradianceRadianceProbeResolution
                    : settings.RadianceCacheRadianceProbeResolution,
                8,
                64);
        }

        private static bool UseRadianceCacheClipMapIrradianceConfiguration(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return settings.RadianceCacheCalculateIrradiance || settings.RadianceCacheEnableMultiBounceFromRadianceCache;
        }

        public static int ResolveRadianceCacheClipMapFinalProbeResolution(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
