        {
            return Mathf.Max(1, ResolveRadianceCacheClipMapRadianceProbeResolution(settings) / RadianceCacheClipMapTraceFromProbesGroupSize);
        }

        public static int ResolveRadianceCacheClipMapBaseProbeTraceTileResolution(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return Mathf.Max(1, ResolveRadianceCacheClipMapRadianceProbeResolution(settings) / RadianceCacheClipMapTraceFromProbesGroupSize / 2);
        }

        public static int ResolveRadianceCacheClipMapMaxProbeTraceTileResolution(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            return Mathf.Max(1, ResolveRadianceCacheClipMapRadianceProbeResolution(settings) / RadianceCacheClipMapTraceFromProbesGroupSize * 2);
        }

        public static int ResolveRadianceCacheClipMapIrradianceProbeResolution(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
