        public static float ResolveScreenProbeGatherMaxRayIntensity(BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings, Camera camera)
        {
            var maxRayIntensity = Mathf.Clamp(settings.GatherMaxRayIntensity, 0.01f, 40f);
            if (BurtGISceneVoxelClipmapStateUtility.HasValidTraceResources(camera))
            {
                maxRayIntensity = Mathf.Clamp(maxRayIntensity, 0.01f, 1f);
            }

            return maxRayIntensity;
        }

        public static BurtRadianceCacheClipMapState ResolveRadianceCacheClipMapState(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var atlasResolutionInProbes = ResolveRadianceCacheClipMapProbeAtlasResolutionInProbes(camera, settings);
            var clipmapResolution = ResolveRadianceCacheClipMapResolution(settings);
            var clipmapCount = ResolveRadianceCacheClipMapCount(settings);
            var viewOrigin = camera != null ? camera.transform.position : Vector3.zero;
            var hasSceneVoxelClipmap = BurtGISceneVoxelVolumeUtility.TryResolveRadianceCacheClipmap(camera, out var sceneVoxelCenterExtent, out var sceneVoxelDistributionBase);
            var hasGeneratedSceneVoxelClipmap = !hasSceneVoxelClipmap &&
                TryResolveGeneratedSceneVoxelClipmap(camera, settings, out sceneVoxelCenterExtent, out sceneVoxelDistributionBase);
            var clipmapBaseCenter = hasSceneVoxelClipmap
                ? new Vector3(sceneVoxelCenterExtent.x, sceneVoxelCenterExtent.y, sceneVoxelCenterExtent.z)
                : hasGeneratedSceneVoxelClipmap
                    ? new Vector3(sceneVoxelCenterExtent.x, sceneVoxelCenterExtent.y, sceneVoxelCenterExtent.z)
                : viewOrigin;
            var clipmapBaseExtent = hasSceneVoxelClipmap
                ? Mathf.Max(0.01f, sceneVoxelCenterExtent.w)
                : hasGeneratedSceneVoxelClipmap
                    ? Mathf.Max(0.01f, sceneVoxelCenterExtent.w)
                : UseRadianceCacheClipMapIrradianceConfiguration(settings)
                    ? settings.RadianceCacheIrradianceClipMapWorldExtent
                    : settings.RadianceCacheClipMapWorldExtent;
            var clipmapDistributionBase = hasSceneVoxelClipmap
                ? Mathf.Max(1f, sceneVoxelDistributionBase)
                : hasGeneratedSceneVoxelClipmap
                    ? Mathf.Max(1f, sceneVoxelDistributionBase)
                : RadianceCacheClipMapDistributionBase;
            var worldPositionToProbeCoord = new Vector4[RadianceCacheClipMapCount];
            var probeCoordToWorldCenter = new Vector4[RadianceCacheClipMapCount];
            var clipmapCenterExtent = new Vector4[RadianceCacheClipMapCount];
            var clipmapParameters = new Vector4[RadianceCacheClipMapCount];

            for (var clipmapIndex = 0; clipmapIndex < RadianceCacheClipMapMaxCount; ++clipmapIndex)
            {
                var clipmapExtent = clipmapBaseExtent * Mathf.Pow(clipmapDistributionBase, clipmapIndex);
                var cellSize = Mathf.Max(0.001f, (2f * clipmapExtent) / clipmapResolution);
                var gridCenterSource = hasSceneVoxelClipmap || hasGeneratedSceneVoxelClipmap ? clipmapBaseCenter : viewOrigin;
                var gridCenter = new Vector3(
                    Mathf.FloorToInt(gridCenterSource.x / cellSize),
                    Mathf.FloorToInt(gridCenterSource.y / cellSize),
                    Mathf.FloorToInt(gridCenterSource.z / cellSize)) * cellSize;
                var clipmapMin = gridCenter - clipmapExtent * Vector3.one - 0.5f * cellSize * Vector3.one;
                var probeCoordToWorldBias = clipmapMin + 0.5f * cellSize * Vector3.one;
                var worldPositionToProbeScale = 1f / cellSize;
                var worldPositionToProbeBias = -clipmapMin * worldPositionToProbeScale;

                worldPositionToProbeCoord[clipmapIndex] = new Vector4(
                    worldPositionToProbeBias.x,
                    worldPositionToProbeBias.y,
                    worldPositionToProbeBias.z,
                    worldPositionToProbeScale);
                probeCoordToWorldCenter[clipmapIndex] = new Vector4(
                    probeCoordToWorldBias.x,
                    probeCoordToWorldBias.y,
                    probeCoordToWorldBias.z,
                    cellSize);
                clipmapCenterExtent[clipmapIndex] = new Vector4(
                    gridCenter.x,
                    gridCenter.y,
                    gridCenter.z,
                    clipmapExtent);
                clipmapParameters[clipmapIndex] = new Vector4(
                    cellSize,
                    cellSize,
                    0f,
                    clipmapIndex);
            }

            return new BurtRadianceCacheClipMapState(
                new Vector4(atlasResolutionInProbes, ResolveRadianceCacheClipMapRadianceProbeResolution(settings), clipmapCount, clipmapResolution),
                new Vector4(clipmapBaseExtent, clipmapDistributionBase, RadianceCacheClipMapInvFadeSize, ResolveRadianceCacheClipMapFinalProbeResolution(settings)),
                worldPositionToProbeCoord,
                probeCoordToWorldCenter,
                clipmapCenterExtent,
                clipmapParameters);
        }

        private static bool TryResolveGeneratedSceneVoxelClipmap(
            Camera camera,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            out Vector4 centerExtent,
            out float distributionBase)
        {
            centerExtent = Vector4.zero;
            distributionBase = 2f;
            if (!settings.Enabled ||
                settings.RadianceCacheType != ScreenProbeRadianceCacheType.ClipMap ||
                (!settings.TraceSceneVoxel &&
                    !settings.TraceVoxelOctree &&
                    !settings.TraceScreenGrid &&
                    !settings.TraceUseWorldRadianceClipMap &&
                    !settings.RadianceCacheCalculateIrradiance &&
                    !settings.RadianceCacheEnableMultiBounceFromRadianceCache))
            {
                return false;
            }

            var extent = Mathf.Max(1f, settings.SceneVoxelClipMapFirstWorldExtent);
            var fallbackCenter = camera != null ? camera.transform.position : Vector3.zero;
            var center = settings.SceneVoxelFollowCamera
                ? ResolveSceneVoxelFollowCenter(camera, settings, new Vector4(fallbackCenter.x, fallbackCenter.y, fallbackCenter.z, extent))
                : settings.SceneVoxelOrigin;
            var cellSize = Mathf.Max(0.001f, extent * 2f / NormalizeSceneVoxelRadianceResolution(SceneVoxelRadianceResolution));
            center = new Vector3(
                Mathf.Round(center.x / cellSize) * cellSize,
                Mathf.Round(center.y / cellSize) * cellSize,
                Mathf.Round(center.z / cellSize) * cellSize);
            centerExtent = new Vector4(center.x, center.y, center.z, extent);
            distributionBase = settings.SceneVoxelClipMapDistributionBase;
            return true;
        }

        public static Vector4 ResolveSceneVoxelCenterExtent(
            Camera camera,
            BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings,
            BurtRadianceCacheClipMapState clipMapState,
            int sceneVoxelResolution = SceneVoxelRadianceResolution)
        {
            var fallbackCenterExtent = clipMapState.ClipmapCenterExtent != null && clipMapState.ClipmapCenterExtent.Length > 0
                ? clipMapState.ClipmapCenterExtent[0]
                : Vector4.zero;
            var extent = Mathf.Max(1f, settings.SceneVoxelClipMapFirstWorldExtent);
            var center = settings.SceneVoxelFollowCamera
                ? ResolveSceneVoxelFollowCenter(camera, settings, fallbackCenterExtent)
                : settings.SceneVoxelOrigin;
            var cellSize = Mathf.Max(0.001f, extent * 2f / NormalizeSceneVoxelRadianceResolution(sceneVoxelResolution));
            center = new Vector3(
                Mathf.Round(center.x / cellSize) * cellSize,
                Mathf.Round(center.y / cellSize) * cellSize,
                Mathf.Round(center.z / cellSize) * cellSize);
            return BurtGISceneVoxelVolumeUtility.ResolveCenterExtent(camera, new Vector4(center.x, center.y, center.z, extent));
        }

        private static Vector3 ResolveSceneVoxelFollowCenter(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings, Vector4 fallbackCenterExtent)
        {
            var center = camera != null
                ? camera.transform.position + camera.transform.forward * settings.SceneVoxelCameraForward
                : new Vector3(fallbackCenterExtent.x, fallbackCenterExtent.y, fallbackCenterExtent.z);
            return BurtXRenderPivot.TryGetTopPosition(out var pivotPosition)
                ? pivotPosition
                : center;
        }

        public static Vector3 ResolveSceneVoxelClipMapForward(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            if (settings.SceneVoxelFollowCamera && camera != null)
            {
                var forward = camera.transform.forward;
                forward.y = 0f;
                return forward.sqrMagnitude > 0.000001f ? forward.normalized : Vector3.forward;
            }

            return Vector3.forward;
        }

        public static string ResolveRadianceCacheClipMapResourceContractLabel(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings, BurtRenderPipelineAsset asset = null)
        {
            if (!settings.Enabled)
            {
                return "Disabled";
            }

            if (settings.RadianceCacheType != ScreenProbeRadianceCacheType.ClipMap)
            {
                return "Disabled(CacheType=" + settings.RadianceCacheType + ")";
            }

            if (!SystemInfo.supportsComputeShaders)
            {
                return "Disabled(ComputeShadersUnsupported)";
            }

            var atlasResolutionInProbes = ResolveRadianceCacheClipMapProbeAtlasResolutionInProbes(camera, settings);
            var clipmapState = ResolveRadianceCacheClipMapState(camera, settings);
            var sceneVoxelVolumeDriven = BurtGISceneVoxelVolumeUtility.TryResolveRadianceCacheClipmap(camera, out _, out _);
            var generatedSceneVoxelDriven = !sceneVoxelVolumeDriven &&
                TryResolveGeneratedSceneVoxelClipmap(camera, settings, out _, out _);
            var hardwareRayTrace = settings.RadianceCacheTraceHardwareRay && asset != null && asset.EnableXGIHardwareRayTracing;
            var traceSource = hardwareRayTrace
                ? "HardwareRayTracing"
                : settings.TraceVoxelOctree
                    ? "VoxelOctree"
                    : settings.TraceSceneVoxel
                        ? "SceneVoxel"
                        : "SceneCacheOnly";
            var anchor = sceneVoxelVolumeDriven
                ? "SceneVoxelVolumeClipmap"
                : generatedSceneVoxelDriven
                    ? "GeneratedSceneVoxelClipmap"
                    : "CameraSnapped";
            return "ClipMapLiteContract(AtlasProbes=" + atlasResolutionInProbes + "x" + atlasResolutionInProbes + ",ProbeRes=" + ResolveRadianceCacheClipMapRadianceProbeResolution(settings) + ",Clipmaps=" + ResolveRadianceCacheClipMapCount(settings) + ",ClipmapRes=" + ResolveRadianceCacheClipMapResolution(settings).ToString("0.###") + ",WorldExtent=" + clipmapState.WorldParams.x.ToString("0.###") + ",Distribution=" + clipmapState.WorldParams.y.ToString("0.###") + ",Anchor=" + anchor + ",TracePath=" + ResolveRadianceCacheHardwareRayTracingStatusLabel(asset, settings) + ",TraceSource=" + traceSource + ",VoxelTrace=ScreenProbe(MaxSteps=" + settings.TraceVoxelMaxTraceSteps + ",Step=" + settings.TraceVoxelStepFactor.ToString("0.###") + "),TraceBuffers=IndirectArgs8+TileDataUInt2DistanceGatedPriorityBucketCostBudgetDirectionBinSortTraceWritebackEquiAreaResample+ConeMarchVoxelOctreeHashGridSceneCache,HashGrid=ValueTileBucketCountVisibilityUpdateTileIndirectArgsDebugLite Cells=" + ResolveRadianceCacheHashGridCellCount() + ")";
        }

        public static string ResolveRadianceCacheHardwareRayTracingStatusLabel(BurtRenderPipelineAsset asset, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            if (!settings.Enabled)
            {
                return "Disabled";
            }

            if (!settings.RadianceCacheTraceHardwareRay)
            {
                return "ComputeFallback(VolumeOff)";
            }

            if (asset == null)
            {
                return "ComputeFallback(NoAsset)";
            }

            if (!asset.XGIHardwareRayTracingEnabledInAsset)
            {
                return "ComputeFallback(AssetOff)";
            }

            if (!SystemInfo.supportsRayTracing)
            {
                return "ComputeFallback(PlatformNoRayTracing)";
            }

            if (asset.XGIRadianceCacheHardwareRayTracingShader == null)
            {
                return "ComputeFallback(MissingRayTracingShaderAsset)";
            }

            return "DXRReady";
        }

        public static string ResolveScreenProbeHardwareRayTracingStatusLabel(BurtRenderPipelineAsset asset, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            if (!settings.Enabled)
            {
                return "Disabled";
            }

            if (!settings.TraceHardwareRay)
            {
                return "ComputeFallback(VolumeOff)";
            }

            if (!SupportsScreenProbeTraceCompactCompute())
            {
                return "ComputeFallback(CompactQueueUnsupported)";
            }

            if (!settings.TraceCompact)
            {
                return "ComputeFallback(CompactQueueDisabled)";
            }

            if (asset == null)
            {
                return "ComputeFallback(NoAsset)";
            }

            if (!asset.XGIHardwareRayTracingEnabledInAsset)
            {
                return "ComputeFallback(AssetOff)";
            }

            if (!SystemInfo.supportsRayTracing)
            {
                return "ComputeFallback(PlatformNoRayTracing)";
            }

            if (asset.XGIRadianceCacheHardwareRayTracingShader == null)
            {
                return "ComputeFallback(MissingRayTracingShaderAsset)";
            }

            return "DXRReady";
        }

        public static string ResolveXGICompatShaderStatusLabel()
        {
            var missing = string.Empty;
            var missingCount = 0;
            for (var i = 0; i < XGICompatShaderNames.Length; i++)
            {
                var shaderName = XGICompatShaderNames[i];
                if (Shader.Find(shaderName) != null)
                {
                    continue;
                }

                if (missingCount > 0)
                {
                    missing += ",";
                }

                missing += shaderName;
                missingCount++;
            }

            return missingCount == 0
                ? "Ready(Shaders=" + XGICompatShaderNames.Length + ")"
                : "Missing(" + missing + ")";
        }

        public static string ResolveXGICompatRayTracingStatusLabel()
        {
            var radianceCacheRayTracingShader = Resources.Load<RayTracingShader>(XGIRadianceCacheRayTracingResourcePath);
            if (radianceCacheRayTracingShader == null)
            {
                return "Missing(" + XGIRadianceCacheRayTracingResourcePath + ")";
            }

            var bakingRayTracingShader = Resources.Load<RayTracingShader>(XGIProbeBakingRayTracingResourcePath);
            if (bakingRayTracingShader == null)
            {
                return "Missing(" + XGIProbeBakingRayTracingResourcePath + ")";
            }

            return SystemInfo.supportsRayTracing
                ? "Ready(RadianceCacheDXR=1,BakingDXR=1)"
                : "Ready(RadianceCacheDXR=1,BakingDXR=1,PlatformNoRayTracing)";
        }

        public static string ResolveXGIResourceStatusReport()
        {
            return "[BurtRP][XGIResourceValidation]\n" +
                "BurtGIShaderStatus=" + ResolveScreenSpaceGlobalIlluminationShaderStatusLabel() + "\n" +
                "BurtGIScreenProbeComputeStatus=" + ResolveScreenProbeComputeStatusLabel() + "\n" +
                "BurtGIRadianceCacheComputeStatus=" + BurtScreenSpaceGlobalIlluminationRadianceCacheClipMapPass.ResolveComputeResourceStatusLabel() + "\n" +
                "BurtGICopyTexture3DStatus=" + BurtScreenSpaceGlobalIlluminationPass.ResolveCopyTexture3DResourceStatusLabel() + "\n" +
                "BurtGIRuntimeComputeStatus=" + ResolveXGIRuntimeComputeStatusLabel() + "\n" +
                "BurtGIXGISdfDebugStatus=" + ResolveXGISdfDebugStatusLabel() + "\n" +
                "BurtGIProbePhysicalPoolUploadStatus=" + BurtGIVirtualProbePhysicalPool.ResolveUploadComputeStatusLabel() + "\n" +
                "BurtGITranslucencyVolumeComputeStatus=" + ResolveTranslucencyVolumeComputeStatusLabel() + "\n" +
                "BurtGITranslucencyVolumeRuntimeStatus=" + BurtGITranslucencyVolumeRuntimeState.ResolveStatusLabel() + "\n" +
                "BurtGIXGICompatShaderStatus=" + ResolveXGICompatShaderStatusLabel() + "\n" +
                "BurtGIXGICompatRayTracingStatus=" + ResolveXGICompatRayTracingStatusLabel();
        }

        private static RenderTextureDescriptor CreateRadianceCacheClipMapProbeAtlasDescriptor(Camera camera, BurtScreenSpaceGlobalIlluminationScreenProbeSettings settings)
        {
            var descriptor = CreateScreenSpaceGlobalIlluminationScreenProbeDescriptor(camera, settings);
            var atlasResolutionInProbes = ResolveRadianceCacheClipMapProbeAtlasResolutionInProbes(camera, settings);
            var radianceProbeResolution = ResolveRadianceCacheClipMapRadianceProbeResolution(settings);
            descriptor.width = Mathf.Max(1, atlasResolutionInProbes * radianceProbeResolution);
            descriptor.height = Mathf.Max(1, atlasResolutionInProbes * radianceProbeResolution);
            descriptor.enableRandomWrite = true;
            return descriptor;
        }

