        private static BurtScreenSpaceGlobalIlluminationSettings CreateScreenSpaceGlobalIlluminationSettings(ScreenSpaceGlobalIlluminationVolumeComponent component)
        {
            var quality = component.quality.value;
            var resolution = component.resolution.value;
            var sampleCount = component.sampleCount.value;
            var maxSteps = component.maxSteps.value;
            var radius = component.radius.value;
            var thickness = component.thickness.value;
            var blur = component.blur.value;
            var blurSharpness = component.blurSharpness.value;
            var spatialDenoiseRadius = component.spatialDenoiseRadius.value;
            var spatialDenoiseStrength = component.spatialDenoiseStrength.value;
            var leakGuardStrength = component.leakGuardStrength.value;
            var edgeFadeStrength = component.edgeFadeStrength.value;
            var normalConeTightness = component.normalConeTightness.value;
            var skyEdgeSuppression = component.skyEdgeSuppression.value;
            var temporalVarianceClamp = component.temporalVarianceClamp.value;
            var temporalHitRejection = component.temporalHitRejection.value;
            var enableBackfaceDiffuse = component.enableBackfaceDiffuse.value;
            var enableRoughSpecular = component.enableRoughSpecular.value;
            var useTranslucencyVolume = component.useTranslucencyVolume.value;
            var sceneVoxelTraceMaxSteps = component.sceneVoxelTraceMaxSteps.value;
            var sceneVoxelTraceStepFactor = component.sceneVoxelTraceStepFactor.value;
            ApplyScreenSpaceGlobalIlluminationQualityPreset(
                quality,
                ref resolution,
                ref sampleCount,
                ref maxSteps,
                ref radius,
                ref thickness,
                ref blur,
                ref blurSharpness,
                ref spatialDenoiseRadius,
                ref spatialDenoiseStrength,
                ref leakGuardStrength,
                ref edgeFadeStrength,
                ref normalConeTightness,
                ref skyEdgeSuppression,
                ref temporalVarianceClamp,
                ref temporalHitRejection);
            ApplyScreenSpaceGlobalIlluminationXGIQualityPreset(
                quality,
                ref enableBackfaceDiffuse,
                ref enableRoughSpecular,
                ref useTranslucencyVolume,
                ref sceneVoxelTraceMaxSteps,
                ref sceneVoxelTraceStepFactor);

            return new BurtScreenSpaceGlobalIlluminationSettings(
                true,
                quality,
                resolution,
                component.intensity.value,
                radius,
                sampleCount,
                maxSteps,
                thickness,
                component.skyFallback.value,
                component.radianceClamp.value,
                component.normalWeight.value,
                component.distanceFade.value,
                blur,
                blurSharpness,
                spatialDenoiseRadius,
                spatialDenoiseStrength,
                leakGuardStrength,
                edgeFadeStrength,
                normalConeTightness,
                skyEdgeSuppression,
                component.shortRangeAO.value,
                component.shortRangeAOWeight.value,
                component.shortRangeAOApplyWeight.value,
                component.shortRangeAOSlopeCompareToleranceScale.value,
                component.temporalAccumulation.value,
                component.temporalFeedback.value,
                component.temporalDepthRejection.value,
                component.temporalNormalRejection.value,
                component.temporalClamp.value,
                temporalVarianceClamp,
                temporalHitRejection,
                component.finalGather.value,
                component.irradianceFieldStrength.value,
                component.irradianceFieldBaked.value,
                enableBackfaceDiffuse,
                enableRoughSpecular,
                component.screenProbeMaxRoughnessToEvaluateRoughSpecular.value,
                component.xgiCharacterIntensity.value,
                component.xgiScreenRatio.value,
                component.xgiScreenRatioSpeed.value,
                useTranslucencyVolume,
                component.sceneVoxelAlwaysUpdate.value,
                component.sceneVoxelOriginUpdateDistance.value,
                component.sceneVoxelClipMapCount.value,
                component.sceneVoxelClipMapDistributionBase.value,
                component.sceneVoxelClipMapOffset03.value,
                component.sceneVoxelClipMapUpdateDistance03.value,
                component.sceneVoxelClipMapOffset47.value,
                component.sceneVoxelClipMapUpdateDistance47.value,
                component.sceneVoxelClipMapResolution.value,
                component.sceneVoxelMaterialBudget.value,
                component.sceneVoxelMaterialGenerateMethod.value,
                component.sceneVoxelDrawVegetation.value,
                component.sceneVoxelDrawGrass.value,
                component.sceneVoxelLightingType.value,
                component.sceneVoxelLightingDirectionalShadow.value,
                component.sceneVoxelLightingPunctualShadow.value,
                component.sceneVoxelLightingSkyLight.value,
                component.sceneVoxelDiffuseColorBoost.value,
                component.sceneVoxelAvoidBleeding.value,
                component.sceneVoxelMaxSampleCount.value,
                component.sceneVoxelMultiBounce.value,
                component.sceneVoxelDirectionCount.value,
                sceneVoxelTraceMaxSteps,
                sceneVoxelTraceStepFactor,
                component.screenProbeSkylightLeaking.value,
                component.screenProbeSkylightLeakingRoughness.value,
                component.screenProbeFullSkylightLeakingDistance.value,
                component.screenProbeTraceSkyCubemap.value,
                component.sceneVoxelDirectLightIntensity.value,
                new Vector3(component.sceneVoxelDirectLightTint.value.linear.r, component.sceneVoxelDirectLightTint.value.linear.g, component.sceneVoxelDirectLightTint.value.linear.b),
                component.sceneVoxelIndirectLightIntensity.value,
                new Vector3(component.sceneVoxelIndirectLightTint.value.linear.r, component.sceneVoxelIndirectLightTint.value.linear.g, component.sceneVoxelIndirectLightTint.value.linear.b),
                component.sceneVoxelEnableSkyVisibility.value,
                component.sceneVoxelDebugExpandView.value,
                component.sceneVoxelDebugExpandViewDistance.value,
                component.sceneVoxelDebugShowMipmapID.value,
                0,
                component.sceneVoxelDebugByTrace.value,
                component.sceneVoxelDebugDrawProbe.value,
                component.sceneVoxelDebugProbeSizeWS.value,
                component.localSkyProbeShowDebugSphere.value);
        }

        private static BurtScreenSpaceGlobalIlluminationSettings ApplyTemporalAACompatibilityOverrides(
            BurtScreenSpaceGlobalIlluminationSettings settings,
            BurtRenderRequest request)
        {
            if (!settings.Enabled || !ShouldUseTemporalAACompatibility(request))
            {
                return settings;
            }

            return new BurtScreenSpaceGlobalIlluminationSettings(
                true,
                settings.Quality,
                ScreenSpaceGlobalIlluminationResolution.Full,
                settings.Intensity,
                settings.Radius,
                settings.SampleCount,
                settings.MaxSteps,
                settings.Thickness,
                settings.SkyFallback,
                settings.RadianceClamp,
                settings.NormalWeight,
                settings.DistanceFade,
                settings.Blur,
                Mathf.Max(settings.BlurSharpness, 0.22f),
                settings.SpatialDenoiseRadius,
                Mathf.Max(settings.SpatialDenoiseStrength, 0.82f),
                Mathf.Max(settings.LeakGuardStrength, 0.72f),
                Mathf.Max(settings.EdgeFadeStrength, 0.6f),
                Mathf.Max(settings.NormalConeTightness, 0.62f),
                Mathf.Max(settings.SkyEdgeSuppression, 0.7f),
                settings.ShortRangeAO,
                settings.ShortRangeAOWeight,
                settings.ShortRangeAOApplyWeight,
                settings.ShortRangeAOSlopeCompareToleranceScale,
                false,
                settings.TemporalFeedback,
                settings.TemporalDepthRejection,
                settings.TemporalNormalRejection,
                settings.TemporalClamp,
                settings.TemporalVarianceClamp,
                settings.TemporalHitRejection,
                settings.FinalGather,
                settings.IrradianceFieldStrength,
                settings.IrradianceFieldBaked,
                settings.EnableBackfaceDiffuse,
                settings.EnableRoughSpecular,
                settings.ScreenProbeMaxRoughnessToEvaluateRoughSpecular,
                settings.XGICharacterIntensity,
                settings.XGIScreenRatio,
                settings.XGIScreenRatioSpeed,
                settings.UseTranslucencyVolume,
                settings.SceneVoxelAlwaysUpdate,
                settings.SceneVoxelOriginUpdateDistance,
                settings.SceneVoxelClipMapCount,
                settings.SceneVoxelClipMapDistributionBase,
                settings.SceneVoxelClipMapOffset03,
                settings.SceneVoxelClipMapUpdateDistance03,
                settings.SceneVoxelClipMapOffset47,
                settings.SceneVoxelClipMapUpdateDistance47,
                settings.SceneVoxelClipMapResolution,
                settings.SceneVoxelMaterialBudget,
                settings.SceneVoxelMaterialGenerateMethod,
                settings.SceneVoxelDrawVegetation,
                settings.SceneVoxelDrawGrass,
                settings.SceneVoxelLightingType,
                settings.SceneVoxelLightingDirectionalShadow,
                settings.SceneVoxelLightingPunctualShadow,
                settings.SceneVoxelLightingSkyLight,
                settings.SceneVoxelDiffuseColorBoost,
                settings.SceneVoxelAvoidBleeding,
                settings.SceneVoxelMaxSampleCount,
                settings.SceneVoxelMultiBounce,
                settings.SceneVoxelDirectionCount,
                settings.SceneVoxelTraceMaxSteps,
                settings.SceneVoxelTraceStepFactor,
                settings.ScreenProbeSkylightLeaking,
                settings.ScreenProbeSkylightLeakingRoughness,
                settings.ScreenProbeFullSkylightLeakingDistance,
                settings.ScreenProbeTraceSkyCubemap,
                settings.SceneVoxelDirectLightIntensity,
                settings.SceneVoxelDirectLightTint,
                settings.SceneVoxelIndirectLightIntensity,
                settings.SceneVoxelIndirectLightTint,
                settings.SceneVoxelEnableSkyVisibility,
                settings.SceneVoxelDebugExpandView,
                settings.SceneVoxelDebugExpandViewDistance,
                settings.SceneVoxelDebugShowMipmapID,
                settings.SceneVoxelDebugLayer,
                settings.SceneVoxelDebugByTrace,
                settings.SceneVoxelDebugDrawProbe,
                settings.SceneVoxelDebugProbeSizeWS,
                settings.LocalSkyProbeShowDebugSphere);
        }

        public static bool ShouldUseTemporalAACompatibility(BurtRenderRequest request)
        {
            var temporalAA = request != null ? request.TemporalAA : null;
            if (temporalAA != null && temporalAA.Enabled)
            {
                return true;
            }

            return IsScreenSpaceGlobalIlluminationDebugMode(BurtShadingDebugSettings.Mode) &&
                !IsScreenSpaceGlobalIlluminationTemporalDiagnosticDebugMode(BurtShadingDebugSettings.Mode) &&
                PostProcessUtility.HasActiveTemporalAASource(request);
        }

        private static void ApplyScreenSpaceGlobalIlluminationQualityPreset(
            ScreenSpaceGlobalIlluminationQuality quality,
            ref ScreenSpaceGlobalIlluminationResolution resolution,
            ref int sampleCount,
            ref int maxSteps,
            ref float radius,
            ref float thickness,
            ref bool blur,
            ref float blurSharpness,
            ref float spatialDenoiseRadius,
            ref float spatialDenoiseStrength,
            ref float leakGuardStrength,
            ref float edgeFadeStrength,
            ref float normalConeTightness,
            ref float skyEdgeSuppression,
            ref float temporalVarianceClamp,
            ref float temporalHitRejection)
        {
            switch (quality)
            {
                case ScreenSpaceGlobalIlluminationQuality.Low:
                    resolution = ScreenSpaceGlobalIlluminationResolution.Half;
                    sampleCount = 8;
                    maxSteps = 6;
                    radius = Mathf.Min(radius, 1.5f);
                    thickness = Mathf.Max(thickness, 0.45f);
                    blur = true;
                    blurSharpness = 0.12f;
                    spatialDenoiseRadius = 1f;
                    spatialDenoiseStrength = 0.65f;
                    leakGuardStrength = 0.55f;
                    edgeFadeStrength = 0.45f;
                    normalConeTightness = 0.45f;
                    skyEdgeSuppression = 0.5f;
                    temporalVarianceClamp = 1f;
                    temporalHitRejection = 0.65f;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.Medium:
                    resolution = ScreenSpaceGlobalIlluminationResolution.Half;
                    sampleCount = 12;
                    maxSteps = 8;
                    radius = Mathf.Max(radius, 2f);
                    thickness = Mathf.Max(thickness, 0.35f);
                    blur = true;
                    blurSharpness = 0.18f;
                    spatialDenoiseRadius = 1.25f;
                    spatialDenoiseStrength = 0.75f;
                    leakGuardStrength = 0.65f;
                    edgeFadeStrength = 0.5f;
                    normalConeTightness = 0.55f;
                    skyEdgeSuppression = 0.6f;
                    temporalVarianceClamp = 1.25f;
                    temporalHitRejection = 0.55f;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.High:
                    resolution = ScreenSpaceGlobalIlluminationResolution.Full;
                    sampleCount = 20;
                    maxSteps = 12;
                    radius = Mathf.Max(radius, 3f);
                    thickness = Mathf.Max(thickness, 0.28f);
                    blur = true;
                    blurSharpness = 0.24f;
                    spatialDenoiseRadius = 1.5f;
                    spatialDenoiseStrength = 0.85f;
                    leakGuardStrength = 0.75f;
                    edgeFadeStrength = 0.6f;
                    normalConeTightness = 0.68f;
                    skyEdgeSuppression = 0.72f;
                    temporalVarianceClamp = 1.5f;
                    temporalHitRejection = 0.45f;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.Ultra:
                    resolution = ScreenSpaceGlobalIlluminationResolution.Full;
                    sampleCount = 28;
                    maxSteps = 16;
                    radius = Mathf.Max(radius, 4f);
                    thickness = Mathf.Max(thickness, 0.24f);
                    blur = true;
                    blurSharpness = 0.28f;
                    spatialDenoiseRadius = 1.75f;
                    spatialDenoiseStrength = 0.9f;
                    leakGuardStrength = 0.82f;
                    edgeFadeStrength = 0.68f;
                    normalConeTightness = 0.74f;
                    skyEdgeSuppression = 0.78f;
                    temporalVarianceClamp = 1.75f;
                    temporalHitRejection = 0.4f;
                    break;
            }
        }

        private static void ApplyScreenSpaceGlobalIlluminationXGIQualityPreset(
            ScreenSpaceGlobalIlluminationQuality quality,
            ref bool enableBackfaceDiffuse,
            ref bool enableRoughSpecular,
            ref bool useTranslucencyVolume,
            ref int sceneVoxelTraceMaxSteps,
            ref float sceneVoxelTraceStepFactor)
        {
            switch (quality)
            {
                case ScreenSpaceGlobalIlluminationQuality.Low:
                case ScreenSpaceGlobalIlluminationQuality.Medium:
                    sceneVoxelTraceMaxSteps = 8;
                    sceneVoxelTraceStepFactor = 10f;
                    enableBackfaceDiffuse = false;
                    enableRoughSpecular = false;
                    useTranslucencyVolume = false;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.High:
                    sceneVoxelTraceMaxSteps = 16;
                    sceneVoxelTraceStepFactor = 5f;
                    enableBackfaceDiffuse = false;
                    enableRoughSpecular = true;
                    useTranslucencyVolume = true;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.Ultra:
                    sceneVoxelTraceMaxSteps = 32;
                    sceneVoxelTraceStepFactor = 2f;
                    enableBackfaceDiffuse = true;
                    enableRoughSpecular = true;
                    useTranslucencyVolume = true;
                    break;
            }
        }

        private static void ApplyScreenSpaceGlobalIlluminationScreenProbeQualityPreset(
            ScreenSpaceGlobalIlluminationQuality quality,
            ref int screenProbeSpacingPixels,
            ref int screenProbeAdaptiveMinDownSampleFactor,
            ref int screenProbeTraceOctahedronResolution,
            ref ScreenProbeTraceSource screenProbeTraceSources,
            ref int screenProbeReprojectionMaxFramesAccumulated,
            ref float screenProbeHistoryDistanceThreshold,
            ref int radianceCacheNumProbesToTraceBudget,
            ref int translucencyVolumeGridPixelSize,
            ref float translucencyVolumeEndDistanceFromCamera,
            ref float translucencyVolumeGridDistributionZScale)
        {
            switch (quality)
            {
                case ScreenSpaceGlobalIlluminationQuality.Low:
                    screenProbeSpacingPixels = 32;
                    screenProbeAdaptiveMinDownSampleFactor = 16;
                    screenProbeTraceOctahedronResolution = 8;
                    screenProbeTraceSources = ScreenProbeTraceSource.Screen | ScreenProbeTraceSource.VoxelOctree | ScreenProbeTraceSource.SkyCubemap;
                    screenProbeReprojectionMaxFramesAccumulated = 20;
                    screenProbeHistoryDistanceThreshold = 0.02f;
                    radianceCacheNumProbesToTraceBudget = 30;
                    translucencyVolumeGridPixelSize = 128;
                    translucencyVolumeEndDistanceFromCamera = 40f;
                    translucencyVolumeGridDistributionZScale = 2f;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.Medium:
                    screenProbeSpacingPixels = 32;
                    screenProbeAdaptiveMinDownSampleFactor = 16;
                    screenProbeTraceOctahedronResolution = 8;
                    screenProbeTraceSources = ScreenProbeTraceSource.Screen | ScreenProbeTraceSource.VoxelOctree | ScreenProbeTraceSource.SkyCubemap;
                    screenProbeReprojectionMaxFramesAccumulated = 20;
                    screenProbeHistoryDistanceThreshold = 0.02f;
                    radianceCacheNumProbesToTraceBudget = 50;
                    translucencyVolumeGridPixelSize = 128;
                    translucencyVolumeEndDistanceFromCamera = 40f;
                    translucencyVolumeGridDistributionZScale = 2f;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.High:
                    screenProbeSpacingPixels = 16;
                    screenProbeAdaptiveMinDownSampleFactor = 8;
                    screenProbeTraceOctahedronResolution = 8;
                    screenProbeTraceSources = ScreenProbeTraceSource.Screen | ScreenProbeTraceSource.VoxelOctree | ScreenProbeTraceSource.SkyCubemap;
                    screenProbeReprojectionMaxFramesAccumulated = 20;
                    screenProbeHistoryDistanceThreshold = 0.02f;
                    radianceCacheNumProbesToTraceBudget = 100;
                    translucencyVolumeGridPixelSize = 128;
                    translucencyVolumeEndDistanceFromCamera = 60f;
                    translucencyVolumeGridDistributionZScale = 3f;
                    break;
                case ScreenSpaceGlobalIlluminationQuality.Ultra:
                    screenProbeSpacingPixels = 16;
                    screenProbeAdaptiveMinDownSampleFactor = 8;
                    screenProbeTraceOctahedronResolution = 8;
                    screenProbeTraceSources = ScreenProbeTraceSource.Screen | ScreenProbeTraceSource.VoxelOctree | ScreenProbeTraceSource.SkyCubemap;
                    screenProbeReprojectionMaxFramesAccumulated = 20;
                    screenProbeHistoryDistanceThreshold = 0.02f;
                    radianceCacheNumProbesToTraceBudget = 100;
                    translucencyVolumeGridPixelSize = 64;
                    translucencyVolumeEndDistanceFromCamera = 80f;
                    translucencyVolumeGridDistributionZScale = 4f;
                    break;
            }
        }

        private static void ApplyScreenSpaceGlobalIlluminationResolution(ref RenderTextureDescriptor descriptor, BurtScreenSpaceGlobalIlluminationSettings settings)
        {
            if (settings.Resolution != ScreenSpaceGlobalIlluminationResolution.Half)
            {
                return;
            }

            descriptor.width = Mathf.Max(1, (descriptor.width + 1) / 2);
            descriptor.height = Mathf.Max(1, (descriptor.height + 1) / 2);
        }

        private static ScreenSpaceGlobalIlluminationVolumeComponent GetScreenSpaceGlobalIlluminationVolumeComponent()
        {
            var volumeManager = VolumeManager.instance;
            if (volumeManager == null)
            {
                return null;
            }

            var stack = volumeManager.stack;
            if (stack == null)
            {
                return null;
            }

            return stack.GetComponent<ScreenSpaceGlobalIlluminationVolumeComponent>();
        }
    }

    internal static class BurtScreenSpaceGlobalIlluminationRenderTargetUtility
    {
        public static void Allocate(
            BurtRenderGraphContext context,
            string passName,
            int textureId,
            BurtRenderTargetHandle target,
            RenderTextureDescriptor descriptor,
            FilterMode filterMode)
        {
            if (context == null)
            {
                return;
            }

            var cmd = context.AcquireCommandBuffer(passName);
            cmd.GetTemporaryRT(textureId, descriptor, filterMode);
            if (descriptor.dimension != TextureDimension.Tex3D)
            {
                cmd.SetRenderTarget(target.Identifier);
                cmd.ClearRenderTarget(false, true, Color.clear);
            }

            cmd.SetGlobalTexture(textureId, target.Identifier);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }

        public static void Release(BurtRenderGraphContext context, string passName, int textureId)
        {
            if (context == null)
            {
                return;
            }

            var cmd = context.AcquireCommandBuffer(passName);
            cmd.ReleaseTemporaryRT(textureId);
            context.ExecuteLegacyCommandBuffer(cmd);
            context.ReleaseCommandBuffer(cmd);
        }
    }
}
